_RAW_REGISTRY_JSON = "{\"economics::MPC (Marginal Propensity to Consume)\": {\"domain\": \"economics\", \"concept\": \"MPC (Marginal Propensity to Consume)\", \"explanation\": \"the fraction of additional income that a household spends on consumption rather than saving\", \"reason\": \"it determines the size of the spending multiplier and helps predict how fiscal policy stimulates the economy\", \"concrete_examples\": [\"If a family receives a $500 tax rebate and spends $400 of it on groceries and clothing, their MPC is 0.80.\", \"When workers get a $200 bonus and save $60 while spending $140, the MPC is 0.70.\", \"A retiree who spends every dollar of a $300 pension increase has an MPC of 1.0.\"], \"numerical_examples\": [\"If income rises from $40,000 to $42,000 and consumption rises from $35,000 to $36,600, MPC = $1,600/$2,000 = 0.80.\", \"With MPC = 0.75, the spending multiplier is 1/(1\u22120.75) = 4, so a $100 billion government injection raises GDP by $400 billion.\", \"If MPC = 0.90, each additional $1 of income generates $0.90 of consumption, leaving only $0.10 for saving.\"], \"misconceptions\": [[\"MPC is always the same for rich and poor households\", \"Empirically, lower-income households tend to have higher MPCs because a larger share of additional income goes to necessities, while wealthier households save more of their marginal income.\"]], \"analogies\": [\"MPC is like a leaky bucket: pour income in at the top and some leaks out as saving; the bigger the holes, the lower the MPC.\"], \"prerequisites\": [\"basic algebra\", \"percentage calculations\"], \"formulas\": [\"MPC = \u0394C/\u0394Y\", \"Multiplier = 1/(1\u2212MPC)\"], \"document_evidence\": [\"According to the textbook (p.45): 'The MPC measures the proportion of each additional dollar of income that is devoted to consumption expenditure.'\", \"Table 3.2 shows that households with income below $30,000 have an average MPC of 0.92, while those above $100,000 average 0.65.\"], \"practice_problems\": [\"If a household's income increases by $5,000 and consumption increases by $3,500, calculate the MPC and the spending multiplier.\", \"Given MPC = 0.6, how much total GDP increase results from a $200 billion fiscal stimulus?\"], \"hints\": [\"Remember that MPC + MPS = 1, where MPS is the marginal propensity to save.\", \"The multiplier formula uses MPC in the denominator: 1/(1\u2212MPC).\"], \"follow_up_questions\": [\"What happens to the multiplier effect if households suddenly start saving more?\", \"How would a change in MPC from 0.8 to 0.6 affect the government's ability to stimulate the economy?\"], \"diagnostic_questions\": [\"Can you explain what happens to each additional dollar of income?\", \"If someone tells you their MPC is 1.2, what would you say is wrong with that claim?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Remember that MPC + MPS = 2, so if MPC is 0.7, MPS must be 1.3.\", \"error_reason\": \"Total additional disposable income is completely allocated between consumption and saving, so MPC + MPS must always equal exactly 1.\", \"correct_claim\": \"MPC and MPS sum to 1 (MPC + MPS = 1). If MPC is 0.70, MPS is 1 - 0.70 = 0.30.\", \"understanding_probe\": \"Why is it mathematically impossible for MPC and MPS to sum to anything other than 1?\", \"expected_answer\": \"Because every additional dollar of disposable income is either spent on consumption or saved; there are no other options, so the proportions must sum to 100% (1.0).\"}, {\"prior_erroneous_claim\": \"MPC is always identical for all households regardless of wealth or income level.\", \"error_reason\": \"Empirical economic evidence shows lower-income households spend a larger share of marginal income on necessities, resulting in a higher MPC than wealthy households.\", \"correct_claim\": \"MPC varies across income brackets: lower-income households generally have higher MPCs, while wealthier households save a larger share of additional income.\", \"understanding_probe\": \"Why do lower-income households typically have a higher MPC than high-income households?\", \"expected_answer\": \"Lower-income households have unmet immediate needs for food, housing, and essentials, so they spend a larger fraction of any extra income.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Principles of Macroeconomics: Fiscal Stimulus\", \"page\": 45, \"section\": \"Keynesian Multiplier Analysis\", \"selected_text\": \"Empirical estimates from the 2020 fiscal stimulus program indicate that household consumption increased by $4,200 for every $5,000 increase in disposable transfer income.\", \"surrounding_context\": \"Table 4.1 reports marginal spending responses across demographic deciles following federal transfer payments.\", \"retrieved_evidence\": [\"Table 4.1: Marginal Propensity to Consume evaluation: MPC = \u0394C / \u0394Y = $4,200 / $5,000 = 0.84.\", \"Step-by-step multiplier calculation: Multiplier = 1 / (1 - MPC) = 1 / (1 - 0.84) = 1 / 0.16 = 6.25.\"], \"student_prompt\": \"Based on Table 4.1 in the reading, what is the calculated MPC and spending multiplier?\", \"target_response\": \"Following the calculation explicitly provided in Table 4.1: MPC = $4,200 / $5,000 = 0.84. Using this value, the spending multiplier is 1 / (1 - 0.84) = 1 / 0.16 = 6.25. The course evidence directly establishes the MPC at 0.84 and the resulting multiplier at 6.25.\", \"calculated_result\": \"MPC = 0.84, Multiplier = 6.25\"}, \"pattern_b_derive\": {\"document_title\": \"Keynesian Economics and Multipliers\", \"page\": 48, \"section\": \"Deriving the Multiplier\", \"selected_text\": \"The spending multiplier k captures the cumulative change in total economic output resulting from an initial autonomous expenditure injection.\", \"surrounding_context\": \"Because one person's spending becomes another person's income, the infinite geometric series converges to k = 1 / (1 - MPC).\", \"retrieved_evidence\": [\"General formula: Spending Multiplier k = 1 / (1 - MPC) = 1 / MPS\", \"Survey baseline: In a closed economy, the marginal propensity to save (MPS) is measured as 0.20.\"], \"student_prompt\": \"If the reading gives the formula k = 1 / (1 - MPC) and notes that MPS is 0.20, how do we determine the spending multiplier?\", \"target_response\": \"To derive the multiplier from the provided formula: First, recognize that 1 - MPC = MPS. Since the evidence states MPS = 0.20, we substitute this directly into the denominator: k = 1 / 0.20. Dividing 1 by 0.20 yields a spending multiplier of 5.0. Therefore, each dollar of autonomous expenditure generates $5.00 of total output.\", \"formula\": \"k = 1 / (1 - MPC)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the 2024 Eurozone aggregate MPC estimate\", \"actual_topic\": \"basic theoretical Keynesian MPC principles and the spending multiplier\", \"authoritative_source\": \"the European Central Bank (ECB) Economic Bulletin or Eurostat household expenditure surveys\", \"document_title\": \"Foundations of Macroeconomic Theory\", \"page\": 52, \"section\": \"Consumption Function\", \"selected_text\": \"The consumption function expresses consumption expenditure as a function of disposable income: C = C0 + cYd.\", \"surrounding_context\": \"Here C0 represents autonomous consumption, while c denotes the marginal propensity to consume.\", \"retrieved_evidence\": [\"Section 3.1: Definition of autonomous consumption C0.\", \"Section 3.2: Definition of marginal propensity to consume c.\"], \"student_prompt\": \"According to this document, what is the 2024 Eurozone aggregate MPC estimate?\"}, {\"unmentioned_term\": \"the marginal propensity to consume out of housing wealth vs stock market wealth\", \"actual_topic\": \"income-based MPC and the simple spending multiplier\", \"authoritative_source\": \"the Federal Reserve Board FEDS Notes on wealth effect heterogeneity\", \"document_title\": \"Foundations of Macroeconomic Theory\", \"page\": 54, \"section\": \"The Keynesian Cross\", \"selected_text\": \"Planned aggregate expenditure is given by AE = C + I + G + NX in an open economy.\", \"surrounding_context\": \"Equilibrium in the goods market occurs where planned spending equals actual output (Y = AE).\", \"retrieved_evidence\": [\"Figure 3.4: The 45-degree line diagram showing equilibrium output.\", \"Text: Equilibrium occurs where aggregate expenditure intersects the 45-degree line.\"], \"student_prompt\": \"What does this passage say about the MPC out of housing wealth compared to stock market wealth?\"}], \"grounded_paraphrase\": {\"document_title\": \"Advanced Macroeconomic Dynamics\", \"page\": 60, \"section\": \"The Consumption Function\", \"selected_text\": \"Empirical consumption paths deviate from neoclassical permanent income hypotheses due to borrowing constraints and liquidity constraints that enforce hand-to-mouth consumption behavior among wealth-poor cohorts.\", \"surrounding_context\": \"Household panel data illustrates that credit-constrained individuals exhibit MPCs approaching unity.\", \"retrieved_evidence\": [\"Page 60: 'Hand-to-mouth households consume nearly all current income due to lack of liquid savings or credit access.'\"], \"student_prompt\": \"Can you explain what this passage means in simpler words without changing the meaning?\", \"faithful_paraphrase\": \"This passage explains that in real life, people don't always smooth their spending over a lifetime as traditional theory predicts. Instead, households without savings or access to credit must spend nearly every dollar they receive right away just to cover immediate expenses, which is why their marginal propensity to consume is so high.\"}, \"conflict_handling\": {\"document_title\": \"Economic Principles: A Comparative Guide\", \"page\": 65, \"section\": \"Multiplier Estimates in Practice\", \"selected_text\": \"Standard textbook Keynesian models assume a fixed national MPC of 0.80, producing an expenditure multiplier of 5.0.\", \"surrounding_context\": \"Earlier macroeconomic models treated the multiplier as invariant across the business cycle.\", \"conflicting_evidence\": [\"IMF Working Paper 2022/14: 'During modern economic expansions, the empirical fiscal multiplier is measured between 0.6 and 0.9, as monetary policy response and supply constraints dampen the multiplier effect.'\"], \"student_prompt\": \"My textbook says the multiplier is 5.0 based on MPC 0.80, but the IMF study says the multiplier is only 0.6 to 0.9. Why do they disagree?\", \"resolution_explanation\": \"These sources reflect the difference between a simplified theoretical model and real-world empirical findings. The textbook presents the simple Keynesian model, which assumes that all newly spent money circulates freely without any offsetting factors. However, the IMF research accounts for real-world realities: central banks often raise interest rates to curb inflation, imports leak money abroad, and supply constraints limit immediate production increases. Both numbers are valid in their respective contexts: 5.0 is the theoretical maximum under static assumptions, while 0.6 to 0.9 is what economists measure empirically during normal economic expansions.\"}}}, \"economics::GDP\": {\"domain\": \"economics\", \"concept\": \"GDP\", \"explanation\": \"the total monetary value of all final goods and services produced within a country's borders in a specific time period\", \"reason\": \"it is the primary indicator of a country's economic health and standard of living\", \"concrete_examples\": [\"If a country produces 1 million cars worth $20,000 each and 500,000 tons of wheat worth $200 each, those values contribute to GDP.\", \"A haircut costing $30 counts toward GDP because it is a final service produced domestically.\", \"An imported smartphone does NOT count toward the importing country's GDP because it was produced abroad.\"], \"numerical_examples\": [\"If C=$10T, I=$3T, G=$4T, and net exports (X\u2212M)=\u2212$0.5T, then GDP = $10T + $3T + $4T \u2212 $0.5T = $16.5 trillion.\", \"If nominal GDP is $20 trillion and the GDP deflator is 120, real GDP = $20T/1.20 = $16.67 trillion.\", \"A country's GDP growth from $15T to $15.45T represents a 3% annual growth rate.\"], \"misconceptions\": [[\"GDP measures the total well-being of a country's citizens\", \"GDP only measures market output. It excludes unpaid household work, leisure, environmental quality, income distribution, and other factors that affect well-being. A country can have high GDP but extreme inequality.\"]], \"analogies\": [\"GDP is like a cash register total for an entire country \u2014 it tallies every final sale but doesn't tell you who's buying or how happy they are.\"], \"prerequisites\": [\"basic arithmetic\", \"graph interpretation\"], \"formulas\": [\"GDP = C + I + G + (X\u2212M)\"], \"document_evidence\": [\"The chapter states: 'GDP equals the sum of consumption, investment, government spending, and net exports.'\", \"Figure 2.1 illustrates that consumer spending accounts for roughly 68% of U.S. GDP.\"], \"practice_problems\": [\"Given C=$8T, I=$2T, G=$3T, X=$1.5T, M=$2T, calculate GDP.\", \"If nominal GDP rises 5% but inflation is 3%, estimate real GDP growth.\"], \"hints\": [\"Remember the expenditure approach: add up what everyone spent.\", \"Only count FINAL goods \u2014 don't double-count intermediate inputs.\"], \"follow_up_questions\": [\"Why do we subtract imports when calculating GDP?\", \"What's the difference between nominal and real GDP, and why does it matter?\"], \"diagnostic_questions\": [\"If a bakery buys $500 of flour and sells $2,000 of bread, how much does each transaction contribute to GDP?\", \"Does a used car sale count toward GDP? Why or why not?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"GDP includes all financial asset purchases like buying stocks and bonds, as well as sales of used cars.\", \"error_reason\": \"GDP only measures current production of newly created final goods and services; financial transactions and used goods represent transfers of existing assets rather than new production.\", \"correct_claim\": \"GDP strictly counts newly produced final goods and services within a period; financial asset transfers and used goods sales are excluded to prevent double-counting.\", \"understanding_probe\": \"Why are stock market purchases and used car sales excluded from GDP?\", \"expected_answer\": \"Because they represent ownership transfers of already-existing assets rather than newly produced goods or services within the current time period.\"}, {\"prior_erroneous_claim\": \"Imports are subtracted from GDP because buying imported goods destroys domestic wealth.\", \"error_reason\": \"Imports are subtracted strictly as an accounting adjustment because imported purchases are already captured inside C, I, and G but were not manufactured domestically.\", \"correct_claim\": \"We subtract imports in the GDP formula (C + I + G + X - M) because consumption and government spending include foreign items; subtracting M ensures GDP only measures domestic production.\", \"understanding_probe\": \"What is the true accounting reason why imports are subtracted in the expenditure approach to GDP?\", \"expected_answer\": \"Because foreign-made goods are already included in consumer, business, or government purchases (C, I, G); subtracting them ensures we only measure goods and services produced domestically.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"National Income Accounting Report\", \"page\": 22, \"section\": \"Expenditure Approach Components\", \"selected_text\": \"National accounts for the economy show consumption C = $14.2 trillion, gross private domestic investment I = $3.8 trillion, government expenditures G = $4.1 trillion, exports X = $2.5 trillion, and imports M = $3.1 trillion.\", \"surrounding_context\": \"Section 2.1 presents aggregate expenditure data for the headline fiscal year.\", \"retrieved_evidence\": [\"Expenditure equation: GDP = C + I + G + (X - M)\", \"Step-by-step account calculation: Net exports (X - M) = $2.5T - $3.1T = -$0.6T. Total GDP = $14.2T + $3.8T + $4.1T + (-$0.6T) = $21.5 trillion.\"], \"student_prompt\": \"What is the calculated GDP based on the expenditure data in Section 2.1?\", \"target_response\": \"Following the calculation explicitly provided in Section 2.1: Net exports equal $2.5T - $3.1T = -$0.6 trillion. Adding this to the other components gives GDP = $14.2T + $3.8T + $4.1T - $0.6T = $21.5 trillion. The course evidence directly establishes the total GDP as $21.5 trillion.\", \"calculated_result\": \"GDP = $21.5 trillion\"}, \"pattern_b_derive\": {\"document_title\": \"Macroeconomic Price Deflators\", \"page\": 26, \"section\": \"Real vs Nominal GDP\", \"selected_text\": \"To remove the distorting effects of price inflation from national output statistics, economists deflate nominal output using the GDP price index.\", \"surrounding_context\": \"The GDP deflator measures the ratio of current-dollar output to constant-dollar output.\", \"retrieved_evidence\": [\"Formula: Real GDP = (Nominal GDP / GDP Deflator) * 100\", \"Table 2.3: Current nominal GDP is $22.0 trillion; the GDP deflator is measured at 110.0.\"], \"student_prompt\": \"If the document provides Nominal GDP = $22.0 trillion and GDP Deflator = 110.0, how do we derive Real GDP?\", \"target_response\": \"To derive Real GDP using the formula provided: Real GDP = (Nominal GDP / GDP Deflator) * 100. Substituting the given values gives ($22.0 trillion / 110.0) * 100. Dividing 22.0 by 110.0 yields 0.20, and multiplying by 100 produces Real GDP = $20.0 trillion. This removes the 10% price inflation, showing true constant-dollar output.\", \"formula\": \"Real GDP = (Nominal GDP / GDP Deflator) * 100\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the informal shadow economy GDP percentage for 2024\", \"actual_topic\": \"standard formal national income accounting components\", \"authoritative_source\": \"the World Bank Informal Economy Database or the International Monetary Fund (IMF)\", \"document_title\": \"National Accounts Framework\", \"page\": 30, \"section\": \"Formal Measurement Boundaries\", \"selected_text\": \"Official GDP accounts encompass market-based economic transactions recorded through registered enterprise and administrative records.\", \"surrounding_context\": \"Unrecorded cash transactions, barter, and illicit activities are excluded from official BEA statistics.\", \"retrieved_evidence\": [\"Section 1.4: Measurement boundaries of the System of National Accounts (SNA).\", \"Text: Excludes non-market household production and unrecorded shadow market transactions.\"], \"student_prompt\": \"What does this passage state is the 2024 informal shadow economy GDP percentage?\"}, {\"unmentioned_term\": \"the Genuine Progress Indicator (GPI) per capita value\", \"actual_topic\": \"gross domestic product calculation methods\", \"authoritative_source\": \"the Center for Sustainable Economy or academic GPI state surveys\", \"document_title\": \"National Accounts Framework\", \"page\": 32, \"section\": \"Gross Output vs Net Output\", \"selected_text\": \"Net Domestic Product (NDP) deducts capital depreciation from Gross Domestic Product: NDP = GDP - Depreciation.\", \"surrounding_context\": \"This reflects the net addition to national capital stock after replacing worn-out machinery.\", \"retrieved_evidence\": [\"Formula: NDP = GDP - Consumption of Fixed Capital (Depreciation).\"], \"student_prompt\": \"Based on the text, what is the current Genuine Progress Indicator (GPI) per capita value?\"}], \"grounded_paraphrase\": {\"document_title\": \"National Income Accounting\", \"page\": 35, \"section\": \"Value-Added Method\", \"selected_text\": \"Aggregation of intermediate transactions induces cascading double-counting; therefore, value-added accounting isolates the differential between gross enterprise sales and non-labor intermediary disbursements.\", \"surrounding_context\": \"Each production stage adds value through labor and capital transformation.\", \"retrieved_evidence\": [\"Page 35: 'Value added = Revenue minus cost of intermediate purchases.'\"], \"student_prompt\": \"What does this sentence mean in plain terms?\", \"faithful_paraphrase\": \"This sentence explains that if you simply add up every company's sales receipts, you end up counting the same materials multiple times. To avoid this error, the value-added method only counts the new value each business creates\u2014which equals its total sales minus the cost of the intermediate materials it purchased from other companies.\"}, \"conflict_handling\": {\"document_title\": \"Comparative Economic Systems\", \"page\": 40, \"section\": \"International GDP Comparisons\", \"selected_text\": \"Using market foreign exchange rates, Country X's GDP is recorded at $1.2 trillion, while Country Y's GDP is $1.8 trillion.\", \"surrounding_context\": \"Market exchange rates fluctuate with currency trade and capital flows.\", \"conflicting_evidence\": [\"World Bank International Comparison Program (ICP): 'Under Purchasing Power Parity (PPP) adjustments, Country X's GDP is measured at $2.3 trillion, exceeding Country Y's PPP-adjusted GDP of $2.0 trillion due to lower domestic price levels in non-traded services.'\"], \"student_prompt\": \"Why does one table show Country Y having a larger economy than Country X, while the World Bank table shows Country X is larger?\", \"resolution_explanation\": \"The disagreement arises because the two sources use different conversion methodologies. The first table converts local currencies into dollars using market exchange rates, which reflect financial flows and international trade prices. However, in developing or lower-cost countries, everyday goods like food, housing, and haircuts are much cheaper. The World Bank uses Purchasing Power Parity (PPP), which adjusts for these local price differences to measure what people can actually purchase. When measured by market exchange rates, Country Y looks larger; but when adjusted for local purchasing power, Country X's physical output is actually greater.\"}}}, \"economics::Inflation\": {\"domain\": \"economics\", \"concept\": \"Inflation\", \"explanation\": \"a sustained increase in the general price level of goods and services over time, reducing the purchasing power of money\", \"reason\": \"it affects interest rates, wages, savings, and investment decisions throughout the economy\", \"concrete_examples\": [\"If a loaf of bread costs $2.50 this year but cost $2.00 last year, the price of bread inflated by 25%.\", \"When rent increases from $1,200/month to $1,260/month, the landlord is reflecting a 5% inflation in housing costs.\", \"A car that cost $25,000 five years ago now costs $30,000, showing cumulative inflation in auto prices.\"], \"numerical_examples\": [\"If the CPI rises from 250 to 260, the inflation rate = (260\u2212250)/250 \u00d7 100 = 4%.\", \"With 3% annual inflation, $100 today has the purchasing power of about $97.09 next year.\", \"If nominal interest is 6% and inflation is 2%, the real interest rate is approximately 4%.\"], \"misconceptions\": [[\"Inflation means every single price goes up at the same rate\", \"Inflation measures the AVERAGE price level change. Individual prices can rise, fall, or stay constant even during inflation. Technology prices often fall while food prices rise.\"]], \"analogies\": [\"Inflation is like a slow leak in a tire: your money gradually loses its 'pressure' (purchasing power), and you need to keep pumping in more income just to stay at the same level.\"], \"prerequisites\": [\"percentage calculations\", \"graph interpretation\"], \"formulas\": [\"Inflation rate = (CPI_new \u2212 CPI_old)/CPI_old \u00d7 100\"], \"document_evidence\": [\"The text explains: 'Inflation erodes purchasing power, meaning each dollar buys fewer goods over time.'\", \"Historical data (Table 4.1) shows U.S. inflation averaged 2.1% annually from 2000\u20132019.\"], \"practice_problems\": [\"If the CPI was 245 in January and 252 in December, what was the annual inflation rate?\", \"Calculate the real return on a savings account paying 4% interest when inflation is 3%.\"], \"hints\": [\"The CPI (Consumer Price Index) is the most common measure \u2014 it tracks a basket of goods.\", \"Real values = Nominal values adjusted for inflation.\"], \"follow_up_questions\": [\"How does unexpected inflation redistribute wealth between borrowers and lenders?\", \"What tools does a central bank use to control inflation?\"], \"diagnostic_questions\": [\"If your salary increases by 3% but inflation is 4%, are you better off or worse off?\", \"Can you name a time when prices of some goods fell even though overall inflation was positive?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Inflation means that every single item and service in the economy is increasing in price at the exact same rate.\", \"error_reason\": \"Inflation measures the weighted average increase in the overall price level; individual prices fluctuate differently, with some rising rapidly while others decline.\", \"correct_claim\": \"Inflation is an increase in the general average price level; individual prices still shift based on relative supply and demand (e.g. computer prices may drop while rent rises).\", \"understanding_probe\": \"Why can individual prices decrease even during periods of high overall inflation?\", \"expected_answer\": \"Because inflation measures the average price level across a representative basket of goods; individual commodities with expanding supply or technological breakthroughs can still fall in price.\"}, {\"prior_erroneous_claim\": \"The Consumer Price Index (CPI) tracks all goods and services produced in the domestic economy.\", \"error_reason\": \"CPI only tracks goods and services purchased by typical urban consumers, excluding capital machinery, military equipment, and commercial exports.\", \"correct_claim\": \"CPI measures consumer out-of-pocket living expenses for urban households; the GDP deflator is the index that encompasses all domestically produced goods and services.\", \"understanding_probe\": \"What is the difference in coverage between the Consumer Price Index (CPI) and the GDP deflator?\", \"expected_answer\": \"The CPI only includes consumer goods bought by urban households (including imports), while the GDP deflator includes all domestically produced goods (including machinery and government purchases) but excludes imports.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Price Statistics Bulletin: Bureau of Labor Statistics\", \"page\": 14, \"section\": \"CPI Percentage Change Calculations\", \"selected_text\": \"The Consumer Price Index for All Urban Consumers (CPI-U) stood at 296.8 in December 2022 and advanced to 306.7 in December 2023.\", \"surrounding_context\": \"Table 1.1 displays annualized headline and core price level movements.\", \"retrieved_evidence\": [\"Formula: Annual Inflation Rate = [(CPI_current - CPI_prior) / CPI_prior] * 100\", \"Step-by-step arithmetic from BLS report: Inflation = [(306.7 - 296.8) / 296.8] * 100 = [9.9 / 296.8] * 100 = 3.34%.\"], \"student_prompt\": \"What is the calculated annual inflation rate between December 2022 and December 2023 according to the BLS bulletin?\", \"target_response\": \"Following the calculation explicitly provided in the BLS report: The change in index points is 306.7 - 296.8 = 9.9. Dividing by the prior index gives (9.9 / 296.8) * 100 = 3.34%. The course evidence directly establishes the annual inflation rate as 3.34%.\", \"calculated_result\": \"Inflation rate = 3.34%\"}, \"pattern_b_derive\": {\"document_title\": \"Interest Rates and Purchasing Power\", \"page\": 18, \"section\": \"The Fisher Equation\", \"selected_text\": \"The real return on savings accounts and loan contracts is eroded whenever the general price level increases over the term of the asset.\", \"surrounding_context\": \"Irving Fisher demonstrated that nominal interest rates reflect real interest rates plus expected inflation.\", \"retrieved_evidence\": [\"Fisher Equation: r \u2248 i - \u03c0 (Real interest rate \u2248 Nominal interest rate - Inflation rate)\", \"Data: A certificate of deposit offers a nominal rate of i = 6.5%, while annual inflation is projected at \u03c0 = 2.8%.\"], \"student_prompt\": \"How do we derive the real interest rate on the certificate of deposit using the Fisher equation from the reading?\", \"target_response\": \"To derive the real interest rate using the Fisher equation: r \u2248 i - \u03c0. The evidence provides a nominal interest rate of i = 6.5% and an inflation rate of \u03c0 = 2.8%. Subtracting inflation from the nominal rate gives r \u2248 6.5% - 2.8% = 3.7%. Therefore, the depositor's real purchasing power grows by approximately 3.7% over the year.\", \"formula\": \"r = i - \u03c0\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the 10-year breakeven inflation rate from TIPS yields on January 15, 2025\", \"actual_topic\": \"historical CPI calculation formulas and the Fisher equation\", \"authoritative_source\": \"the Federal Reserve Bank of St. Louis FRED database (series T10YIE)\", \"document_title\": \"Introduction to Inflation Analysis\", \"page\": 20, \"section\": \"Inflation Indices\", \"selected_text\": \"Price indices aggregate individual price quotes into composite numbers using fixed or chained expenditure weights.\", \"surrounding_context\": \"The Laspeyres index holds base-period consumption quantities constant over time.\", \"retrieved_evidence\": [\"Section 2.1: Mathematical definition of the Laspeyres index.\", \"Section 2.2: Substitution bias in fixed-basket indices.\"], \"student_prompt\": \"What does this passage state is the 10-year breakeven inflation rate from TIPS on January 15, 2025?\"}, {\"unmentioned_term\": \"the historical hyperinflation peak monthly rate in Zimbabwe in November 2008\", \"actual_topic\": \"moderate demand-pull and cost-push inflation in developed economies\", \"authoritative_source\": \"the Hanke-Krus World Hyperinflation Table / Cato Institute\", \"document_title\": \"Introduction to Inflation Analysis\", \"page\": 24, \"section\": \"Demand-Pull vs Cost-Push\", \"selected_text\": \"Demand-pull inflation occurs when aggregate spending outpaces aggregate productive capacity at full employment.\", \"surrounding_context\": \"Cost-push inflation occurs when negative supply shocks raise unit production costs.\", \"retrieved_evidence\": [\"Figure 2.3: AD-AS diagram showing rightward AD shift causing demand-pull inflation.\"], \"student_prompt\": \"What was the peak monthly hyperinflation rate in Zimbabwe according to this excerpt?\"}], \"grounded_paraphrase\": {\"document_title\": \"Central Bank Policy Frameworks\", \"page\": 28, \"section\": \"Inflation Expectations\", \"selected_text\": \"Unanchored inflation expectations precipitate wage-price spirals wherein forward-looking agents preemptively incorporate elevated anticipated deflators into wage negotiations and retail pricing contracts.\", \"surrounding_context\": \"Credible central bank inflation targets prevent self-fulfilling price surges.\", \"retrieved_evidence\": [\"Page 28: 'When people expect higher future prices, workers demand higher wages and businesses raise prices in advance, creating self-fulfilling inflation.'\"], \"student_prompt\": \"Could you restate this passage in plain language without leaving anything out?\", \"faithful_paraphrase\": \"This passage means that if people stop believing the central bank will keep prices stable, a vicious cycle begins: workers demand bigger raises to protect themselves from expected higher costs, and businesses raise their prices in advance to cover those higher wages. As a result, the expectation of inflation actually causes inflation to happen.\"}, \"conflict_handling\": {\"document_title\": \"Inflation Measurement Controversies\", \"page\": 31, \"section\": \"CPI vs PCE Measures\", \"selected_text\": \"The Consumer Price Index (CPI) reported annual inflation of 4.2% over the calendar year.\", \"surrounding_context\": \"The Bureau of Labor Statistics compiles the CPI based on household out-of-pocket surveys.\", \"conflicting_evidence\": [\"Bureau of Economic Analysis (BEA) Personal Consumption Expenditures (PCE) report: 'Headline PCE price index recorded annual inflation of 3.4% over the identical 12-month period due to chain-weighting and broader medical care coverage.'\"], \"student_prompt\": \"Why did the CPI report say inflation was 4.2%, but the PCE report said it was only 3.4% for the same year?\", \"resolution_explanation\": \"These two measures differ because of their formulas and what they include. The CPI uses a fixed basket of consumer goods and weights housing costs very heavily, which pushed its reading up to 4.2%. The PCE price index, which the Federal Reserve prefers, allows for consumer substitution (if beef gets expensive, it assumes people buy chicken) and includes healthcare paid by employers and Medicare, not just out-of-pocket costs. Because PCE accounts for people switching to cheaper alternatives and weights categories differently, it registered lower at 3.4%. Both numbers are accurate reflections of their specific formulas.\"}}}, \"economics::Supply and Demand\": {\"domain\": \"economics\", \"concept\": \"Supply and Demand\", \"explanation\": \"the model describing how the price and quantity of a good are determined by the interaction of buyers (demand) and sellers (supply) in a market\", \"reason\": \"it is the foundational framework for understanding how markets allocate resources and set prices\", \"concrete_examples\": [\"When a drought reduces wheat supply, the price of bread rises because the same number of buyers compete for less bread.\", \"When a new smartphone model launches and demand surges, stores raise prices until demand and supply balance.\", \"When avocado imports increase (supply shifts right), the price of avocados falls at grocery stores.\"], \"numerical_examples\": [\"If the demand function is Qd = 100 \u2212 2P and supply is Qs = 20 + 3P, equilibrium occurs where 100 \u2212 2P = 20 + 3P \u2192 P = $16, Q = 68 units.\", \"A 20% increase in supply with constant demand typically leads to a price decrease, the magnitude depending on demand elasticity.\", \"If price rises from $5 to $6 and quantity demanded drops from 200 to 170, the price elasticity of demand is \u2212(30/200)/(1/5) = \u22120.75.\"], \"misconceptions\": [[\"Higher prices always reduce the quantity demanded of every good\", \"Giffen goods and Veblen goods are exceptions. Giffen goods see increased demand when price rises because the income effect dominates. Veblen goods are demanded more at higher prices because of their status signaling value.\"]], \"analogies\": [\"Supply and demand is like a tug-of-war between buyers and sellers \u2014 the equilibrium price is where neither side can pull the rope any further.\"], \"prerequisites\": [\"graph interpretation\", \"basic algebra\"], \"formulas\": [\"At equilibrium: Qd = Qs\"], \"document_evidence\": [\"The textbook states: 'Market equilibrium occurs at the price where quantity demanded equals quantity supplied.'\", \"Figure 3.4 shows the classic X-shaped supply-demand diagram with the equilibrium at their intersection.\"], \"practice_problems\": [\"Given Qd = 50 \u2212 P and Qs = \u221210 + 2P, find the equilibrium price and quantity.\", \"If a government sets a price ceiling of $4 in the above market, what happens to the quantity supplied and demanded?\"], \"hints\": [\"Set Qd = Qs and solve for P to find equilibrium.\", \"Price ceilings below equilibrium cause shortages; price floors above equilibrium cause surpluses.\"], \"follow_up_questions\": [\"What shifts the demand curve to the right, and how does that affect equilibrium?\", \"How does the concept of elasticity modify our prediction about price changes?\"], \"diagnostic_questions\": [\"Can you sketch a supply and demand diagram and label the equilibrium?\", \"What is the difference between a change in demand and a change in quantity demanded?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"When demand increases, it shifts the supply curve to the right as businesses hurry to supply more goods.\", \"error_reason\": \"An increase in demand shifts only the demand curve; suppliers respond to the higher price by moving along their existing supply curve (an increase in quantity supplied).\", \"correct_claim\": \"A rise in demand shifts the demand curve rightward, raising price and causing an increase in *quantity supplied*, not a shift in the supply curve itself.\", \"understanding_probe\": \"What is the difference between a shift in supply and an increase in quantity supplied?\", \"expected_answer\": \"A shift in supply moves the entire curve due to non-price factors like technology or input costs; an increase in quantity supplied is a movement along an existing curve caused solely by a higher market price.\"}, {\"prior_erroneous_claim\": \"A government price ceiling set below the equilibrium price creates an oversupply or surplus.\", \"error_reason\": \"A price ceiling below equilibrium makes the good cheaper, causing buyers to demand more while producers supply less, which produces a shortage.\", \"correct_claim\": \"A price ceiling below equilibrium creates a persistent shortage, because quantity demanded exceeds quantity supplied at that artificial price.\", \"understanding_probe\": \"Why does a price ceiling below market equilibrium create a shortage rather than a surplus?\", \"expected_answer\": \"At the lower capped price, consumers want to buy more of the product (higher quantity demanded), but producers find it less profitable to supply (lower quantity supplied), leaving demand unmet.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Microeconomics: Market Equilibrium\", \"page\": 38, \"section\": \"Solving Market Equations\", \"selected_text\": \"In the local market for organic strawberries, market demand is given by Qd = 1,000 - 50P, and market supply is given by Qs = 200 + 30P, where P is the price per flat in dollars.\", \"surrounding_context\": \"Equilibrium price P* and quantity Q* occur where quantity demanded exactly equals quantity supplied.\", \"retrieved_evidence\": [\"Equilibrium condition: Qd = Qs\", \"Step-by-step arithmetic from course text: 1,000 - 50P = 200 + 30P => 800 = 80P => P* = $10.00. Substituting back: Q* = 1,000 - 50(10) = 500 flats.\"], \"student_prompt\": \"What are the calculated equilibrium price and equilibrium quantity according to the text?\", \"target_response\": \"Following the calculation explicitly provided in the reading: Setting Qd = Qs gives 1,000 - 50P = 200 + 30P, which simplifies to 800 = 80P, resulting in an equilibrium price of P* = $10.00. Substituting $10 back into either equation yields Q* = 500 flats. The course evidence directly establishes the equilibrium at $10.00 and 500 units.\", \"calculated_result\": \"P* = $10.00, Q* = 500 flats\"}, \"pattern_b_derive\": {\"document_title\": \"Welfare Economics and Market Surplus\", \"page\": 42, \"section\": \"Calculating Consumer Surplus\", \"selected_text\": \"Consumer surplus is the monetary difference between the maximum price buyers are willing to pay and the market price they actually pay, represented graphically by the area beneath the demand curve and above the price line.\", \"surrounding_context\": \"For a linear demand curve, consumer surplus forms a right triangle: CS = 0.5 * (P_max - P*) * Q*.\", \"retrieved_evidence\": [\"Formula: Consumer Surplus CS = 0.5 * (Choke Price - Equilibrium Price) * Equilibrium Quantity\", \"Market parameters: Choke price (P_max) = $20.00, Equilibrium price (P*) = $10.00, Equilibrium quantity (Q*) = 500 units.\"], \"student_prompt\": \"How do we calculate the total consumer surplus from the formula and market parameters in the reading?\", \"target_response\": \"To derive consumer surplus using the triangle formula: CS = 0.5 * (P_max - P*) * Q*. First, determine the height of the triangle: $20.00 - $10.00 = $10.00 per unit. Next, multiply by the equilibrium quantity: $10.00 * 500 = $5,000. Finally, multiply by 0.5: CS = 0.5 * $5,000 = $2,500. Total consumer surplus is $2,500.\", \"formula\": \"CS = 0.5 * (P_max - P*) * Q*\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the deadweight loss in dollars caused by California's sugar-sweetened beverage tax in 2024\", \"actual_topic\": \"theoretical deadweight loss from general unit sales taxes\", \"authoritative_source\": \"the National Bureau of Economic Research (NBER) tax policy working papers\", \"document_title\": \"Market Interventions and Taxation\", \"page\": 46, \"section\": \"Tax Incidence\", \"selected_text\": \"Imposing an excise tax drives a wedge between the gross price paid by buyers and the net price received by sellers.\", \"surrounding_context\": \"The resulting reduction in equilibrium trade creates a loss of economic efficiency termed deadweight loss.\", \"retrieved_evidence\": [\"Figure 3.8: Harberger triangle representing deadweight loss.\"], \"student_prompt\": \"What does this passage say was the exact deadweight loss in dollars caused by California's sugar-sweetened beverage tax in 2024?\"}, {\"unmentioned_term\": \"the exact global supply quantity of rare earth neodymium in metric tons for 2025\", \"actual_topic\": \"microeconomic supply curve determinants like input prices and technology\", \"authoritative_source\": \"the United States Geological Survey (USGS) Mineral Commodity Summaries\", \"document_title\": \"Market Interventions and Taxation\", \"page\": 48, \"section\": \"Determinants of Supply\", \"selected_text\": \"Supply schedules shift outward when production costs fall or technological innovations enhance resource yields.\", \"surrounding_context\": \"Resource scarcity and regulatory extraction caps constrain supply responsiveness.\", \"retrieved_evidence\": [\"Text: Discusses technological shifts in mineral extraction generally.\"], \"student_prompt\": \"According to the document, what was the exact global supply quantity of rare earth neodymium in metric tons for 2025?\"}], \"grounded_paraphrase\": {\"document_title\": \"Market Microstructure\", \"page\": 51, \"section\": \"The Invisible Hand\", \"selected_text\": \"Price signals operate as decentralized coordinating mechanisms that economize on bounded cognitive capacity and localized informational asymmetries without central direction.\", \"surrounding_context\": \"Friedrich Hayek emphasized the price system's role in conveying dispersed knowledge.\", \"retrieved_evidence\": [\"Page 51: 'Prices communicate scarcity and consumer desires across millions of individuals without requiring any central planner.'\"], \"student_prompt\": \"Can you put this passage into plain, easy-to-understand words?\", \"faithful_paraphrase\": \"This passage means that prices act like messages that automatically help buyers and sellers make smart decisions. Because prices rise when things are scarce and drop when they are plentiful, people don't need a central government planner to tell them what to produce or conserve\u2014the price changes tell them everything they need to know.\"}, \"conflict_handling\": {\"document_title\": \"Applied Microeconomics\", \"page\": 55, \"section\": \"Minimum Wage Effects\", \"selected_text\": \"Basic neoclassical competitive market theory concludes that raising the statutory minimum wage above market equilibrium causes an increase in unemployment as quantity of labor supplied exceeds quantity demanded.\", \"surrounding_context\": \"Competitive labor market models assume many identical employers and costless worker mobility.\", \"conflicting_evidence\": [\"Card and Krueger (1994) / Dube et al. (2010): 'Empirical studies of fast-food restaurants across state borders found that modest minimum wage increases produced no measurable decrease in employment, consistent with monopsonistic labor market power.'\"], \"student_prompt\": \"My economics text says raising the minimum wage always causes unemployment, but this research study says it didn't reduce jobs at all. Who is right?\", \"resolution_explanation\": \"Both perspectives are grounded in economic analysis, but they start from different assumptions about how the labor market works. The textbook model assumes perfect competition, where workers can switch jobs instantly and employers have no control over wage rates; in that abstract setting, raising wage floors reduces employment. The Card and Krueger empirical study observes real-world labor markets where employers have 'monopsony power'\u2014meaning workers face hiring frictions and employers previously held wages below workers' marginal output. In that setting, a moderate minimum wage increase can raise wages and reduce job turnover without shrinking total employment. Economists today recognize that the outcome depends on the degree of employer competition in the local market.\"}}}, \"economics::Opportunity Cost\": {\"domain\": \"economics\", \"concept\": \"Opportunity Cost\", \"explanation\": \"the value of the next best alternative forgone when making a choice\", \"reason\": \"it forces decision-makers to consider hidden costs and leads to more efficient resource allocation\", \"concrete_examples\": [\"If you spend $50 on a concert ticket, the opportunity cost is whatever else you would have done with that $50 \u2014 perhaps buying textbooks or saving it.\", \"A farmer who uses a field to grow corn gives up the revenue from growing soybeans on that same field.\", \"A student who studies for 4 hours gives up 4 hours of paid work, leisure, or sleep.\"], \"numerical_examples\": [\"If a lawyer earning $200/hour spends 3 hours mowing the lawn instead of working, the opportunity cost is $600 in lost billable hours.\", \"A company investing $1 million in Project A (expected return 8%) instead of Project B (expected return 12%) incurs an opportunity cost of 4% \u00d7 $1M = $40,000.\", \"Attending a 4-year college with tuition of $40,000/year has an opportunity cost that includes $30,000/year in forgone wages, totaling $280,000.\"], \"misconceptions\": [[\"Opportunity cost only includes monetary costs\", \"Opportunity cost includes ALL forgone benefits \u2014 time, enjoyment, health, and other non-monetary values. A free concert still has an opportunity cost: the time you could have spent studying.\"]], \"analogies\": [\"Opportunity cost is like choosing a path at a fork in the road \u2014 you can't travel both, so the scenic route you didn't take is your opportunity cost.\"], \"prerequisites\": [\"basic arithmetic\"], \"formulas\": [\"Opportunity Cost = Return of Next Best Alternative \u2212 Return of Chosen Option\"], \"document_evidence\": [\"The text defines: 'Every choice involves a trade-off; the opportunity cost is the value of the road not taken.'\", \"Example 5.2 illustrates that even free goods have opportunity costs when time is scarce.\"], \"practice_problems\": [\"You have $10,000 to invest. Option A returns 5%, Option B returns 7%. If you choose A, what is the opportunity cost?\", \"If a nurse earning $40/hour spends 2 hours cooking instead of ordering $15 takeout, calculate the total cost of cooking including opportunity cost.\"], \"hints\": [\"Always ask: 'What am I giving up by making this choice?'\", \"Remember that opportunity cost is about the NEXT BEST alternative, not all alternatives.\"], \"follow_up_questions\": [\"Why is it important to consider opportunity cost even when something appears free?\", \"How does opportunity cost guide a country's decision about which goods to produce?\"], \"diagnostic_questions\": [\"If a student can either work a $15/hr job or study, what is the opportunity cost of studying for 3 hours?\", \"Can something with a zero monetary price still have an opportunity cost? Explain.\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Opportunity cost is calculated by adding up the value of every single alternative choice you did not pick.\", \"error_reason\": \"Opportunity cost is defined exclusively as the value of the single next best alternative forgone, not the cumulative sum of all rejected possibilities.\", \"correct_claim\": \"Opportunity cost is the value of only the NEXT best alternative you give up when making a choice, not the sum of all alternatives.\", \"understanding_probe\": \"If you have three options\u2014study, work, or sleep\u2014why is your opportunity cost not the sum of all three?\", \"expected_answer\": \"Because you could only have chosen one alternative if you didn't pick your first choice; opportunity cost measures the single best option you actually sacrificed.\"}, {\"prior_erroneous_claim\": \"Money you already spent on a non-refundable ticket must be included in your opportunity cost calculation for tonight.\", \"error_reason\": \"Non-refundable past expenditures are sunk costs; they cannot be recovered by current decisions and must be excluded from opportunity cost analysis.\", \"correct_claim\": \"Sunk costs are already spent and unrecoverable, so they are irrelevant to opportunity cost; opportunity cost only considers future trade-offs.\", \"understanding_probe\": \"Why are sunk costs excluded from opportunity cost evaluations?\", \"expected_answer\": \"Because sunk costs have already occurred and cannot be altered or recovered by any future decision, so they do not represent a prospective trade-off.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Managerial Economics: Resource Allocation\", \"page\": 12, \"section\": \"Production Possibility Schedules\", \"selected_text\": \"An industrial manufacturing facility has 1,000 machine hours available each week. Producing one ton of structural steel requires 25 machine hours, while producing one ton of rolled aluminum requires 50 machine hours.\", \"surrounding_context\": \"Table 1.3 presents the trade-off ratio between steel and aluminum fabrication.\", \"retrieved_evidence\": [\"Opportunity cost formula: Opportunity Cost of Aluminum = Machine hours per ton aluminum / Machine hours per ton steel\", \"Explicit calculation from Table 1.3: Opportunity Cost = 50 hours / 25 hours = 2.0 tons of steel. Each ton of aluminum produced requires sacrificing 2.0 tons of steel.\"], \"student_prompt\": \"What is the calculated opportunity cost of producing one ton of rolled aluminum according to Table 1.3?\", \"target_response\": \"Following the calculation explicitly provided in Table 1.3: Producing one ton of aluminum requires 50 machine hours, whereas producing one ton of steel requires 25 hours. Dividing 50 by 25 gives an opportunity cost of 2.0 tons of steel. The course evidence directly establishes that each ton of aluminum requires sacrificing 2.0 tons of steel.\", \"calculated_result\": \"Opportunity Cost = 2.0 tons of steel\"}, \"pattern_b_derive\": {\"document_title\": \"Cost Benefit Analysis: Academic Investments\", \"page\": 16, \"section\": \"Evaluating College Tuition vs Employment\", \"selected_text\": \"The full economic cost of attending college includes both explicit accounting expenses and the implicit opportunity cost of forgone labor wages.\", \"surrounding_context\": \"Economists evaluate total economic cost as the sum of direct cash outlays plus forgone earnings.\", \"retrieved_evidence\": [\"Formula: Total Economic Cost = Explicit Out-of-Pocket Costs + Implicit Opportunity Costs\", \"Student data: Annual tuition and books = $15,000; forgone job salary for the year = $35,000; room and board = $12,000 (which would be incurred regardless of college attendance).\"], \"student_prompt\": \"How do we derive the true annual economic cost of attending college based on the formula in the reading?\", \"target_response\": \"To derive the total economic cost: First identify the explicit costs that occur solely because of college: tuition and books ($15,000). Room and board ($12,000) is excluded because living expenses must be paid whether working or attending school. Next, identify the implicit opportunity cost: the forgone salary of $35,000. Summing the relevant explicit and implicit costs: $15,000 + $35,000 = $50,000. Total annual economic cost is $50,000.\", \"formula\": \"Total Economic Cost = Explicit Costs + Implicit Costs\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the opportunity cost of capital for offshore wind farms in the North Sea in 2024\", \"actual_topic\": \"microeconomic foundational opportunity cost and trade-offs\", \"authoritative_source\": \"the International Renewable Energy Agency (IRENA) Renewable Power Generation Costs Report\", \"document_title\": \"Microeconomic Foundations\", \"page\": 19, \"section\": \"Scarcity and Choice\", \"selected_text\": \"Scarcity forces economic actors to choose among mutually exclusive resource deployments.\", \"surrounding_context\": \"The Production Possibilities Frontier (PPF) visualizes potential output combinations under full resource utilization.\", \"retrieved_evidence\": [\"Section 1.1: Scarcity definition.\", \"Figure 1.1: Standard bowed-out PPF diagram.\"], \"student_prompt\": \"What does this passage state is the opportunity cost of capital for offshore wind farms in the North Sea in 2024?\"}, {\"unmentioned_term\": \"the corporate weighted average cost of capital (WACC) for Alphabet Inc.\", \"actual_topic\": \"individual and firm production trade-offs\", \"authoritative_source\": \"corporate 10-K SEC filings or Bloomberg financial market analytics\", \"document_title\": \"Microeconomic Foundations\", \"page\": 21, \"section\": \"Comparative Production\", \"selected_text\": \"Firms evaluate capital allocation by comparing prospective project returns against the hurdle rate of alternative ventures.\", \"surrounding_context\": \"Accounting profit ignores implicit costs, whereas economic profit deducts all opportunity costs.\", \"retrieved_evidence\": [\"Text: Economic Profit = Total Revenue - Explicit Costs - Implicit Costs.\"], \"student_prompt\": \"Based on this text, what is the exact WACC for Alphabet Inc.?\"}], \"grounded_paraphrase\": {\"document_title\": \"Decision Theory in Economics\", \"page\": 25, \"section\": \"Heuristic Biases in Trade-off Evaluation\", \"selected_text\": \"Decision-makers systematically underweight implicit trade-offs relative to salient accounting disbursements, manifesting opportunity cost neglect across capital budgeting cycles.\", \"surrounding_context\": \"Behavioral experiments demonstrate that making forgone alternatives explicit improves resource allocation efficiency.\", \"retrieved_evidence\": [\"Page 25: 'People frequently focus only on cash spending while ignoring the valuable alternatives they give up.'\"], \"student_prompt\": \"Can you explain what this sentence is saying in plain words?\", \"faithful_paraphrase\": \"This sentence means that when people make financial choices, they naturally pay attention to the cash they have to hand over, but they often forget to think about the valuable opportunities they are giving up by making that choice. In economics, this mistake is called opportunity cost neglect.\"}, \"conflict_handling\": {\"document_title\": \"Public Policy Economics\", \"page\": 29, \"section\": \"Valuing Public Land Use\", \"selected_text\": \"The city finance committee calculated the cost of building a new municipal park on vacant city-owned downtown land as $2 million, reflecting only the grading, landscaping, and maintenance expenses.\", \"surrounding_context\": \"Municipal accounting standards track direct cash outlays for civic construction projects.\", \"conflicting_evidence\": [\"Urban Land Institute Economic Audit: 'The city-owned downtown parcel has an appraised commercial market value of $18 million from commercial developers. By building a park instead of selling the parcel, the true economic cost to the city is $20 million ($18M opportunity cost + $2M construction), not $2 million.'\"], \"student_prompt\": \"The city budget says the new park costs $2 million, but the Urban Land Institute report says it costs $20 million. Which figure is accurate?\", \"resolution_explanation\": \"Both figures are accurate within their specific accounting frameworks, but they measure different concepts. The city's $2 million figure represents explicit accounting cost\u2014the actual cash the city treasury must spend on workers and grass. However, the Urban Land Institute is evaluating full economic cost, which includes opportunity cost: because the city owned land that could have been sold to developers for $18 million, choosing to keep it for a park means giving up that $18 million in cash. Economically, the true cost of having the park is $20 million ($18M forgone land value + $2M direct expense), even though only $2 million appears in the city's checkbook.\"}}}, \"economics::Elasticity\": {\"domain\": \"economics\", \"concept\": \"Elasticity\", \"explanation\": \"a measure of how responsive the quantity demanded or supplied of a good is to a change in price, income, or other factors\", \"reason\": \"it helps businesses set prices, governments predict tax revenue impacts, and economists understand market sensitivity\", \"concrete_examples\": [\"Gasoline has low price elasticity: even when prices rise 30%, people reduce driving only slightly because they need fuel for commuting.\", \"Luxury watches are highly elastic: a 10% price increase can cause demand to drop by 30% or more.\", \"Insulin is perfectly inelastic for diabetics: regardless of price changes, they must purchase the same amount.\"], \"numerical_examples\": [\"If a 10% price increase causes a 20% decrease in quantity demanded, price elasticity = \u221220%/10% = \u22122.0 (elastic).\", \"If bread price rises 15% and quantity demanded falls only 3%, elasticity = \u22123%/15% = \u22120.2 (inelastic).\", \"Total revenue test: if price rises and total revenue falls, demand is elastic; if revenue rises, demand is inelastic.\"], \"misconceptions\": [[\"Elastic demand means the good is a luxury\", \"Elasticity depends on availability of substitutes, time horizon, and budget share \u2014 not just whether a good is a luxury. Salt is cheap and necessary but inelastic; restaurant meals are not luxury goods but have many substitutes, making them elastic.\"]], \"analogies\": [\"Elasticity is like a rubber band \u2014 an elastic good stretches a lot (big quantity change) with a small pull (price change), while an inelastic good is stiff and barely moves.\"], \"prerequisites\": [\"percentage calculations\", \"basic algebra\"], \"formulas\": [\"Price Elasticity of Demand = %\u0394Qd / %\u0394P\"], \"document_evidence\": [\"Section 4.3 states: 'Goods with many close substitutes tend to have elastic demand.'\", \"Table 4.2 lists estimated elasticities: gasoline (\u22120.3), airline travel (\u22121.1), restaurant meals (\u22121.6).\"], \"practice_problems\": [\"If the price of coffee rises from $4 to $5 and sales drop from 1,000 to 800 cups, calculate the price elasticity of demand.\", \"A firm raises price by 5% and sees revenue increase. Is demand elastic or inelastic? Explain.\"], \"hints\": [\"Elasticity greater than 1 (in absolute value) means elastic; less than 1 means inelastic.\", \"More substitutes \u2192 more elastic. Longer time to adjust \u2192 more elastic.\"], \"follow_up_questions\": [\"Why does the time horizon matter for elasticity?\", \"How should a firm set its price if it knows demand is elastic?\"], \"diagnostic_questions\": [\"If a 5% price cut leads to a 2% increase in quantity demanded, is this good elastic or inelastic?\", \"Why might the elasticity of a good change over time?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The price elasticity of demand is the exact same thing as the slope of the demand curve.\", \"error_reason\": \"Slope measures absolute change (\u0394P/\u0394Q), whereas elasticity measures proportional percentage change (%\u0394Q / %\u0394P); on a straight-line demand curve, slope is constant but elasticity changes at every point.\", \"correct_claim\": \"Elasticity measures percentage sensitivity (%\u0394Q/%\u0394P), while slope measures unit change (\u0394P/\u0394Q). A linear demand curve has constant slope but elasticity that ranges from elastic at the top to inelastic at the bottom.\", \"understanding_probe\": \"Why is elasticity not constant along a downward-sloping straight-line demand curve even though the slope is constant?\", \"expected_answer\": \"Because elasticity measures percentage changes; at higher prices, a $1 drop is a small percentage price change that yields a large percentage quantity increase, whereas at low prices, the reverse is true.\"}, {\"prior_erroneous_claim\": \"When demand for a product is inelastic, lowering the price will increase total revenue.\", \"error_reason\": \"Inelastic demand means percentage change in quantity is smaller than percentage change in price, so price cuts lose more revenue per unit than is gained from additional sales.\", \"correct_claim\": \"If demand is inelastic (|Ed| < 1), cutting the price decreases total revenue; raising the price increases total revenue.\", \"understanding_probe\": \"Why does cutting prices on an inelastic good decrease a firm's total revenue?\", \"expected_answer\": \"Because the percentage increase in units sold is smaller than the percentage drop in price, meaning the extra sales are not enough to make up for the lower price received on all units.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Applied Microeconomics: Pricing Decisions\", \"page\": 55, \"section\": \"The Midpoint Formula for Price Elasticity\", \"selected_text\": \"A theater company changes its ticket price from P1 = $10.00 to P2 = $12.00, causing ticket sales to decline from Q1 = 100 tickets to Q2 = 80 tickets per evening.\", \"surrounding_context\": \"Section 3.4 demonstrates price elasticity calculation using the midpoint method.\", \"retrieved_evidence\": [\"Midpoint Formula: Ed = [(Q2 - Q1) / ((Q1 + Q2) / 2)] / [(P2 - P1) / ((P1 + P2) / 2)]\", \"Step-by-step arithmetic from course text: \u0394Q = 80 - 100 = -20; Q_avg = 90; %\u0394Q = -20 / 90 = -0.222. \u0394P = $12 - $10 = $2; P_avg = $11; %\u0394P = 2 / 11 = 0.1818. Ed = -0.222 / 0.1818 = -1.22 (Absolute value |Ed| = 1.22, elastic).\"], \"student_prompt\": \"What is the calculated price elasticity of demand using the midpoint formula from Section 3.4?\", \"target_response\": \"Following the calculation explicitly provided in Section 3.4: Percentage change in quantity is -20 / 90 = -0.222, and percentage change in price is 2 / 11 = 0.1818. Dividing the two gives Ed = -0.222 / 0.1818 = -1.22. In absolute terms, |Ed| = 1.22, showing that demand is price elastic. The course evidence directly establishes the elasticity value as -1.22.\", \"calculated_result\": \"Ed = -1.22 (|Ed| = 1.22)\"}, \"pattern_b_derive\": {\"document_title\": \"Cross-Price Elasticity of Demand\", \"page\": 59, \"section\": \"Substitutes vs Complements\", \"selected_text\": \"Cross-price elasticity of demand (Exy) quantifies the percentage responsiveness of the quantity demanded of good X relative to a percentage price change in good Y.\", \"surrounding_context\": \"Positive cross-price elasticity identifies substitute goods, whereas negative values identify complementary goods.\", \"retrieved_evidence\": [\"Formula: Exy = %\u0394Qx / %\u0394Py\", \"Market data: The price of streaming platform Y increases by 15%, causing the subscriber count of competing platform X to rise by 12%.\"], \"student_prompt\": \"How do we derive the cross-price elasticity from the data in the text, and what does the sign tell us?\", \"target_response\": \"To derive cross-price elasticity: Exy = %\u0394Qx / %\u0394Py. Substituting the given values: Exy = +12% / +15% = +0.80. The calculated cross-price elasticity is +0.80. Because Exy is positive, goods X and Y are substitute goods: when the price of service Y rises, consumers switch away from Y and increase their demand for platform X.\", \"formula\": \"Exy = %\u0394Qx / %\u0394Py\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the price elasticity of demand for retail oat milk in California grocery stores in 2024\", \"actual_topic\": \"theoretical price and cross-price elasticity formulas\", \"authoritative_source\": \"the USDA Economic Research Service (ERS) Food Demand and Price Elasticity Database\", \"document_title\": \"Consumer Demand Modeling\", \"page\": 63, \"section\": \"Elasticity Categorization\", \"selected_text\": \"Demand is categorized as perfectly inelastic when Ed = 0, unit elastic when |Ed| = 1, and infinitely elastic when |Ed| approaches infinity.\", \"surrounding_context\": \"Necessities with few close substitutes typically display highly inelastic consumer demand.\", \"retrieved_evidence\": [\"Section 3.1: Table of theoretical elasticity thresholds.\"], \"student_prompt\": \"According to the reading, what is the price elasticity of demand for retail oat milk in California grocery stores in 2024?\"}, {\"unmentioned_term\": \"the income elasticity of demand for private jet aviation charters\", \"actual_topic\": \"inferior vs normal goods classification\", \"authoritative_source\": \"the Federal Aviation Administration (FAA) Aerospace Forecasts\", \"document_title\": \"Consumer Demand Modeling\", \"page\": 66, \"section\": \"Income Elasticity\", \"selected_text\": \"Income elasticity of demand (Ei) is positive for normal goods and negative for inferior goods.\", \"surrounding_context\": \"Luxury goods have income elasticities strictly greater than 1.0.\", \"retrieved_evidence\": [\"Text: Normal goods have Ei > 0; luxury goods have Ei > 1.\"], \"student_prompt\": \"What does this passage state is the exact income elasticity of demand for private jet aviation charters?\"}], \"grounded_paraphrase\": {\"document_title\": \"Managerial Economics: Revenue Optimization\", \"page\": 70, \"section\": \"Total Revenue Test\", \"selected_text\": \"Isoelastic demand schedules exhibit unitary marginal revenue precisely at the point where the inframarginal price dilution exactly offsets extra-marginal volume expansion.\", \"surrounding_context\": \"At this point, total revenue reaches its mathematical peak.\", \"retrieved_evidence\": [\"Page 70: 'Total revenue is maximized where demand is unit elastic, because price drops are exactly balanced by higher volume.'\"], \"student_prompt\": \"Can you explain this excerpt in simple English?\", \"faithful_paraphrase\": \"This excerpt means that a company maximizes its total sales revenue when demand is unit elastic. At this exact point, if the business lowers the price slightly, the revenue lost from selling each unit cheaper is perfectly balanced by the extra revenue gained from selling more units, so total revenue is at its highest possible point.\"}, \"conflict_handling\": {\"document_title\": \"Energy Economics and Public Policy\", \"page\": 74, \"section\": \"Gasoline Price Elasticity\", \"selected_text\": \"Short-run empirical studies find that gasoline demand has an extremely low price elasticity of -0.20, meaning a 10% price increase reduces fuel consumption by only 2%.\", \"surrounding_context\": \"In the short term, commuters cannot easily change home locations or vehicle fuel efficiency.\", \"conflicting_evidence\": [\"Long-run Energy Demand Survey (Energy Journal 2021): 'Over a 5-to-10-year horizon, the long-run price elasticity of gasoline demand is measured at -0.75, nearly four times more responsive than short-run estimates as consumers purchase hybrid/electric vehicles and relocate closer to transit.'\"], \"student_prompt\": \"One part of the text says gasoline elasticity is -0.20, but the study notes it is -0.75. Why is there such a large difference?\", \"resolution_explanation\": \"This difference highlights the crucial distinction between short-run and long-run elasticity. In the short run (weeks or months), drivers have fixed commutes, fixed vehicles, and few immediate transit alternatives, so they must pay higher gas prices (inelastic demand of -0.20). But over the long run (several years), consumers have time to adapt: they buy more fuel-efficient or electric cars, switch to public transit, or move closer to work. Because consumers have far more substitution options over time, long-run demand is much more elastic (-0.75) than short-run demand.\"}}}, \"economics::Comparative Advantage\": {\"domain\": \"economics\", \"concept\": \"Comparative Advantage\", \"explanation\": \"the ability of a country or individual to produce a good at a lower opportunity cost than another, even if they are less efficient in absolute terms\", \"reason\": \"it explains why trade benefits all parties and is the foundation of international trade theory\", \"concrete_examples\": [\"Even if a doctor is faster at typing than a secretary, the doctor has a comparative advantage in medicine because the opportunity cost of typing (lost medical fees) is very high.\", \"Brazil has a comparative advantage in coffee production because its climate and soil make the opportunity cost of growing coffee lower than for most other countries.\", \"China may have an absolute advantage in both shirts and computers, but if its opportunity cost of shirts is lower, it has a comparative advantage in shirts.\"], \"numerical_examples\": [\"Country A produces 1 car in 10 hours or 5 tons of wheat in 10 hours. Country B produces 1 car in 20 hours or 2 tons of wheat in 20 hours. Country A's opportunity cost of 1 car = 5 tons of wheat; Country B's = 2 tons. Country B has comparative advantage in cars.\", \"If the US can produce 100 units of tech or 50 units of textiles, and Vietnam can produce 20 units of tech or 40 units of textiles, Vietnam has a comparative advantage in textiles (OC = 0.5 tech per textile vs US's 2).\", \"With trade, if both countries specialize, total output increases even though one country is absolutely better at everything.\"], \"misconceptions\": [[\"A country that is worse at producing everything has no basis for trade\", \"Comparative advantage shows that even a country less efficient at everything can still benefit from trade by specializing in goods where its opportunity cost is lowest. This is different from absolute advantage.\"]], \"analogies\": [\"Comparative advantage is like a basketball player who is also a great cook \u2014 it makes more sense for them to play basketball (where their edge is greatest) and hire a chef, even if they can cook well.\"], \"prerequisites\": [\"basic arithmetic\", \"opportunity cost\"], \"formulas\": [\"Opportunity Cost of Good X = Amount of Good Y sacrificed / Amount of Good X produced\"], \"document_evidence\": [\"David Ricardo's principle (p.78): 'Trade benefits both parties when each specializes in the good where their opportunity cost is lowest.'\", \"Table 6.1 compares production possibilities for two countries to illustrate comparative advantage.\"], \"practice_problems\": [\"Country X produces 30 bushels of corn or 10 yards of cloth per day. Country Y produces 20 bushels of corn or 15 yards of cloth. Which country has a comparative advantage in cloth?\", \"Explain why both countries benefit from trade, even if Country X is better at producing both goods.\"], \"hints\": [\"Calculate the opportunity cost for each good in each country, then compare.\", \"Comparative advantage is about RELATIVE efficiency, not absolute efficiency.\"], \"follow_up_questions\": [\"How does comparative advantage change when technology improves in one country?\", \"Can a country have a comparative advantage in everything? Why or why not?\"], \"diagnostic_questions\": [\"What is the difference between absolute advantage and comparative advantage?\", \"If you're the best at everything in a group project, should you do all the work? How does this relate to comparative advantage?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"A country that has an absolute advantage in producing every single good has no reason to trade with other nations.\", \"error_reason\": \"Trade is governed by comparative advantage (lower opportunity cost), not absolute advantage; mutual gains exist whenever countries have different internal opportunity cost ratios.\", \"correct_claim\": \"Even if one country is more efficient at producing everything in absolute terms, both nations gain by specializing in goods where they hold a comparative advantage (lower opportunity cost).\", \"understanding_probe\": \"Why should a country with absolute advantage in all goods still trade with less efficient nations?\", \"expected_answer\": \"Because producing a good in which it has a high opportunity cost takes resources away from goods it produces with even greater comparative efficiency; trade allows it to specialize where its advantage is greatest.\"}, {\"prior_erroneous_claim\": \"Comparative advantage is determined by whichever country uses the lowest number of labor hours per unit of output.\", \"error_reason\": \"Using the lowest labor hours per unit defines absolute advantage; comparative advantage requires calculating the opportunity cost ratio of one good in terms of another.\", \"correct_claim\": \"Comparative advantage is determined by comparing opportunity costs (what must be given up), not by absolute labor hours per unit.\", \"understanding_probe\": \"What is the difference between having an absolute advantage and a comparative advantage in production?\", \"expected_answer\": \"Absolute advantage means producing a good using fewer inputs or hours; comparative advantage means producing a good at a lower opportunity cost in terms of other goods forgone.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"International Trade Theory: The Ricardian Model\", \"page\": 82, \"section\": \"Labor Requirements and Trade Terms\", \"selected_text\": \"In a two-country model, Country A requires 10 hours of labor to produce 1 unit of wine and 20 hours to produce 1 unit of cloth. Country B requires 30 hours of labor to produce 1 unit of wine and 40 hours to produce 1 unit of cloth.\", \"surrounding_context\": \"Section 4.2 calculates internal opportunity cost ratios to establish mutually beneficial terms of trade.\", \"retrieved_evidence\": [\"Country A opportunity cost: 1 wine = 10/20 cloth = 0.5 cloth. (1 cloth = 20/10 wine = 2.0 wine).\", \"Country B opportunity cost: 1 wine = 30/40 cloth = 0.75 cloth. (1 cloth = 40/30 wine = 1.33 wine).\", \"Step-by-step conclusion: Country A has comparative advantage in wine (0.5 < 0.75 cloth). Country B has comparative advantage in cloth (1.33 < 2.0 wine). Mutually beneficial terms of trade: 1 wine for 0.60 cloth.\"], \"student_prompt\": \"Based on Section 4.2, what are the calculated opportunity costs and which country has comparative advantage in which good?\", \"target_response\": \"Following the calculation explicitly provided in Section 4.2: In Country A, 1 unit of wine costs 10/20 = 0.5 units of cloth. In Country B, 1 unit of wine costs 30/40 = 0.75 units of cloth. Because 0.5 < 0.75, Country A has the comparative advantage in wine. For cloth, Country B gives up 1.33 units of wine compared to Country A's 2.0 units of wine, so Country B has the comparative advantage in cloth. The course evidence directly establishes these specialization assignments.\", \"calculated_result\": \"Country A in wine (0.5 cloth), Country B in cloth (1.33 wine)\"}, \"pattern_b_derive\": {\"document_title\": \"Gains from Specialization and Trade\", \"page\": 86, \"section\": \"Establishing the Terms of Trade\", \"selected_text\": \"For voluntary trade to occur between two nations, the international exchange ratio (terms of trade) must lie strictly between the domestic opportunity cost ratios of the trading partners.\", \"surrounding_context\": \"If terms of trade fall outside this range, one nation will find domestic production more advantageous than international exchange.\", \"retrieved_evidence\": [\"Rule: Domestic opportunity cost of Country 1 < Terms of Trade < Domestic opportunity cost of Country 2\", \"Data: Nation X gives up 2 bushels of wheat to produce 1 barrel of oil; Nation Y gives up 5 bushels of wheat to produce 1 barrel of oil.\"], \"student_prompt\": \"How do we derive the viable terms of trade range for oil and wheat between Nation X and Nation Y?\", \"target_response\": \"To derive the viable terms of trade: International exchange must benefit both countries compared to domestic production. Nation X gives up 2 bushels of wheat per barrel of oil, while Nation Y gives up 5 bushels. Therefore, any exchange price between 2 and 5 bushels of wheat per barrel of oil will benefit both nations: Nation X gains because it receives more than 2 bushels of wheat per barrel exported, and Nation Y gains because it buys oil for less than the 5 bushels it would cost to produce at home.\", \"formula\": \"Cost_low < Terms_of_Trade < Cost_high\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the 2024 bilateral tariff schedule on electric vehicle lithium cells between the US and South Korea under KORUS\", \"actual_topic\": \"classical Ricardian comparative advantage trade theory\", \"authoritative_source\": \"the United States International Trade Commission (USITC) Harmonized Tariff Schedule / USTR\", \"document_title\": \"Foundations of Global Trade\", \"page\": 90, \"section\": \"Ricardian Assumptions\", \"selected_text\": \"The classical Ricardian framework presumes constant returns to scale and mobile labor within national borders.\", \"surrounding_context\": \"Transportation frictions and non-tariff trade barriers are excluded from basic Ricardian models.\", \"retrieved_evidence\": [\"Section 4.1: Theoretical assumptions of Ricardian comparative advantage.\"], \"student_prompt\": \"What does this passage state is the 2024 bilateral tariff schedule on electric vehicle lithium cells under KORUS?\"}, {\"unmentioned_term\": \"the Heckscher-Ohlin empirical Leontief paradox findings from the 1947 US input-output tables\", \"actual_topic\": \"two-country two-good labor productivity comparative advantage\", \"authoritative_source\": \"Wassily Leontief (1953) Review of Economics and Statistics / NBER\", \"document_title\": \"Foundations of Global Trade\", \"page\": 93, \"section\": \"Factor Proportions Theory\", \"selected_text\": \"Comparative advantage extends to multi-factor economies where capital-abundant nations export capital-intensive goods.\", \"surrounding_context\": \"The Heckscher-Ohlin model emphasizes national endowments of labor, land, and capital.\", \"retrieved_evidence\": [\"Text: Discusses factor endowments generally without historical empirical test tables.\"], \"student_prompt\": \"According to the reading, what were the exact empirical results of Leontief's 1947 paradox test?\"}], \"grounded_paraphrase\": {\"document_title\": \"International Trade Dynamics\", \"page\": 97, \"section\": \"Distributional Consequences of Trade\", \"selected_text\": \"While aggregate national income expands through trade integration, the Stolper-Samuelson theorem demonstrates that owners of abundant factors experience real income gains while owners of scarce factors endure real income depreciation.\", \"surrounding_context\": \"Trade liberalization creates both concentrated domestic losers and dispersed winners.\", \"retrieved_evidence\": [\"Page 97: 'Trade makes the country as a whole richer, but workers or capital owners in industries competing with imports suffer lower wages or profits.'\"], \"student_prompt\": \"Can you explain what this passage means in simpler words?\", \"faithful_paraphrase\": \"This passage explains that although free trade makes a nation wealthier overall, it does not benefit everyone equally. People who own or work in the resources the country has in abundance gain higher earnings, but workers and businesses in industries that face heavy foreign competition end up with lower wages or profits.\"}, \"conflict_handling\": {\"document_title\": \"Modern Trade Controversies\", \"page\": 102, \"section\": \"Strategic Trade Policy\", \"selected_text\": \"Traditional trade theory argues that free trade based on comparative advantage maximizes global welfare and that government subsidies distort efficient production.\", \"surrounding_context\": \"Classical free-trade models assume constant returns to scale and perfect competition.\", \"conflicting_evidence\": [\"Strategic Trade Theory (Paul Krugman / Brander-Spencer Model): 'In high-tech industries with massive economies of scale and high R&D barriers (such as commercial jetliner manufacturing), government subsidies can allow a domestic firm like Airbus or Boeing to capture global monopoly profits, increasing national welfare at the expense of trading partners.'\"], \"student_prompt\": \"The textbook says government subsidies always harm trade efficiency, but strategic trade theory says subsidies can help a nation. Why do they conflict?\", \"resolution_explanation\": \"The disagreement comes down to market structure. Traditional comparative advantage assumes competitive markets with small firms and constant returns to scale (like farming or textiles), where subsidies cause waste. Strategic trade theory looks at oligopolistic industries like aerospace or microchips, where massive upfront R&D costs mean only two or three firms can survive globally. In those specific high-tech markets, government backing can deter foreign rivals and capture profits that wouldn't exist under simple free-market rules. Both theories are correct for their respective industries: comparative advantage applies to competitive goods, while strategic trade theory applies to high-barrier technological monopolies.\"}}}, \"economics::Fiscal Policy\": {\"domain\": \"economics\", \"concept\": \"Fiscal Policy\", \"explanation\": \"the use of government spending and taxation to influence the economy's aggregate demand, employment, and price level\", \"reason\": \"it allows governments to stabilize business cycles, combat recessions, and manage public services\", \"concrete_examples\": [\"During the 2008 recession, the US government passed a stimulus package increasing spending on infrastructure to boost employment and demand.\", \"A government cutting income tax rates puts more money in consumers' pockets, encouraging spending and economic growth.\", \"Increasing military spending is expansionary fiscal policy that raises aggregate demand.\"], \"numerical_examples\": [\"If the government increases spending by $100 billion and MPC = 0.8, the multiplier is 5, so GDP increases by $500 billion.\", \"A $50 billion tax cut with MPC = 0.75 has a tax multiplier of \u2212MPC/(1\u2212MPC) = \u22123, increasing GDP by $150 billion.\", \"If the budget deficit is $800 billion (spending $4.5T, revenue $3.7T), the government must borrow the difference.\"], \"misconceptions\": [[\"Government spending always leads to economic growth\", \"If the economy is already at full employment, additional government spending can cause inflation ('crowding out') rather than real growth, and the borrowed money raises interest rates, reducing private investment.\"]], \"analogies\": [\"Fiscal policy is like a thermostat for the economy: the government turns up spending (heat) during recessions and turns it down (cool) during booms to maintain a comfortable temperature.\"], \"prerequisites\": [\"basic algebra\", \"graph interpretation\"], \"formulas\": [\"Government Spending Multiplier = 1/(1\u2212MPC)\", \"Tax Multiplier = \u2212MPC/(1\u2212MPC)\"], \"document_evidence\": [\"The chapter notes: 'Fiscal policy is most effective when the economy operates below full employment and monetary policy alone is insufficient.'\", \"Case study 7.3 examines the 2009 American Recovery and Reinvestment Act's impact on employment.\"], \"practice_problems\": [\"With MPC = 0.80, compare the GDP impact of a $200 billion spending increase vs. a $200 billion tax cut.\", \"Explain why the spending multiplier is larger than the tax multiplier.\"], \"hints\": [\"Expansionary = more spending or less taxes. Contractionary = less spending or more taxes.\", \"The spending multiplier is always larger than the tax multiplier because some of the tax cut is saved.\"], \"follow_up_questions\": [\"What is the difference between automatic stabilizers and discretionary fiscal policy?\", \"Why might there be a time lag between implementing fiscal policy and seeing its effects?\"], \"diagnostic_questions\": [\"During a recession, should the government increase or decrease spending? Why?\", \"What is 'crowding out' and how does it limit the effectiveness of fiscal policy?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The government spending multiplier and the tax cut multiplier are exactly equal in size.\", \"error_reason\": \"The tax cut multiplier is smaller (-MPC / (1 - MPC)) because households save part of a tax cut (leakage) rather than spending 100% of it into the economy.\", \"correct_claim\": \"The government spending multiplier is larger than the tax cut multiplier because government spending enters aggregate demand directly, whereas part of a tax cut is saved.\", \"understanding_probe\": \"Why does $100 billion of direct government spending have a larger stimulative impact on GDP than a $100 billion tax cut?\", \"expected_answer\": \"Because the full $100 billion of government spending immediately enters the economy as aggregate demand, whereas households save a fraction of a tax cut (MPS) rather than spending all of it.\"}, {\"prior_erroneous_claim\": \"Fiscal policy can completely eliminate all recessions immediately without any operational time lags.\", \"error_reason\": \"Fiscal policy is hindered by recognition lags (identifying the recession), legislative lags (passing bills through Congress), and implementation lags (spending the funds).\", \"correct_claim\": \"Fiscal policy faces significant recognition, legislative, and implementation lags that can delay stimulus until after a recession has already begun to recover.\", \"understanding_probe\": \"What are the three main time lags that complicate discretionary fiscal policy?\", \"expected_answer\": \"The recognition lag (time to realize a recession is happening), the legislative lag (time for lawmakers to pass legislation), and the implementation lag (time to disburse funds and execute projects).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Macroeconomic Policy Analysis: Multipliers\", \"page\": 110, \"section\": \"Comparing Expenditure and Tax Multipliers\", \"selected_text\": \"In a closed economy with an estimated marginal propensity to consume MPC = 0.80, Congress considers either a $100 billion infrastructure spending package or a $100 billion tax rebate.\", \"surrounding_context\": \"Section 5.1 compares the aggregate demand shifts generated by equal-sized fiscal instruments.\", \"retrieved_evidence\": [\"Formulas: Government Spending Multiplier kg = 1 / (1 - MPC); Tax Multiplier kt = -MPC / (1 - MPC).\", \"Step-by-step arithmetic from report: kg = 1 / (1 - 0.80) = 1 / 0.20 = 5.0. Total GDP change from spending = 5.0 * $100B = +$500 billion. kt = -0.80 / (1 - 0.80) = -0.80 / 0.20 = -4.0. Total GDP change from tax cut = -4.0 * (-$100B) = +$400 billion.\"], \"student_prompt\": \"What are the calculated GDP changes from the $100 billion spending increase versus the $100 billion tax cut?\", \"target_response\": \"Following the calculation explicitly provided in Section 5.1: The government spending multiplier is 1 / 0.20 = 5.0, resulting in a GDP increase of 5.0 * $100B = $500 billion. The tax multiplier is -0.80 / 0.20 = -4.0, resulting in a GDP increase of -4.0 * (-$100B) = $400 billion. The direct spending package creates $100 billion more in total GDP expansion because none of the initial round is leaked into savings.\", \"calculated_result\": \"Spending GDP change = +$500B, Tax cut GDP change = +$400B\"}, \"pattern_b_derive\": {\"document_title\": \"Fiscal Balances and Output\", \"page\": 114, \"section\": \"The Balanced Budget Multiplier\", \"selected_text\": \"When a government increases spending by amount \u0394G and finances it entirely through an equal increase in taxes \u0394T (so \u0394G = \u0394T), aggregate output still expands.\", \"surrounding_context\": \"The balanced budget multiplier combines the simultaneous effects of the spending and tax multipliers.\", \"retrieved_evidence\": [\"Formulas: \u0394Y = (kg * \u0394G) + (kt * \u0394T), where kg = 1 / (1 - MPC) and kt = -MPC / (1 - MPC).\", \"Condition: Balanced budget expansion with \u0394G = \u0394T = $50 billion.\"], \"student_prompt\": \"How do we derive the balanced budget multiplier from the spending and tax multiplier formulas in the text?\", \"target_response\": \"To derive the balanced budget multiplier: Combine the two multiplier formulas where \u0394G = \u0394T. Total change in output is \u0394Y = [1 / (1 - MPC)] * \u0394G + [-MPC / (1 - MPC)] * \u0394G. Factoring out \u0394G gives [(1 - MPC) / (1 - MPC)] * \u0394G = 1.0 * \u0394G. Therefore, the balanced budget multiplier is exactly 1.0. An equal $50 billion increase in spending and taxes expands GDP by exactly $50 billion.\", \"formula\": \"Balanced Budget Multiplier = kg + kt = (1 - MPC)/(1 - MPC) = 1.0\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the Congressional Budget Office (CBO) baseline federal deficit projection for fiscal year 2029\", \"actual_topic\": \"theoretical fiscal multiplier formulas and automatic stabilizers\", \"authoritative_source\": \"the Congressional Budget Office (CBO) Budget and Economic Outlook report\", \"document_title\": \"Fiscal Policy Mechanisms\", \"page\": 118, \"section\": \"Automatic vs Discretionary Stabilizers\", \"selected_text\": \"Automatic stabilizers, such as progressive income taxation and unemployment insurance benefits, cushion disposable income fluctuations without legislative intervention.\", \"surrounding_context\": \"Tax revenues decline automatically during downturns, supporting consumer spending.\", \"retrieved_evidence\": [\"Section 5.3: Definition of automatic stabilizers.\"], \"student_prompt\": \"According to this passage, what is the CBO baseline federal deficit projection for fiscal year 2029?\"}, {\"unmentioned_term\": \"the Japanese debt-to-GDP ratio following the 2023 supplementary budget\", \"actual_topic\": \"mechanisms of discretionary fiscal expansion\", \"authoritative_source\": \"the Ministry of Finance Japan or IMF World Economic Outlook Database\", \"document_title\": \"Fiscal Policy Mechanisms\", \"page\": 121, \"section\": \"Sovereign Debt and Deficits\", \"selected_text\": \"Persistent fiscal deficits accumulate into total national public debt.\", \"surrounding_context\": \"High public debt ratios can lead to crowding out of private capital investment.\", \"retrieved_evidence\": [\"Text: Discusses debt accumulation and crowding out conceptually.\"], \"student_prompt\": \"What does the document state was the Japanese debt-to-GDP ratio following the 2023 supplementary budget?\"}], \"grounded_paraphrase\": {\"document_title\": \"Public Finance and Macroeconomics\", \"page\": 125, \"section\": \"Crowding-Out Dynamics\", \"selected_text\": \"Sovereign debt issuance to finance fiscal deficits exacerbates loanable funds scarcity, exerting upward pressure on nominal yields and curtailing rate-sensitive private capital formation.\", \"surrounding_context\": \"When government borrowing absorbs national savings, private investment projects become unviable.\", \"retrieved_evidence\": [\"Page 125: 'Government borrowing increases interest rates, which causes businesses to cut back on building factories and buying equipment.'\"], \"student_prompt\": \"Can you rephrase this excerpt in plain English without losing the core point?\", \"faithful_paraphrase\": \"This excerpt means that when the government borrows heavily to fund deficit spending, it competes with businesses for available loans. This competition drives interest rates higher, making borrowing too expensive for private companies, which then reduce their spending on new factories, equipment, and technology (known as crowding out).\"}, \"conflict_handling\": {\"document_title\": \"Debates in Modern Macroeconomics\", \"page\": 130, \"section\": \"Ricardian Equivalence vs Keynesian Multipliers\", \"selected_text\": \"Standard Keynesian analysis shows that a debt-financed tax cut stimulates current consumer spending and raises aggregate demand by putting disposable cash into workers' hands.\", \"surrounding_context\": \"Keynesian models assume consumers treat temporary tax cuts as immediate income additions.\", \"conflicting_evidence\": [\"Barro (1974) Ricardian Equivalence Hypothesis: 'Forward-looking consumers recognize that debt-financed tax cuts today imply higher future taxes to service government debt; rational households save the entire tax rebate rather than spending it, resulting in a fiscal stimulus multiplier of zero.'\"], \"student_prompt\": \"Why does the Keynesian chapter say tax cuts increase spending, while the Barro reading says tax cuts have zero effect on spending?\", \"resolution_explanation\": \"These two theories arrive at opposite conclusions because they make fundamentally different assumptions about human behavior. The Keynesian model assumes households are focused on immediate cash flow\u2014many have limited savings or cannot borrow easily, so when they get a tax cut, they spend most of it right away. In contrast, the Ricardian Equivalence model assumes households are fully rational, forward-looking, and plan for their heirs; they realize that government borrowing today must be paid back with higher taxes tomorrow, so they save the tax cut to pay future tax bills. In the real world, most evidence shows consumer behavior is in between: some people save tax cuts, but many spend them, giving tax cuts a modest positive multiplier rather than zero.\"}}}, \"economics::Monetary Policy\": {\"domain\": \"economics\", \"concept\": \"Monetary Policy\", \"explanation\": \"the actions taken by a central bank to manage the money supply and interest rates to achieve macroeconomic objectives like stable prices, full employment, and economic growth\", \"reason\": \"it is the primary tool for controlling inflation and stabilizing the economy in the short to medium term\", \"concrete_examples\": [\"When the Federal Reserve lowers the federal funds rate, borrowing becomes cheaper, encouraging businesses to invest and consumers to spend.\", \"During high inflation, the central bank raises interest rates to make borrowing expensive, cooling demand and slowing price increases.\", \"Quantitative easing involves the central bank buying government bonds to inject money into the economy.\"], \"numerical_examples\": [\"If the central bank lowers the interest rate from 5% to 3%, a business considering a $1 million loan saves $20,000/year in interest, making the investment more attractive.\", \"With a reserve requirement of 10%, a $1,000 deposit can create up to $10,000 in new money through the money multiplier (1/0.10).\", \"If the target inflation rate is 2% and actual inflation is 4%, the Taylor Rule suggests the central bank should raise rates.\"], \"misconceptions\": [[\"The central bank directly controls all interest rates in the economy\", \"The central bank sets the overnight rate (e.g., federal funds rate) at which banks lend to each other. Other rates (mortgages, car loans, corporate bonds) are influenced by this rate but are also determined by risk, term, and market expectations.\"]], \"analogies\": [\"Monetary policy is like controlling the water pressure in a plumbing system \u2014 the central bank adjusts the main valve (interest rates) to increase or decrease the flow of money through the economy.\"], \"prerequisites\": [\"percentage calculations\", \"basic algebra\"], \"formulas\": [\"Money Multiplier = 1/Reserve Requirement\"], \"document_evidence\": [\"The text states: 'By adjusting the federal funds rate, the Federal Reserve influences borrowing costs throughout the economy.'\", \"Figure 8.2 shows the inverse relationship between interest rates and investment spending.\"], \"practice_problems\": [\"If the reserve requirement is 20%, what is the money multiplier? How much total money can $5,000 in new deposits create?\", \"Explain the transmission mechanism: how does lowering the fed funds rate eventually boost GDP?\"], \"hints\": [\"Lower interest rates \u2192 cheaper borrowing \u2192 more investment and consumption \u2192 higher GDP.\", \"The money multiplier is 1 divided by the reserve requirement ratio.\"], \"follow_up_questions\": [\"What happens when interest rates are already near zero \u2014 what tools does the central bank still have?\", \"How do inflation expectations affect the central bank's ability to manage the economy?\"], \"diagnostic_questions\": [\"If the economy is overheating, should the central bank raise or lower interest rates?\", \"What is the difference between fiscal policy and monetary policy?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The Federal Reserve directly dictates consumer mortgage and credit card interest rates by law.\", \"error_reason\": \"The Fed sets the federal funds target rate for interbank overnight loans; commercial banks independently set consumer lending rates based on market benchmarks and credit risk.\", \"correct_claim\": \"The Federal Reserve sets the federal funds rate (the rate banks charge each other for overnight loans); commercial lending rates adjust indirectly through market competition.\", \"understanding_probe\": \"How does the Federal Reserve influence consumer mortgage rates if it doesn't set them directly?\", \"expected_answer\": \"By altering the federal funds rate and bank reserves, the Fed changes banks' borrowing costs, which ripples through the prime rate and market yields into consumer mortgage rates.\"}, {\"prior_erroneous_claim\": \"Printing more money always increases economic output without any danger of causing inflation.\", \"error_reason\": \"Expanding the money supply beyond the economy's productive capacity fuels demand-pull inflation and depreciates purchasing power without raising real GDP.\", \"correct_claim\": \"Excessive monetary expansion leads to inflation rather than real growth once an economy operates near full employment capacity.\", \"understanding_probe\": \"What happens when the money supply grows much faster than the real production of goods and services?\", \"expected_answer\": \"Too much money chases too few goods, leading to inflation that reduces purchasing power without increasing real output.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Money, Banking, and Financial Markets\", \"page\": 138, \"section\": \"The Money Multiplier and Reserve Requirements\", \"selected_text\": \"A commercial bank receives a new cash deposit of $10,000. Under central bank regulations, the required reserve ratio (rr) is mandated at 10.0%.\", \"surrounding_context\": \"Section 6.2 calculates the theoretical maximum expansion of the commercial banking money supply.\", \"retrieved_evidence\": [\"Money Multiplier Formula: M = 1 / rr\", \"Step-by-step arithmetic from course text: Multiplier M = 1 / 0.10 = 10.0. Maximum potential increase in checkable deposits = Initial Deposit * Multiplier = $10,000 * 10 = $100,000. Maximum new loans created = $100,000 - $10,000 initial deposit = $90,000.\"], \"student_prompt\": \"What is the calculated money multiplier and maximum potential deposit creation from the $10,000 deposit?\", \"target_response\": \"Following the calculation explicitly provided in Section 6.2: The money multiplier is M = 1 / 0.10 = 10.0. Multiplying the initial deposit by the multiplier gives $10,000 * 10 = $100,000 in maximum potential checkable deposits. The banking system can create up to $90,000 in new loans. The course evidence directly establishes the multiplier at 10.0 and total potential deposits at $100,000.\", \"calculated_result\": \"Money Multiplier = 10.0, Total Deposits = $100,000\"}, \"pattern_b_derive\": {\"document_title\": \"Monetary Policy Rules: The Taylor Rule\", \"page\": 142, \"section\": \"Setting the Target Policy Rate\", \"selected_text\": \"John Taylor proposed a systematic policy rule for central banks to adjust nominal interest rates in response to deviations in inflation and economic output.\", \"surrounding_context\": \"The standard Taylor Rule prescribes: i = r* + \u03c0 + 0.5(\u03c0 - \u03c0*) + 0.5(y - y*).\", \"retrieved_evidence\": [\"Taylor Rule Formula: Target Rate i = r* + \u03c0 + 0.5*(Inflation Gap) + 0.5*(Output Gap)\", \"Data: Neutral real rate r* = 2.0%, current inflation \u03c0 = 4.0%, inflation target \u03c0* = 2.0%, output gap (y - y*) = 1.0%.\"], \"student_prompt\": \"How do we calculate the prescribed target policy rate using the Taylor Rule from the reading?\", \"target_response\": \"To derive the target policy rate using the Taylor Rule: First calculate the inflation gap: 4.0% - 2.0% = 2.0%. Next, multiply the gaps by their policy weights: 0.5 * 2.0% = 1.0% for inflation, and 0.5 * 1.0% = 0.5% for the output gap. Finally, sum all components: i = 2.0% (neutral rate) + 4.0% (inflation) + 1.0% + 0.5% = 7.5%. The Taylor Rule prescribes a target policy rate of 7.5%.\", \"formula\": \"i = r* + \u03c0 + 0.5(\u03c0 - \u03c0*) + 0.5(y - y*)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the Bank of Japan's total foreign exchange asset holdings in yen as of Q3 2025\", \"actual_topic\": \"general central banking tools including open market operations and reserve ratios\", \"authoritative_source\": \"the Bank of Japan Financial Statistics Time-Series Database\", \"document_title\": \"Central Bank Operations\", \"page\": 146, \"section\": \"Open Market Operations\", \"selected_text\": \"The Federal Reserve conducts open market operations by buying and selling Treasury securities to adjust commercial bank reserves.\", \"surrounding_context\": \"Purchasing bonds expands bank reserves and lowers the federal funds rate.\", \"retrieved_evidence\": [\"Section 6.1: Mechanics of domestic open market operations.\"], \"student_prompt\": \"According to the reading, what were the Bank of Japan's total foreign exchange asset holdings in Q3 2025?\"}, {\"unmentioned_term\": \"the Swiss National Bank negative interest rate floor level in 2015\", \"actual_topic\": \"the federal funds rate target corridor and repo facilities\", \"authoritative_source\": \"the Swiss National Bank (SNB) Monetary Policy Decisions archive\", \"document_title\": \"Central Bank Operations\", \"page\": 149, \"section\": \"Interest on Reserve Balances\", \"selected_text\": \"The Federal Reserve sets the Interest on Reserve Balances (IORB) rate as the primary tool to control the overnight federal funds rate within its target range.\", \"surrounding_context\": \"Arbitrage between IORB and the overnight repo rate maintains the policy target corridor.\", \"retrieved_evidence\": [\"Text: Explains the IORB floor system for the US Federal Reserve.\"], \"student_prompt\": \"What was the Swiss National Bank's negative interest rate floor level in 2015 according to this text?\"}], \"grounded_paraphrase\": {\"document_title\": \"Monetary Economics\", \"page\": 153, \"section\": \"The Transmission Mechanism\", \"selected_text\": \"Central bank policy rate tightening induces asset price deflation through elevated discount rates, concurrently curbing credit intermediation via widening risk premia and contracting commercial bank liquidity buffers.\", \"surrounding_context\": \"These monetary channels cumulatively decelerate interest-sensitive investment and consumer durable spending.\", \"retrieved_evidence\": [\"Page 153: 'Raising interest rates lowers stock and bond prices, makes loans harder to get, and leads banks to lend less money.'\"], \"student_prompt\": \"Can you explain what this passage is saying in clear, everyday language?\", \"faithful_paraphrase\": \"This passage explains what happens when a central bank raises interest rates: it causes the value of stocks and bonds to fall, raises borrowing costs for businesses and households, and makes banks more cautious about lending out money. As a result, companies and consumers cut back on taking out loans to buy equipment, cars, or homes.\"}, \"conflict_handling\": {\"document_title\": \"Monetary Theory Perspectives\", \"page\": 158, \"section\": \"Monetarism vs New Keynesian View\", \"selected_text\": \"Milton Friedman's classical monetarism asserts that inflation is always and everywhere a monetary phenomenon caused by excessive money supply expansion, advocating a fixed annual money growth rule.\", \"surrounding_context\": \"Monetarists argued that velocity of money was stable and predictable over long periods.\", \"conflicting_evidence\": [\"Modern Central Banking Frameworks (Bernanke / Woodford): 'Financial deregulation and electronic payments destabilized money velocity in the 1980s and 1990s, rendering money supply targeting obsolete; modern central banks target interest rates and inflation forecasts directly rather than money aggregate growth.'\"], \"student_prompt\": \"Why did Friedman insist on targeting money supply growth, while modern central banks focus on interest rates instead of money aggregates?\", \"resolution_explanation\": \"This historical shift reflects how the financial system evolved. In the 1960s and 1970s, the relationship between money supply growth and GDP (known as velocity) was relatively stable, which supported Friedman's monetarist view that controlling money growth was the best way to prevent inflation. However, in the 1980s and 1990s, credit cards, automated teller machines, and electronic banking transformed how people hold and move money, causing velocity to fluctuate unpredictably. Because targeting money supply aggregates became unreliable, central banks like the Federal Reserve shifted in the 1990s to targeting short-term interest rates and inflation forecasts directly.\"}}}, \"economics::Externalities\": {\"domain\": \"economics\", \"concept\": \"Externalities\", \"explanation\": \"costs or benefits of a market transaction that affect third parties who are not directly involved in the transaction\", \"reason\": \"they cause market failure because private costs/benefits diverge from social costs/benefits, justifying government intervention\", \"concrete_examples\": [\"A factory polluting a river imposes a negative externality on downstream fishermen and communities who bear health and cleanup costs.\", \"Getting vaccinated creates a positive externality because it protects not just you but also those around you through herd immunity.\", \"A beekeeper's bees pollinate a neighboring farmer's crops \u2014 a positive externality the beekeeper is not compensated for.\"], \"numerical_examples\": [\"If producing one ton of steel costs $100 privately but causes $30 in pollution damage, the social cost is $130. Without intervention, the market overproduces steel.\", \"A Pigouvian tax of $30/ton on steel production would internalize the externality, aligning private and social costs.\", \"If each vaccination costs $20 but provides $50 in community health benefits, the social benefit ($70) exceeds the private benefit ($20).\"], \"misconceptions\": [[\"Externalities only refer to pollution and environmental damage\", \"Externalities include ANY spillover \u2014 positive (education, vaccination, R&D) and negative (noise, congestion, secondhand smoke). They can be production or consumption externalities in any sector.\"]], \"analogies\": [\"An externality is like secondhand smoke \u2014 your smoking affects the health of everyone nearby, and they didn't choose to breathe it in.\"], \"prerequisites\": [\"basic algebra\", \"graph interpretation\"], \"formulas\": [\"Social Cost = Private Cost + External Cost\", \"Social Benefit = Private Benefit + External Benefit\"], \"document_evidence\": [\"The text explains: 'When external costs exist, the market equilibrium quantity exceeds the socially optimal quantity.'\", \"Diagram 9.1 shows the deadweight loss triangle caused by overproduction with a negative externality.\"], \"practice_problems\": [\"If the private cost of producing a widget is $10 and the external cost is $3, what Pigouvian tax should the government impose?\", \"Draw a supply-demand diagram showing how a negative externality leads to overproduction and label the deadweight loss.\"], \"hints\": [\"Negative externalities \u2192 social cost > private cost \u2192 overproduction.\", \"Positive externalities \u2192 social benefit > private benefit \u2192 underproduction.\"], \"follow_up_questions\": [\"What is the Coase theorem, and when does it suggest government intervention is unnecessary?\", \"How do cap-and-trade systems address negative externalities differently from taxes?\"], \"diagnostic_questions\": [\"Can you give an example of a positive externality in education?\", \"Why does the free market produce too much of a good with negative externalities?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The only way to address a negative externality is for the government to shut down the emitting factory completely.\", \"error_reason\": \"Economic remedies like Pigouvian taxes, cap-and-trade permits, or property rights assignment align private costs with social costs to reach the optimal level of output without shutting down production.\", \"correct_claim\": \"Negative externalities are corrected by internalizing the external cost (e.g. through a Pigouvian tax equal to marginal external damage) to reach the socially optimal quantity, not necessarily by zeroing production.\", \"understanding_probe\": \"Why is the socially optimal level of pollution usually greater than zero?\", \"expected_answer\": \"Because the goods producing the pollution provide economic benefits to society; the goal is to balance the marginal benefit of production against the marginal social cost of pollution, not eliminate all economic activity.\"}, {\"prior_erroneous_claim\": \"Goods with positive externalities are already produced in excessive quantities by private markets.\", \"error_reason\": \"Because private buyers only consider their own private benefit, market demand reflects private benefit rather than social benefit, leading competitive markets to under-produce goods with positive externalities.\", \"correct_claim\": \"Private markets under-produce goods with positive externalities (like vaccines or education) because private buyers do not capture the full social benefits created for others.\", \"understanding_probe\": \"Why do competitive markets under-produce goods that generate positive externalities?\", \"expected_answer\": \"Because individual consumers only pay for the private benefits they personally receive, ignoring the extra benefits conferred on others, which leaves market demand lower than the true social benefit.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Environmental Economics: Market Failures\", \"page\": 166, \"section\": \"Calculating the Pigouvian Tax\", \"selected_text\": \"A chemical factory operates in a competitive market where market demand is P = 100 - Q and the factory's private marginal cost is PMC = 20 + Q. The production process releases toxic runoff that causes marginal external damage of MD = $10.00 per unit.\", \"surrounding_context\": \"Section 7.2 demonstrates how to calculate market equilibrium versus social optimum.\", \"retrieved_evidence\": [\"Formulas: Private equilibrium: P = PMC; Social optimum: P = SMC = PMC + MD\", \"Step-by-step arithmetic from report: Private equilibrium: 100 - Q = 20 + Q => 2Q = 80 => Q_private = 40 units; P_private = $60.00. Social optimum: SMC = (20 + Q) + 10 = 30 + Q. 100 - Q = 30 + Q => 2Q = 70 => Q_social = 35 units; P_social = $65.00. Optimal Pigouvian tax t* = MD = $10.00 per unit.\"], \"student_prompt\": \"What are the calculated private market output, socially optimal output, and optimal Pigouvian tax in Section 7.2?\", \"target_response\": \"Following the calculation explicitly provided in Section 7.2: Private market equilibrium sets PMC equal to demand: 20 + Q = 100 - Q, giving Q_private = 40 units at P = $60.00. The social marginal cost includes the $10 external damage (SMC = 30 + Q). Setting SMC equal to demand gives 30 + Q = 100 - Q, producing the socially optimal quantity Q_social = 35 units at P = $65.00. The optimal Pigouvian tax equals the marginal damage: t* = $10.00 per unit. The course evidence directly establishes these values.\", \"calculated_result\": \"Q_private = 40, Q_social = 35, Pigouvian tax = $10.00\"}, \"pattern_b_derive\": {\"document_title\": \"Public Goods and Positive Externalities\", \"page\": 170, \"section\": \"Marginal Social Benefit of Immunization\", \"selected_text\": \"When an individual receives a vaccination, they gain private immunity and also reduce contagion risks for non-vaccinated members of the community.\", \"surrounding_context\": \"The Marginal Social Benefit (MSB) is the vertical sum of Marginal Private Benefit (MPB) and Marginal External Benefit (MEB).\", \"retrieved_evidence\": [\"Formula: MSB = MPB + MEB\", \"Data: Private willingness to pay for a flu vaccine is MPB = $30.00; the external epidemiological benefit to coworkers is valued at MEB = $25.00.\"], \"student_prompt\": \"How do we derive the total Marginal Social Benefit (MSB) of the vaccination from the formulas in the text?\", \"target_response\": \"To derive the Marginal Social Benefit: MSB = MPB + MEB. Substituting the values from the text: MSB = $30.00 (private value) + $25.00 (community protection value) = $55.00. Because the total social benefit ($55.00) exceeds the private benefit ($30.00), a public subsidy of $25.00 per dose is justified to align private consumer choice with social efficiency.\", \"formula\": \"MSB = MPB + MEB\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the European Union Emissions Trading System (EU ETS) carbon allowance auction clearing price on October 12, 2024\", \"actual_topic\": \"theoretical Coase theorem conditions and Pigouvian taxation\", \"authoritative_source\": \"the European Energy Exchange (EEX) carbon market reports / Ember Climate\", \"document_title\": \"Environmental Policy Instruments\", \"page\": 174, \"section\": \"Cap-and-Trade Systems\", \"selected_text\": \"Cap-and-trade programs establish a regulatory cap on aggregate emissions and allocate tradable emission permits among regulated emitters.\", \"surrounding_context\": \"Permit trading ensures that emissions reductions are achieved at the lowest overall cost across firms.\", \"retrieved_evidence\": [\"Section 7.4: Theory of tradeable pollution permits.\"], \"student_prompt\": \"What was the exact EU ETS carbon allowance auction clearing price on October 12, 2024 according to this document?\"}, {\"unmentioned_term\": \"the exact decibel noise mitigation threshold for Boeing 787 takeoffs at London Heathrow Airport\", \"actual_topic\": \"property rights and Coase theorem bargaining\", \"authoritative_source\": \"the UK Civil Aviation Authority (CAA) Environmental Noise Directive reports\", \"document_title\": \"Environmental Policy Instruments\", \"page\": 177, \"section\": \"The Coase Theorem\", \"selected_text\": \"Ronald Coase proved that when property rights are clearly assigned and transaction costs are negligible, private parties can negotiate efficient outcomes without government taxation.\", \"surrounding_context\": \"High transaction costs and large numbers of affected parties prevent Coasean bargaining in real-world air pollution scenarios.\", \"retrieved_evidence\": [\"Text: Requirements for Coase theorem applicability: zero transaction costs and well-defined property rights.\"], \"student_prompt\": \"According to the reading, what is the exact decibel noise mitigation threshold for Boeing 787 takeoffs at London Heathrow?\"}], \"grounded_paraphrase\": {\"document_title\": \"Welfare Economics\", \"page\": 181, \"section\": \"Market Failure Remediation\", \"selected_text\": \"Imposition of Pigouvian levies internalizes environmental externalities by realigning private marginal operational schedules with collective social expenditure curves.\", \"surrounding_context\": \"When firms pay the full social cost of their emissions, market incentives naturally reduce pollution.\", \"retrieved_evidence\": [\"Page 181: 'A tax equal to the environmental damage forces businesses to pay for their pollution, making private costs equal to social costs.'\"], \"student_prompt\": \"Can you explain this excerpt in simple words?\", \"faithful_paraphrase\": \"This excerpt means that by placing a tax on pollution equal to the damage it causes, the government forces companies to pay the real cost of their actions. Because polluting is no longer free, the company's private costs match the true cost to society, encouraging the business to reduce waste and pollute less.\"}, \"conflict_handling\": {\"document_title\": \"Environmental Economics Debates\", \"page\": 185, \"section\": \"Taxes vs Cap-and-Trade\", \"selected_text\": \"Standard theoretical microeconomics demonstrates that a Pigouvian tax and an emissions cap-and-trade system achieve identical economic efficiency when the regulator has perfect information about marginal abatement costs.\", \"surrounding_context\": \"Under certainty, setting the optimal price (tax) or setting the optimal quantity (cap) leads to the same market outcome.\", \"conflicting_evidence\": [\"Weitzman (1974) 'Prices vs. Quantities': 'Under uncertainty regarding marginal abatement costs, taxes and cap-and-trade are not equivalent: if the marginal damage curve is steep (e.g. toxic threshold hazards), a quantity cap is far safer, while if marginal damage is flat (e.g. global greenhouse gases), an emissions tax avoids devastating economic cost volatility.'\"], \"student_prompt\": \"Why does the textbook say carbon taxes and cap-and-trade are identical, while Weitzman's paper says they produce very different results under uncertainty?\", \"resolution_explanation\": \"The textbook claim assumes perfect information: if regulators know exact business costs and environmental damages, setting the price (tax) or setting the quantity (cap) leads to the exact same point on the graph. Martin Weitzman's famous insight was analyzing what happens under uncertainty when regulators must guess. If you set a carbon tax and clean-up costs turn out to be unexpectedly high, businesses pollute more than planned. If you set a cap and clean-up costs soar, permit prices explode and hurt the economy. Weitzman proved that when environmental danger has a strict tipping point (steep damage curve), you must control the quantity with a cap; but when damage accumulates slowly over decades, controlling the price with a tax provides stability.\"}}}, \"accountancy::Double-Entry Bookkeeping\": {\"domain\": \"accountancy\", \"concept\": \"Double-Entry Bookkeeping\", \"explanation\": \"an accounting system where every financial transaction is recorded in at least two accounts \u2014 a debit in one and a credit in another \u2014 keeping the accounting equation balanced\", \"reason\": \"it provides a complete record of transactions, enables error detection, and ensures the accounting equation (Assets = Liabilities + Equity) always holds\", \"concrete_examples\": [\"When a business buys a $5,000 computer with cash, it debits Equipment (asset increases) and credits Cash (asset decreases).\", \"When a company borrows $10,000 from a bank, it debits Cash (asset increases) and credits Loans Payable (liability increases).\", \"When a customer pays $1,000 for services, it debits Cash and credits Service Revenue.\"], \"numerical_examples\": [\"A company buys inventory for $3,000 on credit: Debit Inventory $3,000, Credit Accounts Payable $3,000. Assets and Liabilities both increase by $3,000.\", \"After recording Debit Rent Expense $2,000 and Credit Cash $2,000, the trial balance still balances because total debits = total credits.\", \"If total debits are $145,000 and total credits are $143,000, there is a $2,000 error that must be found.\"], \"misconceptions\": [[\"Debit always means an increase and credit always means a decrease\", \"The effect depends on the account type. Debits increase assets and expenses but decrease liabilities, equity, and revenue. Credits do the opposite. For example, crediting Cash decreases it (asset), but crediting Revenue increases it.\"]], \"analogies\": [\"Double-entry bookkeeping is like a balanced see-saw \u2014 every time you add weight (debit) on one side, you must add equal weight (credit) on the other to keep it level.\"], \"prerequisites\": [\"basic arithmetic\"], \"formulas\": [\"Assets = Liabilities + Equity\", \"Debits must always equal Credits\"], \"document_evidence\": [\"Chapter 2 states: 'The fundamental principle of double-entry is that every transaction affects at least two accounts, maintaining the balance of the accounting equation.'\", \"Example 2.3 traces a sale on credit through both the revenue and receivable accounts.\"], \"practice_problems\": [\"Record the journal entry for purchasing office supplies worth $500 with cash.\", \"A company receives $8,000 from a customer who owed money. Write the journal entry and explain which accounts are affected.\"], \"hints\": [\"Ask: What comes in? What goes out? Debit what comes in, credit what goes out.\", \"Remember DEALER: Dividends, Expenses, Assets increase with Debits; Liabilities, Equity, Revenue increase with Credits.\"], \"follow_up_questions\": [\"What happens if a transaction is only recorded in one account?\", \"How does double-entry help detect errors?\"], \"diagnostic_questions\": [\"If you debit Cash, what type of account must you credit to keep things balanced?\", \"Why is it called 'double-entry' and not 'single-entry'?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Remember that debits always represent cash coming into the company and credits represent cash leaving.\", \"error_reason\": \"Debits increase asset and expense accounts, while credits increase liability, equity, and revenue accounts; debit does not universally mean cash in, nor credit cash out.\", \"correct_claim\": \"In double-entry accounting, debit and credit simply refer to the left and right sides of a ledger entry. For example, crediting accounts payable records an increase in what you owe, not a cash outflow.\", \"understanding_probe\": \"If a company buys office supplies on credit, what is debited and what is credited?\", \"expected_answer\": \"Supplies Expense (or Supplies Asset) is debited to increase the asset/expense, and Accounts Payable is credited to increase the liability.\"}, {\"prior_erroneous_claim\": \"A transaction only needs one entry if it is very small or routine.\", \"error_reason\": \"The foundational duality postulate of double-entry bookkeeping mandates that every single transaction must have at least one debit and one credit of equal value to maintain the accounting equation.\", \"correct_claim\": \"Every transaction, regardless of size, must affect at least two accounts with total debits equaling total credits so that Assets = Liabilities + Equity remains balanced.\", \"understanding_probe\": \"Why can an accounting entry never have a debit without a corresponding credit?\", \"expected_answer\": \"Because every resource acquired has a source of financing; omitting a side breaks the fundamental accounting equation Assets = Liabilities + Equity.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Financial Accounting Principles and Ledger Mechanics\", \"page\": 24, \"section\": \"The Accounting Equation and Trial Balance\", \"selected_text\": \"On March 15, Apex Logistics acquired machinery for $45,000, paying $15,000 in cash and financing the remaining $30,000 through a long-term bank note payable.\", \"surrounding_context\": \"Table 2.1 illustrates the compound journal entry and the verification of total debit and credit equality.\", \"retrieved_evidence\": [\"Table 2.1 Compound Journal Entry: Debit Machinery (Asset) $45,000; Credit Cash (Asset) $15,000; Credit Notes Payable (Liability) $30,000.\", \"Verification calculation: Total Debits = $45,000; Total Credits = $15,000 + $30,000 = $45,000. Net change in total assets = +$45,000 - $15,000 = +$30,000, matched by +$30,000 in liabilities.\"], \"student_prompt\": \"What are the exact debits, credits, and net asset changes recorded in Table 2.1?\", \"target_response\": \"Following the explicit ledger entries in Table 2.1: The transaction records a debit of $45,000 to Machinery, a credit of $15,000 to Cash, and a credit of $30,000 to Notes Payable. Total debits ($45,000) equal total credits ($45,000). The net change in total assets is +$30,000 ($45,000 increase in machinery minus $15,000 decrease in cash), which exactly balances the $30,000 increase in liabilities.\", \"calculated_result\": \"Total Debits = $45,000, Total Credits = $45,000, Net Asset Change = +$30,000\"}, \"pattern_b_derive\": {\"document_title\": \"Intermediate Financial Accounting\", \"page\": 28, \"section\": \"Maintaining Balance Sheet Equilibrium\", \"selected_text\": \"The accounting equation Assets = Liabilities + Stockholders' Equity must hold across all transactions.\", \"surrounding_context\": \"Revenues increase retained earnings while expenses and dividends decrease retained earnings under expanded equity.\", \"retrieved_evidence\": [\"Expanded Accounting Equation: Assets = Liabilities + Common Stock + Beginning Retained Earnings + Revenues - Expenses - Dividends\", \"Balance Sheet snapshot: Assets = $320,000; Liabilities = $140,000; Common Stock = $50,000; Beginning Retained Earnings = $80,000; Revenues = $95,000; Dividends = $10,000.\"], \"student_prompt\": \"How do we derive total expenses for the period using the expanded accounting equation and the provided snapshot values?\", \"target_response\": \"To derive total expenses: Substitute the values into Assets = Liabilities + Common Stock + Beginning Retained Earnings + Revenues - Expenses - Dividends. Setting up the equation: $320,000 = $140,000 + $50,000 + $80,000 + $95,000 - Expenses - $10,000. Summing the positive equity and liability terms: $140,000 + $50,000 + $80,000 + $95,000 - $10,000 = $355,000. Thus, $320,000 = $355,000 - Expenses. Solving for Expenses yields $355,000 - $320,000 = $35,000. Total expenses for the period are $35,000.\", \"formula\": \"Assets = Liabilities + Equity + Revenues - Expenses - Dividends\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the specific Sarbanes-Oxley Section 404 compliance audit penalty for Apex Logistics\", \"actual_topic\": \"the mechanics of double-entry journal entries and the expanded accounting equation\", \"authoritative_source\": \"the Public Company Accounting Oversight Board (PCAOB) enforcement database or SEC regulatory filings\", \"document_title\": \"Ledger Mechanics and Control Accounts\", \"page\": 32, \"section\": \"Trial Balance Preparation\", \"selected_text\": \"A trial balance lists all open ledger accounts and their debit or credit balances at a specific point in time.\", \"surrounding_context\": \"If total debit balances do not match total credit balances, an error exists in ledger posting or journal entry math.\", \"retrieved_evidence\": [\"Section 1.4: Purpose of the unadjusted trial balance.\", \"Section 1.5: Steps for locating posting imbalances.\"], \"student_prompt\": \"According to this text, what fine did Apex Logistics receive under Sarbanes-Oxley Section 404?\"}, {\"unmentioned_term\": \"the cloud ERP subscription licensing costs for automated ledger software\", \"actual_topic\": \"manual journalizing and the posting process to T-accounts\", \"authoritative_source\": \"enterprise software vendor pricing guides or IT procurement documentation\", \"document_title\": \"Ledger Mechanics and Control Accounts\", \"page\": 35, \"section\": \"General Journal Entries\", \"selected_text\": \"Journal entries record chronological business transactions with dates, account titles, reference codes, and monetary amounts.\", \"surrounding_context\": \"Each transaction is transferred to general ledger accounts during the posting routine.\", \"retrieved_evidence\": [\"Exhibit 2.3: Standard two-column general journal formatting.\"], \"student_prompt\": \"What does the reading state regarding the annual cloud ERP software fee for running these ledger accounts?\"}], \"grounded_paraphrase\": {\"document_title\": \"Core Accounting Foundations\", \"page\": 18, \"section\": \"The Duality Principle\", \"selected_text\": \"The dual-aspect concept necessitates that every economic resource acquired by an entity creates an equivalent proprietary or creditor claim against those assets.\", \"surrounding_context\": \"Consequently, bookkeeping systems maintain continuous mathematical equilibrium through reciprocal debit and credit entries.\", \"retrieved_evidence\": [\"Page 18: 'Every asset acquisition generates a corresponding liability or equity claim, preserving balance.'\"], \"student_prompt\": \"Can you explain this duality principle passage in everyday words without altering its meaning?\", \"faithful_paraphrase\": \"This passage means that whenever a business gets any asset or resource, that resource was either paid for with borrowed money or provided by the owners. Because every asset is tied to where it came from, accounting records must keep assets exactly equal to liabilities plus equity through matching debits and credits.\"}, \"conflict_handling\": {\"document_title\": \"Comparative Bookkeeping Systems\", \"page\": 40, \"section\": \"Historical vs Modern Treatment of Cash Discounts\", \"selected_text\": \"Under the gross method of recording sales, sales revenue is initially recognized at the full invoice amount without deducting early settlement discounts.\", \"surrounding_context\": \"The net method, however, records receivables and revenue net of allowable cash discounts at the point of sale.\", \"retrieved_evidence\": [\"Source A (Textbook Chapter 3): Gross method records Sales at full invoice price ($1,000) and recognizes Sales Discounts ($20) only upon early payment.\", \"Source B (Industry Practice Note): Net method records Sales at discounted price ($980) and recognizes Sales Discounts Forfeited ($20) as financial income if payment is late.\"], \"student_prompt\": \"Source A says the sale is recorded at $1,000, but Source B says it is recorded at $980. Which is right?\", \"resolution_explanation\": \"Both sources are correct within their respective accounting methods. Source A describes the gross method, which records the receivable and revenue at the full $1,000 and records the $20 discount only if the buyer pays early. Source B describes the net method, which assumes the customer will take the discount and records the initial sale at $980. The choice between methods reflects whether management expects customers to take discounts, but both are acceptable under GAAP when applied consistently.\"}}}, \"accountancy::Accrual Accounting\": {\"domain\": \"accountancy\", \"concept\": \"Accrual Accounting\", \"explanation\": \"an accounting method that records revenues when earned and expenses when incurred, regardless of when cash is actually received or paid\", \"reason\": \"it provides a more accurate picture of a company's financial performance by matching revenues with the expenses that generated them in the same period\", \"concrete_examples\": [\"A law firm records revenue in December when it completes a case, even though the client pays in January.\", \"Rent expense for December is recorded in December even if the check is mailed on January 2.\", \"Insurance paid annually ($12,000) is spread as $1,000/month expense, not recorded entirely in the payment month.\"], \"numerical_examples\": [\"A company delivers $50,000 of goods in March but receives payment in April. Under accrual accounting, March revenue = $50,000; cash accounting would show $0.\", \"Prepaid insurance of $6,000 for 6 months: each month records $1,000 in insurance expense through an adjusting entry.\", \"Salaries earned by employees in December ($15,000) but paid January 5 are accrued as a liability on December 31.\"], \"misconceptions\": [[\"Accrual accounting shows how much cash a company actually has\", \"Accrual accounting shows economic performance, not cash position. A company can report high profits under accrual accounting while having very little cash because revenue was recorded when earned, not when collected. The cash flow statement shows actual cash.\"]], \"analogies\": [\"Accrual accounting is like tracking calories you EAT, not when you buy the groceries \u2014 it measures economic activity when it happens, not when money changes hands.\"], \"prerequisites\": [\"basic arithmetic\", \"double-entry bookkeeping basics\"], \"formulas\": [\"Revenue Recognition: Record when earned, not when cash received\", \"Matching Principle: Record expenses in the same period as related revenue\"], \"document_evidence\": [\"The text states: 'Under GAAP, accrual accounting is required because it better reflects economic reality than cash-basis accounting.'\", \"Example 3.5 contrasts the same transactions under cash vs. accrual accounting to show the difference.\"], \"practice_problems\": [\"A consulting firm performs $20,000 of work in November but won't be paid until January. Record the November journal entry.\", \"Prepaid rent of $24,000 covers January\u2013December. What adjusting entry is needed each month?\"], \"hints\": [\"Ask: When was the service performed or the benefit received? That's when you record it.\", \"Adjusting entries at period-end ensure revenues and expenses land in the correct period.\"], \"follow_up_questions\": [\"Why is the matching principle important for investors analyzing financial statements?\", \"What is the difference between a cash-basis and accrual-basis income statement?\"], \"diagnostic_questions\": [\"If a company received $10,000 cash for work it hasn't done yet, is that revenue under accrual accounting?\", \"Can a company be profitable on paper but unable to pay its bills? How is that possible?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Under accrual accounting, you only recognize revenue after the client sends the cash and the check clears.\", \"error_reason\": \"Accrual accounting recognizes revenue when performance obligations are satisfied, regardless of when cash is collected; cash collection only governs cash-basis accounting.\", \"correct_claim\": \"Under accrual accounting, revenue is recognized when earned\u2014when services are performed or goods delivered\u2014and an account receivable is recorded if cash has not yet been received.\", \"understanding_probe\": \"If a consulting firm completes a project on December 28 but receives payment on January 15, in which year is revenue recognized under accrual accounting?\", \"expected_answer\": \"In December of the current year, because the work was completed and the performance obligation was satisfied before year-end.\"}, {\"prior_erroneous_claim\": \"Accrued expenses are expenses that have already been paid in advance of receiving benefits.\", \"error_reason\": \"Expenses paid in advance are prepaid expenses (assets); accrued expenses are costs that have been incurred but not yet paid or billed.\", \"correct_claim\": \"Accrued expenses represent liabilities for goods or services already received or used for which payment has not yet been disbursed (e.g., accrued salaries at month-end).\", \"understanding_probe\": \"What is the key difference between a prepaid expense and an accrued expense?\", \"expected_answer\": \"A prepaid expense is paid before the expense is incurred (an asset), while an accrued expense is incurred before cash is paid (a liability).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Accrual Principles and Year-End Adjusting Entries\", \"page\": 58, \"section\": \"Accrued Interest and Payroll Calculations\", \"selected_text\": \"On December 1, Horizon Corp borrowed $120,000 on a 6-month, 8.0% annual interest note. Employees also worked the last 4 days of December, earning $3,200 per day to be paid on January 5.\", \"surrounding_context\": \"Section 3.2 details the accrued expense adjusting entries required on December 31 before closing the books.\", \"retrieved_evidence\": [\"Interest calculation: Accrued Interest = Principal * Annual Rate * (Time / 12) = $120,000 * 0.08 * (1 / 12) = $800.00.\", \"Accrued wages calculation: 4 days * $3,200/day = $12,800.00.\", \"Total accrued expense adjustments on December 31 = $800.00 + $12,800.00 = $13,600.00.\"], \"student_prompt\": \"What are the exact interest, wage, and total accrued expense adjustments required on December 31 according to Section 3.2?\", \"target_response\": \"Following the calculation explicitly provided in Section 3.2: Accrued interest for the one month in December is $120,000 * 0.08 * (1/12) = $800.00. Accrued wages for the four unbilled workdays are 4 * $3,200 = $12,800.00. Adding these together yields total accrued expense adjustments of $800.00 + $12,800.00 = $13,600.00 for the December 31 financial statements.\", \"calculated_result\": \"Accrued Interest = $800, Accrued Wages = $12,800, Total Accrual = $13,600\"}, \"pattern_b_derive\": {\"document_title\": \"Revenue Recognition and Deferred Income\", \"page\": 64, \"section\": \"Unearned Revenue Amortization\", \"selected_text\": \"When a software firm receives an upfront annual subscription fee, cash is debited and unearned revenue is credited.\", \"surrounding_context\": \"Revenue is earned ratably over the 12-month service period as performance obligations are continuously fulfilled.\", \"retrieved_evidence\": [\"Formula: Monthly Recognized Revenue = Total Contract Value / Contract Duration in Months\", \"Contract terms: Received $72,000 upfront cash payment on September 1 for a 12-month cloud hosting contract running through August 31.\"], \"student_prompt\": \"How do we derive the recognized subscription revenue and remaining unearned revenue balance as of December 31?\", \"target_response\": \"To derive the balances: First compute monthly recognized revenue: $72,000 / 12 = $6,000 per month. Next, count the elapsed months from September 1 to December 31, which is 4 months (September, October, November, December). Multiplying monthly revenue by elapsed time gives $6,000 * 4 = $24,000 in recognized revenue on the income statement. Finally, subtract recognized revenue from the upfront cash to find the ending balance: $72,000 - $24,000 = $48,000 in unearned revenue on the balance sheet.\", \"formula\": \"Recognized Revenue = (Contract Value / Months) * Elapsed Months\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the specific IRS penalty percentage for late filing of corporate Form 1120\", \"actual_topic\": \"GAAP accrual adjusting entries and revenue matching principles\", \"authoritative_source\": \"the IRS Internal Revenue Code Section 6651 guidance or the official Form 1120 instructions\", \"document_title\": \"Adjusting Accounts for Financial Statements\", \"page\": 70, \"section\": \"Matching Principle Applications\", \"selected_text\": \"The matching principle dictates that expenses incurred in generating revenues must be recognized in the identical accounting period as the related revenue.\", \"surrounding_context\": \"Adjusting entries are essential to allocate revenues and expenses to their appropriate accounting intervals.\", \"retrieved_evidence\": [\"Section 4.1: Distinction between deferrals and accruals.\", \"Section 4.2: Four major types of adjusting entries under US GAAP.\"], \"student_prompt\": \"According to this document, what is the IRS penalty percentage for filing Form 1120 late?\"}, {\"unmentioned_term\": \"the market price per share of Horizon Corp common stock\", \"actual_topic\": \"accrual adjustments for interest expense and unbilled wages\", \"authoritative_source\": \"public equity exchange ticker feeds or SEC Form 10-K market data disclosures\", \"document_title\": \"Adjusting Accounts for Financial Statements\", \"page\": 72, \"section\": \"Current Liability Disclosures\", \"selected_text\": \"Current liabilities are obligations expected to be liquidated within one operating cycle or one year, whichever is longer.\", \"surrounding_context\": \"Accounts payable, wages payable, and interest payable constitute primary current liabilities.\", \"retrieved_evidence\": [\"Table 4.4: Sample Current Liabilities Section of the Balance Sheet.\"], \"student_prompt\": \"What does this text state regarding Horizon Corp's current stock price per share?\"}], \"grounded_paraphrase\": {\"document_title\": \"Conceptual Framework for Financial Reporting\", \"page\": 50, \"section\": \"Accrual Accounting Foundations\", \"selected_text\": \"Accrual accounting depicts the effects of transactions and other events on a reporting entity's economic resources and claims in the periods in which those effects occur, even if the resulting cash receipts and payments occur in a different period.\", \"surrounding_context\": \"This provides a better basis for assessing past and future performance than solely relying on net operating cash receipts.\", \"retrieved_evidence\": [\"Page 50: 'Transactions are recorded when economic activities happen, regardless of when cash transfers occur.'\"], \"student_prompt\": \"Could you restate this passage in plain terms without changing what it means?\", \"faithful_paraphrase\": \"This passage means that accrual accounting records revenues and expenses when the actual business activity happens\u2014such as delivering a product or performing a service\u2014rather than waiting for cash to change hands. By recording transactions when they occur, financial statements show a clearer and more accurate picture of a company's real financial performance.\"}, \"conflict_handling\": {\"document_title\": \"Financial Reporting Under US GAAP and IFRS\", \"page\": 82, \"section\": \"Recognizing Contingent Accruals\", \"selected_text\": \"Under US GAAP (ASC 450), a loss contingency is accrued if it is probable and can be reasonably estimated, where probable is defined as likely to occur (typically 75-80% threshold).\", \"surrounding_context\": \"IFRS (IAS 37) uses the term provision and defines probable as more likely than not (>50% threshold).\", \"retrieved_evidence\": [\"US GAAP ASC 450: Accrue liability only when loss is 'probable' (high probability, around 75%-80%).\", \"IFRS IAS 37: Accrue provision when obligation is 'probable' defined as 'more likely than not' (>50%).\"], \"student_prompt\": \"Why does one textbook say a pending lawsuit with a 60% chance of loss must be accrued, while another says it should only be disclosed in footnotes?\", \"resolution_explanation\": \"The discrepancy arises because the textbooks are applying different accounting standards. Under IFRS (IAS 37), 'probable' means more likely than not (greater than 50%), so a 60% likelihood requires accruing a liability on the balance sheet. Under US GAAP (ASC 450), 'probable' requires a significantly higher likelihood (typically 75% to 80%); therefore, at 60%, US GAAP requires footnote disclosure rather than balance sheet accrual.\"}}}, \"accountancy::Financial Ratios\": {\"domain\": \"accountancy\", \"concept\": \"Financial Ratios\", \"explanation\": \"quantitative metrics computed from financial statement data that measure a company's profitability, liquidity, solvency, and efficiency\", \"reason\": \"they allow investors, creditors, and managers to assess financial health, compare companies, and make informed decisions\", \"concrete_examples\": [\"A company with current assets of $200,000 and current liabilities of $100,000 has a current ratio of 2.0, indicating good short-term liquidity.\", \"A profit margin of 15% means that for every $1 of revenue, the company keeps $0.15 as profit.\", \"A debt-to-equity ratio of 1.5 means the company uses $1.50 of debt for every $1 of shareholder equity.\"], \"numerical_examples\": [\"Current Ratio = $300,000 / $150,000 = 2.0 \u2014 the company can cover short-term obligations twice over.\", \"ROE = Net Income ($50,000) / Shareholder Equity ($250,000) = 20%, meaning each dollar of equity generates $0.20 of profit.\", \"Inventory Turnover = COGS ($600,000) / Average Inventory ($100,000) = 6 times per year.\"], \"misconceptions\": [[\"A higher current ratio is always better\", \"An excessively high current ratio (e.g., 8.0) may indicate the company is inefficiently using its assets \u2014 sitting on too much cash or carrying excess inventory rather than investing for growth.\"]], \"analogies\": [\"Financial ratios are like a doctor's vital signs for a company \u2014 blood pressure (liquidity), heart rate (efficiency), and temperature (profitability) each tell part of the health story.\"], \"prerequisites\": [\"basic arithmetic\", \"percentages\"], \"formulas\": [\"Current Ratio = Current Assets / Current Liabilities\", \"ROE = Net Income / Shareholder Equity\", \"Debt-to-Equity = Total Debt / Total Equity\"], \"document_evidence\": [\"Table 5.1 presents industry-average financial ratios for benchmarking.\", \"The text advises: 'No single ratio tells the full story; always analyze multiple ratios together and compare to industry benchmarks.'\"], \"practice_problems\": [\"A company has net income of $80,000, total equity of $400,000, total assets of $1,000,000, and total debt of $600,000. Calculate ROE and debt-to-equity.\", \"If current assets are $120,000 and current liabilities are $80,000, what is the current ratio? What if the company uses $40,000 cash to pay a short-term loan?\"], \"hints\": [\"Liquidity ratios use current items from the balance sheet.\", \"Profitability ratios relate earnings to revenue or equity.\"], \"follow_up_questions\": [\"Why is comparing ratios across different industries potentially misleading?\", \"How does DuPont analysis decompose ROE into its component drivers?\"], \"diagnostic_questions\": [\"If a company's current ratio is 0.8, what does that tell you about its liquidity?\", \"What is the difference between ROE and ROA?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The quick ratio includes inventory in the numerator because inventory is considered a liquid current asset.\", \"error_reason\": \"The quick ratio specifically excludes inventory and prepaid expenses because inventory cannot be converted into cash immediately without price concessions or delays.\", \"correct_claim\": \"The quick ratio (acid-test) includes only quick assets: cash, marketable securities, and accounts receivable, divided by current liabilities. Inventory is excluded.\", \"understanding_probe\": \"Why is inventory intentionally excluded from the quick ratio calculation?\", \"expected_answer\": \"Because inventory takes time to sell and convert into cash, and forced liquidation could require steep discounts, making it unreliable for meeting immediate short-term obligations.\"}, {\"prior_erroneous_claim\": \"A higher debt-to-equity ratio always indicates superior financial health and lower default risk.\", \"error_reason\": \"A high debt-to-equity ratio means the company is heavily leveraged with debt, increasing fixed interest burdens and financial distress risk during downturns.\", \"correct_claim\": \"A higher debt-to-equity ratio indicates greater financial leverage and higher risk; while it can amplify return on equity in good times, it increases vulnerability to insolvency.\", \"understanding_probe\": \"What financial risk increases when a firm significantly increases its debt-to-equity ratio?\", \"expected_answer\": \"The risk of default or bankruptcy increases because the company must service mandatory interest and principal payments regardless of operating profits.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Financial Statement Analysis and Liquidity Ratios\", \"page\": 95, \"section\": \"Assessing Working Capital Health\", \"selected_text\": \"Beacon Industrial reported the following balance sheet balances: Cash $40,000, Marketable Securities $20,000, Accounts Receivable $60,000, Inventory $80,000, Accounts Payable $70,000, and Short-Term Notes $30,000.\", \"surrounding_context\": \"Section 4.3 calculates liquidity metrics to assess short-term solvency under creditor covenants.\", \"retrieved_evidence\": [\"Current Assets = $40,000 + $20,000 + $60,000 + $80,000 = $200,000. Current Liabilities = $70,000 + $30,000 = $100,000.\", \"Step-by-step arithmetic from report: Current Ratio = Current Assets / Current Liabilities = $200,000 / $100,000 = 2.00. Quick Ratio = (Cash + Securities + Receivables) / Current Liabilities = ($40,000 + $20,000 + $60,000) / $100,000 = $120,000 / $100,000 = 1.20.\"], \"student_prompt\": \"What are the exact Current Ratio and Quick Ratio calculated for Beacon Industrial in Section 4.3?\", \"target_response\": \"Following the calculation explicitly provided in Section 4.3: Total current assets are $200,000 and total current liabilities are $100,000, giving a Current Ratio of $200,000 / $100,000 = 2.00. For the Quick Ratio, excluding inventory leaves $120,000 in quick assets, resulting in $120,000 / $100,000 = 1.20. The course evidence directly establishes the Current Ratio at 2.00 and the Quick Ratio at 1.20.\", \"calculated_result\": \"Current Ratio = 2.00, Quick Ratio = 1.20\"}, \"pattern_b_derive\": {\"document_title\": \"Corporate Profitability: DuPont Analysis\", \"page\": 102, \"section\": \"Decomposing Return on Equity\", \"selected_text\": \"The DuPont framework decomposes Return on Equity (ROE) into three distinct operating and financing drivers.\", \"surrounding_context\": \"ROE reflects net profit margin, asset turnover, and the equity multiplier.\", \"retrieved_evidence\": [\"DuPont Formula: ROE = Net Profit Margin * Asset Turnover * Equity Multiplier = (Net Income / Sales) * (Sales / Total Assets) * (Total Assets / Equity)\", \"Financial data: Net Profit Margin = 6.0% (0.06), Total Asset Turnover = 1.50, Total Assets = $500,000, Total Shareholders' Equity = $200,000.\"], \"student_prompt\": \"How do we derive the company's Equity Multiplier and overall Return on Equity (ROE) using the DuPont formula?\", \"target_response\": \"To derive ROE using the DuPont framework: First calculate the Equity Multiplier: Total Assets / Equity = $500,000 / $200,000 = 2.50. Next, apply the DuPont three-part formula: ROE = Net Profit Margin * Asset Turnover * Equity Multiplier. Multiplying these components: 0.06 * 1.50 * 2.50 = 0.09 * 2.50 = 0.225 or 22.5%. The company's Equity Multiplier is 2.50 and its overall Return on Equity is 22.5%.\", \"formula\": \"ROE = Margin * Turnover * Equity Multiplier\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the average Bloomberg terminal subscription fee for equity analysts\", \"actual_topic\": \"profitability, liquidity, and solvency ratio formulas\", \"authoritative_source\": \"Bloomberg L.P. commercial service agreements or professional financial analyst vendor catalogs\", \"document_title\": \"Handbook of Financial Ratios\", \"page\": 115, \"section\": \"Solvency and Coverage Ratios\", \"selected_text\": \"The Times Interest Earned (TIE) ratio measures the ability of a firm to meet interest obligations from operating income: EBIT / Interest Expense.\", \"surrounding_context\": \"Creditors monitor interest coverage closely to evaluate default probability during cyclical downturns.\", \"retrieved_evidence\": [\"Section 5.2: Definition and benchmark thresholds for Times Interest Earned.\", \"Section 5.3: Debt-to-Equity and Debt-to-Capitalization formulas.\"], \"student_prompt\": \"What does this text state regarding the monthly subscription cost of a Bloomberg terminal for ratio analysis?\"}, {\"unmentioned_term\": \"the exact credit rating assigned to Beacon Industrial by Moody's or S&P\", \"actual_topic\": \"balance sheet liquidity computations including Current and Quick ratios\", \"authoritative_source\": \"credit rating agency press releases from Standard & Poor's or Moody's Investors Service\", \"document_title\": \"Handbook of Financial Ratios\", \"page\": 118, \"section\": \"Credit Health Metrics\", \"selected_text\": \"Analysts assess solvency by pairing short-term liquidity ratios with long-term debt coverage metrics.\", \"surrounding_context\": \"A quick ratio above 1.0 indicates adequate liquidity under normal billing cycles.\", \"retrieved_evidence\": [\"Table 5.4: Liquidity benchmarks by manufacturing industry code.\"], \"student_prompt\": \"What specific credit rating did Moody's assign to Beacon Industrial in this document?\"}], \"grounded_paraphrase\": {\"document_title\": \"Financial Metric Interpretation\", \"page\": 90, \"section\": \"Operating Efficiency Metrics\", \"selected_text\": \"Inventory turnover metrics evaluate the velocity at which an enterprise's aggregate physical merchandise stock is monetized and replenished throughout a discrete reporting cycle.\", \"surrounding_context\": \"Higher turnover figures typically signal robust merchandising velocity and minimized working capital obsolescence.\", \"retrieved_evidence\": [\"Page 90: 'Inventory turnover reveals how many times stock is sold and replaced during a year, reflecting sales velocity.'\"], \"student_prompt\": \"Can you put this passage about inventory turnover into simple, clear words?\", \"faithful_paraphrase\": \"This passage explains that the inventory turnover ratio measures how quickly a business sells and replaces its inventory over a given year. When turnover is high, it means products are selling fast and the company is not tying up too much cash in stock sitting on warehouse shelves.\"}, \"conflict_handling\": {\"document_title\": \"Corporate Finance Reference Manual\", \"page\": 125, \"section\": \"Asset Base Selection in Turnover Ratios\", \"selected_text\": \"In calculating Total Asset Turnover (Sales / Assets), academic textbooks frequently utilize year-end ending total assets, whereas professional financial analysts mandate using average total assets.\", \"surrounding_context\": \"When a firm grows rapidly, using ending assets underestimates operating efficiency relative to average capital deployed.\", \"retrieved_evidence\": [\"Formula A (Textbook Chapter 5): Asset Turnover = Annual Sales / Ending Total Assets.\", \"Formula B (CFA Institute Standard): Asset Turnover = Annual Sales / Average Total Assets [(Beginning + Ending Assets) / 2].\"], \"student_prompt\": \"One formula calculates asset turnover using ending assets, but another uses average assets. Which should I use?\", \"resolution_explanation\": \"Both approaches are used, but they serve different contexts. Using average assets is technically superior and standard in professional analysis because sales occur across the entire year, so pairing sales with the average assets employed throughout that year aligns flow and stock measures. However, using ending assets is a common simplification when historical prior-year balance sheet data is unavailable.\"}}}, \"accountancy::Depreciation Methods\": {\"domain\": \"accountancy\", \"concept\": \"Depreciation Methods\", \"explanation\": \"systematic approaches to allocating the cost of a tangible asset over its useful life, reflecting the consumption of economic benefit\", \"reason\": \"it matches the cost of assets to the revenue they help generate and provides accurate financial reporting of asset values\", \"concrete_examples\": [\"A delivery truck purchased for $60,000 with a 5-year life and $10,000 salvage value depreciates $10,000/year under straight-line.\", \"A computer losing value quickly might use declining-balance depreciation, recording more expense in early years.\", \"A factory machine producing 100,000 units over its life uses units-of-production depreciation: expense per unit = (cost \u2212 salvage) / total units.\"], \"numerical_examples\": [\"Straight-line: ($50,000 cost \u2212 $5,000 salvage) / 10 years = $4,500/year depreciation expense.\", \"Double-declining balance, Year 1: $50,000 \u00d7 (2/10) = $10,000. Year 2: ($50,000 \u2212 $10,000) \u00d7 0.20 = $8,000.\", \"Units-of-production: ($80,000 \u2212 $8,000) / 200,000 units = $0.36 per unit. If 30,000 units produced in Year 1, depreciation = $10,800.\"], \"misconceptions\": [[\"Depreciation represents the actual decline in market value of an asset\", \"Accounting depreciation is a cost allocation method, not a valuation technique. A building might appreciate in market value while still being depreciated on the books. Depreciation allocates historical cost to expense over time.\"]], \"analogies\": [\"Depreciation is like spreading the cost of a bus pass over all the months you use it, rather than recording the full cost when you first buy it.\"], \"prerequisites\": [\"basic arithmetic\", \"percentages\"], \"formulas\": [\"Straight-Line = (Cost \u2212 Salvage) / Useful Life\", \"DDB Rate = (2 / Useful Life) \u00d7 Book Value\"], \"document_evidence\": [\"Section 8.2 states: 'Straight-line depreciation allocates equal amounts to each period, while accelerated methods front-load the expense.'\", \"Comparative Example 8.1 shows the same asset depreciated under three methods over 5 years.\"], \"practice_problems\": [\"Equipment costs $100,000, has a salvage value of $10,000, and a useful life of 6 years. Calculate Year 1 depreciation under straight-line and double-declining balance.\", \"A machine produced 50,000 units this year out of a total expected 200,000 units. Cost is $120,000, salvage $20,000. What is this year's depreciation?\"], \"hints\": [\"Straight-line gives constant annual expense; DDB gives higher early expenses.\", \"For units-of-production, the per-unit rate stays the same; the annual expense varies with output.\"], \"follow_up_questions\": [\"Why might a company choose accelerated depreciation over straight-line?\", \"How does the choice of depreciation method affect reported net income?\"], \"diagnostic_questions\": [\"What are the three pieces of information you need to calculate straight-line depreciation?\", \"If an asset's book value reaches its salvage value, can you continue to depreciate it?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The double-declining balance method subtracts salvage value from the asset cost before multiplying by the depreciation rate.\", \"error_reason\": \"Double-declining balance applies the percentage to the beginning book value (carrying amount) without subtracting salvage value, though the asset is not depreciated below salvage value.\", \"correct_claim\": \"In double-declining balance, the rate is applied to the full book value (Cost - Accumulated Depreciation) without deducting salvage value upfront. Salvage value only acts as a floor to stop depreciation.\", \"understanding_probe\": \"How is salvage value handled differently between straight-line and double-declining balance depreciation?\", \"expected_answer\": \"In straight-line, salvage value is subtracted from cost upfront to get depreciable cost; in double-declining balance, it is ignored initially and only acts as a stopping floor at the end.\"}, {\"prior_erroneous_claim\": \"Depreciation represents cash set aside in a special savings account to purchase a replacement asset when the old one wears out.\", \"error_reason\": \"Depreciation is a non-cash accounting allocation of historical cost over useful life; it does not involve any cash inflow, outflow, or reserve fund.\", \"correct_claim\": \"Depreciation is simply an allocation of historical asset cost to expense over its useful life to match revenues; it does not represent or accumulate cash.\", \"understanding_probe\": \"Does recording $10,000 of depreciation expense reduce the company's cash balance by $10,000?\", \"expected_answer\": \"No, depreciation is a non-cash expense; it reduces reported net income and asset book value, but does not affect cash directly.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Fixed Asset Accounting and Cost Allocation\", \"page\": 142, \"section\": \"Straight-Line vs Accelerated Methods\", \"selected_text\": \"Precision Tooling purchased industrial laser equipment for $100,000 on January 1, estimating a 5-year useful life and a $10,000 residual salvage value.\", \"surrounding_context\": \"Table 5.2 contrasts Year 1 and Year 2 depreciation schedules across methods.\", \"retrieved_evidence\": [\"Straight-Line calculation: Annual Depreciation = (Cost - Salvage) / Life = ($100,000 - $10,000) / 5 = $90,000 / 5 = $18,000 per year.\", \"Double-Declining Balance (DDB) rate: 2 * (1 / 5) = 40.0% per year.\", \"DDB Year 1 Expense = $100,000 * 40.0% = $40,000. Book Value ending Year 1 = $60,000.\", \"DDB Year 2 Expense = $60,000 * 40.0% = $24,000. Book Value ending Year 2 = $36,000.\"], \"student_prompt\": \"What are the exact straight-line annual expense and the DDB expenses for Year 1 and Year 2 according to Table 5.2?\", \"target_response\": \"Following the explicit calculations in Table 5.2: Straight-line annual depreciation is ($100,000 - $10,000) / 5 = $18,000 each year. Under the 40% double-declining balance method, Year 1 expense is $100,000 * 0.40 = $40,000, leaving a $60,000 book value. Year 2 DDB expense is $60,000 * 0.40 = $24,000. The course text directly establishes straight-line at $18,000 and DDB at $40,000 for Year 1 and $24,000 for Year 2.\", \"calculated_result\": \"Straight-line = $18,000/yr, DDB Year 1 = $40,000, DDB Year 2 = $24,000\"}, \"pattern_b_derive\": {\"document_title\": \"Capital Asset Management\", \"page\": 148, \"section\": \"Units-of-Production Cost Allocation\", \"selected_text\": \"Under the units-of-production method, depreciation expense varies directly with operational machine usage rather than the passage of calendar time.\", \"surrounding_context\": \"The per-unit rate allocates the depreciable base across expected lifetime operating hours.\", \"retrieved_evidence\": [\"Formula: Depreciation Rate per Unit = (Cost - Salvage Value) / Total Estimated Lifetime Production Units\", \"Asset data: Heavy delivery truck purchased for $85,000 with an estimated salvage value of $15,000 and expected lifetime service of 200,000 miles. Year 1 mileage driven = 32,000 miles.\"], \"student_prompt\": \"How do we derive the per-mile depreciation rate and total Year 1 depreciation expense using the units-of-production method?\", \"target_response\": \"To derive the expense using the units-of-production method: First calculate depreciable cost: $85,000 - $15,000 = $70,000. Divide this depreciable base by total lifetime miles: $70,000 / 200,000 miles = $0.35 per mile. Finally, multiply the per-mile rate by Year 1 actual usage: $0.35 * 32,000 miles = $11,200. Total Year 1 depreciation expense is $11,200.\", \"formula\": \"Depreciation Expense = [(Cost - Salvage) / Lifetime Units] * Units Used\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the salvage auction bid received for Precision Tooling's older CNC lathe\", \"actual_topic\": \"depreciation schedule formulas and comparison of straight-line versus DDB\", \"authoritative_source\": \"industrial auction house appraisal documents or internal fixed asset retirement slips\", \"document_title\": \"Fixed Asset Cost Allocation\", \"page\": 155, \"section\": \"Asset Impairment Testing\", \"selected_text\": \"An asset is impaired when its carrying book value exceeds its estimated undiscounted future cash flows.\", \"surrounding_context\": \"Impairment losses write down the asset book value to fair value on the balance sheet.\", \"retrieved_evidence\": [\"Section 6.1: Two-step impairment testing under US GAAP ASC 360.\"], \"student_prompt\": \"What does this chapter say about the specific salvage bid received for Precision Tooling's old CNC lathe?\"}, {\"unmentioned_term\": \"the corporate income tax rate enacted for Year 2030\", \"actual_topic\": \"straight-line and units-of-production financial accounting depreciation\", \"authoritative_source\": \"the official tax code provisions published by the Department of the Treasury\", \"document_title\": \"Fixed Asset Cost Allocation\", \"page\": 158, \"section\": \"Tax vs Book Depreciation\", \"selected_text\": \"Firms frequently maintain two sets of depreciation books: MACRS schedules for federal income taxes and straight-line for financial reporting.\", \"surrounding_context\": \"Temporary timing differences generate deferred tax assets and liabilities.\", \"retrieved_evidence\": [\"Table 6.3: Differences between MACRS half-year convention and GAAP.\"], \"student_prompt\": \"According to this text, what will the corporate income tax rate be in 2030?\"}], \"grounded_paraphrase\": {\"document_title\": \"Intermediate Financial Accounting Standards\", \"page\": 135, \"section\": \"Depreciation Concept Definition\", \"selected_text\": \"Depreciation is an accounting convention of systematic and rational cost allocation designed to amortize the capitalized expenditure of tangible property over its estimated economic utility period, rather than a valuation assessment.\", \"surrounding_context\": \"The net book value reflected on balance sheets does not purport to represent current disposable liquidation proceeds.\", \"retrieved_evidence\": [\"Page 135: 'Depreciation allocates cost over an asset's useful life; it does not measure the current market selling price.'\"], \"student_prompt\": \"Can you explain this definition of depreciation in plain language without distorting its meaning?\", \"faithful_paraphrase\": \"This passage clarifies that depreciation is simply a method for spreading the original cost of equipment or buildings across the years they are used. It is an expense allocation tool, not a way to determine what the asset would sell for on today's market.\"}, \"conflict_handling\": {\"document_title\": \"International vs Domestic Accounting\", \"page\": 162, \"section\": \"Revaluation Model for Long-Lived Assets\", \"selected_text\": \"Under US GAAP (ASC 360), property, plant, and equipment must be carried strictly at historical cost less accumulated depreciation and impairment.\", \"surrounding_context\": \"In contrast, IFRS (IAS 16) permits the revaluation model, allowing upward adjustments of fixed assets to current fair market value.\", \"retrieved_evidence\": [\"US GAAP Rule: Upward revaluations of fixed assets above historical cost are strictly prohibited.\", \"IFRS IAS 16 Rule: Entities may elect the revaluation model, crediting upward market value gains to a revaluation surplus in equity.\"], \"student_prompt\": \"One text states a company can never write up its building value when property values surge, but an international report shows an upward write-up. Why?\", \"resolution_explanation\": \"This difference is caused by the differing standards of US GAAP versus IFRS. Under US GAAP, write-ups to fair market value are strictly forbidden because of the historical cost principle. Under IFRS (IAS 16), companies have the option to adopt the revaluation model, allowing them to revalue fixed assets upward to fair market value and record the gain in a revaluation surplus within equity.\"}}}, \"accountancy::Cost-Volume-Profit Analysis\": {\"domain\": \"accountancy\", \"concept\": \"Cost-Volume-Profit Analysis\", \"explanation\": \"a managerial accounting method that examines how changes in costs, sales volume, and price affect a company's profit, particularly to find the break-even point\", \"reason\": \"it helps managers make pricing decisions, plan production levels, and assess the risk of different sales scenarios\", \"concrete_examples\": [\"A bakery selling cupcakes at $5 each with variable cost of $2 and fixed costs of $3,000/month breaks even at 1,000 cupcakes.\", \"A software company with very low variable costs per user has a low break-even point but high contribution margin.\", \"If a restaurant's fixed costs rise due to rent increases, its break-even point shifts higher.\"], \"numerical_examples\": [\"Break-even units = Fixed Costs / Contribution Margin per unit = $10,000 / ($25 \u2212 $15) = 1,000 units.\", \"To earn a target profit of $5,000 with CM per unit of $10 and fixed costs of $10,000, required sales = ($10,000 + $5,000)/$10 = 1,500 units.\", \"Contribution margin ratio = ($25 \u2212 $15) / $25 = 40%. Break-even revenue = $10,000 / 0.40 = $25,000.\"], \"misconceptions\": [[\"The break-even point only applies to manufacturing companies\", \"CVP analysis applies to ANY business \u2014 services, retail, tech startups. Every business has fixed costs, variable costs, and revenue, so break-even analysis is universally applicable.\"]], \"analogies\": [\"Break-even is like filling a swimming pool \u2014 fixed costs are the initial volume you must fill, and each unit sold adds a bucket of water (contribution margin). Once the pool is full (break-even), every additional bucket overflows as profit.\"], \"prerequisites\": [\"basic algebra\", \"percentages\"], \"formulas\": [\"Break-Even Units = Fixed Costs / (Price \u2212 Variable Cost)\", \"CM Ratio = (Price \u2212 VC) / Price\"], \"document_evidence\": [\"The text explains: 'The contribution margin is the amount each unit contributes toward covering fixed costs and generating profit.'\", \"Graph 10.1 shows how total revenue and total cost lines intersect at the break-even point.\"], \"practice_problems\": [\"A company sells widgets at $40 each, variable cost is $24, fixed costs are $48,000. Find the break-even in units and dollars.\", \"What happens to the break-even point if variable cost increases by $4 per unit?\"], \"hints\": [\"Contribution margin per unit = Price \u2212 Variable cost. This is what each unit 'contributes' to covering fixed costs.\", \"After break-even, every unit sold adds exactly the contribution margin amount to profit.\"], \"follow_up_questions\": [\"How does operating leverage affect the riskiness of a business?\", \"What is the margin of safety and why is it important?\"], \"diagnostic_questions\": [\"What does it mean when a company is 'below break-even'?\", \"If you double fixed costs, what happens to the break-even point?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The break-even point in units is calculated by dividing fixed costs by the selling price per unit.\", \"error_reason\": \"Break-even units equals fixed costs divided by contribution margin per unit (Price - Variable Cost), not selling price alone, because variable costs must also be covered.\", \"correct_claim\": \"The break-even point in units is Fixed Costs / Contribution Margin per Unit, where Contribution Margin = Unit Selling Price - Unit Variable Cost.\", \"understanding_probe\": \"Why does dividing fixed costs by selling price give an incorrect, understated break-even quantity?\", \"expected_answer\": \"Because each unit sold incurs variable production costs, so only the contribution margin\u2014the leftover portion of the selling price\u2014is actually available to pay down fixed costs.\"}, {\"prior_erroneous_claim\": \"If a company doubles its sales volume, its operating profit will always double exactly.\", \"error_reason\": \"Because fixed costs remain constant, operating leverage causes operating profit to increase by a greater percentage than sales volume.\", \"correct_claim\": \"Because fixed costs are fixed, profit increases by the full contribution margin of each additional unit sold, creating operating leverage where profit grows faster than sales.\", \"understanding_probe\": \"What is the degree of operating leverage, and how does it affect profit growth?\", \"expected_answer\": \"It measures how sensitive operating income is to percentage changes in sales; higher fixed costs create higher leverage, causing profit to grow at a faster rate than revenue.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Managerial Accounting and CVP Models\", \"page\": 175, \"section\": \"Break-Even and Target Profit Formulas\", \"selected_text\": \"Vanguard Manufacturing produces athletic gear sold at $50 per unit. Direct variable costs are $30 per unit, and annual enterprise fixed costs total $180,000.\", \"surrounding_context\": \"Section 5.2 establishes baseline break-even volume and safety margin calculations.\", \"retrieved_evidence\": [\"Contribution Margin per unit = Selling Price - Variable Cost = $50 - $30 = $20 per unit. Contribution Margin Ratio = $20 / $50 = 40.0%.\", \"Break-even units calculation: Break-Even Units = Fixed Costs / CM per unit = $180,000 / $20 = 9,000 units.\", \"Break-even revenue calculation: Break-Even Sales = Fixed Costs / CM Ratio = $180,000 / 0.40 = $450,000.\"], \"student_prompt\": \"What are the exact break-even units and break-even sales revenue computed in Section 5.2?\", \"target_response\": \"Following the explicit calculation in Section 5.2: The unit contribution margin is $50 - $30 = $20, giving a contribution margin ratio of 40%. Dividing fixed costs of $180,000 by the $20 contribution margin yields a break-even point of 9,000 units. In sales revenue, dividing $180,000 by 0.40 yields $450,000. The text directly establishes break-even volume at 9,000 units and break-even revenue at $450,000.\", \"calculated_result\": \"Break-even units = 9,000, Break-even revenue = $450,000\"}, \"pattern_b_derive\": {\"document_title\": \"Managerial Planning and Profit Sensitivity\", \"page\": 182, \"section\": \"Target Pretax Profit Planning\", \"selected_text\": \"To achieve a targeted operating profit, sales volume must cover both fixed overhead and the designated profit hurdle.\", \"surrounding_context\": \"The contribution margin from all units sold beyond break-even drops directly into operating profit.\", \"retrieved_evidence\": [\"Formula: Target Sales Units = (Fixed Costs + Target Operating Income) / Contribution Margin per Unit\", \"Operational baseline: Fixed costs = $180,000; Selling price = $50; Variable cost = $30 (CM = $20); Target operating profit = $60,000.\"], \"student_prompt\": \"How do we derive the required sales volume in units and total revenue to achieve the target profit of $60,000?\", \"target_response\": \"To derive the target sales volume: First add the target profit to fixed costs: $180,000 + $60,000 = $240,000 in total margin required. Divide this sum by the unit contribution margin: $240,000 / $20 = 12,000 units. To find total required revenue, multiply the required units by the selling price: 12,000 units * $50 = $600,000 (or divide $240,000 by the 40% CM ratio). Vanguard must sell 12,000 units generating $600,000 in revenue to achieve $60,000 in operating profit.\", \"formula\": \"Target Units = (Fixed Costs + Target Profit) / CM_unit\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the hourly union wage rate negotiated by Vanguard Manufacturing for factory workers\", \"actual_topic\": \"contribution margin ratios and break-even unit formulas\", \"authoritative_source\": \"the company's collective bargaining agreement or human resources compensation schedules\", \"document_title\": \"CVP Analysis and Operating Decisions\", \"page\": 190, \"section\": \"Sensitivity Analysis\", \"selected_text\": \"Operating leverage reflects how changes in sales volume translate into changes in operating profits.\", \"surrounding_context\": \"Firms with high fixed costs experience dramatic swings in profitability across economic cycles.\", \"retrieved_evidence\": [\"Section 6.1: Degree of Operating Leverage (DOL) formula: Contribution Margin / Operating Income.\"], \"student_prompt\": \"According to this text, what hourly union wage does Vanguard pay its factory workers?\"}, {\"unmentioned_term\": \"the commercial shipping freight rate per container from Shenzhen to Los Angeles\", \"actual_topic\": \"break-even and target profit volume formulas\", \"authoritative_source\": \"ocean freight indices like the Shanghai Containerized Freight Index (SCFI) or shipping line contracts\", \"document_title\": \"CVP Analysis and Operating Decisions\", \"page\": 194, \"section\": \"Multi-Product Sales Mix\", \"selected_text\": \"In multi-product environments, break-even analysis requires weighting contribution margins by the sales mix ratio.\", \"surrounding_context\": \"Shifts toward higher-margin products lower the aggregate break-even point.\", \"retrieved_evidence\": [\"Table 6.2: Weighted-Average Contribution Margin Calculation.\"], \"student_prompt\": \"What does the reading say about the current container freight rate from Shenzhen to Los Angeles?\"}], \"grounded_paraphrase\": {\"document_title\": \"Managerial Cost Concepts\", \"page\": 170, \"section\": \"The Contribution Margin Concept\", \"selected_text\": \"Contribution margin denotes the residual monetary inflow generated by revenue that remains accessible to defray aggregate periodic fixed commitments and subsequently accrue toward operating net income.\", \"surrounding_context\": \"Unlike gross margin, contribution margin deducts all variable costs regardless of whether they originate in manufacturing or administration.\", \"retrieved_evidence\": [\"Page 170: 'Contribution margin is the revenue left after variable costs to cover fixed costs and generate profits.'\"], \"student_prompt\": \"Can you explain this definition of contribution margin in simple words?\", \"faithful_paraphrase\": \"This passage explains that contribution margin is the money left over from each sale after paying all variable costs. That remaining cash is what the business uses first to pay off its ongoing fixed overhead, and once those fixed costs are fully covered, any additional contribution margin becomes profit.\"}, \"conflict_handling\": {\"document_title\": \"Strategic Cost Management\", \"page\": 200, \"section\": \"Linear vs Non-Linear CVP Assumptions\", \"selected_text\": \"Traditional CVP models assume unit selling prices and unit variable costs remain strictly linear and invariant across the relevant range.\", \"surrounding_context\": \"Economists, by contrast, incorporate diminishing returns and downward-sloping demand curves where marginal revenue declines.\", \"retrieved_evidence\": [\"Accounting Model: Break-even is a single unique point because Price and Variable Cost per unit are assumed constant.\", \"Economic Model: Multiple break-even points can exist because selling additional units requires reducing price, producing a parabolic total revenue curve.\"], \"student_prompt\": \"Why does my accounting book show exactly one break-even point, while my economics book shows two break-even points on the curve?\", \"resolution_explanation\": \"The models make different behavioral assumptions. Accounting CVP assumes constant unit prices and variable costs within a 'relevant range' of production, creating straight lines that intersect at a single break-even point. Economic models incorporate diminishing marginal returns and price reductions required to sell higher quantities, producing curved revenue and cost lines that often intersect twice\u2014once at low output and once at high output.\"}}}, \"accountancy::Budget Variance Analysis\": {\"domain\": \"accountancy\", \"concept\": \"Budget Variance Analysis\", \"explanation\": \"the process of comparing actual financial results to budgeted amounts to identify differences (variances) and understand their causes\", \"reason\": \"it helps managers evaluate performance, identify cost overruns or savings, and make corrective decisions\", \"concrete_examples\": [\"If the marketing department budgeted $50,000 but spent $55,000, there is an unfavorable variance of $5,000.\", \"If actual sales revenue is $120,000 against a budget of $100,000, the $20,000 favorable variance indicates better-than-expected sales.\", \"A material price variance occurs when a company pays $12/unit for raw materials instead of the budgeted $10/unit.\"], \"numerical_examples\": [\"Sales volume variance: Budget = 10,000 units at $20 = $200,000. Actual = 11,000 units at $20 = $220,000. Favorable variance = $20,000.\", \"Labor efficiency variance: Standard 2 hrs/unit \u00d7 1,000 units = 2,000 hrs budgeted. Actual = 2,200 hrs. Unfavorable variance = 200 hrs \u00d7 $15/hr = $3,000.\", \"Total variance = Price variance + Quantity variance. If price variance is \u2212$2,000 (favorable) and quantity variance is +$3,500 (unfavorable), total is +$1,500 unfavorable.\"], \"misconceptions\": [[\"An unfavorable variance always means poor management\", \"Unfavorable variances can result from factors outside management's control \u2014 supply chain disruptions, raw material price spikes, or intentional quality improvements. Context matters more than the direction of the variance.\"]], \"analogies\": [\"Variance analysis is like comparing your actual driving route to GPS directions \u2014 deviations can be bad (traffic jams) or good (shortcuts), and you need to understand the reason to judge the outcome.\"], \"prerequisites\": [\"basic arithmetic\", \"percentages\"], \"formulas\": [\"Variance = Actual \u2212 Budget\", \"Material Price Variance = (Actual Price \u2212 Standard Price) \u00d7 Actual Quantity\"], \"document_evidence\": [\"Chapter 12 states: 'Variance analysis decomposes the total difference between actual and budgeted results into price and quantity components.'\", \"Table 12.3 illustrates a complete variance analysis for a manufacturing department.\"], \"practice_problems\": [\"Budget: 5,000 units of raw material at $8/unit. Actual: 5,200 units at $7.50/unit. Calculate the material price variance and quantity variance.\", \"Is a $3,000 favorable labor rate variance always good news? Explain.\"], \"hints\": [\"Favorable = actual is better than budget (lower costs or higher revenue). Unfavorable = actual is worse.\", \"Decompose total variance into price/rate and quantity/efficiency components.\"], \"follow_up_questions\": [\"When should a manager investigate a variance versus ignoring it?\", \"How do flexible budgets improve variance analysis?\"], \"diagnostic_questions\": [\"If actual costs are lower than budgeted, is the variance favorable or unfavorable?\", \"What is the difference between a static budget variance and a flexible budget variance?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"A favorable budget variance always means company managers performed exceptionally well and should receive bonuses.\", \"error_reason\": \"A favorable variance simply means actual revenue was higher or actual cost lower than budgeted; it could result from buying inferior low-quality materials, cutting vital maintenance, or unrealistic budget targets.\", \"correct_claim\": \"A favorable variance only indicates actual results were better than budget numerically (higher revenues or lower expenses); it requires root-cause investigation because cutting quality or maintenance can harm the firm.\", \"understanding_probe\": \"Why might a 'favorable' raw materials price variance actually be bad for a manufacturing company?\", \"expected_answer\": \"Purchasing managers might have bought cheap, defective materials that caused massive production waste, machine breakdowns, or customer returns.\"}, {\"prior_erroneous_claim\": \"Flexible budget variances compare actual costs against the original static planning budget created six months ago.\", \"error_reason\": \"A flexible budget recalculates budgeted revenues and costs using the actual output level achieved, isolating cost control from volume differences.\", \"correct_claim\": \"A flexible budget adjusts budgeted costs to the actual activity level achieved, allowing managers to evaluate spending efficiency without distortion from sales volume changes.\", \"understanding_probe\": \"What is the purpose of preparing a flexible budget instead of relying on a static budget?\", \"expected_answer\": \"To isolate whether variances were caused by selling more/fewer units (volume variance) versus spending more/less per unit than planned (flexible budget variance).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Standard Costing and Variance Decomposition\", \"page\": 215, \"section\": \"Direct Materials Price and Quantity Variances\", \"selected_text\": \"Delta Chem budgeted standard direct material usage of 2.0 kg per unit at $6.00 per kg. During June, Delta produced 5,000 finished units, using 10,800 kg of chemical purchased at $5.75 per kg.\", \"surrounding_context\": \"Section 4.1 decomposes the total direct materials variance into price and efficiency components.\", \"retrieved_evidence\": [\"Formulas: Materials Price Variance (MPV) = (Actual Price - Standard Price) * Actual Quantity; Materials Quantity Variance (MQV) = (Actual Quantity - Standard Quantity Allowed) * Standard Price.\", \"Step-by-step arithmetic from report: Standard Quantity Allowed = 5,000 units * 2.0 kg = 10,000 kg. MPV = ($5.75 - $6.00) * 10,800 kg = -$0.25 * 10,800 = -$2,700 (Favorable). MQV = (10,800 kg - 10,000 kg) * $6.00 = +800 kg * $6.00 = +$4,800 (Unfavorable). Net Materials Variance = +$2,100 Unfavorable.\"], \"student_prompt\": \"What are the exact direct materials price, quantity, and net variances calculated in Section 4.1?\", \"target_response\": \"Following the explicit calculations in Section 4.1: The Materials Price Variance is ($5.75 - $6.00) * 10,800 kg = $2,700 Favorable, because material was purchased for $0.25 less per kilogram. The Materials Quantity Variance is (10,800 kg - 10,000 kg) * $6.00 = $4,800 Unfavorable, because workers consumed 800 kg more than standard. Combining these yields a Net Materials Variance of $2,100 Unfavorable ($4,800 U - $2,700 F).\", \"calculated_result\": \"Price Variance = $2,700 F, Quantity Variance = $4,800 U, Net Variance = $2,100 U\"}, \"pattern_b_derive\": {\"document_title\": \"Standard Costing Systems: Labor Standards\", \"page\": 222, \"section\": \"Direct Labor Variance Decomposition\", \"selected_text\": \"Direct labor variance analysis isolates the wage rate paid to workers from worker productivity.\", \"surrounding_context\": \"The standard labor hours allowed is based on the actual units of good output manufactured.\", \"retrieved_evidence\": [\"Formulas: Labor Rate Variance (LRV) = (Actual Rate - Standard Rate) * Actual Hours; Labor Efficiency Variance (LEV) = (Actual Hours - Standard Hours Allowed) * Standard Rate.\", \"Production data: 2,000 units produced. Standard: 1.5 hours per unit at $20.00/hr. Actual: 3,200 hours worked totaling $67,200 in payroll (Actual Rate = $21.00/hr).\"], \"student_prompt\": \"How do we derive the Labor Rate Variance and Labor Efficiency Variance from the production data?\", \"target_response\": \"To derive the labor variances: First determine standard hours allowed: 2,000 units * 1.5 hours = 3,000 hours. Next, calculate the Labor Rate Variance: (Actual Rate - Standard Rate) * Actual Hours = ($21.00 - $20.00) * 3,200 hrs = +$1.00 * 3,200 = $3,200 Unfavorable, since workers were paid $1.00/hr above standard. Then calculate the Labor Efficiency Variance: (Actual Hours - Standard Hours) * Standard Rate = (3,200 hrs - 3,000 hrs) * $20.00 = +200 hrs * $20.00 = $4,000 Unfavorable. Total labor variance is $7,200 Unfavorable.\", \"formula\": \"LRV = (AR - SR) * AH; LEV = (AH - SH) * SR\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact bonus check amount paid to Delta Chem's purchasing director\", \"actual_topic\": \"standard costing formulas for direct material price and quantity variances\", \"authoritative_source\": \"internal executive payroll records or the compensation committee minutes\", \"document_title\": \"Performance Measurement and Standard Costs\", \"page\": 230, \"section\": \"Management by Exception\", \"selected_text\": \"Management by exception focuses executive investigation only on variances that exceed designated percentage or monetary thresholds.\", \"surrounding_context\": \"Routine statistical boundaries prevent wasted managerial time investigating minor random noise.\", \"retrieved_evidence\": [\"Section 5.3: Setting variance investigation tolerance bands (e.g., \u00b15% or $5,000).\"], \"student_prompt\": \"What does this text state regarding the exact bonus paid to Delta Chem's purchasing director?\"}, {\"unmentioned_term\": \"the OSHA inspection safety compliance score for Delta Chem's manufacturing plant\", \"actual_topic\": \"direct labor efficiency and rate variance calculations\", \"authoritative_source\": \"the official Occupational Safety and Health Administration (OSHA) establishment inspection report\", \"document_title\": \"Performance Measurement and Standard Costs\", \"page\": 235, \"section\": \"Operational Benchmarking\", \"selected_text\": \"Standard hours reflect engineering time-and-motion studies designed to determine optimal labor pacing.\", \"surrounding_context\": \"Unfavorable efficiency variances often signal training deficits or equipment malfunctions.\", \"retrieved_evidence\": [\"Exhibit 5.4: Root causes of unfavorable labor efficiency in chemical batch processing.\"], \"student_prompt\": \"What is Delta Chem's official OSHA safety rating according to this document?\"}], \"grounded_paraphrase\": {\"document_title\": \"Management Control Systems\", \"page\": 210, \"section\": \"Flexible Budget Definition\", \"selected_text\": \"A flexible budget dynamically recalibrates benchmark cost projections to reflect the ex-post realized operating output, thereby isolating authentic operational cost expenditure efficiency from exogenous volume-driven distortions.\", \"surrounding_context\": \"This separation allows executive evaluation of departmental managerial control over discretionary expenses.\", \"retrieved_evidence\": [\"Page 210: 'Flexible budgets adjust targets to actual output, separating spending efficiency from sales volume changes.'\"], \"student_prompt\": \"Can you rephrase this passage about flexible budgets in everyday words?\", \"faithful_paraphrase\": \"This passage means that a flexible budget recalculates what costs should have been for the actual number of units produced. By comparing actual spending to this adjusted budget, managers can see whether costs were controlled efficiently without being misled by whether sales were higher or lower than originally planned.\"}, \"conflict_handling\": {\"document_title\": \"Advanced Cost Accounting Perspectives\", \"page\": 240, \"section\": \"Point of Purchase vs Point of Usage Variance Timing\", \"selected_text\": \"Textbooks differ on when the Direct Materials Price Variance should be recognized: at the point of raw materials purchase or at the point of production usage.\", \"surrounding_context\": \"Recognizing variances at purchase enables immediate feedback, whereas recognizing at usage couples the variance with work-in-process inventory.\", \"retrieved_evidence\": [\"Method 1 (Standard Industry Best Practice): Materials Price Variance computed on Quantity Purchased, providing immediate purchasing department accountability.\", \"Method 2 (Alternative Academic Approach): Materials Price Variance computed on Quantity Used, delaying variance recognition until materials enter the factory floor.\"], \"student_prompt\": \"Should the materials price variance be computed using the quantity of materials purchased or the quantity used in production?\", \"resolution_explanation\": \"Both methods exist in practice, but they differ in timing. Computing the price variance at the time of purchase is preferred in modern management accounting because it flags purchasing price differences immediately, allowing faster corrective action before materials sit in inventory. Computing it at the time of usage isolates variances only as goods are made, which matches inventory flow but delays accountability.\"}}}, \"accountancy::Time Value of Money\": {\"domain\": \"accountancy\", \"concept\": \"Time Value of Money\", \"explanation\": \"the principle that a dollar today is worth more than a dollar in the future because it can be invested to earn interest or returns\", \"reason\": \"it underlies all financial decision-making including investment analysis, loan pricing, and retirement planning\", \"concrete_examples\": [\"Receiving $1,000 today is better than $1,000 in 5 years because you can invest today's $1,000 and earn interest.\", \"A company comparing two projects must discount future cash flows to present value to make a fair comparison.\", \"Mortgage payments are calculated using TVM to spread a large sum into equal monthly payments over 30 years.\"], \"numerical_examples\": [\"Future Value: $1,000 at 5% for 3 years = $1,000 \u00d7 (1.05)\u00b3 = $1,157.63.\", \"Present Value: $5,000 received in 4 years at 6% = $5,000 / (1.06)\u2074 = $3,960.47.\", \"Annuity: Monthly payment on a $200,000 mortgage at 6% for 30 years = approximately $1,199/month.\"], \"misconceptions\": [[\"You can simply subtract inflation to convert future dollars to today's value\", \"Proper discounting uses compound interest mathematics, not simple subtraction. Subtracting inflation gives an approximation but becomes increasingly inaccurate for longer time periods and higher rates.\"]], \"analogies\": [\"Time value of money is like a seed \u2014 a dollar today is a seed you can plant, and it grows into more dollars over time through compounding.\"], \"prerequisites\": [\"basic arithmetic\", \"percentages\"], \"formulas\": [\"FV = PV \u00d7 (1 + r)\u207f\", \"PV = FV / (1 + r)\u207f\"], \"document_evidence\": [\"The text explains: 'The time value of money is the most important concept in finance because it enables comparison of cash flows occurring at different times.'\", \"Table 14.1 provides present value factors for common interest rates and periods.\"], \"practice_problems\": [\"What is the present value of $10,000 to be received in 5 years if the discount rate is 8%?\", \"If you invest $5,000 today at 7% annual interest, how much will you have in 10 years?\"], \"hints\": [\"Use the FV formula to grow money forward in time, PV formula to bring it back to today.\", \"Higher discount rates make future money worth less today.\"], \"follow_up_questions\": [\"How does compounding frequency (annual vs. monthly) affect the future value?\", \"Why is the discount rate sometimes called the 'opportunity cost of capital'?\"], \"diagnostic_questions\": [\"Would you prefer $10,000 today or $12,000 in 3 years? What additional information do you need to decide?\", \"If interest rates rise, what happens to the present value of future cash flows?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Compounding interest monthly gives you the exact same ending balance as compounding interest annually at the same nominal rate.\", \"error_reason\": \"More frequent compounding earns interest on previously earned interest sooner, resulting in a higher effective annual rate (EAR) than annual compounding.\", \"correct_claim\": \"Compounding more frequently (e.g., monthly vs annually) produces a higher ending balance because interest earned each month itself generates subsequent interest in future months.\", \"understanding_probe\": \"If an investment offers 12% nominal annual interest, will your effective annual return be higher with annual or monthly compounding?\", \"expected_answer\": \"Monthly compounding produces a higher effective return (12.68% vs 12.00%) because accumulated interest earns interest 12 times a year instead of once.\"}, {\"prior_erroneous_claim\": \"To find the present value of a future cash flow, you multiply the future amount by (1 + r)^n.\", \"error_reason\": \"Multiplying by (1 + r)^n computes future value (compounding); present value requires dividing by (1 + r)^n (discounting).\", \"correct_claim\": \"Present value is found by discounting: PV = FV / (1 + r)^n. Multiplying by (1 + r)^n would calculate future compounded value, not present discounted value.\", \"understanding_probe\": \"Why does money received in the future have a lower present value today when interest rates rise?\", \"expected_answer\": \"Because higher interest rates mean you could earn more by investing today, so you need less initial money today to reach that future target amount.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Corporate Finance and Capital Budgeting\", \"page\": 255, \"section\": \"Net Present Value and Discounting Mechanics\", \"selected_text\": \"An equipment upgrade requires an initial cash outlay of $50,000 and generates guaranteed net cash inflows of $20,000 at Year 1, $25,000 at Year 2, and $20,000 at Year 3. The hurdle cost of capital is 10.0%.\", \"surrounding_context\": \"Section 3.1 details the step-by-step discounted cash flow calculation of project NPV.\", \"retrieved_evidence\": [\"Discount factors at 10%: Year 1 = 1 / 1.10 = 0.9091; Year 2 = 1 / 1.10^2 = 0.8264; Year 3 = 1 / 1.10^3 = 0.7513.\", \"Step-by-step arithmetic from text: PV of Year 1 = $20,000 * 0.9091 = $18,182; PV of Year 2 = $25,000 * 0.8264 = $20,660; PV of Year 3 = $20,000 * 0.7513 = $15,026. Total PV of inflows = $18,182 + $20,660 + $15,026 = $53,868. Net Present Value = $53,868 - $50,000 initial cost = +$3,868.\"], \"student_prompt\": \"What are the present values of each year's cash flows and the resulting Net Present Value in Section 3.1?\", \"target_response\": \"Following the explicit calculations in Section 3.1: Discounting at 10% yields a Year 1 PV of $18,182, a Year 2 PV of $20,660, and a Year 3 PV of $15,026. The sum of all discounted inflows is $53,868. Subtracting the initial investment of $50,000 results in an NPV of +$3,868. Because the NPV is positive ($3,868), the investment adds economic value beyond the 10% hurdle rate.\", \"calculated_result\": \"Inflow PVs = $18,182, $20,660, $15,026; Total PV = $53,868; NPV = +$3,868\"}, \"pattern_b_derive\": {\"document_title\": \"Valuation and Interest Rate Mathematics\", \"page\": 262, \"section\": \"Present Value of an Ordinary Annuity\", \"selected_text\": \"An annuity represents a stream of equal cash payments received at regular intervals for a fixed duration.\", \"surrounding_context\": \"The present value of an ordinary annuity discounts each individual equal payment back to time zero.\", \"retrieved_evidence\": [\"Formula: PV_annuity = PMT * [ (1 - (1 + r)^(-n)) / r ]\", \"Terms: Annual payment PMT = $8,000 for n = 4 years at an annual interest rate r = 5.0% (0.05).\"], \"student_prompt\": \"How do we derive the present value of this 4-year, $8,000 annuity using the formula provided in the text?\", \"target_response\": \"To derive the present value of the annuity: Evaluate the term (1 + r)^(-n) where r = 0.05 and n = 4: 1.05^(-4) = 1 / 1.215506 = 0.822702. Next, calculate the numerator: 1 - 0.822702 = 0.177298. Divide this by the interest rate r = 0.05: 0.177298 / 0.05 = 3.54595. Finally, multiply this annuity factor by the annual payment: $8,000 * 3.54595 = $28,367.60. The present value of the annuity is $28,367.60.\", \"formula\": \"PV = PMT * [ (1 - (1+r)^-n) / r ]\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the price of gold per troy ounce on the London Bullion Market\", \"actual_topic\": \"present value formulas, discounting cash flows, and net present value\", \"authoritative_source\": \"the London Bullion Market Association (LBMA) official fixing prices\", \"document_title\": \"Principles of Time Value of Money\", \"page\": 270, \"section\": \"Perpetuities and Growing Annuities\", \"selected_text\": \"A perpetuity is a continuous stream of identical cash flows that continues indefinitely: PV = PMT / r.\", \"surrounding_context\": \"Preferred stock dividends that never mature are traditionally valued as perpetuities.\", \"retrieved_evidence\": [\"Section 4.2: Derivation of the constant perpetuity formula.\"], \"student_prompt\": \"According to this document, what was the price of gold per ounce on the London exchange?\"}, {\"unmentioned_term\": \"the sovereign credit default swap spread for Japanese government bonds\", \"actual_topic\": \"ordinary annuity discounting and capital budgeting NPV mechanics\", \"authoritative_source\": \"financial market pricing feeds from S&P Global Market Intelligence or Markit CDS data\", \"document_title\": \"Principles of Time Value of Money\", \"page\": 274, \"section\": \"Risk-Adjusted Discount Rates\", \"selected_text\": \"The discount rate incorporates both pure time preference and an adjustment for project uncertainty.\", \"surrounding_context\": \"Higher risk projects require higher hurdle rates to compensate capital providers.\", \"retrieved_evidence\": [\"Figure 4.4: Capital Asset Pricing Model security market line.\"], \"student_prompt\": \"What does this chapter state regarding the sovereign CDS spread for Japanese debt?\"}], \"grounded_paraphrase\": {\"document_title\": \"Corporate Finance Theory\", \"page\": 250, \"section\": \"The Fundamental TVM Axiom\", \"selected_text\": \"A monetary unit acquired at the present juncture possesses superior economic value relative to an identical unit received prospectively, attributable to its intrinsic capacity to generate interim investment yields and compensate for temporal postponement.\", \"surrounding_context\": \"Consequently, intertemporal financial comparisons necessitate discounting all cash flows to an equivalent epoch.\", \"retrieved_evidence\": [\"Page 250: 'Money today is worth more than money tomorrow because it can be invested to earn returns immediately.'\"], \"student_prompt\": \"Can you reword this passage explaining the time value of money into clear, simple terms?\", \"faithful_paraphrase\": \"This passage explains the basic rule of the time value of money: a dollar in your hand today is worth more than a dollar you might get in the future. That is because you can invest today's dollar right away to earn interest, whereas waiting for future money costs you that earning opportunity.\"}, \"conflict_handling\": {\"document_title\": \"Capital Budgeting Comparison Guide\", \"page\": 280, \"section\": \"NPV vs IRR in Mutually Exclusive Projects\", \"selected_text\": \"When choosing between mutually exclusive projects of differing scales, the Internal Rate of Return (IRR) can favor a smaller high-percentage project, whereas Net Present Value (NPV) selects the project adding the most total dollar wealth.\", \"surrounding_context\": \"Finance theory universally establishes that NPV takes precedence over IRR because it directly maximizes shareholder wealth.\", \"retrieved_evidence\": [\"Project Alpha: NPV = $50,000, IRR = 22%. Initial cost = $500,000.\", \"Project Beta: NPV = $15,000, IRR = 35%. Initial cost = $30,000.\", \"Textbook Conflict Note: Ranking by IRR chooses Project Beta (35% > 22%), but ranking by NPV chooses Project Alpha ($50k > $15k).\"], \"student_prompt\": \"Project Beta has a 35% IRR while Project Alpha has a 22% IRR, but the report says to choose Project Alpha. Why?\", \"resolution_explanation\": \"This conflict is a classic capital budgeting ranking dilemma between IRR and NPV for mutually exclusive projects. Even though Project Beta has a higher percentage return (35% vs 22%), it is on a tiny investment of $30,000, creating only $15,000 in added wealth. Project Alpha generates $50,000 in net present value dollar wealth. Finance theory dictates choosing Project Alpha because maximizing total dollar shareholder wealth (NPV) always takes precedence over percentage return (IRR).\"}}}, \"accountancy::Inventory Valuation\": {\"domain\": \"accountancy\", \"concept\": \"Inventory Valuation\", \"explanation\": \"the method used to assign costs to inventory items (FIFO, LIFO, or weighted average), which affects reported cost of goods sold and ending inventory value\", \"reason\": \"the chosen method impacts reported profits, taxes, and balance sheet values, especially when prices are changing\", \"concrete_examples\": [\"Under FIFO (First-In, First-Out), the oldest inventory costs are expensed first. If early purchases were cheaper, FIFO reports higher profit.\", \"Under LIFO (Last-In, First-Out), the newest costs are expensed first. During rising prices, LIFO reports lower profit and lower taxes.\", \"Weighted average assigns the same average cost per unit to both COGS and ending inventory.\"], \"numerical_examples\": [\"Purchases: 100 units at $10, then 100 units at $14. Sold 120 units. FIFO COGS = (100\u00d7$10) + (20\u00d7$14) = $1,280. LIFO COGS = (100\u00d7$14) + (20\u00d7$10) = $1,600.\", \"Weighted average: Total cost = $2,400 / 200 units = $12/unit. COGS for 120 units = $1,440.\", \"The FIFO vs LIFO difference in COGS ($320) directly impacts pre-tax profit by the same amount.\"], \"misconceptions\": [[\"FIFO and LIFO refer to the physical flow of goods\", \"FIFO and LIFO are cost flow assumptions, not descriptions of how goods physically move through a warehouse. A company can ship the newest items first while using FIFO for costing purposes.\"]], \"analogies\": [\"Inventory valuation is like choosing which bills in your wallet to spend first \u2014 you can use the oldest ones (FIFO), the newest ones (LIFO), or treat them all as equally worn (weighted average).\"], \"prerequisites\": [\"basic arithmetic\"], \"formulas\": [\"COGS = Beginning Inventory + Purchases \u2212 Ending Inventory\"], \"document_evidence\": [\"Section 7.4 states: 'Under rising prices, FIFO produces higher reported income and higher ending inventory values compared to LIFO.'\", \"Comparative Example 7.2 calculates COGS under all three methods using identical purchase data.\"], \"practice_problems\": [\"Given three purchases (50 units at $8, 60 units at $10, 40 units at $12) and 90 units sold, calculate COGS under FIFO and LIFO.\", \"Explain why a company might choose LIFO during a period of rising prices.\"], \"hints\": [\"FIFO: oldest costs go to COGS. LIFO: newest costs go to COGS.\", \"During rising prices: FIFO = higher profit, higher taxes; LIFO = lower profit, lower taxes.\"], \"follow_up_questions\": [\"Why is LIFO not permitted under International Financial Reporting Standards (IFRS)?\", \"How does the choice of inventory method affect the balance sheet?\"], \"diagnostic_questions\": [\"If prices are rising, which method reports higher net income: FIFO or LIFO?\", \"What does 'cost flow assumption' mean, and why does it matter?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"During periods of rising prices, FIFO results in higher cost of goods sold and lower reported net income than LIFO.\", \"error_reason\": \"In inflation, FIFO assumes the oldest, cheapest goods are sold first, resulting in lower COGS and higher reported net income; LIFO assigns the newest, most expensive goods to COGS.\", \"correct_claim\": \"Under rising prices, FIFO results in lower COGS (because older, lower costs are matched to sales) and higher net income, while LIFO yields higher COGS and lower net income.\", \"understanding_probe\": \"Why do companies often prefer LIFO for income tax purposes during periods of sustained inflation?\", \"expected_answer\": \"Because LIFO reports higher COGS, which reduces reported taxable income and thereby lowers immediate cash income tax payments.\"}, {\"prior_erroneous_claim\": \"Under US GAAP, companies can freely switch back and forth between FIFO and LIFO each month to maximize earnings.\", \"error_reason\": \"The consistency principle prohibits arbitrary accounting changes; switching methods requires formal justification that the new method is preferable and retrospective financial restatement.\", \"correct_claim\": \"GAAP enforces the consistency principle: inventory valuation methods must be applied uniformly from period to period; changing methods requires justification and retrospective restatement.\", \"understanding_probe\": \"What accounting principle prevents a company from changing its inventory valuation method every quarter?\", \"expected_answer\": \"The consistency principle, which ensures financial statements are comparable across different years and prevents earnings manipulation.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Inventory Accounting and Cost Flow Assumptions\", \"page\": 295, \"section\": \"FIFO vs LIFO Cost Allocations\", \"selected_text\": \"Retail Goods Inc. started the month with 100 units at $10.00. Purchases were: Day 10, 200 units at $12.00; Day 20, 150 units at $14.00. Total available goods: 450 units costing $5,500. On Day 25, 300 units were sold.\", \"surrounding_context\": \"Section 3.2 compares the ending inventory and Cost of Goods Sold under FIFO and LIFO periodic systems.\", \"retrieved_evidence\": [\"FIFO allocation: 300 units sold come from Beginning (100 @ $10 = $1,000) + Day 10 (200 @ $12 = $2,400) = COGS $3,400. Ending inventory = 150 units @ $14 = $2,100.\", \"LIFO allocation: 300 units sold come from Day 20 (150 @ $14 = $2,100) + Day 10 (150 @ $12 = $1,800) = COGS $3,900. Ending inventory = 100 @ $10 + 50 @ $12 = $1,000 + $600 = $1,600.\"], \"student_prompt\": \"What are the exact COGS and ending inventory balances for both FIFO and LIFO calculated in Section 3.2?\", \"target_response\": \"Following the explicit calculations in Section 3.2: Under FIFO, Cost of Goods Sold is $1,000 + $2,400 = $3,400, and ending inventory is $2,100 (150 units at $14). Under LIFO, Cost of Goods Sold is $2,100 + $1,800 = $3,900, and ending inventory is $1,000 + $600 = $1,600. The text directly establishes that FIFO yields $3,400 COGS and $2,100 ending inventory, while LIFO yields $3,900 COGS and $1,600 ending inventory.\", \"calculated_result\": \"FIFO: COGS = $3,400, End Inv = $2,100; LIFO: COGS = $3,900, End Inv = $1,600\"}, \"pattern_b_derive\": {\"document_title\": \"Inventory Valuation: Lower of Cost or Market\", \"page\": 302, \"section\": \"LCM Ceiling and Floor Derivations\", \"selected_text\": \"Under US GAAP (ASC 330), when evaluating inventory under the lower-of-cost-or-market rule, 'market' is constrained by a ceiling and a floor.\", \"surrounding_context\": \"Designated market value is the middle value among replacement cost, net realizable value (ceiling), and net realizable value less normal profit margin (floor).\", \"retrieved_evidence\": [\"Formulas: Ceiling = Estimated Selling Price - Disposal Costs; Floor = Ceiling - Normal Profit Margin.\", \"Item data: Inventory cost = $80. Selling price = $100; Disposal shipping costs = $10; Normal profit margin = 20% of selling price ($20); Current replacement cost = $65.\"], \"student_prompt\": \"How do we derive the ceiling, floor, designated market value, and final LCM inventory valuation?\", \"target_response\": \"To derive the lower of cost or market valuation: First calculate the ceiling (NRV): $100 selling price - $10 disposal cost = $90. Next calculate the floor: $90 ceiling - $20 normal profit = $70. Now compare replacement cost ($65), ceiling ($90), and floor ($70). Designated market value is the middle value: since replacement cost ($65) is below the floor ($70), designated market value is capped at the floor of $70. Finally, compare designated market value ($70) with original historical cost ($80). Lower of cost or market dictates valuing the inventory at $70 per unit.\", \"formula\": \"Market = Mid(Replacement Cost, NRV Ceiling, Floor); Valuation = Min(Cost, Market)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the pallet rack aisle width safety clearance required in Amazon fulfillment centers\", \"actual_topic\": \"cost flow assumptions including FIFO, LIFO, and lower-of-cost-or-market rules\", \"authoritative_source\": \"OSHA warehouse safety standards or internal Amazon logistics facility specifications\", \"document_title\": \"Principles of Inventory Accounting\", \"page\": 312, \"section\": \"Periodic vs Perpetual Systems\", \"selected_text\": \"A perpetual inventory system continuously records changes in inventory and cost of goods sold as sales transactions take place.\", \"surrounding_context\": \"Bar-code scanning and point-of-sale software have made perpetual systems standard across commercial retail.\", \"retrieved_evidence\": [\"Section 4.1: Ledger entries for perpetual inventory purchases and sales.\"], \"student_prompt\": \"What does this text state regarding the minimum pallet rack aisle width in Amazon fulfillment warehouses?\"}, {\"unmentioned_term\": \"the exact wholesale spot price of copper wire on the London Metal Exchange\", \"actual_topic\": \"weighted average and specific identification inventory valuation techniques\", \"authoritative_source\": \"London Metal Exchange (LME) official daily cash contract settlement reports\", \"document_title\": \"Principles of Inventory Accounting\", \"page\": 315, \"section\": \"Cost Allocation Variations\", \"selected_text\": \"The weighted-average cost method allocates cost based on the average unit cost of all identical goods available for sale during the period.\", \"surrounding_context\": \"This method smooths price fluctuations across volatile commodity markets.\", \"retrieved_evidence\": [\"Formula: Weighted Average Unit Cost = Total Cost of Goods Available / Total Units Available.\"], \"student_prompt\": \"What does the reading cite as today's London Metal Exchange spot price for copper wire?\"}], \"grounded_paraphrase\": {\"document_title\": \"Intermediate Financial Accounting\", \"page\": 290, \"section\": \"Cost Flow Assumptions vs Physical Movement\", \"selected_text\": \"Inventory accounting cost flow assumptions denote systematic financial allocation methodologies and are intentionally disassociated from the empirical chronological physical sequence in which tangible goods are physically removed from storage.\", \"surrounding_context\": \"An enterprise may legally utilize LIFO financial accounting even while physically rotating merchandise on a strict first-in, first-out stock management schedule.\", \"retrieved_evidence\": [\"Page 290: 'Cost flow assumptions are accounting rules for calculating costs; they do not dictate how goods physically move off the shelf.'\"], \"student_prompt\": \"Can you explain this passage about inventory cost flows in clear, simple terms?\", \"faithful_paraphrase\": \"This passage clarifies that inventory methods like FIFO and LIFO are just accounting formulas for tracking dollars, not rules for how warehouse workers handle physical boxes. A company can use LIFO on its financial books to save on taxes while physically shipping its oldest products first to prevent spoilage.\"}, \"conflict_handling\": {\"document_title\": \"International Accounting Comparison\", \"page\": 320, \"section\": \"The International Prohibition of LIFO\", \"selected_text\": \"Under US GAAP (ASC 330), LIFO is a fully permitted inventory valuation assumption, supported by the IRS LIFO conformity rule.\", \"surrounding_context\": \"In contrast, International Financial Reporting Standards (IAS 2) strictly prohibits the use of LIFO for all financial statements.\", \"retrieved_evidence\": [\"US GAAP Rule: LIFO is permitted, and if used for tax purposes, must also be used for financial reporting (LIFO Conformity Rule).\", \"IFRS IAS 2 Rule: LIFO is explicitly banned because it leaves outdated historical costs on the balance sheet, distorting asset valuation.\"], \"student_prompt\": \"Why does a US textbook teach LIFO calculations while a European corporate accounting guide says LIFO is completely forbidden?\", \"resolution_explanation\": \"This conflict stems from differing jurisdictional standards. Under US GAAP, LIFO is allowed and widely used because US tax law allows companies to use LIFO to lower taxable income, provided they also use it on their financial statements (the LIFO conformity rule). Under IFRS (IAS 2), which governs European and many international companies, LIFO is strictly prohibited because standard-setters concluded that reporting decades-old inventory costs on the balance sheet distorts financial reality.\"}}}, \"accountancy::Tax Principles\": {\"domain\": \"accountancy\", \"concept\": \"Tax Principles\", \"explanation\": \"the fundamental rules governing how taxes are assessed, including concepts like progressive taxation, deductions, credits, and the difference between tax avoidance and evasion\", \"reason\": \"understanding tax principles is essential for compliance, planning, and making informed financial decisions that minimize legal tax liability\", \"concrete_examples\": [\"In a progressive tax system, someone earning $50,000 pays a lower effective rate than someone earning $200,000 because higher brackets are taxed at higher rates.\", \"A business deducting $10,000 in office rent reduces its taxable income by $10,000, not its tax bill by $10,000.\", \"A $2,000 tax credit reduces the actual tax owed by $2,000, dollar-for-dollar, unlike a deduction.\"], \"numerical_examples\": [\"With brackets of 10% up to $10,000 and 22% on $10,001-$40,000: tax on $30,000 income = ($10,000 \u00d7 0.10) + ($20,000 \u00d7 0.22) = $1,000 + $4,400 = $5,400.\", \"Effective tax rate = $5,400 / $30,000 = 18%, which is lower than the marginal rate of 22%.\", \"A $1,000 deduction for someone in the 22% bracket saves $220 in taxes, while a $1,000 credit saves the full $1,000.\"], \"misconceptions\": [[\"Moving into a higher tax bracket means ALL your income is taxed at the higher rate\", \"Tax brackets are marginal \u2014 only the income above the threshold is taxed at the higher rate. If the 22% bracket starts at $40,000, earning $41,000 means only the last $1,000 is taxed at 22%, not all $41,000.\"]], \"analogies\": [\"Progressive tax brackets are like filling stacked cups \u2014 the first cup fills at a low rate, the next at a higher rate, but only the water in each cup is taxed at that cup's rate.\"], \"prerequisites\": [\"basic arithmetic\", \"percentages\"], \"formulas\": [\"Effective Tax Rate = Total Tax / Total Income\", \"Tax Savings from Deduction = Deduction Amount \u00d7 Marginal Rate\"], \"document_evidence\": [\"The text states: 'A tax deduction reduces taxable income, while a tax credit directly reduces the tax liability \u2014 credits are generally more valuable.'\", \"Table 15.1 shows current federal income tax brackets and rates.\"], \"practice_problems\": [\"Calculate the total tax and effective rate for someone earning $75,000 using the bracket: 10% up to $10,000, 12% from $10,001\u2013$40,000, 22% from $40,001\u2013$85,000.\", \"Compare the tax savings of a $5,000 deduction vs. a $5,000 credit for someone in the 24% bracket.\"], \"hints\": [\"Tax brackets are marginal \u2014 apply each rate only to the income within that bracket.\", \"Credits reduce tax owed; deductions reduce taxable income. Credits are almost always worth more.\"], \"follow_up_questions\": [\"What is the difference between tax avoidance (legal) and tax evasion (illegal)?\", \"Why do governments offer tax credits for certain activities like education or renewable energy?\"], \"diagnostic_questions\": [\"If someone says 'I don't want a raise because it'll put me in a higher tax bracket,' what misconception do they have?\", \"Is a $1,000 deduction or a $500 credit worth more to someone in the 30% bracket?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"If a taxpayer enters a higher marginal tax bracket, all of their previous income is also taxed at that higher rate.\", \"error_reason\": \"Progressive tax systems use marginal brackets: only the incremental income falling within the higher bracket is taxed at the higher rate, not prior income.\", \"correct_claim\": \"Under a progressive marginal tax bracket system, each tax rate applies only to the slice of income within that specific bracket; moving into a higher bracket never reduces total after-tax income on earlier dollars.\", \"understanding_probe\": \"If you earn $1 more and cross into a 32% tax bracket from a 24% bracket, does your entire salary get taxed at 32%?\", \"expected_answer\": \"No, only that additional $1 is taxed at 32%; all your prior earnings continue to be taxed at the lower rates of the preceding brackets.\"}, {\"prior_erroneous_claim\": \"A tax deduction of $1,000 saves you $1,000 in actual taxes owed, exactly like a tax credit.\", \"error_reason\": \"A deduction reduces taxable income, saving Taxpayer * Marginal Tax Rate; a tax credit reduces the final tax bill dollar-for-dollar.\", \"correct_claim\": \"A tax deduction reduces taxable income (saving $1,000 * marginal rate, e.g., $240 at a 24% rate), whereas a tax credit reduces your actual tax liability dollar-for-dollar ($1,000 savings).\", \"understanding_probe\": \"Which provides greater tax savings for a taxpayer in the 22% bracket: a $1,000 tax deduction or a $1,000 tax credit?\", \"expected_answer\": \"The $1,000 tax credit, because it reduces the tax bill by the full $1,000, whereas the deduction only reduces taxes by $220 ($1,000 * 22%).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Tax Principles and Corporate Taxation\", \"page\": 335, \"section\": \"Effective vs Marginal Tax Rate Calculations\", \"selected_text\": \"An individual taxpayer has taxable income of $100,000 subject to three progressive tax brackets: Bracket 1: $0 to $20,000 at 10.0%; Bracket 2: $20,001 to $80,000 at 20.0%; Bracket 3: $80,001 to $100,000 at 30.0%.\", \"surrounding_context\": \"Section 2.3 computes the exact total tax liability, marginal rate, and effective average tax rate.\", \"retrieved_evidence\": [\"Bracket 1 tax = $20,000 * 0.10 = $2,000.\", \"Bracket 2 tax = ($80,000 - $20,000) * 0.20 = $60,000 * 0.20 = $12,000.\", \"Bracket 3 tax = ($100,000 - $80,000) * 0.30 = $20,000 * 0.30 = $6,000.\", \"Total tax calculation: Total Tax = $2,000 + $12,000 + $6,000 = $20,000. Effective Tax Rate = Total Tax / Total Taxable Income = $20,000 / $100,000 = 20.0%. Marginal Tax Rate = 30.0%.\"], \"student_prompt\": \"What are the exact total tax liability and effective tax rate calculated in Section 2.3?\", \"target_response\": \"Following the explicit calculation in Section 2.3: Tax in Bracket 1 is $2,000 ($20,000 * 10%), tax in Bracket 2 is $12,000 ($60,000 * 20%), and tax in Bracket 3 is $6,000 ($20,000 * 30%). Summing these gives a total tax liability of $2,000 + $12,000 + $6,000 = $20,000. Dividing total tax by total income yields an effective tax rate of $20,000 / $100,000 = 20.0%, while the marginal rate on the last dollar is 30.0%.\", \"calculated_result\": \"Total Tax = $20,000, Effective Tax Rate = 20.0%, Marginal Tax Rate = 30.0%\"}, \"pattern_b_derive\": {\"document_title\": \"Municipal Bonds and Tax-Exempt Yield Equivalence\", \"page\": 342, \"section\": \"Taxable Equivalent Yield Formula\", \"selected_text\": \"Interest earned on municipal bonds is generally exempt from federal income taxation, creating an incentive for investors in high marginal brackets.\", \"surrounding_context\": \"Investors compare tax-exempt municipal bonds against taxable corporate bonds using taxable equivalent yield.\", \"retrieved_evidence\": [\"Formula: Taxable Equivalent Yield (TEY) = Tax-Exempt Municipal Yield / (1 - Marginal Tax Rate)\", \"Market conditions: City municipal bond yields 4.20% tax-free. Investor has a marginal federal income tax rate of 30.0% (0.30).\"], \"student_prompt\": \"How do we derive the taxable equivalent yield for this investor from the formula in the reading?\", \"target_response\": \"To derive the taxable equivalent yield: Substitute the values into TEY = Tax-Exempt Yield / (1 - Marginal Tax Rate). The denominator is 1 - 0.30 = 0.70. Dividing the municipal yield by 0.70 gives: 4.20% / 0.70 = 6.00%. This means a taxable corporate bond would need to yield at least 6.00% to match the after-tax return of the 4.20% municipal bond for an investor in the 30% tax bracket.\", \"formula\": \"TEY = Municipal Yield / (1 - Marginal Rate)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the state sales tax rate on retail apparel purchases in Austin, Texas\", \"actual_topic\": \"progressive income tax structures, effective tax rates, and tax-equivalent yields\", \"authoritative_source\": \"the Texas Comptroller of Public Accounts tax rate locator database\", \"document_title\": \"Foundations of Taxation\", \"page\": 350, \"section\": \"Classification of Taxes\", \"selected_text\": \"Taxes are categorized into progressive, proportional (flat), and regressive structures based on how the effective tax rate changes with income.\", \"surrounding_context\": \"Sales and excise taxes are generally regressive because lower-income households spend a larger percentage of income on taxed consumption.\", \"retrieved_evidence\": [\"Section 3.1: Definitions of progressive, regressive, and proportional taxation.\"], \"student_prompt\": \"According to this chapter, what is the exact sales tax percentage on clothing in Austin, Texas?\"}, {\"unmentioned_term\": \"the exact foreign tax credit limitation dollar threshold on IRS Form 1116\", \"actual_topic\": \"marginal tax brackets and municipal bond taxable equivalent yields\", \"authoritative_source\": \"IRS Publication 514 and official instructions for Form 1116 Foreign Tax Credit\", \"document_title\": \"Foundations of Taxation\", \"page\": 355, \"section\": \"Tax Credits vs Tax Deductions\", \"selected_text\": \"Tax credits reduce tax liability dollar-for-dollar and may be nonrefundable or refundable.\", \"surrounding_context\": \"The Child Tax Credit and Earned Income Tax Credit are prominent individual tax credits.\", \"retrieved_evidence\": [\"Table 3.4: Comparison of refundable versus nonrefundable credits under federal law.\"], \"student_prompt\": \"What does this text state regarding the specific foreign tax credit cap on Form 1116?\"}], \"grounded_paraphrase\": {\"document_title\": \"Public Finance and Tax Policy\", \"page\": 330, \"section\": \"Horizontal and Vertical Equity\", \"selected_text\": \"Vertical equity posits that taxpayers endowed with superior ability to contribute financial resources should bear an escalating proportion of public fiscal burdens, whereas horizontal equity mandates egalitarian tax incidence across economically homogeneous cohorts.\", \"surrounding_context\": \"These ethical norms underpin the design of progressive rate brackets and standard deduction thresholds.\", \"retrieved_evidence\": [\"Page 330: 'Vertical equity means higher earners pay higher rates; horizontal equity means equals are taxed equally.'\"], \"student_prompt\": \"Can you explain what horizontal and vertical equity mean based on this passage in simple terms?\", \"faithful_paraphrase\": \"This passage outlines two basic fairness principles in taxation. Vertical equity means that people who earn more money should pay a higher percentage of their income in taxes because they have a greater ability to pay. Horizontal equity means that people who earn the same income and are in similar financial situations should be taxed equally.\"}, \"conflict_handling\": {\"document_title\": \"Tax Accounting Reference\", \"page\": 360, \"section\": \"Book Income vs Taxable Income Differences\", \"selected_text\": \"Net income reported on corporate GAAP financial statements rarely equals taxable income reported on IRS Form 1120.\", \"surrounding_context\": \"Differences are categorized as permanent differences (e.g., municipal interest, fines) or temporary differences (e.g., accelerated depreciation).\", \"retrieved_evidence\": [\"Source A (Annual Report 10-K): Pre-tax GAAP income is $1,000,000 and Income Tax Expense on the income statement is $210,000 (21%).\", \"Source B (IRS Form 1120): Taxable income is $800,000 and current taxes paid to the IRS are $168,000 (21% * $800,000).\"], \"student_prompt\": \"Why does the annual report show $210,000 in income tax expense when the company only paid $168,000 in cash taxes to the IRS?\", \"resolution_explanation\": \"This discrepancy occurs because of temporary differences between GAAP financial accounting and IRS tax rules. For tax purposes, the company took accelerated depreciation, lowering its current taxable income to $800,000 and cash taxes to $168,000. However, under GAAP (ASC 740), financial statements recognize total tax expense on the full $1,000,000 book income ($210,000), recording the $42,000 difference as a deferred tax liability that will be paid in future years as tax depreciation diminishes.\"}}}, \"accountancy::Audit Procedures\": {\"domain\": \"accountancy\", \"concept\": \"Audit Procedures\", \"explanation\": \"the systematic methods auditors use to gather evidence and form an opinion on whether financial statements are fairly presented in accordance with accounting standards\", \"reason\": \"they provide assurance to stakeholders that financial information is reliable, complete, and free from material misstatement\", \"concrete_examples\": [\"An auditor sends confirmation letters to a company's customers to verify that accounts receivable balances are accurate.\", \"Physical inventory counts involve auditors visiting warehouses to count and compare actual stock against recorded amounts.\", \"Analytical procedures compare current-year financial ratios to prior years and industry averages to identify unusual fluctuations.\"], \"numerical_examples\": [\"If the company reports $2 million in receivables but confirmations verify only $1.85 million, the $150,000 discrepancy requires investigation.\", \"An auditor sets materiality at 5% of net income. If net income is $500,000, any misstatement over $25,000 is material.\", \"Sampling: If the auditor tests 50 out of 5,000 invoices and finds 3 errors, the projected error rate is 6%, suggesting further investigation.\"], \"misconceptions\": [[\"An audit guarantees that the financial statements are 100% correct\", \"An audit provides 'reasonable assurance,' not absolute certainty. Auditors use sampling and professional judgment, and there is always some risk that a material misstatement goes undetected. Fraud deliberately designed to evade detection may escape even a well-conducted audit.\"]], \"analogies\": [\"An audit is like a health check-up \u2014 the doctor runs tests and examines samples but can't check every cell in your body. They provide reasonable confidence about your health, not a guarantee.\"], \"prerequisites\": [\"basic arithmetic\", \"understanding of financial statements\"], \"formulas\": [\"Materiality Threshold = Percentage \u00d7 Base Amount (e.g., 5% of net income)\"], \"document_evidence\": [\"The auditing standards state: 'The auditor must obtain sufficient appropriate evidence to support the opinion on the financial statements.'\", \"ISA 500 outlines the types of audit evidence: inspection, observation, confirmation, recalculation, and inquiry.\"], \"practice_problems\": [\"If net income is $1,000,000 and materiality is set at 3%, what is the materiality threshold? What types of errors would be considered immaterial?\", \"An auditor finds that 4 out of 40 sampled transactions have documentation errors. What should the auditor do next?\"], \"hints\": [\"Audit evidence should be both sufficient (enough) and appropriate (relevant and reliable).\", \"The higher the risk, the more evidence the auditor needs to gather.\"], \"follow_up_questions\": [\"What is the difference between an internal audit and an external audit?\", \"What are the auditor's options if they discover a material misstatement that management refuses to correct?\"], \"diagnostic_questions\": [\"Why do auditors use sampling rather than checking every single transaction?\", \"What does 'reasonable assurance' mean in the context of an audit?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"An external financial statement audit certifies with 100% absolute certainty that a company's financial statements are completely free of all fraud and error.\", \"error_reason\": \"Auditors provide 'reasonable assurance'\u2014a high but not absolute level of assurance\u2014because audits use selective sampling, inherent limitations of internal control, and persuasive rather than conclusive evidence.\", \"correct_claim\": \"An external audit provides 'reasonable assurance' (not absolute 100% certainty) that financial statements are free of material misstatement, acknowledging that sampling and fraud concealment create inherent limitations.\", \"understanding_probe\": \"Why can an independent auditor never offer a 100% guarantee that financial statements are free of error?\", \"expected_answer\": \"Because auditors rely on testing samples of transactions rather than inspecting every single transaction, and sophisticated fraud can be deliberately hidden with forged documents.\"}, {\"prior_erroneous_claim\": \"The management representation letter relieves the external auditor of the duty to gather independent corroborating audit evidence.\", \"error_reason\": \"Management representations are required documentary evidence, but they complement rather than replace independent audit procedures like substantive testing.\", \"correct_claim\": \"A management representation letter confirms executive assertions but is not a substitute for independent substantive testing; auditors must still verify balances with third-party evidence.\", \"understanding_probe\": \"Why can't an auditor simply accept management's written letter as proof that accounts receivable are valid?\", \"expected_answer\": \"Because management has a self-interest in presenting favorable statements; auditing standards require independent verification like external customer confirmations.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Auditing and Assurance Services: Sampling Methods\", \"page\": 375, \"section\": \"Audit Risk Model and Sample Size Determination\", \"selected_text\": \"The AICPA Audit Risk Model establishes the relationship: Audit Risk (AR) = Inherent Risk (IR) * Control Risk (CR) * Detection Risk (DR).\", \"surrounding_context\": \"Section 4.2 calculates the planned detection risk needed to keep overall audit risk at the acceptable benchmark.\", \"retrieved_evidence\": [\"Audit Risk Model formula: DR = AR / (IR * CR)\", \"Audit engagement parameters: The engagement partner sets acceptable Audit Risk AR = 5.0% (0.05). Inherent Risk IR is evaluated at high (100% = 1.00), and internal Control Risk CR is evaluated as moderate (40% = 0.40).\", \"Step-by-step arithmetic from report: Risk of Material Misstatement (RMM) = IR * CR = 1.00 * 0.40 = 0.40 (40.0%). Planned Detection Risk DR = AR / RMM = 0.05 / 0.40 = 0.125 or 12.5%.\"], \"student_prompt\": \"What are the calculated Risk of Material Misstatement and Planned Detection Risk in Section 4.2?\", \"target_response\": \"Following the calculation explicitly provided in Section 4.2: First compute the combined Risk of Material Misstatement (RMM): IR * CR = 1.00 * 0.40 = 0.40 (40.0%). Next, solve for planned Detection Risk: DR = AR / (IR * CR) = 0.05 / 0.40 = 0.125 or 12.5%. The engagement team must design substantive audit procedures rigorous enough to keep detection risk down to 12.5% in order to hold overall audit risk at 5.0%.\", \"calculated_result\": \"RMM = 40.0%, Planned Detection Risk = 12.5%\"}, \"pattern_b_derive\": {\"document_title\": \"Substantive Testing and Audit Sampling\", \"page\": 382, \"section\": \"Monetary-Unit Sampling (MUS)\", \"selected_text\": \"In monetary-unit sampling, every dollar in a population has an equal probability of selection.\", \"surrounding_context\": \"The sampling interval determines how frequently items are drawn from the cumulative monetary ledger.\", \"retrieved_evidence\": [\"Formula: Sampling Interval = Tolerable Misstatement / Reliability Factor\", \"Parameters: Population book value = $2,500,000; Tolerable misstatement = $100,000; Reliability factor for zero expected misstatements at 5% risk of incorrect acceptance = 3.0.\"], \"student_prompt\": \"How do we derive the sampling interval and required sample size from the audit parameters?\", \"target_response\": \"To derive the sampling interval and sample size: Divide tolerable misstatement by the reliability factor: $100,000 / 3.0 = $33,333.33 for the sampling interval. Next, derive the sample size by dividing total population book value by the sampling interval: $2,500,000 / $33,333.33 = 75 items. The auditor will sample every 33,333rd dollar in the ledger, resulting in an audit sample size of 75 items.\", \"formula\": \"Interval = Tolerable Misstatement / Reliability Factor; Sample Size = Book Value / Interval\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact hourly billing rate of the PwC senior audit manager\", \"actual_topic\": \"the audit risk model, substantive sampling methods, and evidence gathering\", \"authoritative_source\": \"internal accounting firm client engagement fee agreements or billing invoices\", \"document_title\": \"Auditing and Attestation Principles\", \"page\": 390, \"section\": \"Audit Evidence and Confirmations\", \"selected_text\": \"External confirmations involve obtaining written evidence directly from third parties such as banks and trade receivables.\", \"surrounding_context\": \"Positive confirmations request a reply regardless of whether the balance matches.\", \"retrieved_evidence\": [\"Section 5.1: Distinguishing positive versus negative accounts receivable confirmations.\"], \"student_prompt\": \"According to this text, what hourly billing rate does the PwC senior audit manager charge on this engagement?\"}, {\"unmentioned_term\": \"the cybersecurity encryption protocol used by the client's SQL database\", \"actual_topic\": \"auditor independence standards and analytical procedures\", \"authoritative_source\": \"client enterprise IT infrastructure documentation or cybersecurity audit logs\", \"document_title\": \"Auditing and Attestation Principles\", \"page\": 395, \"section\": \"Substantive Analytical Procedures\", \"selected_text\": \"Auditors compare recorded client balances against independently developed auditor expectations.\", \"surrounding_context\": \"Significant unexpected fluctuations require expanded inquiry and corroborating documentation.\", \"retrieved_evidence\": [\"Table 5.3: Four-step process for executing substantive analytical procedures.\"], \"student_prompt\": \"What does the reading state regarding the client's SQL database cybersecurity encryption algorithm?\"}], \"grounded_paraphrase\": {\"document_title\": \"Professional Standards in Auditing\", \"page\": 370, \"section\": \"Professional Skepticism Axiom\", \"selected_text\": \"Professional skepticism requires maintaining an attitude that includes a questioning mind, being alert to conditions which may indicate possible misstatement due to error or fraud, and a critical assessment of audit evidence, rather than assuming management is inherently dishonest or unquestioningly trustworthy.\", \"surrounding_context\": \"Auditors must critically corroborate evidence even when prior engagements with the client were unblemished.\", \"retrieved_evidence\": [\"Page 370: 'Professional skepticism means keeping an open, questioning mind and verifying evidence without blind trust.'\"], \"student_prompt\": \"Can you explain what professional skepticism means according to this passage in simple terms?\", \"faithful_paraphrase\": \"This passage explains that professional skepticism means an auditor must always keep an inquisitive, alert mindset. Instead of blindly trusting what company managers say or assuming they are crooked, the auditor carefully checks the facts, examines the evidence with a critical eye, and stays alert for any signs of mistakes or deliberate deception.\"}, \"conflict_handling\": {\"document_title\": \"Audit Reporting Standards\", \"page\": 405, \"section\": \"Audit Opinion Classifications\", \"selected_text\": \"An auditor issues a qualified opinion when there is a material misstatement that is not pervasive to the financial statements.\", \"surrounding_context\": \"When a material misstatement is pervasive, fundamentally distorting the financial statements as a whole, the auditor must issue an adverse opinion.\", \"retrieved_evidence\": [\"Condition A: Material misstatement confined to inventory valuation (not pervasive) -> Qualified Opinion ('except for').\", \"Condition B: Material misstatements widespread across revenues, assets, and liabilities (pervasive) -> Adverse Opinion.\"], \"student_prompt\": \"Both cases involve material misstatements, but Case 1 receives a qualified opinion while Case 2 receives an adverse opinion. Why?\", \"resolution_explanation\": \"The difference between a qualified opinion and an adverse opinion depends on pervasiveness. In Case 1, the material misstatement is isolated to a specific account (inventory) and does not taint the overall integrity of the entire financial statement, so the auditor issues a qualified ('except for') opinion. In Case 2, the misstatements are pervasive, meaning they affect multiple major accounts and render the financial statements as a whole misleading; therefore, the auditor must issue an adverse opinion stating the statements do not present fairly under GAAP.\"}}}, \"mathematics::Quadratic Equations\": {\"domain\": \"mathematics\", \"concept\": \"Quadratic Equations\", \"explanation\": \"polynomial equations of the form ax\u00b2 + bx + c = 0, where a \u2260 0, which have at most two solutions that can be found by factoring, completing the square, or using the quadratic formula\", \"reason\": \"they model parabolic trajectories, optimization problems, and appear throughout physics, engineering, and economics\", \"concrete_examples\": [\"A ball thrown upward follows the path h(t) = \u221216t\u00b2 + 64t + 5. Setting h = 0 gives a quadratic equation to find when the ball hits the ground.\", \"Finding two numbers that multiply to 12 and add to 7 means solving x\u00b2 \u2212 7x + 12 = 0.\", \"The area of a rectangle with perimeter 20 is maximized by solving a quadratic: A = x(10 \u2212 x).\"], \"numerical_examples\": [\"Solve 2x\u00b2 \u2212 5x \u2212 3 = 0: Using the quadratic formula, x = (5 \u00b1 \u221a(25+24))/4 = (5 \u00b1 7)/4, giving x = 3 or x = \u22120.5.\", \"Factor x\u00b2 \u2212 9 = 0: (x \u2212 3)(x + 3) = 0, so x = 3 or x = \u22123.\", \"Discriminant of 3x\u00b2 + 2x + 5 = 0: b\u00b2 \u2212 4ac = 4 \u2212 60 = \u221256 < 0, so there are no real solutions.\"], \"misconceptions\": [[\"Every quadratic equation has two different real solutions\", \"The discriminant (b\u00b2 \u2212 4ac) determines the number of solutions. If it's positive, there are two distinct real roots. If zero, there is exactly one repeated root. If negative, there are no real roots (only complex ones).\"]], \"analogies\": [\"A quadratic equation is like a parabolic bridge \u2014 it touches the ground (x-axis) at zero, one, or two points depending on its height and shape.\"], \"prerequisites\": [\"algebra\", \"square roots\"], \"formulas\": [\"x = (\u2212b \u00b1 \u221a(b\u00b2\u22124ac)) / 2a\", \"Discriminant = b\u00b2 \u2212 4ac\"], \"document_evidence\": [\"The text states: 'The quadratic formula provides the solutions to any quadratic equation, whether or not it can be factored.'\", \"Example 2.5 demonstrates completing the square for x\u00b2 + 6x + 2 = 0.\"], \"practice_problems\": [\"Solve 3x\u00b2 + 7x \u2212 6 = 0 using the quadratic formula.\", \"Determine whether x\u00b2 + 4x + 5 = 0 has real solutions without solving it.\"], \"hints\": [\"Check the discriminant first to know how many solutions to expect.\", \"If a = 1 and b\u00b2 \u2212 4ac is a perfect square, try factoring first \u2014 it's faster.\"], \"follow_up_questions\": [\"How does the discriminant relate to the graph of the quadratic function?\", \"When would you choose completing the square over the quadratic formula?\"], \"diagnostic_questions\": [\"What are the three methods for solving quadratic equations?\", \"What does it mean geometrically when a quadratic has no real solutions?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The quadratic formula has -b in front, but if b is already negative, you leave it negative as -b.\", \"error_reason\": \"-b means the opposite of b; if b is negative (e.g., -6), -b evaluates to -(-6) = +6.\", \"correct_claim\": \"In the quadratic formula x = (-b \u00b1 \u221a(b\u00b2 - 4ac)) / (2a), the term -b is the negation of b. If b = -6, then -b is -(-6) = +6.\", \"understanding_probe\": \"If b = -8, what is the value of -b in the quadratic formula?\", \"expected_answer\": \"It is +8, because taking the negative of -8 produces positive 8.\"}, {\"prior_erroneous_claim\": \"If the discriminant b\u00b2 - 4ac is negative, it means the equation has no solutions at all.\", \"error_reason\": \"A negative discriminant means there are no real solutions, but there are two complex (imaginary) conjugate solutions.\", \"correct_claim\": \"When the discriminant b\u00b2 - 4ac < 0, there are no real roots, but there are two distinct complex conjugate roots involving the imaginary unit i.\", \"understanding_probe\": \"What kind of roots exist when the discriminant is negative?\", \"expected_answer\": \"Two complex (or imaginary) conjugate roots, such as x = 2 \u00b1 3i.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"College Algebra and Polynomial Equations\", \"page\": 42, \"section\": \"The Quadratic Formula and Discriminant Analysis\", \"selected_text\": \"Consider the quadratic equation 2x\u00b2 - 7x + 3 = 0, where coefficients are a = 2, b = -7, and c = 3.\", \"surrounding_context\": \"Section 2.1 demonstrates step-by-step discriminant evaluation and exact root calculation.\", \"retrieved_evidence\": [\"Discriminant calculation: \u0394 = b\u00b2 - 4ac = (-7)\u00b2 - 4(2)(3) = 49 - 24 = 25.\", \"Root calculation: x = [-(-7) \u00b1 \u221a25] / [2(2)] = (7 \u00b1 5) / 4.\", \"Exact solutions: x1 = (7 + 5) / 4 = 12 / 4 = 3.0; x2 = (7 - 5) / 4 = 2 / 4 = 0.5.\"], \"student_prompt\": \"What are the exact discriminant and roots calculated for 2x\u00b2 - 7x + 3 = 0 in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The discriminant is (-7)\u00b2 - 4(2)(3) = 49 - 24 = 25. Applying the quadratic formula gives x = (7 \u00b1 \u221a25) / 4 = (7 \u00b1 5) / 4. This produces two distinct real solutions: x1 = (7 + 5) / 4 = 3.0, and x2 = (7 - 5) / 4 = 0.5. The text directly establishes the discriminant at 25 and the two roots at 3.0 and 0.5.\", \"calculated_result\": \"Discriminant = 25, Roots = 3.0 and 0.5\"}, \"pattern_b_derive\": {\"document_title\": \"Algebraic Structures: Completing the Square\", \"page\": 48, \"section\": \"Finding the Vertex Form\", \"selected_text\": \"Any standard quadratic parabola y = ax\u00b2 + bx + c can be rewritten in vertex form y = a(x - h)\u00b2 + k.\", \"surrounding_context\": \"The coordinates of the vertex (h, k) represent the maximum or minimum of the parabolic trajectory.\", \"retrieved_evidence\": [\"Formulas: h = -b / (2a); k = c - (b\u00b2 / (4a))\", \"Equation: y = 3x\u00b2 - 12x + 7 (a = 3, b = -12, c = 7).\"], \"student_prompt\": \"How do we derive the coordinates of the vertex (h, k) and rewrite the parabola in vertex form?\", \"target_response\": \"To derive the vertex form: First compute the x-coordinate h = -b / (2a) = -(-12) / (2 * 3) = 12 / 6 = 2.0. Next, evaluate the function at x = 2 to find k: k = 3(2)\u00b2 - 12(2) + 7 = 3(4) - 24 + 7 = 12 - 24 + 7 = -5.0. Therefore, the vertex is at (2, -5). Substituting a = 3, h = 2, and k = -5 into vertex form gives y = 3(x - 2)\u00b2 - 5.\", \"formula\": \"h = -b/(2a), k = f(h); Vertex form: y = a(x - h)\u00b2 + k\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the numerical value of the Ramanujan tau function at n = 11\", \"actual_topic\": \"solving quadratic equations using factoring, completing the square, and the quadratic formula\", \"authoritative_source\": \"advanced modular forms research literature or the Online Encyclopedia of Integer Sequences (OEIS A000594)\", \"document_title\": \"Elementary Polynomial Algebra\", \"page\": 55, \"section\": \"Factoring Trinomials\", \"selected_text\": \"A monic quadratic x\u00b2 + bx + c factors into (x + p)(x + q) when p + q = b and pq = c.\", \"surrounding_context\": \"Factoring allows rapid identification of polynomial roots through the zero-product property.\", \"retrieved_evidence\": [\"Section 1.2: Table of factor pairs for integer trinomials.\"], \"student_prompt\": \"According to this text, what is the value of the Ramanujan tau function for n = 11?\"}, {\"unmentioned_term\": \"the exact fuel burn rate per second of the SpaceX Raptor 3 rocket engine\", \"actual_topic\": \"projectile motion modeled by quadratic trajectories\", \"authoritative_source\": \"aerospace propulsion engineering manuals or SpaceX technical press briefings\", \"document_title\": \"Elementary Polynomial Algebra\", \"page\": 58, \"section\": \"Parabolic Motion Applications\", \"selected_text\": \"The height of a projectile launched vertically with initial velocity v0 from height h0 is h(t) = -16t\u00b2 + v0t + h0 in feet.\", \"surrounding_context\": \"Setting h(t) = 0 yields the flight duration before ground impact.\", \"retrieved_evidence\": [\"Example 2.4: Trajectory of a baseball thrown with v0 = 64 ft/s.\"], \"student_prompt\": \"What does the reading cite as the exact propellant burn rate of the SpaceX Raptor 3 engine?\"}], \"grounded_paraphrase\": {\"document_title\": \"Principles of Pure Mathematics\", \"page\": 40, \"section\": \"The Fundamental Theorem of Algebra for Degree Two\", \"selected_text\": \"Every univariate polynomial equation of degree two over the field of complex coefficients admits precisely two roots, counted with multiplicity, as guaranteed by the algebraic closure of the complex number system.\", \"surrounding_context\": \"When the discriminant vanishes, the two roots coalesce into a single degenerate root of multiplicity two.\", \"retrieved_evidence\": [\"Page 40: 'Every quadratic equation has exactly two roots over the complex numbers when counting repeated roots.'\"], \"student_prompt\": \"Can you explain this theorem about quadratic equations in simple, everyday language?\", \"faithful_paraphrase\": \"This passage means that every single quadratic equation always has exactly two solutions if you include complex numbers and count double roots. Even if a parabola only touches the axis at one point, math considers that single answer to be two identical roots sitting on top of each other.\"}, \"conflict_handling\": {\"document_title\": \"Calculus and Numerical Methods\", \"page\": 62, \"section\": \"Numerical Instability in the Quadratic Formula\", \"selected_text\": \"When b\u00b2 is much larger than 4ac and b > 0, computing x = (-b + \u221a(b\u00b2 - 4ac)) / (2a) causes catastrophic cancellation on finite-precision computers.\", \"surrounding_context\": \"Numerical analysts instead compute the first root via x1 = (-b - sgn(b)\u221a(b\u00b2 - 4ac)) / (2a) and the second root via x2 = c / (a * x1).\", \"retrieved_evidence\": [\"Standard Formula: x = (-b \u00b1 \u221a(b\u00b2 - 4ac)) / (2a) [Mathematically exact in infinite precision].\", \"Numerical Formula: x1 = (-b - \u221a(b\u00b2 - 4ac)) / (2a), x2 = 2c / (-b - \u221a(b\u00b2 - 4ac)) [Floating-point stable].\"], \"student_prompt\": \"Why does my computer science textbook say the standard quadratic formula can give totally wrong answers on a computer?\", \"resolution_explanation\": \"This occurs because of floating-point roundoff error called catastrophic cancellation. In pure mathematics, the standard quadratic formula is 100% exact. But on a digital computer with finite precision, subtracting two numbers that are nearly identical (like -b and +\u221a(b\u00b2 - 4ac) when 4ac is tiny) wipes out significant digits. Computer scientists use an algebraically equivalent alternative formula that avoids subtracting nearly equal quantities, preserving numerical accuracy.\"}}}, \"mathematics::Derivatives\": {\"domain\": \"mathematics\", \"concept\": \"Derivatives\", \"explanation\": \"the instantaneous rate of change of a function, measuring how the output changes as the input changes by an infinitesimally small amount\", \"reason\": \"they enable optimization (finding maxima and minima), describe velocities and accelerations in physics, and underpin all of calculus\", \"concrete_examples\": [\"The derivative of position with respect to time gives velocity: if s(t) = 5t\u00b2, then v(t) = s'(t) = 10t.\", \"A company's marginal cost curve is the derivative of its total cost function.\", \"The slope of the tangent line to y = x\u00b3 at x = 2 is y' = 3(2\u00b2) = 12.\"], \"numerical_examples\": [\"If f(x) = 4x\u00b3 \u2212 2x + 7, then f'(x) = 12x\u00b2 \u2212 2. At x = 1, f'(1) = 10.\", \"The derivative of sin(x) is cos(x). At x = \u03c0/3, the rate of change is cos(\u03c0/3) = 0.5.\", \"For f(x) = e\u02e3, f'(x) = e\u02e3. The function is its own derivative.\"], \"misconceptions\": [[\"If f'(x) = 0 then x is always a maximum\", \"f'(x) = 0 only means x is a critical point. It could be a maximum, minimum, or inflection point. You need the second derivative test or sign analysis to determine which. For example, f(x) = x\u00b3 has f'(0) = 0 but x = 0 is an inflection point.\"]], \"analogies\": [\"The derivative is like a speedometer \u2014 position tells you where you are, but the derivative (speedometer) tells you how fast you're changing position at this exact moment.\"], \"prerequisites\": [\"algebra\", \"functions\", \"limits\"], \"formulas\": [\"Power rule: d/dx(x\u207f) = nx\u207f\u207b\u00b9\", \"Product rule: (fg)' = f'g + fg'\", \"Chain rule: d/dx[f(g(x))] = f'(g(x))\u00b7g'(x)\"], \"document_evidence\": [\"The text defines: 'The derivative f'(a) equals the slope of the tangent line to the graph of f at the point (a, f(a)).'\", \"Theorem 3.1 states the power rule and provides a proof using limits.\"], \"practice_problems\": [\"Find the derivative of f(x) = 3x\u2074 \u2212 5x\u00b2 + 2x \u2212 1.\", \"Use the chain rule to differentiate g(x) = (2x + 1)\u2075.\"], \"hints\": [\"For polynomials, bring the exponent down and subtract 1: d/dx(x\u207f) = nx\u207f\u207b\u00b9.\", \"The chain rule: differentiate the outside function, then multiply by the derivative of the inside.\"], \"follow_up_questions\": [\"What does the second derivative tell us about the shape of a function?\", \"How do derivatives help us find the maximum profit for a business?\"], \"diagnostic_questions\": [\"What is the geometric interpretation of the derivative at a point?\", \"If f'(x) > 0 on an interval, what does that tell you about f(x)?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The derivative of a product f(x)g(x) is simply f'(x)g'(x).\", \"error_reason\": \"The derivative of a product requires the product rule: f'(x)g(x) + f(x)g'(x); taking the product of the individual derivatives is a classic false rule.\", \"correct_claim\": \"The derivative of a product is given by the product rule: d/dx [f(x)g(x)] = f'(x)g(x) + f(x)g'(x). You cannot simply multiply the derivatives.\", \"understanding_probe\": \"If f(x) = x\u00b2 and g(x) = x\u00b3, why is the derivative not (2x)(3x\u00b2) = 6x\u00b3?\", \"expected_answer\": \"Because the product is x\u2075, whose true derivative is 5x\u2074; applying the product rule correctly gives (2x)(x\u00b3) + (x\u00b2)(3x\u00b2) = 2x\u2074 + 3x\u2074 = 5x\u2074.\"}, {\"prior_erroneous_claim\": \"If the derivative f'(c) = 0, then the function f(x) must have either a local maximum or a local minimum at x = c.\", \"error_reason\": \"f'(c) = 0 only identifies a critical point; the point could be an inflection point (saddle point) where the curve flattens without turning around, like f(x) = x\u00b3 at x = 0.\", \"correct_claim\": \"A zero derivative f'(c) = 0 is a necessary condition for an interior extremum of a differentiable function, but not sufficient; the point could be an inflection point (like x\u00b3 at x=0).\", \"understanding_probe\": \"Does f(x) = x\u00b3 have a maximum or minimum at x = 0, where f'(0) = 0?\", \"expected_answer\": \"Neither; it has an inflection point where the tangent line is horizontal but the function continues increasing on both sides.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Differential Calculus: Differentiation Rules\", \"page\": 88, \"section\": \"Chain Rule and Quotient Rule Applications\", \"selected_text\": \"Differentiate the rational function h(x) = (3x\u00b2 + 1) / (2x - 5) at the point x = 2.\", \"surrounding_context\": \"Section 3.4 demonstrates applying the quotient rule [f'g - fg'] / g\u00b2 to evaluate slopes of rational functions.\", \"retrieved_evidence\": [\"Quotient Rule formula: h'(x) = [f'(x)g(x) - f(x)g'(x)] / [g(x)]\u00b2.\", \"Derivatives: f(x) = 3x\u00b2 + 1 -> f'(x) = 6x; g(x) = 2x - 5 -> g'(x) = 2.\", \"Step-by-step arithmetic at x = 2: f(2) = 3(4) + 1 = 13; f'(2) = 6(2) = 12; g(2) = 2(2) - 5 = -1; g'(2) = 2.\", \"Evaluation: h'(2) = [(12)(-1) - (13)(2)] / (-1)\u00b2 = [-12 - 26] / 1 = -38 / 1 = -38.0.\"], \"student_prompt\": \"What is the exact derivative value h'(2) calculated in Section 3.4 using the quotient rule?\", \"target_response\": \"Following the explicit steps in Section 3.4: Evaluating the components at x = 2 gives f(2) = 13, f'(2) = 12, g(2) = -1, and g'(2) = 2. Applying the quotient rule formula h'(2) = [(12)(-1) - (13)(2)] / (-1)\u00b2 yields (-12 - 26) / 1 = -38.0. The text directly establishes that the slope of the function at x = 2 is exactly -38.\", \"calculated_result\": \"h'(2) = -38.0\"}, \"pattern_b_derive\": {\"document_title\": \"Differential Calculus: The Chain Rule\", \"page\": 94, \"section\": \"Composite Function Derivatives\", \"selected_text\": \"The chain rule states that the derivative of a composite function f(g(x)) is f'(g(x)) * g'(x).\", \"surrounding_context\": \"This rule differentiates functions nested inside powers, exponentials, or trigonometric functions.\", \"retrieved_evidence\": [\"Chain Rule: d/dx [u(x)^n] = n * [u(x)]^(n-1) * u'(x)\", \"Function to differentiate: y = (4x\u00b3 - 5x + 2)\u2074.\"], \"student_prompt\": \"How do we derive the derivative dy/dx for y = (4x\u00b3 - 5x + 2)\u2074 using the chain rule?\", \"target_response\": \"To derive the derivative using the chain rule: Let the inner function be u = 4x\u00b3 - 5x + 2, so the outer function is y = u\u2074. First, differentiate the outer function with respect to u: dy/du = 4u\u00b3. Second, differentiate the inner function with respect to x: du/dx = 12x\u00b2 - 5. Finally, multiply the two derivatives together: dy/dx = (dy/du) * (du/dx) = 4(4x\u00b3 - 5x + 2)\u00b3 * (12x\u00b2 - 5).\", \"formula\": \"dy/dx = f'(g(x)) * g'(x)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact proof of the Poincar\u00e9 conjecture by Grigori Perelman\", \"actual_topic\": \"differential calculus rules including the power, product, quotient, and chain rules\", \"authoritative_source\": \"Perelman's arXiv preprints on Ricci flow with surgery or the Clay Mathematics Institute Millennium Prize documentation\", \"document_title\": \"Foundations of Single-Variable Calculus\", \"page\": 105, \"section\": \"Implicit Differentiation\", \"selected_text\": \"Implicit differentiation applies the chain rule to equations where y cannot be solved explicitly for x.\", \"surrounding_context\": \"Differentiating both sides with respect to x and collecting dy/dx terms yields the slope equation.\", \"retrieved_evidence\": [\"Section 4.1: Derivation of the tangent slope to the folium of Descartes.\"], \"student_prompt\": \"According to this document, how did Grigori Perelman prove the Poincar\u00e9 conjecture?\"}, {\"unmentioned_term\": \"the current trading price of Bitcoin on Coinbase\", \"actual_topic\": \"related rates and optimization of geometric shapes\", \"authoritative_source\": \"Coinbase exchange public REST market feeds\", \"document_title\": \"Foundations of Single-Variable Calculus\", \"page\": 110, \"section\": \"Optimization Problems\", \"selected_text\": \"To maximize or minimize an objective function on a closed interval, test all critical points and endpoints.\", \"surrounding_context\": \"The Extreme Value Theorem guarantees the existence of absolute extrema for continuous functions on closed bounded intervals.\", \"retrieved_evidence\": [\"Example 4.6: Maximizing the volume of an open box constructed from a cardboard sheet.\"], \"student_prompt\": \"What does this text state regarding the current market price of Bitcoin on Coinbase?\"}], \"grounded_paraphrase\": {\"document_title\": \"Mathematical Analysis Principles\", \"page\": 80, \"section\": \"The Derivative as a Limit of Difference Quotients\", \"selected_text\": \"The derivative of a real-valued function at an arbitrary point encapsulates the infinitesimal limiting ratio of the ordinate increment to the abscissa increment as the perturbation parameter converges asymptotically to zero.\", \"surrounding_context\": \"This limit defines the instantaneous rate of change and the geometric gradient of the osculating tangent line.\", \"retrieved_evidence\": [\"Page 80: 'The derivative is the limit of the average rate of change as the step size approaches zero, giving the exact instantaneous slope.'\"], \"student_prompt\": \"Can you put this formal definition of a derivative into simple terms?\", \"faithful_paraphrase\": \"This passage explains that a derivative is simply the instantaneous rate of change of a function. By measuring how much the curve changes over smaller and smaller intervals and taking the limit as that step size shrinks to zero, the derivative gives the exact slope of the tangent line at that single point.\"}, \"conflict_handling\": {\"document_title\": \"Advanced Calculus and Physics Conventions\", \"page\": 118, \"section\": \"Total vs Partial Derivative Notations\", \"selected_text\": \"In multi-variable calculus, mathematicians distinguish between the partial derivative \u2202f/\u2202t and the total derivative df/dt when spatial coordinates are themselves functions of time.\", \"surrounding_context\": \"A student evaluating the time rate of change of temperature T(x(t), t) will find \u2202T/\u2202t ignores movement, while dT/dt includes convective change.\", \"retrieved_evidence\": [\"Partial Derivative \u2202T/\u2202t: Measures rate of temperature change at a fixed stationary coordinate.\", \"Total Derivative dT/dt = \u2202T/\u2202t + (\u2207T \u00b7 v): Measures rate of temperature change experienced by an observer moving through the temperature field.\"], \"student_prompt\": \"Why does my physics text write dT/dt = \u2202T/\u2202t + v\u00b7\u2207T instead of just saying the derivative with respect to time is dT/dt?\", \"resolution_explanation\": \"This distinction arises because temperature depends both directly on time and on position, which changes over time as an object moves. The partial derivative \u2202T/\u2202t measures how temperature changes at one fixed spot. The total derivative dT/dt includes both that local change and the change experienced by moving into warmer or colder areas (v\u00b7\u2207T). The expanded formula accounts for both effects simultaneously.\"}}}, \"mathematics::Integrals\": {\"domain\": \"mathematics\", \"concept\": \"Integrals\", \"explanation\": \"the mathematical operation that computes the accumulated area under a curve, serving as the reverse of differentiation\", \"reason\": \"they enable calculation of total quantities from rates (distance from velocity, total revenue from marginal revenue) and are central to physics, engineering, and probability\", \"concrete_examples\": [\"The integral of a velocity function gives the total distance traveled.\", \"The area under a demand curve between two prices gives consumer surplus.\", \"The integral of a probability density function over an interval gives the probability of that outcome.\"], \"numerical_examples\": [\"\u222b(2x)dx from 0 to 3 = [x\u00b2] from 0 to 3 = 9 \u2212 0 = 9.\", \"\u222b(x\u00b2 + 1)dx = x\u00b3/3 + x + C (indefinite integral).\", \"The area under y = 3x from x = 1 to x = 4 is \u222b3x dx = [3x\u00b2/2] from 1 to 4 = 24 \u2212 1.5 = 22.5.\"], \"misconceptions\": [[\"Integration always gives a positive area\", \"When the function is below the x-axis, the integral is negative. The integral of sin(x) from 0 to 2\u03c0 is zero because the positive and negative areas cancel. To find total physical area, you must integrate the absolute value.\"]], \"analogies\": [\"Integration is like measuring how much water fills an oddly-shaped swimming pool \u2014 you add up infinitely thin slices of water (each with its own depth) to get the total volume.\"], \"prerequisites\": [\"algebra\", \"derivatives\"], \"formulas\": [\"\u222bx\u207f dx = x\u207f\u207a\u00b9/(n+1) + C (n \u2260 \u22121)\", \"Fundamental Theorem: \u222b\u2090\u1d47 f(x)dx = F(b) \u2212 F(a)\"], \"document_evidence\": [\"The text states: 'The Fundamental Theorem of Calculus connects differentiation and integration, showing they are inverse operations.'\", \"Example 5.3 demonstrates the substitution method for integrating composite functions.\"], \"practice_problems\": [\"Evaluate \u222b(3x\u00b2 \u2212 4x + 1)dx from 0 to 2.\", \"Find the indefinite integral of 5e\u00b2\u02e3.\"], \"hints\": [\"The power rule for integration: add 1 to the exponent and divide by the new exponent.\", \"Always add the constant C for indefinite integrals.\"], \"follow_up_questions\": [\"What is the difference between definite and indefinite integrals?\", \"How does substitution simplify complex integrals?\"], \"diagnostic_questions\": [\"If F'(x) = f(x), what is the relationship between F and the integral of f?\", \"Can you always find an antiderivative in closed form? Give an example where you can't.\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The integral of 1/x is simply ln(x) for all real numbers without needing absolute value signs.\", \"error_reason\": \"The domain of ln(x) is strictly x > 0; for negative x, the antiderivative of 1/x is ln|x| + C, which is defined on all non-zero real numbers.\", \"correct_claim\": \"The indefinite integral of 1/x is ln|x| + C. The absolute value is required so the antiderivative is valid for negative values of x as well as positive values.\", \"understanding_probe\": \"Why is writing \u222b 1/x dx = ln(x) + C incomplete for x < 0?\", \"expected_answer\": \"Because the natural logarithm function cannot accept negative numbers; using ln|x| ensures the function is defined and has derivative 1/x on negative domains.\"}, {\"prior_erroneous_claim\": \"A definite integral \u222b[a,b] f(x) dx always equals the physical geometric area between the curve and the x-axis.\", \"error_reason\": \"Definite integrals compute net signed area; regions below the x-axis contribute negative values to the integral, which can cancel out positive areas above the axis.\", \"correct_claim\": \"The definite integral calculates net signed area, where regions above the x-axis are positive and regions below are negative. Total physical area requires integrating |f(x)|.\", \"understanding_probe\": \"If \u222b[-1, 1] x\u00b3 dx = 0, does that mean the area between the curve and the x-axis is zero?\", \"expected_answer\": \"No, the physical area is positive; the integral is zero because the negative region below the axis on [-1, 0] exactly cancels the positive region on [0, 1].\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Integral Calculus: Definite Integration and the FTC\", \"page\": 135, \"section\": \"Evaluating Polynomial Definite Integrals\", \"selected_text\": \"Evaluate the definite integral \u222b[1, 4] (3x\u00b2 - 4x + 5) dx using the Fundamental Theorem of Calculus.\", \"surrounding_context\": \"Section 4.2 presents antiderivative derivation and endpoint subtraction F(b) - F(a).\", \"retrieved_evidence\": [\"Antiderivative: F(x) = \u222b (3x\u00b2 - 4x + 5) dx = x\u00b3 - 2x\u00b2 + 5x.\", \"Upper limit evaluation at x = 4: F(4) = (4)\u00b3 - 2(4)\u00b2 + 5(4) = 64 - 32 + 20 = 52.\", \"Lower limit evaluation at x = 1: F(1) = (1)\u00b3 - 2(1)\u00b2 + 5(1) = 1 - 2 + 5 = 4.\", \"Step-by-step subtraction: \u222b[1, 4] (3x\u00b2 - 4x + 5) dx = F(4) - F(1) = 52 - 4 = 48.0.\"], \"student_prompt\": \"What is the exact numerical value of \u222b[1, 4] (3x\u00b2 - 4x + 5) dx calculated in Section 4.2?\", \"target_response\": \"Following the explicit calculation in Section 4.2: The antiderivative is F(x) = x\u00b3 - 2x\u00b2 + 5x. Evaluating at the upper bound x = 4 gives F(4) = 64 - 32 + 20 = 52. Evaluating at the lower bound x = 1 gives F(1) = 1 - 2 + 5 = 4. Subtracting the lower bound evaluation from the upper bound yields F(4) - F(1) = 52 - 4 = 48.0. The text directly establishes that the value of the integral is exactly 48.\", \"calculated_result\": \"Definite Integral = 48.0\"}, \"pattern_b_derive\": {\"document_title\": \"Techniques of Integration: Integration by Parts\", \"page\": 142, \"section\": \"The Product Antidifferentiation Formula\", \"selected_text\": \"Integration by parts is derived directly from the product rule: \u222b u dv = uv - \u222b v du.\", \"surrounding_context\": \"Choosing u according to the LIATE heuristic prioritizes polynomial factors for differentiation.\", \"retrieved_evidence\": [\"Integration by Parts Formula: \u222b u dv = uv - \u222b v du\", \"Integral to evaluate: \u222b x * e^(2x) dx. Let u = x and dv = e^(2x) dx.\"], \"student_prompt\": \"How do we derive the antiderivative of \u222b x * e^(2x) dx using integration by parts?\", \"target_response\": \"To derive the antiderivative using integration by parts: Set u = x and dv = e^(2x) dx. Differentiating u gives du = dx. Integrating dv gives v = (1/2)e^(2x). Substitute these into the formula \u222b u dv = uv - \u222b v du: x * (1/2)e^(2x) - \u222b (1/2)e^(2x) dx. Evaluating the remaining integral yields (1/2) * (1/2)e^(2x) = (1/4)e^(2x). Thus, the complete antiderivative is (1/2)x * e^(2x) - (1/4)e^(2x) + C, or ((2x - 1)/4)e^(2x) + C.\", \"formula\": \"\u222b u dv = uv - \u222b v du\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact GPS latitude and longitude coordinates of the Large Hadron Collider beam intersection point\", \"actual_topic\": \"definite integration, integration by parts, and the fundamental theorem of calculus\", \"authoritative_source\": \"CERN geodesic survey engineering reports or official LHC experimental facility blueprints\", \"document_title\": \"Single-Variable Integration\", \"page\": 150, \"section\": \"Trigonometric Substitution\", \"selected_text\": \"Integrals containing expressions of the form \u221a(a\u00b2 - x\u00b2) are simplified by substituting x = a sin(\u03b8).\", \"surrounding_context\": \"The substitution exploits the Pythagorean identity 1 - sin\u00b2(\u03b8) = cos\u00b2(\u03b8).\", \"retrieved_evidence\": [\"Section 5.3: Table of standard trigonometric substitutions.\"], \"student_prompt\": \"What does this text state regarding the exact GPS coordinates of the LHC beam intersection at CERN?\"}, {\"unmentioned_term\": \"the market price of a bushel of Kansas hard red winter wheat on July 10, 2025\", \"actual_topic\": \"numerical integration techniques including Simpson's Rule and the Trapezoidal Rule\", \"authoritative_source\": \"the Chicago Board of Trade (CBOT) agricultural futures settlement sheets\", \"document_title\": \"Single-Variable Integration\", \"page\": 155, \"section\": \"Numerical Approximation Methods\", \"selected_text\": \"Simpson's Rule approximates integrals by fitting parabolic arcs across adjacent subintervals.\", \"surrounding_context\": \"The method requires an even number of subintervals and achieves fourth-order error convergence.\", \"retrieved_evidence\": [\"Formula: Simpson's Rule with composite weights 1, 4, 2, 4, ..., 1.\"], \"student_prompt\": \"According to this chapter, what was the CBOT price of hard red winter wheat on July 10, 2025?\"}], \"grounded_paraphrase\": {\"document_title\": \"Foundations of Mathematical Analysis\", \"page\": 130, \"section\": \"The Fundamental Theorem of Calculus\", \"selected_text\": \"The Fundamental Theorem of Calculus establishes an intrinsic reciprocity between differentiation and Riemann integration, asserting that the definite accumulation of a continuous flux function across a compact interval is identically evaluated via the terminal boundary difference of any primitive antiderivative.\", \"surrounding_context\": \"This synthesis bridges the tangent problem of geometry with the quadrature problem of area calculation.\", \"retrieved_evidence\": [\"Page 130: 'The FTC links differentiation and integration, showing that accumulating a rate of change equals the net change in the original quantity between endpoints.'\"], \"student_prompt\": \"Can you explain this passage about the Fundamental Theorem of Calculus in everyday language?\", \"faithful_paraphrase\": \"This passage explains that differentiation and integration are reverse operations of each other. The Fundamental Theorem of Calculus shows that if you want to find the total accumulated amount of something changing continuously over time, you don't have to add up infinite tiny slices manually; you simply find its antiderivative and subtract its value at the start from its value at the end.\"}, \"conflict_handling\": {\"document_title\": \"Advanced Integration Theories\", \"page\": 165, \"section\": \"Riemann vs Lebesgue Integrability\", \"selected_text\": \"The Dirichlet indicator function 1_Q(x), which equals 1 for rational numbers and 0 for irrational numbers on [0, 1], is non-integrable under standard Riemann integration because upper and lower Darboux sums never converge.\", \"surrounding_context\": \"Under Lebesgue integration, however, the measure of rational numbers is zero, so the Lebesgue integral evaluates cleanly to 0.\", \"retrieved_evidence\": [\"Riemann Definition: Dirichlet function has Upper Sum = 1 and Lower Sum = 0; therefore, it is NOT Riemann integrable.\", \"Lebesgue Definition: Measure of rationals \u03bb(Q \u2229 [0,1]) = 0; therefore, the Lebesgue integral \u222b 1_Q d\u03bb = 0.\"], \"student_prompt\": \"One analysis book says the Dirichlet function cannot be integrated, but another book says its integral is 0. Which is true?\", \"resolution_explanation\": \"Both statements are correct within their respective definitions of integration. Under Riemann integration (the standard calculus definition), the function is not integrable because every interval contains both rational and irrational numbers, preventing upper and lower sums from converging. Under Lebesgue integration (the modern measure theory definition used in advanced analysis), the set of rational numbers has measure zero, allowing the integral to exist and equal exactly 0.\"}}}, \"mathematics::Probability Distributions\": {\"domain\": \"mathematics\", \"concept\": \"Probability Distributions\", \"explanation\": \"mathematical functions that describe the likelihood of every possible outcome of a random experiment, specifying probabilities for discrete outcomes or probability densities for continuous outcomes\", \"reason\": \"they form the foundation of statistical inference, risk assessment, quality control, and machine learning\", \"concrete_examples\": [\"A fair die has a uniform distribution: each face has probability 1/6.\", \"Heights of adult women follow approximately a normal distribution with mean ~64 inches and standard deviation ~3 inches.\", \"The number of emails received per hour follows a Poisson distribution if emails arrive independently at a constant average rate.\"], \"numerical_examples\": [\"For a binomial distribution with n=10, p=0.3: P(X=3) = C(10,3)(0.3)\u00b3(0.7)\u2077 \u2248 0.267.\", \"For a normal distribution N(100, 15\u00b2): P(X > 130) corresponds to z = (130\u2212100)/15 = 2, and P(Z > 2) \u2248 0.023.\", \"Poisson with \u03bb=4: P(X=2) = e\u207b\u2074 \u00d7 4\u00b2 / 2! \u2248 0.146.\"], \"misconceptions\": [[\"The probability of A and B is always P(A) \u00d7 P(B)\", \"The multiplication rule P(A and B) = P(A) \u00d7 P(B) only works when A and B are INDEPENDENT. For dependent events, P(A and B) = P(A) \u00d7 P(B|A). Drawing cards without replacement is a classic example where independence fails.\"]], \"analogies\": [\"A probability distribution is like a blueprint for a weighted dart board \u2014 it tells you exactly how likely the dart is to land in each region.\"], \"prerequisites\": [\"basic algebra\", \"combinatorics\"], \"formulas\": [\"P(X = k) for binomial: C(n,k)p\u1d4f(1\u2212p)\u207f\u207b\u1d4f\", \"Normal: z = (x \u2212 \u03bc) / \u03c3\"], \"document_evidence\": [\"The text explains: 'The normal distribution, also called the bell curve, is characterized by its mean and standard deviation.'\", \"Table A.1 provides standard normal z-table values for finding probabilities.\"], \"practice_problems\": [\"A fair coin is flipped 8 times. What is the probability of getting exactly 5 heads?\", \"Scores on a test are normally distributed with mean 75 and SD 10. What proportion of students scored above 90?\"], \"hints\": [\"For the normal distribution, convert to z-scores first, then use the z-table.\", \"The binomial distribution requires: fixed n trials, constant p, independent trials, two outcomes.\"], \"follow_up_questions\": [\"When is it appropriate to approximate the binomial with a normal distribution?\", \"What does the Central Limit Theorem tell us about sample means?\"], \"diagnostic_questions\": [\"What is the difference between a discrete and continuous probability distribution?\", \"Why must the total area under a probability density function equal 1?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"In a continuous probability distribution, the probability that X equals an exact single number like P(X = 3.5) is positive.\", \"error_reason\": \"For any continuous random variable, the probability of taking on any exact single real value is strictly 0; probabilities only exist over non-zero intervals.\", \"correct_claim\": \"For any continuous probability distribution, P(X = c) = 0 for any single point c. Probability is represented by area under the probability density function (PDF) over an interval.\", \"understanding_probe\": \"If a continuous variable X is uniformly distributed between 0 and 10, what is P(X = 4.0)?\", \"expected_answer\": \"P(X = 4.0) is exactly 0, because a single point has no width and therefore zero area under the continuous density curve.\"}, {\"prior_erroneous_claim\": \"The standard deviation of a binomial distribution with n trials and probability p is n * p * (1 - p).\", \"error_reason\": \"n * p * (1 - p) is the variance; standard deviation is the square root of that variance: \u221a(n * p * (1 - p)).\", \"correct_claim\": \"The variance of a binomial distribution is Var(X) = np(1 - p), so its standard deviation is \u03c3 = \u221a(np(1 - p)).\", \"understanding_probe\": \"If a binomial distribution has n = 100 and p = 0.5, what are the variance and standard deviation?\", \"expected_answer\": \"The variance is 100 * 0.5 * 0.5 = 25, and the standard deviation is \u221a25 = 5.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Probability and Statistics for Engineers\", \"page\": 182, \"section\": \"Binomial and Poisson Distribution Parameters\", \"selected_text\": \"An industrial manufacturing line tests components with an independent defect rate of p = 0.05 across batches of n = 400 items.\", \"surrounding_context\": \"Section 3.2 computes the exact expected value, variance, and standard deviation for the defective count.\", \"retrieved_evidence\": [\"Formulas: Mean \u03bc = np; Variance \u03c3\u00b2 = np(1 - p); Standard Deviation \u03c3 = \u221a(np(1 - p)).\", \"Step-by-step arithmetic from text: Mean \u03bc = 400 * 0.05 = 20.0 defects. Variance \u03c3\u00b2 = 400 * 0.05 * (1 - 0.05) = 20 * 0.95 = 19.0. Standard Deviation \u03c3 = \u221a19.0 \u2248 4.3589.\"], \"student_prompt\": \"What are the exact mean, variance, and standard deviation calculated for this batch in Section 3.2?\", \"target_response\": \"Following the calculation explicitly provided in Section 3.2: The expected mean number of defects is \u03bc = 400 * 0.05 = 20.0. The variance is \u03c3\u00b2 = 400 * 0.05 * 0.95 = 19.0. The standard deviation is the square root of the variance: \u03c3 = \u221a19.0 \u2248 4.36. The course text directly establishes the mean at 20.0, variance at 19.0, and standard deviation at approximately 4.36.\", \"calculated_result\": \"Mean = 20.0, Variance = 19.0, Std Dev \u2248 4.36\"}, \"pattern_b_derive\": {\"document_title\": \"Probability Theory: The Normal Distribution\", \"page\": 190, \"section\": \"Standardizing Normal Variables (Z-Score)\", \"selected_text\": \"To evaluate probabilities for an arbitrary normal random variable X ~ N(\u03bc, \u03c3\u00b2), values are standardized into Z-scores: Z = (X - \u03bc) / \u03c3.\", \"surrounding_context\": \"The Z-score measures how many standard deviations an observation lies above or below the distribution mean.\", \"retrieved_evidence\": [\"Z-score Formula: Z = (X - \u03bc) / \u03c3\", \"Distribution parameters: Exam scores are normally distributed with mean \u03bc = 72.0 and standard deviation \u03c3 = 8.0. Student score X = 86.0.\"], \"student_prompt\": \"How do we derive the student's Z-score and interpret its distance from the mean?\", \"target_response\": \"To derive the Z-score: Substitute the exam parameters into the formula Z = (X - \u03bc) / \u03c3. Subtract the mean from the student's score: 86.0 - 72.0 = 14.0 points. Divide this difference by the standard deviation: 14.0 / 8.0 = 1.75. The student's Z-score is +1.75, which means their score lies exactly 1.75 standard deviations above the class mean.\", \"formula\": \"Z = (X - \u03bc) / \u03c3\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the Powerball lottery jackpot amount drawn on January 14, 2026\", \"actual_topic\": \"binomial, Poisson, and normal probability distribution formulas\", \"authoritative_source\": \"the official Multi-State Lottery Association (MUSL) Powerball drawing archives\", \"document_title\": \"Principles of Probability Distributions\", \"page\": 202, \"section\": \"Poisson Processes\", \"selected_text\": \"The Poisson distribution models the frequency of discrete independent events occurring within a continuous interval: P(X = k) = (\u03bb^k * e^(-\u03bb)) / k!.\", \"surrounding_context\": \"Parameter \u03bb represents the average event rate per unit interval.\", \"retrieved_evidence\": [\"Section 4.1: Derivation of the Poisson distribution as the limit of a binomial.\"], \"student_prompt\": \"According to this document, what was the Powerball jackpot amount on January 14, 2026?\"}, {\"unmentioned_term\": \"the exact market capitalization of Nvidia Corporation in euros\", \"actual_topic\": \"exponential distributions and memoryless reliability modeling\", \"authoritative_source\": \"Nasdaq stock exchange market capitalization data converted via European Central Bank reference exchange rates\", \"document_title\": \"Principles of Probability Distributions\", \"page\": 206, \"section\": \"Continuous Lifetime Distributions\", \"selected_text\": \"The exponential distribution is widely utilized to model component lifetimes until failure: f(t) = \u03bbe^(-\u03bbt) for t \u2265 0.\", \"surrounding_context\": \"A defining characteristic of the exponential distribution is its memoryless property.\", \"retrieved_evidence\": [\"Section 4.3: Mathematical proof of the memoryless property.\"], \"student_prompt\": \"What does the text state regarding Nvidia's market capitalization in euros?\"}], \"grounded_paraphrase\": {\"document_title\": \"Mathematical Statistics\", \"page\": 178, \"section\": \"Central Limit Theorem Axiom\", \"selected_text\": \"The Central Limit Theorem guarantees that the normalized summation of an arbitrary sequence of independent and identically distributed random variables endowed with finite second moments converges in distribution toward a canonical Gaussian profile, irrespective of the underlying ancestral population topology.\", \"surrounding_context\": \"This asymptotic convergence justifies the ubiquitous deployment of normal models in empirical inferential statistics.\", \"retrieved_evidence\": [\"Page 178: 'The CLT shows that sample means become normally distributed as sample size increases, regardless of the population's shape.'\"], \"student_prompt\": \"Can you explain what the Central Limit Theorem means in plain, everyday language?\", \"faithful_paraphrase\": \"This passage explains the Central Limit Theorem: when you collect large enough random samples and calculate their averages, those sample averages will form a normal bell-shaped curve. This happens even if the original population you are sampling from is skewed or non-normal, which is why the normal distribution is so widely used in statistics.\"}, \"conflict_handling\": {\"document_title\": \"Statistical Distribution Handbook\", \"page\": 215, \"section\": \"Normal Approximation to the Binomial: Continuity Correction\", \"selected_text\": \"When approximating a discrete binomial probability P(X = k) using a continuous normal distribution, some applied texts omit continuity correction for large n, while rigorous texts mandate evaluating P(k - 0.5 < Y < k + 0.5).\", \"surrounding_context\": \"Omitting the continuity correction introduces discrete-to-continuous boundary bias when sample sizes are moderate.\", \"retrieved_evidence\": [\"Approximation A (Basic Rule): P(X \u2264 k) \u2248 P(Z \u2264 (k - np)/\u03c3) [Simple, but ignores boundary width].\", \"Approximation B (Continuity-Corrected): P(X \u2264 k) \u2248 P(Z \u2264 (k + 0.5 - np)/\u03c3) [Adjusts discrete integer to continuous interval].\"], \"student_prompt\": \"Why does one statistics book add 0.5 when approximating binomial probabilities with the normal curve while another book doesn't?\", \"resolution_explanation\": \"The difference is whether the author uses a 'continuity correction.' The binomial distribution is discrete (bars at integer steps 1, 2, 3), while the normal distribution is a smooth continuous curve. Adding or subtracting 0.5 adjusts the integer point into a continuous interval (e.g., representing integer 5 as the interval from 4.5 to 5.5). When n is very large, that 0.5 shift has negligible impact, so some applied textbooks drop it for simplicity, but using the 0.5 correction provides greater accuracy.\"}}}, \"mathematics::Linear Algebra\": {\"domain\": \"mathematics\", \"concept\": \"Linear Algebra\", \"explanation\": \"the branch of mathematics dealing with vectors, vector spaces, matrices, and linear transformations, focusing on systems of linear equations\", \"reason\": \"it is essential for computer graphics, machine learning, quantum mechanics, engineering, and any field that manipulates multi-dimensional data\", \"concrete_examples\": [\"Solving 3 equations with 3 unknowns (prices of 3 items given 3 budget constraints) is a system of linear equations solvable with matrices.\", \"Image rotation in computer graphics uses a 2\u00d72 rotation matrix to transform every pixel's coordinates.\", \"Google's PageRank algorithm uses eigenvectors of a massive matrix to rank web pages.\"], \"numerical_examples\": [\"Matrix multiplication: [[1,2],[3,4]] \u00d7 [[5],[6]] = [[1\u00d75+2\u00d76],[3\u00d75+4\u00d76]] = [[17],[39]].\", \"Determinant of [[3,1],[2,4]] = 3\u00d74 \u2212 1\u00d72 = 10. Since det \u2260 0, the matrix is invertible.\", \"Eigenvalues of [[2,1],[0,3]]: det(A \u2212 \u03bbI) = (2\u2212\u03bb)(3\u2212\u03bb) = 0 \u2192 \u03bb = 2 or \u03bb = 3.\"], \"misconceptions\": [[\"Matrix multiplication is the same as multiplying corresponding elements\", \"Matrix multiplication uses dot products of rows and columns, not element-wise multiplication. If A is m\u00d7n and B is n\u00d7p, the (i,j) entry of AB is the dot product of row i of A and column j of B. Also, AB \u2260 BA in general.\"]], \"analogies\": [\"A matrix is like a transformation machine \u2014 you feed in a vector (input), and the matrix stretches, rotates, or reflects it to produce a new vector (output).\"], \"prerequisites\": [\"algebra\", \"systems of equations\"], \"formulas\": [\"Ax = b (system of equations)\", \"det([[a,b],[c,d]]) = ad \u2212 bc\"], \"document_evidence\": [\"The text states: 'A system of linear equations can be written in matrix form Ax = b, and solved when A is invertible.'\", \"Theorem 4.2: A square matrix is invertible if and only if its determinant is non-zero.\"], \"practice_problems\": [\"Multiply [[2,0],[1,3]] by [[1,4],[2,5]] and verify the result.\", \"Find the determinant of [[5,3],[2,7]] and determine whether the matrix is invertible.\"], \"hints\": [\"For 2\u00d72 matrices: det = ad \u2212 bc. If det = 0, the matrix is singular (not invertible).\", \"Matrix multiplication is NOT commutative: AB \u2260 BA in general.\"], \"follow_up_questions\": [\"What is an eigenvector, and why is it important in data science?\", \"How do you solve Ax = b when A is not invertible?\"], \"diagnostic_questions\": [\"What does it mean for a matrix to be 'invertible'?\", \"Can you multiply a 2\u00d73 matrix by a 2\u00d72 matrix? Why or why not?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Two vectors are linearly independent if their dot product equals zero.\", \"error_reason\": \"A zero dot product means the vectors are orthogonal (perpendicular), which is a sufficient condition for non-zero vectors to be independent, but linear independence does not require them to be perpendicular at all.\", \"correct_claim\": \"Vectors are linearly independent if no vector in the set can be written as a linear combination of the others (c1*v1 + c2*v2 = 0 implies all c = 0). They do not need to have a zero dot product.\", \"understanding_probe\": \"Are the vectors [1, 0] and [1, 1] linearly independent, even though their dot product is 1, not 0?\", \"expected_answer\": \"Yes, they are linearly independent because neither is a scalar multiple of the other, even though they are not perpendicular.\"}, {\"prior_erroneous_claim\": \"A system of linear equations Ax = b has a unique solution whenever the number of equations equals the number of variables.\", \"error_reason\": \"Having an equal number of equations and unknowns (square matrix) only allows for a unique solution if det(A) \u2260 0; if equations are redundant or contradictory, there may be infinitely many solutions or no solution.\", \"correct_claim\": \"An n x n linear system Ax = b has a unique solution if and only if the coefficient matrix A is invertible (det(A) \u2260 0). If det(A) = 0, the system has either infinitely many solutions or no solution.\", \"understanding_probe\": \"Why does the system x + y = 2 and 2x + 2y = 4 not have a unique solution despite having 2 equations and 2 variables?\", \"expected_answer\": \"Because the second equation is a duplicate multiple of the first, making the determinant 0 and resulting in infinitely many solutions.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Applied Linear Algebra: Eigenvalues and Eigenvectors\", \"page\": 240, \"section\": \"Characteristic Polynomial and Eigenvalue Solutions\", \"selected_text\": \"Determine the eigenvalues of the 2x2 matrix A = [[4, 2], [1, 3]] by solving det(A - \u03bbI) = 0.\", \"surrounding_context\": \"Section 5.1 details the characteristic equation expansion and quadratic factoring.\", \"retrieved_evidence\": [\"Matrix A - \u03bbI = [[4 - \u03bb, 2], [1, 3 - \u03bb]].\", \"Characteristic equation: det(A - \u03bbI) = (4 - \u03bb)(3 - \u03bb) - (2)(1) = \u03bb\u00b2 - 7\u03bb + 12 - 2 = \u03bb\u00b2 - 7\u03bb + 10 = 0.\", \"Factoring: (\u03bb - 5)(\u03bb - 2) = 0.\", \"Exact eigenvalues: \u03bb1 = 5.0, \u03bb2 = 2.0. Verification: Trace(A) = 4 + 3 = 7 = 5 + 2; Det(A) = 4(3) - 2(1) = 10 = 5 * 2.\"], \"student_prompt\": \"What are the exact characteristic equation and eigenvalues calculated for matrix A in Section 5.1?\", \"target_response\": \"Following the explicit calculation in Section 5.1: The characteristic polynomial is det(A - \u03bbI) = (4 - \u03bb)(3 - \u03bb) - 2 = \u03bb\u00b2 - 7\u03bb + 10 = 0. Factoring this yields (\u03bb - 5)(\u03bb - 2) = 0, giving eigenvalues \u03bb1 = 5.0 and \u03bb2 = 2.0. This is verified by checking that the trace (4 + 3 = 7) matches the sum of eigenvalues (5 + 2 = 7) and the determinant (12 - 2 = 10) matches their product (5 * 2 = 10).\", \"calculated_result\": \"Characteristic Eq: \u03bb\u00b2 - 7\u03bb + 10 = 0; Eigenvalues = 5.0 and 2.0\"}, \"pattern_b_derive\": {\"document_title\": \"Linear Vector Spaces: Linear Independence\", \"page\": 248, \"section\": \"Testing Independence via the Wronskian / Determinant\", \"selected_text\": \"A set of n vectors in R^n is linearly independent if and only if the matrix formed by placing them as columns has a non-zero determinant.\", \"surrounding_context\": \"If the determinant is zero, the column vectors are linearly dependent and span a lower-dimensional subspace.\", \"retrieved_evidence\": [\"Criterion: Vectors v1, v2, v3 in R\u00b3 are independent <=> det([v1 | v2 | v3]) \u2260 0.\", \"Vectors: v1 = [1, 2, 0]^T, v2 = [0, 1, 1]^T, v3 = [2, 0, -4]^T.\"], \"student_prompt\": \"How do we derive whether vectors v1, v2, and v3 are linearly independent using the matrix determinant?\", \"target_response\": \"To derive linear independence: Form the 3x3 matrix M with vectors as columns: [[1, 0, 2], [2, 1, 0], [0, 1, -4]]. Compute det(M) by expanding along the first row: 1 * det([[1, 0], [1, -4]]) - 0 + 2 * det([[2, 1], [0, 1]]). Evaluate the 2x2 determinants: 1 * [(1)(-4) - (0)(1)] + 2 * [(2)(1) - (1)(0)] = 1 * (-4) + 2 * (2) = -4 + 4 = 0. Because det(M) = 0, the columns are linearly dependent. In fact, 2*v1 - 4*v2 - v3 = [2, 4, 0] - [0, 4, 4] - [2, 0, -4] = [0, 0, 0].\", \"formula\": \"det([v1 | v2 | v3]) = 0 => Linearly Dependent\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the flight speed of the Boeing 787 Dreamliner at cruising altitude\", \"actual_topic\": \"eigenvalues, eigenvectors, vector spaces, and linear independence\", \"authoritative_source\": \"commercial airliner flight crew operating manuals published by Boeing Commercial Airplanes\", \"document_title\": \"Linear Algebra Principles\", \"page\": 260, \"section\": \"Gram-Schmidt Orthogonalization\", \"selected_text\": \"The Gram-Schmidt process transforms an arbitrary basis into an orthonormal basis: u_k = v_k - sum(proj_u_j(v_k)).\", \"surrounding_context\": \"Orthonormal bases simplify projections and QR matrix factorizations.\", \"retrieved_evidence\": [\"Section 6.2: Algorithm steps for Gram-Schmidt orthogonalization.\"], \"student_prompt\": \"According to this document, what is the cruising speed of a Boeing 787?\"}, {\"unmentioned_term\": \"the exact chemical formula for the synthetic cannabinoid JWH-018\", \"actual_topic\": \"linear transformations, null spaces, and rank-nullity theorem\", \"authoritative_source\": \"forensic chemistry databases or the PubChem compound registry\", \"document_title\": \"Linear Algebra Principles\", \"page\": 265, \"section\": \"The Rank-Nullity Theorem\", \"selected_text\": \"For any linear transformation T: V -> W with finite-dimensional domain V, dim(V) = rank(T) + nullity(T).\", \"surrounding_context\": \"The dimension of the domain equals the dimension of the image plus the dimension of the kernel.\", \"retrieved_evidence\": [\"Theorem 6.4: Formal proof of the Rank-Nullity theorem.\"], \"student_prompt\": \"What does this text state regarding the molecular formula of JWH-018?\"}], \"grounded_paraphrase\": {\"document_title\": \"Advanced Linear Algebra\", \"page\": 235, \"section\": \"Linear Transformations and Invariant Subspaces\", \"selected_text\": \"An eigenvector of an endomorphism on a vector space designates a non-trivial vector whose directional trajectory is preserved under the transformation, undergoing solely scalar dilatation or contraction dictated by its corresponding eigenvalue.\", \"surrounding_context\": \"Finding an eigenbasis diagonalizes the transformation matrix into a pure coordinate scaling operation.\", \"retrieved_evidence\": [\"Page 235: 'An eigenvector is a vector whose direction does not change when transformed by a matrix; it only stretches or shrinks.'\"], \"student_prompt\": \"Can you explain what an eigenvector is based on this passage in simple terms?\", \"faithful_paraphrase\": \"This passage explains that an eigenvector is a special vector that does not rotate or change its directional line when multiplied by a matrix. Instead of pointing in a new direction, it simply stretches, shrinks, or flips along its original line, and the eigenvalue tells you the exact factor by which it was scaled.\"}, \"conflict_handling\": {\"document_title\": \"Matrix Computations and Functional Analysis\", \"page\": 270, \"section\": \"Definition of Positive Definite Matrices: Strict vs Semi-Definite\", \"selected_text\": \"Pure mathematics texts define a symmetric matrix A as positive definite if x^T A x > 0 for all non-zero vectors x, requiring strictly positive eigenvalues.\", \"surrounding_context\": \"In some engineering optimization literature, authors loosely write 'positive definite' to include non-negative curvature x^T A x \u2265 0 (positive semi-definite).\", \"retrieved_evidence\": [\"Rigorous Mathematical Standard: Positive Definite requires x^T A x > 0 for all x \u2260 0 (all eigenvalues \u03bb_i > 0).\", \"Engineering Convention Note: If x^T A x \u2265 0 (some eigenvalues \u03bb = 0), the matrix is strictly Positive Semi-Definite, not Positive Definite.\"], \"student_prompt\": \"One book says a matrix with a zero eigenvalue can be positive definite, but my professor says all eigenvalues must be strictly greater than 0. Who is right?\", \"resolution_explanation\": \"Your professor is adhering to the correct, rigorous mathematical standard. A matrix is positive definite if and only if x^T A x > 0 for all non-zero vectors x, which requires all eigenvalues to be strictly positive (\u03bb > 0). If an eigenvalue is zero, x^T A x can equal zero for a non-zero vector, making the matrix 'positive semi-definite.' Some applied engineering texts casually blur this distinction, but mathematically, zero eigenvalues are excluded from positive definiteness.\"}}}, \"mathematics::Trigonometric Identities\": {\"domain\": \"mathematics\", \"concept\": \"Trigonometric Identities\", \"explanation\": \"equations involving trigonometric functions that are true for all valid input values, used to simplify expressions and solve equations\", \"reason\": \"they simplify complex calculations in physics, engineering, signal processing, and any field involving periodic phenomena\", \"concrete_examples\": [\"The identity sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1 lets you find cos\u03b8 if you know sin\u03b8 without needing a calculator.\", \"In physics, expressing a wave as Asin(\u03c9t + \u03c6) and using sum identities lets you combine two waves into one.\", \"The double-angle formula sin(2\u03b8) = 2sin\u03b8cos\u03b8 simplifies area calculations in trigonometry.\"], \"numerical_examples\": [\"If sin\u03b8 = 3/5, then cos\u00b2\u03b8 = 1 \u2212 9/25 = 16/25, so cos\u03b8 = \u00b14/5.\", \"cos(\u03c0/3 + \u03c0/4) = cos(\u03c0/3)cos(\u03c0/4) \u2212 sin(\u03c0/3)sin(\u03c0/4) = (1/2)(\u221a2/2) \u2212 (\u221a3/2)(\u221a2/2) = (\u221a2 \u2212 \u221a6)/4.\", \"tan(2\u00d730\u00b0) = 2tan30\u00b0/(1 \u2212 tan\u00b230\u00b0) = 2(1/\u221a3)/(1 \u2212 1/3) = (2/\u221a3)/(2/3) = 3/\u221a3 = \u221a3.\"], \"misconceptions\": [[\"sin(A + B) = sinA + sinB\", \"The correct identity is sin(A + B) = sinAcosB + cosAsinB. Simply adding the sines gives incorrect results. For example, sin(30\u00b0 + 60\u00b0) = sin(90\u00b0) = 1, but sin30\u00b0 + sin60\u00b0 = 0.5 + 0.866 = 1.366 \u2260 1.\"]], \"analogies\": [\"Trig identities are like algebraic shortcuts \u2014 knowing that sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1 is like knowing that a\u00b2 \u2212 b\u00b2 = (a\u2212b)(a+b), it lets you simplify without starting from scratch.\"], \"prerequisites\": [\"algebra\", \"basic trigonometry\"], \"formulas\": [\"sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1\", \"sin(A+B) = sinAcosB + cosAsinB\", \"cos(2\u03b8) = cos\u00b2\u03b8 \u2212 sin\u00b2\u03b8\"], \"document_evidence\": [\"The text lists the fundamental identities: Pythagorean, sum/difference, double-angle, and half-angle.\", \"Proof 6.1 derives the sum formula sin(A+B) from the unit circle.\"], \"practice_problems\": [\"Simplify: (1 \u2212 cos\u00b2x) / sinx.\", \"Prove that tan\u00b2\u03b8 + 1 = sec\u00b2\u03b8 starting from sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1.\"], \"hints\": [\"Start with sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1 and divide both sides to get other identities.\", \"For sum/difference identities, don't try to add trig functions directly.\"], \"follow_up_questions\": [\"How are trig identities used in Fourier analysis?\", \"What is the practical use of the double-angle formulas?\"], \"diagnostic_questions\": [\"Is sin(2x) equal to 2sin(x)? Explain.\", \"What is the Pythagorean identity and where does it come from?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The Pythagorean identity states that sin\u00b2(\u03b8) - cos\u00b2(\u03b8) = 1.\", \"error_reason\": \"The Pythagorean identity is sin\u00b2(\u03b8) + cos\u00b2(\u03b8) = 1; subtracting them gives -cos(2\u03b8), not 1.\", \"correct_claim\": \"The fundamental Pythagorean identity is sin\u00b2(\u03b8) + cos\u00b2(\u03b8) = 1. The operation between the squares is addition, derived from the unit circle equation x\u00b2 + y\u00b2 = 1.\", \"understanding_probe\": \"Why does sin\u00b2(\u03b8) + cos\u00b2(\u03b8) always equal 1 on the unit circle?\", \"expected_answer\": \"Because on the unit circle, x = cos(\u03b8) and y = sin(\u03b8), and the circle's equation is x\u00b2 + y\u00b2 = r\u00b2 = 1\u00b2 = 1.\"}, {\"prior_erroneous_claim\": \"The double angle formula for sine is sin(2\u03b8) = 2 sin(\u03b8).\", \"error_reason\": \"Trigonometric functions are non-linear; sin(2\u03b8) = 2 sin(\u03b8) cos(\u03b8), requiring the cosine factor.\", \"correct_claim\": \"The double angle formula is sin(2\u03b8) = 2 sin(\u03b8) cos(\u03b8). You cannot simply pull the 2 out in front because sine is not a linear function.\", \"understanding_probe\": \"If \u03b8 = 30\u00b0, what is sin(2\u03b8) compared to 2 sin(\u03b8)?\", \"expected_answer\": \"sin(60\u00b0) = \u221a3/2 \u2248 0.866, whereas 2 sin(30\u00b0) = 2(0.5) = 1.0; they are not equal, proving sin(2\u03b8) \u2260 2 sin(\u03b8).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Analytical Trigonometry and Identities\", \"page\": 285, \"section\": \"Angle Addition and Double Angle Formulas\", \"selected_text\": \"Given an acute angle \u03b8 in Quadrant I where sin(\u03b8) = 3/5 (0.60) and cos(\u03b8) = 4/5 (0.80), compute the exact values of sin(2\u03b8) and cos(2\u03b8).\", \"surrounding_context\": \"Section 4.1 demonstrates exact double-angle trigonometric calculations.\", \"retrieved_evidence\": [\"Double-angle formulas: sin(2\u03b8) = 2 sin(\u03b8) cos(\u03b8); cos(2\u03b8) = cos\u00b2(\u03b8) - sin\u00b2(\u03b8).\", \"Step-by-step arithmetic from text: sin(2\u03b8) = 2 * (3/5) * (4/5) = 2 * (12/25) = 24/25 = 0.96.\", \"cos(2\u03b8) calculation: cos(2\u03b8) = (4/5)\u00b2 - (3/5)\u00b2 = 16/25 - 9/25 = 7/25 = 0.28.\", \"Identity verification: sin\u00b2(2\u03b8) + cos\u00b2(2\u03b8) = (24/25)\u00b2 + (7/25)\u00b2 = 576/625 + 49/625 = 625/625 = 1.00.\"], \"student_prompt\": \"What are the exact values of sin(2\u03b8) and cos(2\u03b8) calculated in Section 4.1?\", \"target_response\": \"Following the explicit steps in Section 4.1: Using sin(\u03b8) = 3/5 and cos(\u03b8) = 4/5, the double angle formula gives sin(2\u03b8) = 2 * (3/5) * (4/5) = 24/25 = 0.96. For cosine, cos(2\u03b8) = (4/5)\u00b2 - (3/5)\u00b2 = 16/25 - 9/25 = 7/25 = 0.28. The course text directly establishes sin(2\u03b8) as 24/25 (0.96) and cos(2\u03b8) as 7/25 (0.28).\", \"calculated_result\": \"sin(2\u03b8) = 24/25 = 0.96; cos(2\u03b8) = 7/25 = 0.28\"}, \"pattern_b_derive\": {\"document_title\": \"Analytical Trigonometry: Half-Angle Formulas\", \"page\": 292, \"section\": \"Deriving Half-Angle Formulas from Cosine Double Angle\", \"selected_text\": \"The half-angle identities are derived by rearranging the cosine double-angle identity cos(2u) = 1 - 2 sin\u00b2(u).\", \"surrounding_context\": \"Setting 2u = \u03b1 so u = \u03b1/2 isolates the half-angle trigonometric terms.\", \"retrieved_evidence\": [\"Identity: cos(2u) = 1 - 2 sin\u00b2(u)\", \"Objective: Solve for sin(\u03b1/2) in terms of cos(\u03b1).\"], \"student_prompt\": \"How do we derive the half-angle identity for sin(\u03b1/2) from cos(2u) = 1 - 2 sin\u00b2(u)?\", \"target_response\": \"To derive the half-angle identity: Start with cos(2u) = 1 - 2 sin\u00b2(u). Rearrange to isolate the sine term: 2 sin\u00b2(u) = 1 - cos(2u). Divide both sides by 2: sin\u00b2(u) = (1 - cos(2u)) / 2. Now let u = \u03b1/2, which makes 2u = \u03b1: sin\u00b2(\u03b1/2) = (1 - cos(\u03b1)) / 2. Taking the square root of both sides gives the half-angle formula: sin(\u03b1/2) = \u00b1\u221a((1 - cos(\u03b1)) / 2), where the sign is determined by the quadrant of \u03b1/2.\", \"formula\": \"sin(\u03b1/2) = \u00b1\u221a((1 - cos(\u03b1)) / 2)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact construction budget of the Hoover Dam in 1935 dollars\", \"actual_topic\": \"Pythagorean identities, angle addition formulas, and double-angle formulas\", \"authoritative_source\": \"the United States Bureau of Reclamation historical project archives\", \"document_title\": \"Trigonometric Analysis\", \"page\": 305, \"section\": \"Product-to-Sum Formulas\", \"selected_text\": \"Product-to-sum identities convert products of sine and cosine into sums: sin(A)cos(B) = 0.5[sin(A+B) + sin(A-B)].\", \"surrounding_context\": \"These transformations simplify integration of oscillating wave products in Fourier analysis.\", \"retrieved_evidence\": [\"Section 5.2: Proofs of four product-to-sum identities.\"], \"student_prompt\": \"According to this document, what was the total construction cost of the Hoover Dam in 1935?\"}, {\"unmentioned_term\": \"the molecular weight of human hemoglobin in Daltons\", \"actual_topic\": \"law of sines and law of cosines for oblique triangles\", \"authoritative_source\": \"biochemical reference databases or the Protein Data Bank\", \"document_title\": \"Trigonometric Analysis\", \"page\": 310, \"section\": \"Solving Oblique Triangles\", \"selected_text\": \"The Law of Cosines c\u00b2 = a\u00b2 + b\u00b2 - 2ab cos(C) generalizes the Pythagorean theorem to any triangle.\", \"surrounding_context\": \"It resolves SAS and SSS triangle configurations.\", \"retrieved_evidence\": [\"Section 5.4: Law of Cosines geometric proof.\"], \"student_prompt\": \"What does this text state regarding the molecular weight of human hemoglobin?\"}], \"grounded_paraphrase\": {\"document_title\": \"Modern Trigonometry\", \"page\": 280, \"section\": \"Trigonometric Identity Definition\", \"selected_text\": \"A trigonometric identity denotes an algebraic equation involving circular functions that remains invariant under arbitrary substitution of angular arguments across the intersection of their respective operational domains.\", \"surrounding_context\": \"Unlike conditional equations that hold solely for discrete angles, identities reflect geometric invariants of the unit circle.\", \"retrieved_evidence\": [\"Page 280: 'A trigonometric identity is an equation that is true for every angle where the functions are defined.'\"], \"student_prompt\": \"Can you explain what a trigonometric identity is based on this passage in simple terms?\", \"faithful_paraphrase\": \"This passage explains that a trigonometric identity is an equation that is true for every possible angle you plug into it, as long as the functions are mathematically defined at that angle. Unlike regular math equations that are only true for one or two specific answers, an identity describes a universal geometric truth that always holds.\"}, \"conflict_handling\": {\"document_title\": \"Trigonometry Conventions\", \"page\": 318, \"section\": \"Secant and Tangent Pythagorean Identity Forms\", \"selected_text\": \"Starting from sin\u00b2(\u03b8) + cos\u00b2(\u03b8) = 1, dividing through by cos\u00b2(\u03b8) produces tan\u00b2(\u03b8) + 1 = sec\u00b2(\u03b8), whereas dividing by sin\u00b2(\u03b8) yields 1 + cot\u00b2(\u03b8) = csc\u00b2(\u03b8).\", \"surrounding_context\": \"Students often confuse which function has the + 1 on the left side.\", \"retrieved_evidence\": [\"Tangent Form: tan\u00b2(\u03b8) + 1 = sec\u00b2(\u03b8) (or sec\u00b2(\u03b8) - tan\u00b2(\u03b8) = 1).\", \"Cotangent Form: 1 + cot\u00b2(\u03b8) = csc\u00b2(\u03b8) (or csc\u00b2(\u03b8) - cot\u00b2(\u03b8) = 1).\", \"Student Confusion: Writing tan\u00b2(\u03b8) = sec\u00b2(\u03b8) + 1 (incorrect sign flip).\"], \"student_prompt\": \"I saw two different versions: tan\u00b2(\u03b8) + 1 = sec\u00b2(\u03b8) and sec\u00b2(\u03b8) - tan\u00b2(\u03b8) = 1. Are these conflicting identities?\", \"resolution_explanation\": \"These are not conflicting identities; they are algebraically identical rearrangements of the exact same equation. Subtracting tan\u00b2(\u03b8) from both sides of tan\u00b2(\u03b8) + 1 = sec\u00b2(\u03b8) gives 1 = sec\u00b2(\u03b8) - tan\u00b2(\u03b8). Both forms are valid Pythagorean identities derived directly from dividing sin\u00b2(\u03b8) + cos\u00b2(\u03b8) = 1 by cos\u00b2(\u03b8).\"}}}, \"mathematics::Logarithms\": {\"domain\": \"mathematics\", \"concept\": \"Logarithms\", \"explanation\": \"the inverse of exponentiation \u2014 log\u2090(x) answers the question 'to what power must a be raised to get x?'\", \"reason\": \"they transform multiplicative relationships into additive ones, making it easier to work with exponential growth, sound intensity, pH, and computational complexity\", \"concrete_examples\": [\"log\u2081\u2080(1000) = 3 because 10\u00b3 = 1000.\", \"The Richter scale uses logarithms: an earthquake of magnitude 6 is 10 times stronger than magnitude 5.\", \"In computer science, binary search runs in O(log\u2082 n) time because it halves the search space each step.\"], \"numerical_examples\": [\"log\u2082(32) = 5 because 2\u2075 = 32.\", \"Using the product rule: log\u2081\u2080(500) = log\u2081\u2080(5 \u00d7 100) = log\u2081\u2080(5) + log\u2081\u2080(100) = 0.699 + 2 = 2.699.\", \"Solving 2\u02e3 = 10: x = log\u2082(10) = ln(10)/ln(2) \u2248 3.322.\"], \"misconceptions\": [[\"log(A + B) = log(A) + log(B)\", \"The correct rule is log(A \u00d7 B) = log(A) + log(B). Logarithms convert multiplication to addition, not addition to addition. For example, log(2 + 3) = log(5) \u2248 0.699, but log(2) + log(3) = 0.301 + 0.477 = 0.778 \u2260 0.699.\"]], \"analogies\": [\"A logarithm is like counting the number of digits in a number \u2014 log\u2081\u2080 essentially tells you 'how many digits?' minus 1. The number 1000 has 4 digits, and log\u2081\u2080(1000) = 3.\"], \"prerequisites\": [\"algebra\", \"exponents\"], \"formulas\": [\"log\u2090(xy) = log\u2090(x) + log\u2090(y)\", \"log\u2090(x\u207f) = n\u00b7log\u2090(x)\", \"Change of base: log\u2090(x) = ln(x)/ln(a)\"], \"document_evidence\": [\"The text states: 'Logarithms are the inverse of exponential functions: if a\u02e3 = y, then log\u2090(y) = x.'\", \"Table 7.1 summarizes the three key logarithm laws: product, quotient, and power rules.\"], \"practice_problems\": [\"Simplify log\u2082(16) + log\u2082(8) using logarithm rules.\", \"Solve for x: 3\u02e3 = 81.\"], \"hints\": [\"log\u2090(x) asks 'a to what power equals x?'\", \"The product rule converts multiplication inside the log to addition outside.\"], \"follow_up_questions\": [\"Why is the natural logarithm (base e) preferred in calculus?\", \"How are logarithmic scales useful for data spanning many orders of magnitude?\"], \"diagnostic_questions\": [\"What is log\u2081\u2080(100) and how do you know?\", \"If log\u2083(x) = 4, what is x?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The logarithm of a sum equals the sum of the logarithms: log(a + b) = log(a) + log(b).\", \"error_reason\": \"log(a * b) = log(a) + log(b), but log(a + b) cannot be split or expanded; treating log as distributing over addition is a classic false rule.\", \"correct_claim\": \"Logarithms turn multiplication into addition: log(a * b) = log(a) + log(b). The expression log(a + b) cannot be simplified or distributed.\", \"understanding_probe\": \"If a = 10 and b = 100, what is log10(a + b) compared to log10(a) + log10(b)?\", \"expected_answer\": \"log10(110) \u2248 2.041, whereas log10(10) + log10(100) = 1 + 2 = 3.0; they are not equal, proving log(a + b) \u2260 log(a) + log(b).\"}, {\"prior_erroneous_claim\": \"You can take the logarithm of negative numbers in the real number system because squares turn negatives positive.\", \"error_reason\": \"In the real number system, the base b > 0 raised to any real power is strictly positive; therefore, log_b(x) is undefined for x \u2264 0.\", \"correct_claim\": \"The domain of log_b(x) in real analysis is strictly x > 0. You cannot take the logarithm of zero or a negative number in real numbers.\", \"understanding_probe\": \"Why is log10(-5) undefined in the real numbers?\", \"expected_answer\": \"Because 10 raised to any real exponent is always positive; there is no real power of 10 that produces -5.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"College Algebra: Logarithmic Functions and Equations\", \"page\": 330, \"section\": \"Solving Exponential Equations with Logarithms\", \"selected_text\": \"Solve the exponential growth equation 5^(2x - 1) = 125 using base-5 logarithmic properties.\", \"surrounding_context\": \"Section 3.1 details exact algebraic inversion and step-by-step arithmetic.\", \"retrieved_evidence\": [\"Equation: 5^(2x - 1) = 125\", \"Express RHS as a power of 5: 125 = 5\u00b3.\", \"Equating exponents: 2x - 1 = 3 -> 2x = 4 -> x = 2.0.\", \"Logarithmic verification: log5(125) = 3; 2(2.0) - 1 = 4 - 1 = 3.\"], \"student_prompt\": \"What is the exact solution for x in 5^(2x - 1) = 125 calculated in Section 3.1?\", \"target_response\": \"Following the explicit steps in Section 3.1: Rewrite the right-hand side as a power of 5: 125 = 5\u00b3. Since bases are equal, equate exponents: 2x - 1 = 3. Adding 1 to both sides gives 2x = 4, and dividing by 2 yields x = 2.0. The text directly establishes that the exact solution is x = 2.\", \"calculated_result\": \"x = 2.0\"}, \"pattern_b_derive\": {\"document_title\": \"Logarithmic Analysis: The Change of Base Formula\", \"page\": 338, \"section\": \"Deriving the Change of Base Formula\", \"selected_text\": \"To evaluate log_b(x) using common or natural logarithms, we derive the change of base theorem.\", \"surrounding_context\": \"Let y = log_b(x), convert to exponential form b^y = x, and take the logarithm base c of both sides.\", \"retrieved_evidence\": [\"Derivation steps: Let y = log_b(x) <=> b^y = x. Take log_c of both sides: log_c(b^y) = log_c(x).\", \"Power rule: y * log_c(b) = log_c(x). Solve for y: y = log_c(x) / log_c(b).\"], \"student_prompt\": \"How do we derive the change-of-base formula log_b(x) = ln(x) / ln(b) from basic exponential properties?\", \"target_response\": \"To derive the change of base formula: Set y = log_b(x). By definition of a logarithm, this is equivalent to b^y = x. Take the natural logarithm of both sides: ln(b^y) = ln(x). Apply the power property of logarithms to bring y out front: y * ln(b) = ln(x). Finally, divide both sides by ln(b): y = ln(x) / ln(b). Since y = log_b(x), this proves log_b(x) = ln(x) / ln(b).\", \"formula\": \"log_b(x) = ln(x) / ln(b)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact number of registered voters in Miami-Dade County in the 2024 election\", \"actual_topic\": \"properties of logarithms including power, product, quotient, and change-of-base rules\", \"authoritative_source\": \"the Florida Division of Elections voter registration statistics\", \"document_title\": \"Elementary Logarithmic Theory\", \"page\": 345, \"section\": \"Logarithmic Scales: Richter and Decibel\", \"selected_text\": \"The Richter scale calculates earthquake magnitude as M = log10(I / I0), where I is seismic wave amplitude.\", \"surrounding_context\": \"Each whole unit increase on the Richter scale corresponds to a 10-fold increase in measured amplitude.\", \"retrieved_evidence\": [\"Section 4.2: Richter magnitude comparison formulas.\"], \"student_prompt\": \"According to this document, how many registered voters were there in Miami-Dade County in 2024?\"}, {\"unmentioned_term\": \"the exact curb weight of the Tesla Cybertruck in kilograms\", \"actual_topic\": \"decibel calculations and exponential decay half-life formulas\", \"authoritative_source\": \"Tesla Inc. official vehicle specification sheets or Department of Transportation regulatory filings\", \"document_title\": \"Elementary Logarithmic Theory\", \"page\": 350, \"section\": \"Acoustic Decibel Levels\", \"selected_text\": \"Sound intensity in decibels is defined as dB = 10 log10(I / I0), with threshold reference I0 = 10^(-12) W/m\u00b2.\", \"surrounding_context\": \"A 10 dB increase represents a tenfold multiplication of physical acoustic power.\", \"retrieved_evidence\": [\"Table 4.4: Decibel ratings of common urban sound environments.\"], \"student_prompt\": \"What does the reading cite as the curb weight of a Tesla Cybertruck?\"}], \"grounded_paraphrase\": {\"document_title\": \"Foundations of Algebra\", \"page\": 325, \"section\": \"Logarithm Definition\", \"selected_text\": \"A logarithm denotes the functional inverse of exponentiation, indicating the unique exponent to which an invariant positive base must be elevated to synthesize an assigned positive numerical argument.\", \"surrounding_context\": \"Consequently, logarithmic equations map multiplicative scaling dynamics into additive translations.\", \"retrieved_evidence\": [\"Page 325: 'A logarithm is the inverse of an exponent; it gives the power you must raise the base to in order to get a target number.'\"], \"student_prompt\": \"Can you explain what a logarithm is based on this passage in simple words?\", \"faithful_paraphrase\": \"This passage explains that a logarithm is simply the reverse of an exponent. It asks the question: 'What power do I need to raise my base number to so that I reach this target number?' For example, log base 10 of 1,000 is 3, because you must raise 10 to the 3rd power to get 1,000.\"}, \"conflict_handling\": {\"document_title\": \"Scientific Computing Reference\", \"page\": 355, \"section\": \"The Notation log(x): Base 10 vs Base e\", \"selected_text\": \"Introductory algebra textbooks use log(x) for base-10 (common log) and ln(x) for base-e (natural log).\", \"surrounding_context\": \"However, in higher mathematics, physics, and computer programming languages (like Python, C, and R), log(x) universally denotes the natural logarithm base e.\", \"retrieved_evidence\": [\"High School / Engineering Standard: log(x) = base 10, ln(x) = base e.\", \"Pure Mathematics / Computer Science Standard: log(x) = base e (natural log), while base 10 is explicitly written log10(x).\"], \"student_prompt\": \"My math homework says log(100) = 2, but when I typed math.log(100) into Python, it gave 4.605. Which one is wrong?\", \"resolution_explanation\": \"Neither is wrong; they are using different notational conventions. In high school math, 'log' defaults to the common logarithm (base 10), so log10(100) = 2. In computer science and advanced mathematics, 'log' defaults to the natural logarithm (base e \u2248 2.718), and ln(100) \u2248 4.605. To get base 10 in Python, you must use math.log10(100).\"}}}, \"mathematics::Exponential Functions\": {\"domain\": \"mathematics\", \"concept\": \"Exponential Functions\", \"explanation\": \"functions of the form f(x) = a\u02e3 where the variable is in the exponent, modeling quantities that grow or decay at a rate proportional to their current value\", \"reason\": \"they describe population growth, radioactive decay, compound interest, and the spread of diseases \u2014 any process where the rate of change is proportional to the current amount\", \"concrete_examples\": [\"Bacteria doubling every hour follow exponential growth: starting with 100, after 5 hours you have 100 \u00d7 2\u2075 = 3,200.\", \"Radioactive carbon-14 decays exponentially with a half-life of 5,730 years.\", \"Compound interest: $1,000 invested at 5% annual interest grows to $1,000(1.05)\u207f after n years.\"], \"numerical_examples\": [\"A population of 500 growing at 3% per year: P(10) = 500 \u00d7 (1.03)\u00b9\u2070 = 500 \u00d7 1.344 = 672.\", \"Half-life problem: If 200g of a substance has a half-life of 10 years, after 30 years: 200 \u00d7 (1/2)\u00b3 = 25g remains.\", \"Continuous compounding: $5,000 at 4% for 6 years = $5,000 \u00d7 e^(0.04\u00d76) = $5,000 \u00d7 e^0.24 \u2248 $6,356.\"], \"misconceptions\": [[\"Exponential growth continues forever in real systems\", \"Exponential growth is always limited by resources, space, or other constraints. Real populations follow logistic growth (S-shaped), not pure exponential. Exponential models are accurate only in early stages.\"]], \"analogies\": [\"Exponential growth is like a chain letter \u2014 each person sends to 5 friends, who each send to 5 more. The numbers explode because growth feeds on itself.\"], \"prerequisites\": [\"algebra\", \"exponents\"], \"formulas\": [\"f(x) = a\u00b7b\u02e3\", \"Continuous: f(t) = a\u00b7e\u1d4f\u1d57\", \"Half-life: t\u2081/\u2082 = ln(2)/k\"], \"document_evidence\": [\"The text states: 'The number e \u2248 2.718 is the base of the natural exponential function, which arises naturally in continuous growth and decay.'\", \"Example 8.2 compares discrete and continuous compounding of investments.\"], \"practice_problems\": [\"A town of 10,000 grows at 2% per year. What is the population after 15 years?\", \"A substance decays according to N(t) = 100e^(\u22120.05t). How long until half remains?\"], \"hints\": [\"For growth, the base (or rate) must be greater than 1 (or positive). For decay, less than 1 (or negative).\", \"Half-life: set N(t) = N\u2080/2 and solve for t.\"], \"follow_up_questions\": [\"Why is e the 'natural' base for exponential functions?\", \"How do you convert between discrete (compound) and continuous growth models?\"], \"diagnostic_questions\": [\"If a quantity doubles every 5 years, how long until it's 8 times its original size?\", \"What is the difference between linear growth and exponential growth?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The graph of y = 2^x eventually crosses below the x-axis for very large negative values of x.\", \"error_reason\": \"For any positive base b > 0, b^x > 0 for all real x; as x becomes large negative, b^x approaches 0 as a horizontal asymptote but never reaches or crosses below zero.\", \"correct_claim\": \"The function y = 2^x has a horizontal asymptote at y = 0. For negative x, 2^(-10) = 1/1024, which is small and positive, never negative.\", \"understanding_probe\": \"What is the value of 2^(-3), and is it positive or negative?\", \"expected_answer\": \"It is 1/(2\u00b3) = 1/8 = +0.125, which is strictly positive.\"}, {\"prior_erroneous_claim\": \"Exponential growth and polynomial growth with high exponents (like x^10) grow at the same rate in the long run.\", \"error_reason\": \"Any exponential growth b^x (where b > 1) eventually outgrows any polynomial x^n, no matter how large the polynomial's exponent n is.\", \"correct_claim\": \"Exponential growth fundamentally dominates polynomial growth; for sufficiently large x, b^x > x^n for any base b > 1 and any polynomial power n.\", \"understanding_probe\": \"In the limit as x goes to infinity, which grows faster: x^100 or 1.01^x?\", \"expected_answer\": \"1.01^x grows infinitely faster; exponential functions eventually surpass any polynomial, regardless of how small the base or large the exponent.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Applied Calculus: Continuous Compounding and Growth\", \"page\": 372, \"section\": \"Continuous Growth Model A = P e^(rt)\", \"selected_text\": \"A bacterial colony with an initial population of P0 = 500 bacteria grows continuously at a rate of r = 0.08 per hour.\", \"surrounding_context\": \"Section 4.1 calculates the colony size after t = 10 hours using continuous exponential growth.\", \"retrieved_evidence\": [\"Continuous growth formula: A(t) = P0 * e^(rt)\", \"Parameter values: P0 = 500; r = 0.08; t = 10 hours -> rt = 0.08 * 10 = 0.80.\", \"Exponential value from table: e^0.80 \u2248 2.22554.\", \"Step-by-step arithmetic: A(10) = 500 * 2.22554 = 1,112.77 \u2248 1,113 bacteria.\"], \"student_prompt\": \"What is the exact population calculated after 10 hours in Section 4.1?\", \"target_response\": \"Following the explicit steps in Section 4.1: The exponent is rt = 0.08 * 10 = 0.80. Evaluating e^0.80 gives approximately 2.22554. Multiplying this factor by the initial population of 500 yields 500 * 2.22554 = 1,112.77, or approximately 1,113 bacteria. The course text directly establishes the 10-hour population at approximately 1,113 bacteria.\", \"calculated_result\": \"Population = 1,113 bacteria (1,112.77)\"}, \"pattern_b_derive\": {\"document_title\": \"Exponential Dynamics: Radioactive Decay and Half-Life\", \"page\": 378, \"section\": \"Deriving the Half-Life Decay Constant\", \"selected_text\": \"In radioactive decay N(t) = N0 * e^(-kt), the decay constant k is uniquely determined by the isotope's half-life T.\", \"surrounding_context\": \"At time t = T, the remaining quantity equals exactly half of the initial amount: N(T) = N0 / 2.\", \"retrieved_evidence\": [\"Decay equation: N(T) = N0 * e^(-kT) = N0 / 2\", \"Objective: Solve for decay constant k in terms of half-life T.\"], \"student_prompt\": \"How do we derive the formula k = ln(2) / T from the half-life definition?\", \"target_response\": \"To derive the decay constant formula: Start with the half-life condition N0 * e^(-kT) = N0 / 2. Divide both sides by N0: e^(-kT) = 1/2 = 2^(-1). Take the natural logarithm of both sides: ln(e^(-kT)) = ln(2^(-1)). Simplify using log properties: -kT = -ln(2). Divide both sides by -T: k = ln(2) / T. Since ln(2) \u2248 0.693, the continuous decay constant is k \u2248 0.693 / T.\", \"formula\": \"k = ln(2) / T\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact ticket sales revenue of the 2024 Paris Olympic Games opening ceremony\", \"actual_topic\": \"continuous exponential growth, radioactive half-life decay, and asymptotic properties\", \"authoritative_source\": \"the International Olympic Committee (IOC) official financial audit statements\", \"document_title\": \"Principles of Exponential Dynamics\", \"page\": 388, \"section\": \"Logistic Growth Models\", \"selected_text\": \"Logistic growth incorporates a carrying capacity K to constrain unconstrained exponential growth: dP/dt = rP(1 - P/K).\", \"surrounding_context\": \"As population approaches K, the growth rate decelerates toward zero, producing an S-shaped sigmoid curve.\", \"retrieved_evidence\": [\"Section 5.2: Analytical solution of the logistic differential equation.\"], \"student_prompt\": \"According to this document, how much ticket revenue did the 2024 Paris Olympics opening ceremony generate?\"}, {\"unmentioned_term\": \"the average wind speed on Neptune's Great Dark Spot in meters per second\", \"actual_topic\": \"compound interest frequencies and continuous compounding limits\", \"authoritative_source\": \"planetary science atmospheric measurements published by NASA's Jet Propulsion Laboratory (JPL)\", \"document_title\": \"Principles of Exponential Dynamics\", \"page\": 392, \"section\": \"Limits and Euler's Constant\", \"selected_text\": \"Euler's number e is defined as the limit: e = lim (n->inf) (1 + 1/n)^n \u2248 2.71828.\", \"surrounding_context\": \"This limit emerges naturally when compounding financial interest with infinite frequency.\", \"retrieved_evidence\": [\"Section 5.4: Binomial expansion proof of the convergence of e.\"], \"student_prompt\": \"What does the reading cite as the wind speed in Neptune's Great Dark Spot?\"}], \"grounded_paraphrase\": {\"document_title\": \"Calculus and Mathematical Modeling\", \"page\": 368, \"section\": \"The Exponential Rate of Change Axiom\", \"selected_text\": \"The natural exponential function f(x) = e^x constitutes the unique non-trivial real-valued function that serves as its own derivative, ensuring that its instantaneous growth rate is perpetually identical to its current accumulated magnitude.\", \"surrounding_context\": \"This intrinsic proportionality makes exponential functions the foundational archetype for uninhibited organic expansion.\", \"retrieved_evidence\": [\"Page 368: 'e^x is the only function whose derivative equals itself, meaning it grows at a rate exactly equal to its current size.'\"], \"student_prompt\": \"Can you put this passage about e^x into simple words?\", \"faithful_paraphrase\": \"This passage explains what makes the function e^x unique: its rate of growth is always equal to its current value. When the function is at 10, it is growing at a speed of 10; when it reaches 1,000, it is growing at a speed of 1,000. It is the only function in mathematics that is its own exact derivative.\"}, \"conflict_handling\": {\"document_title\": \"Population Biology Reference\", \"page\": 400, \"section\": \"Discrete vs Continuous Growth Parameters: r vs lambda\", \"selected_text\": \"Ecologists model population growth using both discrete geometric time steps N_(t+1) = \u03bb * N_t and continuous differential equations N(t) = N_0 * e^(rt).\", \"surrounding_context\": \"The finite rate of increase \u03bb relates to the intrinsic continuous rate of increase r through \u03bb = e^r.\", \"retrieved_evidence\": [\"Discrete Growth Parameter: \u03bb = 1.20 (population multiplies by 1.20 each year, a 20% annual increase).\", \"Continuous Growth Parameter: r = ln(1.20) \u2248 0.1823 (continuous growth rate is 18.23% per year).\", \"Textbook Note: Confusing discrete \u03bb with continuous r leads to inaccurate compounding predictions.\"], \"student_prompt\": \"One ecology paper says the population growth rate is 20% (\u03bb = 1.20), but another paper using the same data says the growth rate is 18.2% (r = 0.182). Why?\", \"resolution_explanation\": \"These two figures represent the exact same growth rate expressed in two different mathematical frameworks. The first paper uses discrete annual growth (\u03bb = 1.20), meaning the population grows by 20% once a year. The second paper uses continuous exponential growth (e^(rt)), where compounding happens every microsecond. Because continuous compounding accumulates interest on interest continuously, a continuous rate of 18.23% (r = ln(1.20)) produces the exact same annual total of 20%.\"}}}, \"mathematics::Matrix Operations\": {\"domain\": \"mathematics\", \"concept\": \"Matrix Operations\", \"explanation\": \"the arithmetic operations that can be performed on matrices, including addition, scalar multiplication, matrix multiplication, transposition, and finding inverses and determinants\", \"reason\": \"they enable solving systems of equations, performing transformations in graphics and data science, and are the computational backbone of machine learning\", \"concrete_examples\": [\"Adding two 2\u00d72 matrices: [[1,2],[3,4]] + [[5,6],[7,8]] = [[6,8],[10,12]] \u2014 add corresponding elements.\", \"Scalar multiplication: 3 \u00d7 [[1,2],[3,4]] = [[3,6],[9,12]].\", \"The transpose of [[1,2,3],[4,5,6]] is [[1,4],[2,5],[3,6]] \u2014 rows become columns.\"], \"numerical_examples\": [\"[[2,1],[0,3]] \u00d7 [[1,4],[2,5]] = [[(2\u00d71+1\u00d72),(2\u00d74+1\u00d75)],[(0\u00d71+3\u00d72),(0\u00d74+3\u00d75)]] = [[4,13],[6,15]].\", \"Inverse of [[2,1],[5,3]]: det = 6\u22125 = 1. Inverse = [[3,\u22121],[\u22125,2]].\", \"Trace of [[4,1,0],[2,5,3],[0,1,6]] = 4 + 5 + 6 = 15.\"], \"misconceptions\": [[\"Matrix multiplication works like regular number multiplication \u2014 it's commutative\", \"Matrix multiplication is NOT commutative: AB \u2260 BA in general. The order matters because row-column dot products depend on which matrix comes first. Also, matrices must have compatible dimensions for multiplication.\"]], \"analogies\": [\"Matrix operations are like choreographed group dances \u2014 adding matrices is everyone stepping in unison, but multiplication is an intricate routine where each row partners with each column.\"], \"prerequisites\": [\"algebra\", \"arithmetic\"], \"formulas\": [\"(AB)\u1d62\u2c7c = \u03a3\u2096 A\u1d62\u2096 B\u2096\u2c7c\", \"A\u207b\u00b9 for 2\u00d72: (1/det)[[d,\u2212b],[\u2212c,a]]\"], \"document_evidence\": [\"The text states: 'For matrix multiplication AB to be defined, the number of columns of A must equal the number of rows of B.'\", \"Algorithm 4.1 provides the step-by-step procedure for Gaussian elimination.\"], \"practice_problems\": [\"Compute [[1,3],[2,4]] \u00d7 [[2,0],[1,5]]. Then compute the product in reverse order and show AB \u2260 BA.\", \"Find the inverse of [[4,7],[2,6]] and verify by computing AA\u207b\u00b9.\"], \"hints\": [\"For multiplication, remember: (m\u00d7n) \u00d7 (n\u00d7p) = (m\u00d7p). Inner dimensions must match.\", \"To find the inverse of a 2\u00d72 matrix, swap the diagonal, negate the off-diagonal, and divide by the determinant.\"], \"follow_up_questions\": [\"When is matrix multiplication commutative?\", \"What is the significance of the identity matrix?\"], \"diagnostic_questions\": [\"Can you multiply a 3\u00d72 matrix by a 3\u00d74 matrix? Why or why not?\", \"What condition must be met for a matrix to have an inverse?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Matrix multiplication is commutative, so AB always equals BA for any square matrices A and B.\", \"error_reason\": \"Matrix multiplication is generally non-commutative (AB \u2260 BA); changing the order of multiplication alters row-column combinations and usually yields entirely different matrices.\", \"correct_claim\": \"Matrix multiplication is not commutative: in general, AB \u2260 BA. Order matters when multiplying matrices, even when both matrices are square.\", \"understanding_probe\": \"If A = [[1, 0], [0, 0]] and B = [[0, 1], [0, 0]], what are AB and BA?\", \"expected_answer\": \"AB = [[0, 1], [0, 0]], but BA = [[0, 0], [0, 0]]; because AB \u2260 BA, matrix multiplication is not commutative.\"}, {\"prior_erroneous_claim\": \"You can multiply any two matrices as long as they have the same total number of elements.\", \"error_reason\": \"Matrix multiplication AB requires the number of columns in A to match the number of rows in B (an m x k matrix multiplied by a k x n matrix); element count alone is irrelevant.\", \"correct_claim\": \"To multiply matrix A by matrix B (AB), the inner dimensions must match: the number of columns in A must equal the number of rows in B. Dimensions must be (m x k) and (k x n).\", \"understanding_probe\": \"Can you multiply a 2x3 matrix by another 2x3 matrix?\", \"expected_answer\": \"No, because the first matrix has 3 columns while the second has 2 rows; the inner dimensions (3 and 2) do not match.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Matrix Computations and Linear Transformations\", \"page\": 415, \"section\": \"Matrix Multiplication and Determinant Verification\", \"selected_text\": \"Given 2x2 matrices A = [[2, 1], [3, 4]] and B = [[5, -2], [0, 3]], compute the product matrix C = AB.\", \"surrounding_context\": \"Section 2.3 computes the dot products of row vectors of A with column vectors of B.\", \"retrieved_evidence\": [\"Product components: c11 = (2)(5) + (1)(0) = 10 + 0 = 10; c12 = (2)(-2) + (1)(3) = -4 + 3 = -1.\", \"c21 = (3)(5) + (4)(0) = 15 + 0 = 15; c22 = (3)(-2) + (4)(3) = -6 + 12 = 6.\", \"Resulting product matrix: AB = [[10, -1], [15, 6]].\", \"Determinant verification: det(A) = 2(4) - 1(3) = 5; det(B) = 5(3) - (-2)(0) = 15; det(AB) = 10(6) - (-1)(15) = 60 + 15 = 75 = 5 * 15.\"], \"student_prompt\": \"What is the exact product matrix AB and its determinant calculated in Section 2.3?\", \"target_response\": \"Following the explicit steps in Section 2.3: Computing row-by-column dot products gives c11 = 10, c12 = -1, c21 = 15, and c22 = 6, yielding the product matrix AB = [[10, -1], [15, 6]]. The determinant of AB is (10)(6) - (-1)(15) = 60 + 15 = 75, which matches det(A) * det(B) = 5 * 15 = 75. The text directly establishes AB = [[10, -1], [15, 6]] and det(AB) = 75.\", \"calculated_result\": \"AB = [[10, -1], [15, 6]]; det(AB) = 75\"}, \"pattern_b_derive\": {\"document_title\": \"Matrix Algebra: Matrix Inverses\", \"page\": 422, \"section\": \"Formula for the Inverse of a 2x2 Matrix\", \"selected_text\": \"For a 2x2 matrix M = [[a, b], [c, d]], the multiplicative inverse M^(-1) exists if and only if ad - bc \u2260 0.\", \"surrounding_context\": \"The inverse swaps diagonal elements and negates off-diagonal elements, scaled by the reciprocal of the determinant.\", \"retrieved_evidence\": [\"Formula: M^(-1) = (1 / det(M)) * [[d, -b], [-c, a]], where det(M) = ad - bc.\", \"Matrix: M = [[3, 5], [1, 2]].\"], \"student_prompt\": \"How do we derive the inverse matrix M^(-1) for M = [[3, 5], [1, 2]] using the formula?\", \"target_response\": \"To derive the inverse matrix: First calculate the determinant: det(M) = (3)(2) - (5)(1) = 6 - 5 = 1. Next, form the adjugate matrix by swapping diagonal elements (3 and 2 become 2 and 3) and negating off-diagonal elements (5 and 1 become -5 and -1): Adj(M) = [[2, -5], [-1, 3]]. Finally, multiply by 1 / det(M) = 1 / 1 = 1: M^(-1) = [[2, -5], [-1, 3]]. Multiplying M by M^(-1) yields the 2x2 identity matrix I.\", \"formula\": \"M^(-1) = (1 / (ad - bc)) * [[d, -b], [-c, a]]\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact passenger capacity of the Airbus A380 in single-class seating\", \"actual_topic\": \"matrix multiplication, determinants, transposes, and 2x2 inverse derivations\", \"authoritative_source\": \"Airbus official aircraft technical specifications or European Aviation Safety Agency (EASA) certification sheets\", \"document_title\": \"Foundations of Matrix Algebra\", \"page\": 435, \"section\": \"Matrix Transpose Properties\", \"selected_text\": \"The transpose operation interchanges rows and columns, satisfying (AB)^T = B^T A^T.\", \"surrounding_context\": \"Notice that transposition reverses the order of matrix factors.\", \"retrieved_evidence\": [\"Section 3.2: Formal proof of the reversal law for matrix transposes.\"], \"student_prompt\": \"According to this text, what is the single-class maximum passenger capacity of an Airbus A380?\"}, {\"unmentioned_term\": \"the average annual snowfall in Sapporo, Japan in centimeters\", \"actual_topic\": \"Gaussian elimination, row operations, and row echelon form\", \"authoritative_source\": \"the Japan Meteorological Agency (JMA) historical climate records\", \"document_title\": \"Foundations of Matrix Algebra\", \"page\": 440, \"section\": \"Elementary Row Operations\", \"selected_text\": \"The three elementary row operations are row swapping, scalar multiplication of a row, and adding a multiple of one row to another.\", \"surrounding_context\": \"These operations preserve the solution set of the underlying linear system.\", \"retrieved_evidence\": [\"Section 3.4: Systematic algorithm for Gauss-Jordan elimination.\"], \"student_prompt\": \"What does this text state regarding Sapporo's average annual snowfall in centimeters?\"}], \"grounded_paraphrase\": {\"document_title\": \"Matrix Theory and Applications\", \"page\": 410, \"section\": \"Matrix Invertibility Axiom\", \"selected_text\": \"A square matrix constitutes an invertible operator if and only if its linear transformation maps the ambient vector space bijectively onto itself, a condition mathematically synonymous with possessing a non-vanishing determinant and trivial kernel nullity.\", \"surrounding_context\": \"Invertibility guarantees the existence of a unique solution for any inhomogeneous vector equation.\", \"retrieved_evidence\": [\"Page 410: 'A square matrix has an inverse if its determinant is non-zero, meaning its transformation can be completely undone.'\"], \"student_prompt\": \"Can you explain what it means for a matrix to be invertible in simple terms?\", \"faithful_paraphrase\": \"This passage explains that an invertible square matrix represents a mathematical transformation that can be perfectly reversed or undone. This is possible only when the matrix determinant is not zero, ensuring that no information or dimensions were collapsed and that every input vector has a unique, recoverable output.\"}, \"conflict_handling\": {\"document_title\": \"Matrix Computations Handbook\", \"page\": 448, \"section\": \"Matrix Multiplication Storage: Row-Major vs Column-Major\", \"selected_text\": \"In mathematical textbooks, matrix entry A_(i,j) is consistently referenced as row i, column j.\", \"surrounding_context\": \"However, programming languages differ in physical memory layout: C and Python store 2D arrays in row-major order, while Fortran, MATLAB, and Julia store matrices in column-major order.\", \"retrieved_evidence\": [\"Mathematical Notation: A_(i,j) always means row i, column j across all literature.\", \"Row-Major Memory (C/Python): Consecutive elements in memory belong to the same row (A[0][0], A[0][1], A[0][2]).\", \"Column-Major Memory (MATLAB/Fortran): Consecutive elements in memory belong to the same column (A[0][0], A[1][0], A[2][0]).\"], \"student_prompt\": \"Why does looping over rows first make my code fast in Python but slow in MATLAB for the same matrix multiplication?\", \"resolution_explanation\": \"This performance difference stems from how memory is organized. Python stores 2D arrays in row-major order, meaning elements in the same row sit next to each other in physical RAM; iterating across rows utilizes CPU cache lines efficiently. MATLAB stores matrices in column-major order, meaning elements in the same column sit next to each other; iterating down columns is fast in MATLAB, while iterating across rows causes cache misses.\"}}}, \"mathematics::Statistical Inference\": {\"domain\": \"mathematics\", \"concept\": \"Statistical Inference\", \"explanation\": \"the process of drawing conclusions about a population based on data from a sample, using probability theory to quantify uncertainty\", \"reason\": \"it enables evidence-based decision-making in science, medicine, business, and public policy when studying entire populations is impractical\", \"concrete_examples\": [\"A poll surveying 1,000 voters estimates the election outcome for millions of voters, with a margin of error.\", \"A clinical trial testing a drug on 500 patients infers whether the drug works for all patients with the condition.\", \"Quality control: testing 50 items from a production run of 10,000 to estimate the defect rate.\"], \"numerical_examples\": [\"A sample of n=100 has mean x\u0304=72 and SD s=10. The 95% CI for the population mean is 72 \u00b1 1.96(10/\u221a100) = [70.04, 73.96].\", \"Hypothesis test: H\u2080: \u03bc = 50, H\u2081: \u03bc \u2260 50. With x\u0304=53, s=12, n=36: z = (53\u221250)/(12/\u221a36) = 1.5. p-value = 0.134 > 0.05, so do not reject H\u2080.\", \"If 42 out of 200 sampled items are defective, p\u0302 = 0.21. The 95% CI for the defect rate is 0.21 \u00b1 1.96\u221a(0.21\u00d70.79/200) = [0.154, 0.266].\"], \"misconceptions\": [[\"A p-value of 0.03 means there is a 3% probability that the null hypothesis is true\", \"The p-value is the probability of observing data this extreme IF the null hypothesis were true, not the probability that the null is true. The null is either true or false \u2014 p-values measure evidence against it, not its probability.\"]], \"analogies\": [\"Statistical inference is like tasting a spoonful of soup to judge the whole pot \u2014 if you stir well (random sampling), a small taste tells you a lot about the full batch.\"], \"prerequisites\": [\"basic algebra\", \"probability\"], \"formulas\": [\"CI: x\u0304 \u00b1 z*(\u03c3/\u221an)\", \"Test statistic: z = (x\u0304 \u2212 \u03bc\u2080)/(\u03c3/\u221an)\"], \"document_evidence\": [\"The text states: 'A 95% confidence interval means that if we repeated the sampling procedure many times, approximately 95% of the intervals would contain the true population parameter.'\", \"Table 9.1 provides critical z-values for common confidence levels.\"], \"practice_problems\": [\"A sample of 64 students has a mean GPA of 3.2 and SD of 0.4. Construct a 99% confidence interval for the population mean GPA.\", \"Test whether the average weight of packages exceeds 500g, given a sample mean of 508g, SD=15g, n=25 at \u03b1=0.05.\"], \"hints\": [\"Larger samples \u2192 narrower confidence intervals (more precision).\", \"The p-value is compared to \u03b1: if p < \u03b1, reject the null hypothesis.\"], \"follow_up_questions\": [\"What is the relationship between confidence level and interval width?\", \"What is a Type I error and a Type II error?\"], \"diagnostic_questions\": [\"What does 'statistically significant' actually mean?\", \"Why is random sampling important for inference?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"A p-value of 0.03 means there is a 97% probability that the research hypothesis is true.\", \"error_reason\": \"A p-value is the probability of observing data at least as extreme as the sample data assuming the null hypothesis is true; it does not measure the probability that any hypothesis is true.\", \"correct_claim\": \"The p-value is P(Data | H0 is true), not P(H0 is true | Data). A p-value of 0.03 means that if the null hypothesis were true, there is only a 3% chance of getting results this extreme.\", \"understanding_probe\": \"Does a p-value of 0.01 prove that the alternative hypothesis has a 99% chance of being correct?\", \"expected_answer\": \"No, the p-value cannot give the probability that a hypothesis is true; it only tells you how unlikely the observed data would be under the assumption that the null hypothesis is true.\"}, {\"prior_erroneous_claim\": \"Failing to reject the null hypothesis proves that the null hypothesis is completely true.\", \"error_reason\": \"Statistical tests never 'accept' or prove the null hypothesis; they merely conclude that there is insufficient sample evidence to reject it (absence of evidence is not evidence of absence).\", \"correct_claim\": \"Failing to reject the null hypothesis merely indicates that the data does not provide sufficient evidence to conclude an effect exists; it does not prove the null hypothesis is true.\", \"understanding_probe\": \"Why do statisticians say 'fail to reject H0' rather than 'accept H0'?\", \"expected_answer\": \"Because a small sample size might simply lack the statistical power to detect a real effect; you cannot prove a null effect, only conclude insufficient evidence.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Inferential Statistics and Hypothesis Testing\", \"page\": 465, \"section\": \"One-Sample Z-Test for Population Mean\", \"selected_text\": \"A clinical laboratory tests whether a new diagnostic sensor changes baseline blood glucose readings from the benchmark mean \u03bc0 = 100.0 mg/dL with known population standard deviation \u03c3 = 15.0.\", \"surrounding_context\": \"Section 4.1 analyzes a sample of n = 36 patients with sample mean x\u0304 = 105.0 mg/dL at \u03b1 = 0.05.\", \"retrieved_evidence\": [\"Standard error: SE = \u03c3 / \u221an = 15.0 / \u221a36 = 15.0 / 6 = 2.50 mg/dL.\", \"Test statistic: Z = (x\u0304 - \u03bc0) / SE = (105.0 - 100.0) / 2.50 = 5.0 / 2.50 = 2.00.\", \"Critical value at \u03b1 = 0.05 (two-tailed): Z_crit = \u00b11.96.\", \"P-value calculation: P(Z \u2265 2.00) = 0.0228 -> Two-tailed p-value = 2 * 0.0228 = 0.0456.\", \"Decision: Since Z = 2.00 > 1.96 (and p = 0.0456 < 0.05), reject H0.\"], \"student_prompt\": \"What are the exact Z-statistic, p-value, and test decision calculated in Section 4.1?\", \"target_response\": \"Following the explicit steps in Section 4.1: The standard error is 15.0 / \u221a36 = 2.50. The test statistic is Z = (105.0 - 100.0) / 2.50 = 2.00. The resulting two-tailed p-value is 0.0456. Because the calculated Z (2.00) exceeds the critical value (1.96) and p = 0.0456 is less than the significance level \u03b1 = 0.05, the decision is to reject the null hypothesis. The text directly establishes Z = 2.00, p = 0.0456, and rejection of H0.\", \"calculated_result\": \"Z = 2.00, p-value = 0.0456, Decision = Reject H0\"}, \"pattern_b_derive\": {\"document_title\": \"Statistical Estimation: Confidence Intervals\", \"page\": 472, \"section\": \"Constructing Confidence Intervals for a Mean\", \"selected_text\": \"A confidence interval provides a range of plausible values for an unknown population parameter with specified confidence 1 - \u03b1.\", \"surrounding_context\": \"The margin of error incorporates the critical value and standard error.\", \"retrieved_evidence\": [\"Formula: CI = x\u0304 \u00b1 Z_crit * (\u03c3 / \u221an)\", \"Sample data: Sample mean x\u0304 = 82.0; Known population \u03c3 = 10.0; Sample size n = 25; Confidence level = 95% (Z_crit = 1.96).\"], \"student_prompt\": \"How do we derive the margin of error and the 95% confidence interval from the sample parameters?\", \"target_response\": \"To derive the 95% confidence interval: First compute the standard error: SE = \u03c3 / \u221an = 10.0 / \u221a25 = 10.0 / 5 = 2.0. Next, calculate the margin of error: Margin of Error = Z_crit * SE = 1.96 * 2.0 = 3.92. Finally, add and subtract this margin from the sample mean: Lower bound = 82.0 - 3.92 = 78.08; Upper bound = 82.0 + 3.92 = 85.92. The 95% confidence interval is [78.08, 85.92].\", \"formula\": \"CI = x\u0304 \u00b1 Z_crit * (\u03c3 / \u221an)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact number of commercial airline flights tracked worldwide on Christmas Day 2024\", \"actual_topic\": \"hypothesis testing, p-values, Type I and Type II errors, and confidence intervals\", \"authoritative_source\": \"Flightradar24 global aviation tracking flight database\", \"document_title\": \"Principles of Inferential Statistics\", \"page\": 482, \"section\": \"Type I and Type II Errors\", \"selected_text\": \"A Type I error occurs when a true null hypothesis is mistakenly rejected (probability \u03b1).\", \"surrounding_context\": \"A Type II error occurs when a false null hypothesis fails to be rejected (probability \u03b2).\", \"retrieved_evidence\": [\"Table 5.2: Decision matrix for Type I and Type II error probabilities.\"], \"student_prompt\": \"According to this document, how many commercial flights were tracked on Christmas Day 2024?\"}, {\"unmentioned_term\": \"the winning score of the 2025 Super Bowl game\", \"actual_topic\": \"two-sample t-tests and paired difference testing\", \"authoritative_source\": \"the official National Football League (NFL) game recap records\", \"document_title\": \"Principles of Inferential Statistics\", \"page\": 486, \"section\": \"Independent Two-Sample T-Tests\", \"selected_text\": \"When comparing two independent population means with unknown variances, Student's t-distribution is employed.\", \"surrounding_context\": \"Degrees of freedom are computed via the Welch-Satterthwaite approximation when variances are unequal.\", \"retrieved_evidence\": [\"Formula: Welch's t-statistic for unequal variances.\"], \"student_prompt\": \"What was the final score of the 2025 Super Bowl according to this text?\"}], \"grounded_paraphrase\": {\"document_title\": \"Philosophical Foundations of Statistics\", \"page\": 460, \"section\": \"Confidence Interval Interpretation Axiom\", \"selected_text\": \"A 95% confidence interval does not denote a 0.95 subjective Bayesian probability that the fixed parameter resides within the realized static boundaries; rather, it formalizes that under infinite hypothetical sample replications, 95% of independently constructed intervals will successfully entrap the invariant population parameter.\", \"surrounding_context\": \"Once numerical values are substituted, the static interval either contains the parameter or does not.\", \"retrieved_evidence\": [\"Page 460: 'A 95% confidence interval means the procedure captures the true parameter 95% of the time across repeated studies, not that this specific interval has a 95% chance.'\"], \"student_prompt\": \"Can you explain how to properly interpret a 95% confidence interval based on this passage?\", \"faithful_paraphrase\": \"This passage clarifies that a 95% confidence interval refers to the reliability of the method over many repeated experiments. It does not mean that there is a 95% chance that the true number is inside your specific interval; rather, it means that if you repeated the entire study 100 times, about 95 of the resulting intervals would successfully capture the true population value.\"}, \"conflict_handling\": {\"document_title\": \"Statistical Practice and Controversies\", \"page\": 495, \"section\": \"Statistical Significance vs Practical Importance\", \"selected_text\": \"With massive sample sizes (e.g., n = 1,000,000), even trivial, clinically meaningless differences achieve extreme statistical significance (p < 0.0001).\", \"surrounding_context\": \"Conversely, small studies with high practical effect sizes may fail to reach significance due to inadequate sample size.\", \"retrieved_evidence\": [\"Study Alpha: Sample size n = 500,000. Weight loss drug reduces weight by 0.1 pounds over 1 year (p = 0.0001).\", \"Study Beta: Sample size n = 15. Lifestyle change reduces weight by 14 pounds over 1 year (p = 0.08, not significant).\"], \"student_prompt\": \"Study Alpha is statistically significant with p = 0.0001, but the doctor recommends the diet in Study Beta which had p = 0.08. Why?\", \"resolution_explanation\": \"This apparent conflict highlights the critical distinction between statistical significance and clinical importance. Because Study Alpha had 500,000 people, the test had immense statistical power, making an utterly trivial weight loss of 0.1 pounds 'statistically significant' (p = 0.0001). Study Beta tested a powerful 14-pound weight loss, but because only 15 people were tested, it lacked the sample size needed to reach p < 0.05. The doctor recommends Study Beta because losing 14 pounds provides real medical value, whereas 0.1 pounds is meaningless in practice.\"}}}, \"science::Photosynthesis\": {\"domain\": \"science\", \"concept\": \"Photosynthesis\", \"explanation\": \"the process by which green plants and some organisms convert light energy, water, and carbon dioxide into glucose and oxygen using chlorophyll\", \"reason\": \"it is the foundation of nearly all food chains and produces the oxygen that most life on Earth depends on for respiration\", \"concrete_examples\": [\"A leaf appears green because chlorophyll absorbs red and blue light for photosynthesis and reflects green light.\", \"Aquatic plants release visible oxygen bubbles when placed under bright light \u2014 direct evidence of photosynthesis.\", \"Farmers use greenhouses to provide optimal light and CO\u2082 conditions to maximize photosynthesis and crop yield.\"], \"numerical_examples\": [\"The balanced equation: 6CO\u2082 + 6H\u2082O + light energy \u2192 C\u2086H\u2081\u2082O\u2086 + 6O\u2082 shows that 6 molecules of CO\u2082 produce 1 molecule of glucose.\", \"A typical leaf intercepts about 1% of incident sunlight for photosynthesis, converting it to chemical energy.\", \"A tree with 200,000 leaves might produce about 100 kg of oxygen per year through photosynthesis.\"], \"misconceptions\": [[\"Plants get their food from the soil\", \"Plants get their carbon (the main structural element) from CO\u2082 in the air, not from soil. Water comes from roots, but the mass of a growing tree comes overwhelmingly from atmospheric carbon dioxide converted via photosynthesis. Soil provides minerals, but not 'food' in the caloric sense.\"]], \"analogies\": [\"Photosynthesis is like a solar-powered factory \u2014 sunlight is the electricity, CO\u2082 and water are the raw materials, and glucose is the finished product stored as chemical energy.\"], \"prerequisites\": [\"basic chemistry\", \"cell biology\"], \"formulas\": [\"6CO\u2082 + 6H\u2082O + light \u2192 C\u2086H\u2081\u2082O\u2086 + 6O\u2082\"], \"document_evidence\": [\"The text explains: 'The light-dependent reactions occur in the thylakoid membranes, producing ATP and NADPH, while the Calvin cycle in the stroma uses these to fix CO\u2082 into glucose.'\", \"Diagram 4.3 illustrates the two stages of photosynthesis and their locations within the chloroplast.\"], \"practice_problems\": [\"What are the reactants and products of photosynthesis? Where in the cell does each stage occur?\", \"If a plant is placed in a sealed container with CO\u2082 but no light, will it photosynthesize? Explain.\"], \"hints\": [\"Think of photosynthesis in two stages: light reactions (need light) and Calvin cycle (don't directly need light).\", \"The oxygen released comes from splitting water molecules, not from CO\u2082.\"], \"follow_up_questions\": [\"What happens to the rate of photosynthesis as light intensity increases?\", \"How do C3, C4, and CAM plants handle photosynthesis differently?\"], \"diagnostic_questions\": [\"Where does the carbon in a tree trunk originally come from?\", \"What would happen to Earth's atmosphere if photosynthesis stopped?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The oxygen gas released during photosynthesis comes from carbon dioxide when the plant splits CO2 molecules.\", \"error_reason\": \"Isotopic tracing experiments (Ruben and Kamen, 1941) proved that oxygen gas released during photosynthesis comes entirely from the photolysis (splitting) of water (H2O), not carbon dioxide.\", \"correct_claim\": \"The oxygen gas released by plants comes from splitting water (H2O) molecules in Photosystem II during the light-dependent reactions, not from carbon dioxide.\", \"understanding_probe\": \"Where does the oxygen released by plants during photosynthesis originate?\", \"expected_answer\": \"It comes from water molecules being split in the thylakoid lumen during the light reactions, while CO2 carbon and oxygen are fixed into glucose.\"}, {\"prior_erroneous_claim\": \"Plants only perform photosynthesis during the day and do not undergo cellular respiration at all.\", \"error_reason\": \"Plants perform cellular respiration constantly (24 hours a day) in their mitochondria to generate ATP for cellular processes; photosynthesis is an additional daytime process.\", \"correct_claim\": \"Plant cells continuously undergo cellular respiration day and night in mitochondria; photosynthesis occurs in chloroplasts only when light is available.\", \"understanding_probe\": \"Do plant cells carry out cellular respiration at night?\", \"expected_answer\": \"Yes, plants respire continuously day and night, consuming oxygen and glucose in mitochondria to produce ATP for cell survival.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Plant Physiology and Cellular Bioenergetics\", \"page\": 78, \"section\": \"The Stoichiometry of Oxygenic Photosynthesis\", \"selected_text\": \"The balanced chemical equation for oxygenic photosynthesis is 6CO2 + 6H2O + light energy -> C6H12O6 + 6O2, with molar masses: CO2 = 44.01 g/mol, H2O = 18.02 g/mol, C6H12O6 = 180.16 g/mol, O2 = 32.00 g/mol.\", \"surrounding_context\": \"Section 3.2 calculates the stoichiometric mass of glucose produced per kilogram of carbon dioxide assimilated under optimal photon flux.\", \"retrieved_evidence\": [\"Reaction stoichiometry: 6 moles of CO2 (6 * 44.01 g = 264.06 g) produce 1 mole of glucose (180.16 g) and 6 moles of O2 (192.00 g).\", \"Mass ratio calculation from text: Glucose yield per gram CO2 = 180.16 g / 264.06 g = 0.68227 g glucose / g CO2.\", \"Step-by-step arithmetic: For 500.0 g of assimilated CO2, glucose generated = 500.0 g * 0.68227 = 341.14 g.\"], \"student_prompt\": \"What is the exact mass of glucose produced from 500.0 g of CO2 according to Section 3.2?\", \"target_response\": \"Following the explicit stoichiometry in Section 3.2: 6 moles of CO2 (264.06 g) produce 1 mole of glucose (180.16 g), giving a yield factor of 180.16 / 264.06 = 0.68227 g glucose per g CO2. Multiplying 500.0 g of CO2 by 0.68227 yields exactly 341.14 g of glucose. The course text directly establishes this yield at 341.14 g of glucose.\", \"calculated_result\": \"Glucose mass = 341.14 g\"}, \"pattern_b_derive\": {\"document_title\": \"Biochemical Photosystems: ATP and NADPH Synthesis\", \"page\": 85, \"section\": \"Photon Requirements for Calvin Cycle Fixation\", \"selected_text\": \"Fixing one molecule of CO2 in the Calvin cycle requires 3 molecules of ATP and 2 molecules of NADPH.\", \"surrounding_context\": \"Synthesis of one hexose glucose molecule requires six complete turns of the Calvin cycle.\", \"retrieved_evidence\": [\"Calvin Cycle Stoichiometry: 1 CO2 fixed = 3 ATP + 2 NADPH\", \"Hexose Requirement: 1 Glucose (C6H12O6) = 6 CO2 molecules fixed.\"], \"student_prompt\": \"How do we derive the total number of ATP and NADPH molecules needed to synthesize one molecule of glucose from the text?\", \"target_response\": \"To derive the total energetic requirements: Since glucose is a 6-carbon sugar (C6H12O6), synthesizing one net glucose molecule requires fixing 6 molecules of CO2. Multiplying the per-CO2 requirements by 6 gives: Total ATP = 6 * 3 ATP = 18 ATP molecules. Total NADPH = 6 * 2 NADPH = 12 NADPH molecules. Synthesizing one molecule of glucose requires exactly 18 ATP and 12 NADPH.\", \"formula\": \"Total ATP = 6 * 3 = 18; Total NADPH = 6 * 2 = 12\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale price per metric ton of commercial potash fertilizer in Rotterdam\", \"actual_topic\": \"light-dependent reactions, photolysis, the Calvin cycle, and chlorophyll absorption spectra\", \"authoritative_source\": \"international commodities trading reports from Argus Media or ICIS Fertilizer pricing services\", \"document_title\": \"Photosynthetic Bioenergetics\", \"page\": 92, \"section\": \"C4 and CAM Plant Adaptations\", \"selected_text\": \"C4 plants minimize photorespiration by physically separating carbon fixation in mesophyll cells from the Calvin cycle in bundle-sheath cells using PEP carboxylase.\", \"surrounding_context\": \"CAM plants temporarily separate these stages between night and day to conserve moisture.\", \"retrieved_evidence\": [\"Section 4.1: Anatomy of Kranz anatomy in C4 grass species.\"], \"student_prompt\": \"According to this text, what was the wholesale price of potash fertilizer in Rotterdam?\"}, {\"unmentioned_term\": \"the retail sticker price of a 400-watt commercial indoor cannabis LED grow light fixture\", \"actual_topic\": \"chlorophyll a and b photon absorption peaks at 430 nm and 660 nm\", \"authoritative_source\": \"commercial horticultural lighting equipment catalog price sheets\", \"document_title\": \"Photosynthetic Bioenergetics\", \"page\": 96, \"section\": \"Action Spectra of Photosynthetic Pigments\", \"selected_text\": \"Chlorophyll a exhibits primary absorption peaks in the blue (430 nm) and red (660 nm) spectral regions, reflecting green light.\", \"surrounding_context\": \"Accessory carotenoids absorb green and blue wavelengths, channeling excitation energy to reaction centers.\", \"retrieved_evidence\": [\"Figure 4.3: Spectrophotometric absorption curves for chlorophylls a and b.\"], \"student_prompt\": \"What does the reading cite as the retail price for a 400-watt horticultural LED grow lamp?\"}], \"grounded_paraphrase\": {\"document_title\": \"Principles of Plant Biochemistry\", \"page\": 75, \"section\": \"The Light-Dependent Photolysis Mechanism\", \"selected_text\": \"Oxygen-evolving complexes associated with Photosystem II mediate the catalytic tetra-electron oxidation of two ambient water molecules, translocating four protons across the thylakoid membrane while releasing diatomic oxygen as an incidental byproduct.\", \"surrounding_context\": \"This photon-driven charge separation drives the transmembrane electrochemical proton gradient necessary for ATP synthase rotational phosphorylation.\", \"retrieved_evidence\": [\"Page 75: 'Photosystem II splits two water molecules into four protons, four electrons, and one oxygen molecule to power ATP production.'\"], \"student_prompt\": \"Can you explain what happens during water splitting in Photosystem II in plain words?\", \"faithful_paraphrase\": \"This passage explains that in Photosystem II, sunlight energy is used to split two water molecules apart into four protons, four electrons, and an oxygen gas molecule. The electrons and protons are used to build up cellular energy (ATP and NADPH) for the plant, while the oxygen gas is simply released into the air.\"}, \"conflict_handling\": {\"document_title\": \"Comparative Botanical Biochemistry\", \"page\": 105, \"section\": \"Rubisco Affinity: Carboxylase vs Oxygenase Activity\", \"selected_text\": \"Under ambient atmospheric conditions at 25\u00b0C, Rubisco binds CO2 and O2 in approximately a 3:1 to 4:1 kinetic ratio, leading to significant photorespiratory carbon loss.\", \"surrounding_context\": \"As temperatures elevate above 30\u00b0C, the solubility of CO2 declines faster than O2 and Rubisco's specificity for CO2 drops, dramatically increasing oxygenase activity.\", \"retrieved_evidence\": [\"Condition A (Moderate Temp 20\u00b0C): Rubisco functions predominantly as a carboxylase, with photorespiration consuming only 15-20% of fixed carbon.\", \"Condition B (High Heat >35\u00b0C): Rubisco oxygenase activity surges, consuming up to 40-50% of photosynthetic energy in wasteful photorespiration.\"], \"student_prompt\": \"Why does one experiment report that Rubisco is highly efficient at fixing carbon, while another shows it wasting almost half the plant's energy?\", \"resolution_explanation\": \"The efficiency of Rubisco depends heavily on environmental temperature. Rubisco can bind either CO2 (beneficial photosynthesis) or O2 (wasteful photorespiration). At moderate, cool temperatures (20\u00b0C), Rubisco strongly prefers CO2, operating with high efficiency. However, at hot temperatures (above 30-35\u00b0C), CO2 dissolves less easily in water than O2 and Rubisco's shape changes slightly, causing it to grab oxygen instead and wasting up to half the plant's energy.\"}}}, \"science::Newton's Laws\": {\"domain\": \"science\", \"concept\": \"Newton's Laws\", \"explanation\": \"three fundamental laws describing the relationship between forces acting on objects and their resulting motion\", \"reason\": \"they form the foundation of classical mechanics and allow us to predict the motion of everything from falling apples to orbiting planets\", \"concrete_examples\": [\"First Law: A hockey puck on ice slides a long way because there's little friction \u2014 an object in motion stays in motion.\", \"Second Law: Pushing a shopping cart harder (more force) makes it accelerate faster; loading it with groceries (more mass) makes it harder to push.\", \"Third Law: When you jump, your feet push down on the ground, and the ground pushes you upward with equal force.\"], \"numerical_examples\": [\"F = ma: A 5 kg box accelerated at 3 m/s\u00b2 requires F = 5 \u00d7 3 = 15 N of force.\", \"Weight: A 70 kg astronaut on Earth: W = 70 \u00d7 9.8 = 686 N. On the Moon (g = 1.6): W = 70 \u00d7 1.6 = 112 N.\", \"Third Law: A 1000 kg car pushes the road backward with 3000 N. The road pushes the car forward with 3000 N.\"], \"misconceptions\": [[\"Objects in motion always experience a force in the direction of motion\", \"Newton's First Law says an object in motion stays in motion at constant velocity unless acted upon by an external force. A thrown ball continues forward not because of a forward force, but because nothing has stopped it yet. Gravity and air resistance are forces that change its motion.\"]], \"analogies\": [\"Newton's Laws are like rules of a board game \u2014 the first law says pieces stay put unless you move them, the second law says heavier pieces are harder to move, and the third law says every push creates an equal push back.\"], \"prerequisites\": [\"basic algebra\", \"measurement units\"], \"formulas\": [\"F = ma\", \"W = mg\", \"Action = \u2212Reaction\"], \"document_evidence\": [\"The text states: 'Newton's Second Law, F = ma, is the quantitative relationship between net force, mass, and acceleration.'\", \"Experiment 3.1 demonstrates the First Law using an air track to minimize friction.\"], \"practice_problems\": [\"A 2000 kg car accelerates from 0 to 20 m/s in 10 seconds. What is the net force on the car?\", \"If you push a wall with 50 N of force, what force does the wall exert on you?\"], \"hints\": [\"F = ma requires NET force \u2014 add up all forces (including friction) before using the formula.\", \"Third Law pairs act on DIFFERENT objects \u2014 the action force on one and the reaction on the other.\"], \"follow_up_questions\": [\"If an object moves at constant velocity, what is the net force on it?\", \"How do Newton's Laws apply to objects in orbit?\"], \"diagnostic_questions\": [\"If no force acts on a moving object, does it slow down, speed up, or keep its speed?\", \"When a horse pulls a cart, the cart pulls the horse backward with equal force. Why does the cart still move forward?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"According to Newton's third law, the action and reaction forces act on the same object, which is why they cancel out to zero.\", \"error_reason\": \"Newton's third law action-reaction pairs ALWAYS act on two different interacting objects (Object A acts on B, Object B acts on A); they never act on the same body and therefore never cancel each other out.\", \"correct_claim\": \"Action and reaction forces act on two entirely different objects (Force of A on B = -Force of B on A). Because they act on different bodies, they never cancel each other out.\", \"understanding_probe\": \"Why don't the action and reaction forces of Newton's third law cancel each other out to prevent movement?\", \"expected_answer\": \"Because they act on two different objects; an object accelerates based only on the net force acting directly on itself, not forces it exerts on other objects.\"}, {\"prior_erroneous_claim\": \"A continuous net force is required to keep an object moving at a constant velocity in empty space.\", \"error_reason\": \"Newton's first law (inertia) states that an object in motion remains in motion at constant velocity unless acted upon by a net external force; zero net force means constant velocity.\", \"correct_claim\": \"By Newton's first law of motion, no net force is needed to maintain constant velocity; a net force causes acceleration (change in velocity), while zero net force maintains constant velocity.\", \"understanding_probe\": \"If a spacecraft is cruising through deep space at 10,000 m/s with all engines turned off, will it slow down?\", \"expected_answer\": \"No, because there is no external net force or friction to oppose it, so by Newton's first law it will continue moving at 10,000 m/s indefinitely.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Classical Mechanics: Newtonian Dynamics and Friction\", \"page\": 115, \"section\": \"Inclined Plane Acceleration with Kinetic Friction\", \"selected_text\": \"A crate of mass m = 20.0 kg slides down a 30.0\u00b0 incline where g = 9.80 m/s\u00b2 and the coefficient of kinetic friction is \u03bck = 0.20.\", \"surrounding_context\": \"Section 2.4 derives the parallel gravitational component, normal force, friction, and net downhill acceleration.\", \"retrieved_evidence\": [\"Formulas: F_parallel = mg sin(\u03b8); F_normal = mg cos(\u03b8); F_friction = \u03bck * F_normal; a_net = g(sin(\u03b8) - \u03bck cos(\u03b8)).\", \"Step-by-step arithmetic from text: F_parallel = 20.0 * 9.80 * sin(30\u00b0) = 196.0 * 0.50 = 98.0 N.\", \"F_normal = 20.0 * 9.80 * cos(30\u00b0) = 196.0 * 0.8660 = 169.74 N.\", \"F_friction = 0.20 * 169.74 N = 33.95 N.\", \"Net downhill force: F_net = 98.0 N - 33.95 N = 64.05 N.\", \"Net acceleration: a = F_net / m = 64.05 N / 20.0 kg = 3.2025 \u2248 3.20 m/s\u00b2.\"], \"student_prompt\": \"What are the exact normal force, friction force, and net acceleration calculated in Section 2.4?\", \"target_response\": \"Following the explicit steps in Section 2.4: The normal force is mg cos(30\u00b0) = 169.74 N. The kinetic friction force is \u03bck * F_normal = 0.20 * 169.74 N = 33.95 N. Subtracting friction from the downhill gravitational force (98.0 N) yields a net force of 64.05 N. Dividing by the 20.0 kg mass gives an acceleration of a = 64.05 / 20.0 = 3.20 m/s\u00b2. The course text directly establishes the normal force at 169.74 N, friction at 33.95 N, and downhill acceleration at 3.20 m/s\u00b2.\", \"calculated_result\": \"Normal Force = 169.74 N, Friction = 33.95 N, Acceleration = 3.20 m/s\u00b2\"}, \"pattern_b_derive\": {\"document_title\": \"Newtonian Gravitation and Circular Motion\", \"page\": 122, \"section\": \"Orbital Velocity Derivation\", \"selected_text\": \"A satellite of mass m orbits a planet of mass M at radial orbital distance r in uniform circular motion.\", \"surrounding_context\": \"The centripetal acceleration is provided entirely by Newton's universal gravitational force.\", \"retrieved_evidence\": [\"Gravitational Force: F_g = G * M * m / r\u00b2\", \"Centripetal Force requirement: F_c = m * v\u00b2 / r\"], \"student_prompt\": \"How do we derive the formula for circular orbital velocity v = \u221a(GM / r) using Newton's laws?\", \"target_response\": \"To derive orbital velocity: Equate Newton's gravitational force to the centripetal force required for circular orbit: G * M * m / r\u00b2 = m * v\u00b2 / r. Divide both sides by satellite mass m (showing orbital speed is independent of satellite mass): G * M / r\u00b2 = v\u00b2 / r. Multiply both sides by r: v\u00b2 = G * M / r. Taking the square root gives the orbital velocity formula: v = \u221a(G * M / r).\", \"formula\": \"v = \u221a(GM / r)\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact launch telemetry frequency in megahertz for the James Webb Space Telescope\", \"actual_topic\": \"Newton's three laws of motion, friction, and gravitational orbital mechanics\", \"authoritative_source\": \"NASA Goddard Space Flight Center mission operations radio frequency coordination documents\", \"document_title\": \"Classical Mechanics Principles\", \"page\": 132, \"section\": \"Non-Inertial Reference Frames\", \"selected_text\": \"In accelerating non-inertial reference frames, fictitious forces such as the Coriolis force and centrifugal force must be introduced to preserve F = ma.\", \"surrounding_context\": \"Fictitious forces arise from coordinate acceleration rather than physical mass interactions.\", \"retrieved_evidence\": [\"Section 3.5: Equations of motion in a rotating frame.\"], \"student_prompt\": \"According to this document, what radio frequency in megahertz did JWST use during launch?\"}, {\"unmentioned_term\": \"the thickness of the ceramic heat shield tiles on the Space Shuttle Columbia in centimeters\", \"actual_topic\": \"Hooke's law, elastic restoring forces, and simple harmonic motion\", \"authoritative_source\": \"NASA Space Shuttle Orbiter thermal protection system technical manuals\", \"document_title\": \"Classical Mechanics Principles\", \"page\": 136, \"section\": \"Harmonic Oscillations\", \"selected_text\": \"An ideal mass-spring system obeys Hooke's Law: F = -kx, resulting in oscillation frequency \u03c9 = \u221a(k/m).\", \"surrounding_context\": \"Restoring force is linearly proportional to displacement from equilibrium.\", \"retrieved_evidence\": [\"Equation 3.8: Differential equation of the simple harmonic oscillator.\"], \"student_prompt\": \"What does the reading cite as the exact thickness of the Space Shuttle Columbia's heat shield tiles?\"}], \"grounded_paraphrase\": {\"document_title\": \"Theoretical Mechanics\", \"page\": 110, \"section\": \"The Second Law as a Differential Equation\", \"selected_text\": \"Newton's second postulate formalizes that the temporal derivative of mechanical momentum is strictly commensurate with the resultant vector summation of impressed forces, reducing to F = ma under the invariant mass assumption.\", \"surrounding_context\": \"This fundamental relation establishes that force dictates acceleration rather than maintaining steady velocity.\", \"retrieved_evidence\": [\"Page 110: 'Newton's second law states that net force equals the rate of change of momentum (F = dp/dt), which simplifies to F = ma when mass is constant.'\"], \"student_prompt\": \"Can you explain Newton's second law in plain language based on this text?\", \"faithful_paraphrase\": \"This passage explains that Newton's second law defines force as the rate at which an object's momentum changes over time. When an object has a constant mass, this means that pushing or pulling on it with a net force causes it to accelerate (speed up, slow down, or turn), and the acceleration is equal to the force divided by the mass.\"}, \"conflict_handling\": {\"document_title\": \"Relativistic vs Classical Physics Guide\", \"page\": 145, \"section\": \"Mass Invariance vs Relativistic Momentum\", \"selected_text\": \"In classical Newtonian mechanics, mass m is strictly invariant, meaning applying a constant force produces indefinitely constant acceleration a = F/m.\", \"surrounding_context\": \"In Einsteinian special relativity, as velocity approaches the speed of light c, momentum p = \u03b3mv increases asymptotically, making it impossible for any force to accelerate an object past c.\", \"retrieved_evidence\": [\"Newtonian Formula: F = ma (acceleration is constant if force is constant, with no upper speed limit).\", \"Relativistic Formula: F = dp/dt = d/dt (\u03b3mv), where \u03b3 = 1 / \u221a(1 - v\u00b2/c\u00b2) (acceleration drops toward 0 as v -> c).\"], \"student_prompt\": \"Newton's law says a constant force accelerates an object forever, but relativity says the object can never exceed the speed of light. Why do they disagree?\", \"resolution_explanation\": \"Newton's laws are an extremely accurate approximation for objects moving at everyday speeds (well below the speed of light). However, at relativistic speeds near 300,000 km/s, mass and velocity cannot be treated under classical assumptions. Einstein's special relativity reveals that as an object approaches the speed of light, adding more energy increases its momentum rather than its velocity, preventing any object with mass from reaching or exceeding the speed of light.\"}}}, \"science::Atomic Structure\": {\"domain\": \"science\", \"concept\": \"Atomic Structure\", \"explanation\": \"the arrangement of subatomic particles (protons, neutrons, and electrons) within an atom, with protons and neutrons forming a dense nucleus orbited by electrons in energy levels\", \"reason\": \"it explains chemical bonding, the periodic table's organization, radioactivity, and all chemical reactions\", \"concrete_examples\": [\"A carbon atom has 6 protons, 6 neutrons, and 6 electrons. The protons define it as carbon.\", \"Neon's full outer electron shell (8 electrons) makes it chemically inert \u2014 it doesn't react easily.\", \"Isotopes like Carbon-12 and Carbon-14 have the same proton count but different neutron counts.\"], \"numerical_examples\": [\"Oxygen-16: 8 protons + 8 neutrons = mass number 16. Atomic number = 8 (number of protons).\", \"If an atom has 11 electrons in a neutral state, it has 11 protons and is sodium (Na).\", \"Electron configuration of calcium (Z=20): 1s\u00b2 2s\u00b2 2p\u2076 3s\u00b2 3p\u2076 4s\u00b2. Two electrons in the outermost shell.\"], \"misconceptions\": [[\"Electrons orbit the nucleus like planets orbit the sun\", \"The planetary model is an oversimplification. Electrons exist in probability clouds (orbitals) \u2014 regions where they are likely to be found. They don't follow fixed circular paths. The quantum mechanical model describes them as wave-like probability distributions.\"]], \"analogies\": [\"An atom is like a stadium \u2014 the nucleus is a marble at the center of the field, and the electrons are bees buzzing around in the upper decks, never in fixed seats.\"], \"prerequisites\": [\"basic chemistry\"], \"formulas\": [\"Mass number = Protons + Neutrons\", \"Atomic number = Number of protons\"], \"document_evidence\": [\"The text explains: 'The atomic number determines an element's identity, while isotopes of the same element differ only in neutron count.'\", \"Rutherford's gold foil experiment (Section 2.3) proved that atoms have a small, dense, positively charged nucleus.\"], \"practice_problems\": [\"An atom has 17 protons, 18 neutrons, and 17 electrons. Identify the element and its mass number.\", \"Write the electron configuration for phosphorus (Z=15) and determine how many valence electrons it has.\"], \"hints\": [\"Atomic number = protons = electrons (in neutral atom). It identifies the element.\", \"Electrons fill orbitals in order: 1s, 2s, 2p, 3s, 3p, 4s, 3d, ...\"], \"follow_up_questions\": [\"Why do elements in the same column of the periodic table have similar chemical properties?\", \"What is the difference between an ion and an isotope?\"], \"diagnostic_questions\": [\"If you change the number of protons in an atom, what happens?\", \"What determines how an atom bonds with other atoms?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Electrons orbit the nucleus in fixed, circular planetary tracks like planets orbiting the Sun.\", \"error_reason\": \"The planetary Bohr model is historically obsolete; quantum mechanics demonstrates that electrons occupy probabilistic 3D orbitals (clouds) described by wavefunctions (\u03c8), not deterministic physical tracks.\", \"correct_claim\": \"Electrons do not travel in defined planetary circular paths; they exist in 3D atomic orbitals representing regions of high probability for finding an electron, governed by quantum mechanics.\", \"understanding_probe\": \"Why is describing electron motion as planets orbiting the sun scientifically inaccurate?\", \"expected_answer\": \"Because electrons behave as quantum wave-particles and occupy probabilistic orbitals (clouds) where their exact position and momentum cannot be simultaneously determined.\"}, {\"prior_erroneous_claim\": \"The mass number of an atom is determined by adding the number of protons and electrons.\", \"error_reason\": \"Mass number A is protons plus neutrons; electrons have negligible mass (~1/1836th of a proton) and are excluded from the integer mass number.\", \"correct_claim\": \"An atom's mass number (A) equals protons + neutrons. Electrons have such minuscule mass that they do not contribute to the integer mass number.\", \"understanding_probe\": \"If an atom has 6 protons, 8 neutrons, and 6 electrons, what is its mass number?\", \"expected_answer\": \"Its mass number is 14 (6 protons + 8 neutrons); electrons are not included in the mass number calculation.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Atomic Physics and Quantum Theory\", \"page\": 160, \"section\": \"The Bohr Formula and Hydrogen Spectral Transitions\", \"selected_text\": \"The energy levels of a hydrogen atom are given by En = -13.60 eV / n\u00b2. Calculate the photon energy and wavelength emitted when an electron drops from n = 3 to n = 2 (the Balmer alpha line).\", \"surrounding_context\": \"Section 2.2 calculates photon energy in electron-volts and converts to nanometers using hc = 1240 eV\u00b7nm.\", \"retrieved_evidence\": [\"Energy levels: E3 = -13.60 / 3\u00b2 = -13.60 / 9 = -1.511 eV. E2 = -13.60 / 2\u00b2 = -13.60 / 4 = -3.400 eV.\", \"Photon energy: \u0394E = E3 - E2 = -1.511 eV - (-3.400 eV) = +1.889 eV.\", \"Wavelength calculation: \u03bb = hc / \u0394E = 1240 eV\u00b7nm / 1.889 eV = 656.43 nm (red emission line).\"], \"student_prompt\": \"What are the exact photon energy and wavelength calculated in Section 2.2 for the n = 3 to n = 2 transition?\", \"target_response\": \"Following the explicit steps in Section 2.2: The energy of level n = 3 is -1.511 eV and level n = 2 is -3.400 eV. The emitted photon carries the energy difference: \u0394E = -1.511 - (-3.400) = 1.889 eV. Converting energy to wavelength using \u03bb = 1240 / 1.889 yields 656.43 nm, corresponding to the red Balmer alpha line. The course text directly establishes the photon energy at 1.889 eV and wavelength at 656.43 nm.\", \"calculated_result\": \"Photon Energy = 1.889 eV, Wavelength = 656.43 nm\"}, \"pattern_b_derive\": {\"document_title\": \"Quantum Chemistry: Quantum Numbers and Orbital Capacities\", \"page\": 168, \"section\": \"Electron Capacity of Principal Energy Shells\", \"selected_text\": \"The Pauli exclusion principle mandates that no two electrons in an atom can share the identical set of four quantum numbers (n, l, m_l, m_s).\", \"surrounding_context\": \"For a given principal quantum number n, orbital angular momentum l ranges from 0 to n - 1, and magnetic quantum number m_l ranges from -l to +l.\", \"retrieved_evidence\": [\"Quantum Number Rules: For each subshell l, there are 2l + 1 orbitals. Each orbital holds a maximum of 2 electrons (m_s = +1/2, -1/2).\", \"Total orbitals per shell n = sum(2l + 1) for l = 0 to n - 1 = n\u00b2.\"], \"student_prompt\": \"How do we derive the formula for the maximum electron capacity (2n\u00b2) of a principal energy level n?\", \"target_response\": \"To derive the maximum electron capacity: For a given principal shell n, the subshells l run from 0 to n - 1. Each subshell contains 2l + 1 degenerate spatial orbitals. Summing the number of orbitals across all subshells: (2*0 + 1) + (2*1 + 1) + ... + (2(n - 1) + 1) forms the sum of the first n odd integers, which mathematically equals n\u00b2. Since the Pauli exclusion principle allows exactly 2 electrons with opposite spins (m_s = \u00b11/2) per spatial orbital, multiplying the n\u00b2 orbitals by 2 electrons gives the maximum electron capacity: 2n\u00b2.\", \"formula\": \"Max Electrons = 2n\u00b2\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact purchase cost in Japanese yen of the transmission electron microscope installed at Tokyo University\", \"actual_topic\": \"subatomic particles, electron configurations, quantum numbers, and isotopic notation\", \"authoritative_source\": \"Tokyo University institutional procurement records or JEOL microscope sales invoices\", \"document_title\": \"Foundations of Atomic Physics\", \"page\": 178, \"section\": \"Periodic Trends in Ionization Energy\", \"selected_text\": \"First ionization energy generally increases across a period due to increasing effective nuclear charge Z_eff.\", \"surrounding_context\": \"Slight dips occur at group 13 (boron group) and group 16 (oxygen group) due to subshell shielding and electron pairing.\", \"retrieved_evidence\": [\"Figure 3.4: Periodic chart of first ionization potentials.\"], \"student_prompt\": \"According to this text, how much did Tokyo University pay in yen for its transmission electron microscope?\"}, {\"unmentioned_term\": \"the exact battery capacity in kilowatt-hours of the 2025 Hyundai Ioniq 6\", \"actual_topic\": \"Rutherford gold foil experiment and discovery of the atomic nucleus\", \"authoritative_source\": \"Hyundai Motor Company official electric vehicle technical specifications\", \"document_title\": \"Foundations of Atomic Physics\", \"page\": 182, \"section\": \"The Nuclear Model of the Atom\", \"selected_text\": \"Rutherford's alpha scattering experiment revealed that over 99.9% of alpha particles passed undeflected through gold foil.\", \"surrounding_context\": \"The rare large-angle deflections proved that positive charge is concentrated in a tiny, dense nucleus.\", \"retrieved_evidence\": [\"Section 3.1: Rutherford differential scattering cross-section derivation.\"], \"student_prompt\": \"What does the reading cite as the battery size of the Hyundai Ioniq 6 in kWh?\"}], \"grounded_paraphrase\": {\"document_title\": \"Quantum Mechanics Principles\", \"page\": 155, \"section\": \"The Wave-Particle Duality of Electrons\", \"selected_text\": \"De Broglie's hypothesis posits that particulate matter exhibits intrinsic undulatory characteristics, with the characteristic spatial wavelength inversely proportional to the linear momentum vector via Planck's quantum of action.\", \"surrounding_context\": \"This wave nature necessitates modeling atomic electrons as standing wave boundary probability distributions rather than classical point masses.\", \"retrieved_evidence\": [\"Page 155: 'Every particle has a wave nature with wavelength \u03bb = h/p, meaning electrons in atoms act like standing 3D waves rather than tiny orbiting balls.'\"], \"student_prompt\": \"Can you explain what de Broglie's hypothesis means for electrons in simple terms?\", \"faithful_paraphrase\": \"This passage explains that matter has wave-like properties just like light does. Because an electron has very little mass, its wave nature is significant, meaning an electron in an atom doesn't circle around like a tiny marble; instead, it behaves like a three-dimensional standing wave wrapped around the nucleus.\"}, \"conflict_handling\": {\"document_title\": \"Atomic Theory Historical Guide\", \"page\": 190, \"section\": \"Bohr Model vs Quantum Mechanical Orbitals\", \"selected_text\": \"The 1913 Bohr model successfully calculated hydrogen emission lines by postulating fixed circular orbits with quantized angular momentum L = n(h / 2\u03c0).\", \"surrounding_context\": \"In modern quantum mechanics (Schrodinger model), orbital angular momentum for the ground state n = 1 is strictly zero (l = 0), directly contradicting Bohr's assumption that L = 1(h / 2\u03c0).\", \"retrieved_evidence\": [\"Bohr Model (1913): Ground state electron orbits in a circle with angular momentum L = 1 * \u0127.\", \"Schrodinger Quantum Model (1926): Ground state 1s electron has spherical symmetry with orbital angular momentum L = 0.\"], \"student_prompt\": \"Bohr said the electron in hydrogen has angular momentum \u0127, but quantum mechanics says its orbital angular momentum is 0. Why?\", \"resolution_explanation\": \"Bohr's model was a brilliant early stepping stone that got the right energy levels for hydrogen, but its physical picture was incorrect. Bohr assumed the electron was a classical particle racing in a circular orbit, which required an angular momentum of 1 * \u0127 to keep it from spiraling into the nucleus. In modern quantum mechanics, the 1s electron is a spherical cloud (s-orbital) that does not orbit in a directional circle; its orbital angular momentum is exactly zero (l = 0).\"}}}, \"science::Chemical Bonding\": {\"domain\": \"science\", \"concept\": \"Chemical Bonding\", \"explanation\": \"the attractive forces that hold atoms together in molecules or crystals, including ionic bonds (electron transfer), covalent bonds (electron sharing), and metallic bonds\", \"reason\": \"it determines the physical and chemical properties of substances \u2014 melting point, conductivity, reactivity, and shape\", \"concrete_examples\": [\"Table salt (NaCl) forms ionic bonds: sodium donates an electron to chlorine, creating oppositely charged ions that attract.\", \"Water (H\u2082O) has covalent bonds: oxygen shares electrons with two hydrogen atoms.\", \"Metals like copper have metallic bonds where a 'sea' of electrons flows freely, enabling electrical conductivity.\"], \"numerical_examples\": [\"In NaCl: Na (11 electrons) loses 1 \u2192 Na\u207a (10 electrons). Cl (17 electrons) gains 1 \u2192 Cl\u207b (18 electrons).\", \"A carbon atom with 4 valence electrons forms 4 covalent bonds (e.g., methane CH\u2084), sharing one electron with each hydrogen.\", \"Electronegativity difference > 1.7 typically indicates an ionic bond; < 0.5 indicates nonpolar covalent.\"], \"misconceptions\": [[\"Ionic bonds are stronger than covalent bonds\", \"Bond strength depends on context. Individual covalent bonds (like C-C at 346 kJ/mol) can be very strong. Ionic crystals have high lattice energies (NaCl: 787 kJ/mol), but this is a collective property. In water, ionic compounds dissolve easily while covalent diamonds don't, showing strength depends on conditions.\"]], \"analogies\": [\"Ionic bonding is like giving a friend your jacket (transferring), while covalent bonding is like two friends sharing a blanket (sharing electrons).\"], \"prerequisites\": [\"atomic structure\", \"periodic table\"], \"formulas\": [\"Octet rule: atoms tend to gain/lose/share electrons to have 8 in their outer shell\"], \"document_evidence\": [\"The text states: 'The type of bond formed depends primarily on the electronegativity difference between the bonding atoms.'\", \"Lewis dot structures (Section 5.2) visually represent how valence electrons are shared or transferred.\"], \"practice_problems\": [\"Draw the Lewis structure for CO\u2082 and identify the type of bonds present.\", \"Predict whether MgO is ionic or covalent, and explain your reasoning using electronegativity.\"], \"hints\": [\"Large electronegativity difference \u2192 ionic. Small \u2192 covalent.\", \"Use the octet rule as a guide, but know exceptions (H needs 2, expanded octets in period 3+).\"], \"follow_up_questions\": [\"Why does water dissolve salt but not oil?\", \"What is a polar covalent bond and how does it differ from nonpolar?\"], \"diagnostic_questions\": [\"What determines whether atoms will share or transfer electrons?\", \"Why do metals conduct electricity but ionic solids (when solid) do not?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"A covalent bond between two atoms is always nonpolar as long as both atoms are non-metals.\", \"error_reason\": \"Nonpolar covalent bonds only occur when electronegativities are nearly identical (difference < 0.4); bonds between different non-metals (e.g., C-O, H-F) have significant electronegativity differences and are polar covalent.\", \"correct_claim\": \"A covalent bond between two non-metals is polar whenever there is a significant electronegativity difference between them (e.g., H-O or C-Cl), creating partial positive and negative poles.\", \"understanding_probe\": \"Why is the bond in hydrogen chloride (H-Cl) polar even though both hydrogen and chlorine are non-metals?\", \"expected_answer\": \"Because chlorine is much more electronegative than hydrogen, pulling the shared electron pair toward itself and creating a partial negative charge on chlorine and partial positive on hydrogen.\"}, {\"prior_erroneous_claim\": \"Ionic compounds consist of individual discrete molecules like NaCl molecules floating in solution.\", \"error_reason\": \"Ionic compounds do not form discrete molecules; they arrange into continuous 3D crystal lattices of alternating positive and negative ions held by electrostatic forces; NaCl is an empirical formula unit.\", \"correct_claim\": \"Ionic compounds do not contain individual molecules; they exist as extensive three-dimensional crystalline lattices of repeating cations and anions. 'NaCl' is a formula unit, not a discrete molecule.\", \"understanding_probe\": \"Does table salt (NaCl) consist of individual, separate NaCl molecules in a salt shaker?\", \"expected_answer\": \"No, it consists of a vast, continuous 3D crystal lattice where each sodium ion is surrounded by six chloride ions and vice versa.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Chemical Bonding and Molecular Structure\", \"page\": 205, \"section\": \"Lattice Energy and the Born-Haber Cycle\", \"selected_text\": \"Calculate the lattice energy of sodium chloride (NaCl) using the Born-Haber cycle with the following thermodynamic values in kJ/mol: Enthalpy of formation \u0394H_f = -411 kJ/mol; Sublimation of Na \u0394H_sub = +107 kJ/mol; Ionization energy of Na IE = +496 kJ/mol; Dissociation of Cl2 (1/2 bond energy) = +122 kJ/mol; Electron affinity of Cl EA = -349 kJ/mol.\", \"surrounding_context\": \"Section 3.1 sets up Hess's Law summation \u0394H_f = \u0394H_sub + IE + 1/2 D + EA - U_lattice.\", \"retrieved_evidence\": [\"Born-Haber equation: -U_lattice = \u0394H_f - (\u0394H_sub + IE + 1/2 D + EA)\", \"Sum of atomization and ionization terms = +107 + 496 + 122 - 349 = +376 kJ/mol.\", \"Lattice energy calculation: -U_lattice = -411 kJ/mol - 376 kJ/mol = -787 kJ/mol -> U_lattice = +787 kJ/mol.\"], \"student_prompt\": \"What is the exact lattice energy of NaCl calculated in Section 3.1 using the Born-Haber cycle?\", \"target_response\": \"Following the explicit steps in Section 3.1: The sum of the energy terms required to produce gaseous Na+ and Cl- ions from solid sodium and molecular chlorine is 107 + 496 + 122 - 349 = +376 kJ/mol. Subtracting this sum from the enthalpy of formation (-411 kJ/mol) gives -411 - 376 = -787 kJ/mol. Therefore, the lattice energy required to dissociate solid NaCl into gaseous ions is +787 kJ/mol. The text directly establishes the lattice energy at 787 kJ/mol.\", \"calculated_result\": \"Lattice Energy = 787 kJ/mol\"}, \"pattern_b_derive\": {\"document_title\": \"Molecular Orbital Theory: Diatomic Molecules\", \"page\": 212, \"section\": \"Bond Order and Magnetic Properties\", \"selected_text\": \"In molecular orbital (MO) theory, bond order quantifies the net number of chemical bonds between two atoms.\", \"surrounding_context\": \"Electrons in bonding orbitals stabilize the molecule, while electrons in antibonding orbitals destabilize it.\", \"retrieved_evidence\": [\"Formula: Bond Order = (Number of Bonding Electrons - Number of Antibonding Electrons) / 2\", \"MO Configuration for Nitrogen (N2, 14 valence electrons): \u03c3_2s\u00b2 (2 bonding), \u03c3*_2s\u00b2 (2 antibonding), \u03c0_2p\u2074 (4 bonding), \u03c3_2p\u00b2 (2 bonding). Total valence electrons = 10; Bonding = 8; Antibonding = 2.\"], \"student_prompt\": \"How do we derive the bond order of the dinitrogen molecule (N2) using molecular orbital theory?\", \"target_response\": \"To derive the bond order: Count the valence electrons in bonding and antibonding molecular orbitals from the configuration. The bonding orbitals (\u03c3_2s, \u03c0_2p, and \u03c3_2p) contain 2 + 4 + 2 = 8 electrons. The antibonding orbital (\u03c3*_2s) contains 2 electrons. Apply the formula: Bond Order = (Bonding Electrons - Antibonding Electrons) / 2 = (8 - 2) / 2 = 6 / 2 = 3. A bond order of 3 confirms that N2 possesses a stable triple bond.\", \"formula\": \"Bond Order = (N_bonding - N_antibonding) / 2\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact insurance liability premium paid by Dow Chemical for its Baton Rouge polymer plant in 2024\", \"actual_topic\": \"ionic, covalent, and metallic bonding mechanisms and electronegativity trends\", \"authoritative_source\": \"corporate insurance filings or SEC Form 10-K risk factor disclosures\", \"document_title\": \"Principles of Chemical Bonding\", \"page\": 220, \"section\": \"Intermolecular Forces\", \"selected_text\": \"Intermolecular forces encompass London dispersion forces, dipole-dipole attractions, and hydrogen bonding.\", \"surrounding_context\": \"Hydrogen bonding requires hydrogen bonded to strongly electronegative fluorine, oxygen, or nitrogen.\", \"retrieved_evidence\": [\"Section 4.2: Boiling point anomalies across hydrogen halides and hydrides.\"], \"student_prompt\": \"According to this document, how much did Dow Chemical pay for property insurance on its Baton Rouge facility?\"}, {\"unmentioned_term\": \"the total tonnage of plastic waste exported from Germany to Malaysia in 2024\", \"actual_topic\": \"VSEPR molecular geometry predictions and hybridization schemes\", \"authoritative_source\": \"the German Federal Statistical Office (Destatis) foreign trade commodity export database\", \"document_title\": \"Principles of Chemical Bonding\", \"page\": 225, \"section\": \"VSEPR Theory and Molecular Geometries\", \"selected_text\": \"VSEPR theory predicts that electron pairs around a central atom orient to maximize mutual angular separation.\", \"surrounding_context\": \"Water exhibits a bent geometry (104.5\u00b0) due to the repulsion of two non-bonding lone pairs.\", \"retrieved_evidence\": [\"Table 4.3: Electron group geometries from linear to octahedral.\"], \"student_prompt\": \"What does the text state regarding the tons of plastic waste Germany exported to Malaysia in 2024?\"}], \"grounded_paraphrase\": {\"document_title\": \"Physical Chemistry Foundations\", \"page\": 200, \"section\": \"The Covalent Bond as an Electrostatic Potential Well\", \"selected_text\": \"A homonuclear covalent chemical bond represents an equilibrium balance between attractive electrostatic interactions of shared electron probability density with adjacent positive nuclei, and repulsive inter-nuclear and inter-electronic Coulombic forces.\", \"surrounding_context\": \"The internuclear bond distance corresponds strictly to the global minimum of the potential energy curve.\", \"retrieved_evidence\": [\"Page 200: 'A covalent bond forms at the exact distance where the attraction of shared electrons to both nuclei outweighs the repulsion between the two positive nuclei.'\"], \"student_prompt\": \"Can you explain what holds a covalent bond together in simple terms?\", \"faithful_paraphrase\": \"This passage explains that a covalent bond is formed by an electrostatic tug-of-war. The shared negatively charged electrons are pulled toward the positive centers of both atoms. The bond forms at the exact distance where this mutual pull is strongest and keeps the two atoms together, before they get so close that their positive nuclei begin repelling each other.\"}, \"conflict_handling\": {\"document_title\": \"Inorganic Chemistry Reference\", \"page\": 235, \"section\": \"Octet Rule Exceptions: Hypervalent Molecules\", \"selected_text\": \"Introductory chemistry teaches the strict octet rule where atoms never exceed 8 valence electrons.\", \"surrounding_context\": \"However, elements in Period 3 and below (like phosphorus in PCl5 and sulfur in SF6) routinely accommodate 10 or 12 valence electrons, historically attributed to d-orbital hybridization and modernly described by 3-center 4-electron bonds.\", \"retrieved_evidence\": [\"Rule 1 (Introductory Octet Rule): Main-group atoms share electrons to achieve exactly 8 valence electrons.\", \"Rule 2 (Advanced Hypervalence): Elements in Period 3 and beyond have larger atomic radii and can form 'expanded octets' with 10 or 12 electrons (e.g., SF6 has 12 valence electrons).\"], \"student_prompt\": \"My high school teacher said no atom can ever have more than 8 valence electrons, but our college chem book shows SF6 with 12 electrons. Which is right?\", \"resolution_explanation\": \"Both are teaching models appropriate for their level. The octet rule (8 electrons) is strictly obeyed by Period 2 elements like carbon, nitrogen, and oxygen because they only have s and p orbitals. Elements in Period 3 and below (like sulfur and phosphorus) are physically larger and have accessible energy levels that allow them to coordinate more than four bonding atoms, forming 'expanded octets' (such as 12 electrons in SF6). The 8-electron rule is a baseline guideline that applies strictly to second-period elements.\"}}}, \"science::DNA Replication\": {\"domain\": \"science\", \"concept\": \"DNA Replication\", \"explanation\": \"the biological process by which a cell copies its DNA before cell division, producing two identical DNA molecules from one original\", \"reason\": \"it ensures genetic information is faithfully passed from parent to daughter cells, enabling growth, repair, and reproduction\", \"concrete_examples\": [\"Before a skin cell divides, it replicates all 3 billion base pairs of DNA so each new cell gets a complete copy.\", \"Errors in DNA replication can cause mutations, some of which may lead to cancer if they occur in genes controlling cell growth.\", \"PCR (polymerase chain reaction) mimics DNA replication in the lab, amplifying tiny DNA samples for forensic analysis.\"], \"numerical_examples\": [\"Human DNA replication proceeds at about 1,000 nucleotides per second per replication fork, completing 3 billion base pairs in roughly 8 hours using multiple origins.\", \"Replication error rate: DNA polymerase makes about 1 error per 10\u2079 base pairs after proofreading and repair.\", \"Starting from one DNA molecule, after 30 rounds of replication (as in PCR), you get 2\u00b3\u2070 \u2248 1 billion copies.\"], \"misconceptions\": [[\"DNA replication produces two entirely new DNA molecules\", \"Replication is semi-conservative: each new DNA molecule contains one original (parent) strand and one newly synthesized (daughter) strand. Meselson and Stahl's experiment confirmed this in 1958.\"]], \"analogies\": [\"DNA replication is like unzipping a zipper and building a new matching half for each side \u2014 each resulting zipper has one old rail and one new rail.\"], \"prerequisites\": [\"basic cell biology\", \"DNA structure\"], \"formulas\": [\"Base pairing rules: A-T, G-C\"], \"document_evidence\": [\"The text explains: 'Helicase unwinds the double helix, and DNA polymerase synthesizes new strands by adding complementary nucleotides.'\", \"The Meselson-Stahl experiment (Section 8.3) provided definitive evidence for semi-conservative replication.\"], \"practice_problems\": [\"Given a template strand 3'-ATGCCTA-5', write the sequence of the new complementary strand.\", \"Explain the roles of helicase, primase, and DNA polymerase in replication.\"], \"hints\": [\"Remember: A pairs with T, G pairs with C. The new strand is antiparallel to the template.\", \"Replication starts at origins and proceeds in both directions using replication forks.\"], \"follow_up_questions\": [\"What is the leading strand vs. the lagging strand, and why are they different?\", \"How do cells correct errors made during DNA replication?\"], \"diagnostic_questions\": [\"If one strand reads 5'-AATGCG-3', what does the complementary strand read?\", \"Why is DNA replication called 'semi-conservative'?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"DNA polymerase can synthesize new DNA strands in both the 5' to 3' and 3' to 5' directions simultaneously.\", \"error_reason\": \"DNA polymerase can ONLY synthesize DNA in the 5' to 3' direction because the incoming deoxynucleotide triphosphate attaches its 5' phosphate to the 3' OH group of the growing chain; 3' to 5' synthesis is biochemically impossible.\", \"correct_claim\": \"DNA polymerases can only synthesize DNA in the 5' to 3' direction. This enzymatic limitation is why the lagging strand must be synthesized discontinuously in short Okazaki fragments.\", \"understanding_probe\": \"Why does DNA replication require Okazaki fragments on the lagging strand?\", \"expected_answer\": \"Because DNA polymerase can only add nucleotides in the 5' to 3' direction; as the replication fork opens, the lagging strand must be built in reverse discontinuous pieces.\"}, {\"prior_erroneous_claim\": \"DNA polymerase can initiate the synthesis of a new DNA strand completely from scratch without needing a primer.\", \"error_reason\": \"DNA polymerase requires a free 3'-OH group to attach the next nucleotide; RNA primase must first synthesize a short RNA primer to provide that starting 3'-OH group.\", \"correct_claim\": \"DNA polymerase cannot start a new strand from scratch; it requires an existing 3'-OH group provided by a short RNA primer laid down by the enzyme primase.\", \"understanding_probe\": \"What enzyme provides the starting point that DNA polymerase needs to begin synthesizing DNA?\", \"expected_answer\": \"RNA primase, which synthesizes a short RNA primer that gives DNA polymerase the necessary 3'-hydroxyl group to start extending the chain.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Molecular Biology of the Cell: Replication Kinetics\", \"page\": 245, \"section\": \"Replication Fork Progression Rates\", \"selected_text\": \"The bacterial genome of Escherichia coli contains 4.60 x 10^6 base pairs (4.60 Mb) replicated bidirectionally from a single origin of replication (oriC) by two replication forks moving at 1,000 base pairs per second per fork.\", \"surrounding_context\": \"Section 2.1 calculates the theoretical time required for complete bacterial chromosome duplication.\", \"retrieved_evidence\": [\"Genome size = 4,600,000 base pairs. Replication is bidirectional: 2 forks operate simultaneously.\", \"Combined synthesis speed = 2 forks * 1,000 bp/s = 2,000 bp/s.\", \"Step-by-step arithmetic from text: Replication duration = 4,600,000 bp / 2,000 bp/s = 2,300 seconds.\", \"Conversion to minutes: 2,300 seconds / 60 seconds/min = 38.33 minutes (approx 38 minutes 20 seconds).\"], \"student_prompt\": \"What is the exact replication time in seconds and minutes calculated for E. coli in Section 2.1?\", \"target_response\": \"Following the explicit calculation in Section 2.1: The 4.60 x 10^6 bp genome is copied by two replication forks moving bidirectionally at 1,000 bp/s each, giving a combined speed of 2,000 bp/s. Dividing 4,600,000 bp by 2,000 bp/s yields exactly 2,300 seconds. Converting to minutes gives 2,300 / 60 = 38.33 minutes (38 minutes and 20 seconds). The text directly establishes total replication duration at 2,300 seconds (38.33 minutes).\", \"calculated_result\": \"Replication time = 2,300 seconds = 38.33 minutes\"}, \"pattern_b_derive\": {\"document_title\": \"Molecular Genetics: Semi-Conservative Replication\", \"page\": 252, \"section\": \"Meselson-Stahl Density Isotope Distribution\", \"selected_text\": \"The Meselson-Stahl experiment demonstrated semi-conservative replication using 15N (heavy) and 14N (light) nitrogen isotopes.\", \"surrounding_context\": \"Each round of replication uses existing strands as templates and synthesizes brand new daughter strands with ambient 14N.\", \"retrieved_evidence\": [\"Semi-Conservative Rule: After n generations in 14N starting from 100% 15N-DNA: Total DNA molecules = 2^n. Exactly 2 hybrid molecules (15N-14N) persist in all generations. The remaining 2^n - 2 molecules are purely light (14N-14N).\", \"Generation test: Determine the percentage of hybrid and light DNA molecules after Generation 3 (n = 3).\"], \"student_prompt\": \"How do we derive the percentage of hybrid (15N-14N) and light (14N-14N) DNA molecules after 3 generations?\", \"target_response\": \"To derive the isotope distributions after 3 generations: Compute total DNA duplexes: 2\u00b3 = 8 molecules. Under semi-conservative replication, the 2 original heavy 15N strands never disappear; each resides in one hybrid duplex. Thus, exactly 2 out of the 8 molecules are hybrid (15N-14N), which is 2 / 8 = 25.0%. The remaining 8 - 2 = 6 molecules are composed entirely of newly synthesized light DNA (14N-14N), which is 6 / 8 = 75.0%. After 3 generations, the population is 25% hybrid and 75% light DNA.\", \"formula\": \"Hybrid % = (2 / 2^n) * 100%; Light % = ((2^n - 2) / 2^n) * 100%\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact venture capital funding raised by Oxford Nanopore Technologies in Series C\", \"actual_topic\": \"enzymatic machinery of replication including helicase, topoisomerase, single-stranded binding proteins, and ligase\", \"authoritative_source\": \"UK Companies House regulatory corporate filings or venture capital investment tracking databases\", \"document_title\": \"Mechanisms of DNA Replication\", \"page\": 260, \"section\": \"Proofreading and Mismatch Repair\", \"selected_text\": \"DNA polymerase possesses 3' to 5' exonuclease proofreading activity that excises incorrectly paired nucleotides.\", \"surrounding_context\": \"Proofreading improves replication fidelity from one error per 10^5 bases to one per 10^7 bases.\", \"retrieved_evidence\": [\"Section 3.4: Catalytic mechanism of the 3' to 5' exonuclease active site.\"], \"student_prompt\": \"According to this document, how much Series C venture funding did Oxford Nanopore raise?\"}, {\"unmentioned_term\": \"the monthly rent per square foot for commercial biotechnology laboratories in Cambridge, Massachusetts\", \"actual_topic\": \"telomeres, telomerase reverse transcriptase, and the end-replication problem\", \"authoritative_source\": \"commercial real estate market reports from CBRE or JLL Life Sciences\", \"document_title\": \"Mechanisms of DNA Replication\", \"page\": 265, \"section\": \"The End-Replication Problem in Eukaryotes\", \"selected_text\": \"Linear eukaryotic chromosomes shorten at terminal telomeric ends after each division cycle due to removal of the final RNA primer.\", \"surrounding_context\": \"Telomerase maintains length in germline and stem cells using an internal RNA template.\", \"retrieved_evidence\": [\"Figure 3.6: Telomere extension by human telomerase RNA component (TERC).\"], \"student_prompt\": \"What does this text state regarding commercial wet lab rental rates in Cambridge, MA?\"}], \"grounded_paraphrase\": {\"document_title\": \"Molecular Cell Biology\", \"page\": 240, \"section\": \"The Semi-Conservative Mechanism Axiom\", \"selected_text\": \"The semi-conservative paradigm of genomic duplication dictates that upon thermal or enzymatic helicase-mediated separation of the parental duplex, each antecedent polynucleotide strand acts as an immutable stereochemical template directing the complementary nucleotide pairing of an embryonic nascent daughter strand.\", \"surrounding_context\": \"Consequently, each progeny double helix comprises precisely one conserved ancestral strand and one newly assembled strand.\", \"retrieved_evidence\": [\"Page 240: 'Semi-conservative replication means each new DNA molecule keeps one original parent strand and adds one freshly made daughter strand.'\"], \"student_prompt\": \"Can you explain what semi-conservative replication means in everyday words based on this passage?\", \"faithful_paraphrase\": \"This passage explains that semi-conservative replication means the two strands of the original DNA ladder unzip, and each old strand serves as a matching guide to build a new partner strand. When the process finishes, every newly formed DNA double helix consists of one preserved original strand from the parent molecule and one completely brand-new strand.\"}, \"conflict_handling\": {\"document_title\": \"Enzymology of DNA Replication\", \"page\": 272, \"section\": \"Prokaryotic vs Eukaryotic Polymerase Designations\", \"selected_text\": \"In bacterial prokaryotic replication (E. coli), DNA Polymerase III performs the bulk of primary chromosomal synthesis, while DNA Polymerase I removes RNA primers and fills gaps.\", \"surrounding_context\": \"In eukaryotic systems, by contrast, three distinct multi-subunit polymerases divide these duties: Pol \u03b1 synthesizes primers, Pol \u03b4 synthesizes the lagging strand, and Pol \u03b5 synthesizes the leading strand.\", \"retrieved_evidence\": [\"Bacterial Nomenclature: Pol III (main duplicator), Pol I (primer removal / gap repair).\", \"Eukaryotic Nomenclature: Pol \u03b5 (leading strand), Pol \u03b4 (lagging strand), Pol \u03b1 (RNA/DNA primer synthesis).\"], \"student_prompt\": \"One diagram shows DNA Polymerase III making the leading strand, but another chapter says DNA Polymerase Epsilon makes it. Why do they name different enzymes?\", \"resolution_explanation\": \"These two sources are describing different types of organisms. In bacteria (prokaryotes), DNA Polymerase III is the main enzyme that synthesizes both the leading and lagging strands. In humans and other complex cells (eukaryotes), specialized polymerases handle each job: DNA Polymerase Epsilon (Pol \u03b5) synthesizes the leading strand, while DNA Polymerase Delta (Pol \u03b4) synthesizes the lagging strand. The difference is simply bacterial versus human biochemistry.\"}}}, \"science::Cell Mitosis\": {\"domain\": \"science\", \"concept\": \"Cell Mitosis\", \"explanation\": \"the type of cell division that produces two genetically identical daughter cells from a single parent cell, used for growth, repair, and asexual reproduction\", \"reason\": \"it enables organisms to grow from a single fertilized egg, replace damaged tissues, and maintain body systems\", \"concrete_examples\": [\"A scraped knee heals because skin cells undergo mitosis to replace lost cells.\", \"A tadpole growing into a frog involves massive amounts of mitosis as new tissues form.\", \"Cancer occurs when mitosis becomes uncontrolled, producing cells that divide without stopping.\"], \"numerical_examples\": [\"Starting with 1 cell, after 10 rounds of mitosis: 2\u00b9\u2070 = 1,024 cells.\", \"Human red blood cells are replaced at about 200 billion per day through mitosis of precursor cells.\", \"The cell cycle in human cells typically lasts 24 hours, with mitosis itself taking only about 1\u20132 hours.\"], \"misconceptions\": [[\"Mitosis and meiosis produce the same type of cells\", \"Mitosis produces two diploid (2n) cells identical to the parent, used for growth and repair. Meiosis produces four haploid (n) cells (gametes) with half the chromosomes and genetic variation through crossing over. They serve completely different purposes.\"]], \"analogies\": [\"Mitosis is like making a photocopy of a document \u2014 you start with one original and end up with two identical copies, one for each new cell.\"], \"prerequisites\": [\"cell biology\", \"DNA structure\"], \"formulas\": [\"After n divisions: 2\u207f cells\"], \"document_evidence\": [\"The text describes the four phases: 'In prophase, chromosomes condense; in metaphase, they align at the cell's equator; in anaphase, sister chromatids separate; in telophase, nuclear envelopes reform.'\", \"Micrograph 6.4 shows cells at each stage of mitosis in an onion root tip.\"], \"practice_problems\": [\"List the four phases of mitosis in order and describe what happens in each.\", \"If a cell with 46 chromosomes undergoes mitosis, how many chromosomes does each daughter cell have?\"], \"hints\": [\"Remember PMAT: Prophase, Metaphase, Anaphase, Telophase.\", \"Mitosis = identical copies. Meiosis = variation and half the chromosomes.\"], \"follow_up_questions\": [\"What would happen if the spindle fibers failed during anaphase?\", \"How is mitosis regulated, and what goes wrong in cancer?\"], \"diagnostic_questions\": [\"At what phase do chromosomes line up at the middle of the cell?\", \"What is the difference between mitosis and cytokinesis?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Homologous chromosomes pair up and cross over during the prophase of mitosis.\", \"error_reason\": \"Homologous pairing (synapsis) and crossing over occur exclusively during Prophase I of meiosis; in mitosis, sister chromatids line up independently along the metaphase plate without pairing or crossing over.\", \"correct_claim\": \"Crossing over and homologous pairing happen only in meiosis. In mitosis, homologous chromosomes do not pair up; individual sister chromatid pairs align independently along the metaphase plate.\", \"understanding_probe\": \"Does crossing over between homologous chromosomes happen during mitosis?\", \"expected_answer\": \"No, crossing over occurs only in meiosis (Prophase I); mitosis produces genetically identical diploid daughter cells without recombining homologs.\"}, {\"prior_erroneous_claim\": \"Cytokinesis is a stage of mitosis that takes place before anaphase.\", \"error_reason\": \"Mitosis strictly refers to nuclear division (prophase, metaphase, anaphase, telophase); cytokinesis is the physical division of the cytoplasm that occurs after or alongside telophase.\", \"correct_claim\": \"Mitosis is karyokinesis (division of the nucleus). Cytokinesis is the physical division of the cytoplasm that occurs at the very end of cell division, following or overlapping with telophase.\", \"understanding_probe\": \"What is the difference between mitosis and cytokinesis?\", \"expected_answer\": \"Mitosis is the division of the genetic material in the nucleus, while cytokinesis is the physical splitting of the cytoplasm and cell membrane into two daughter cells.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Cell Biology and Cytogenetics\", \"page\": 288, \"section\": \"Cell Cycle Phase Durations and Mitotic Index\", \"selected_text\": \"An actively proliferating human cell line has an overall cell cycle generation time of T = 24.0 hours. A microscopic analysis of 1,200 cultured cells reveals the following phase counts: Interphase = 1,080 cells; Prophase = 60 cells; Metaphase = 24 cells; Anaphase = 12 cells; Telophase = 24 cells.\", \"surrounding_context\": \"Section 2.1 calculates the mitotic index and the exact time spent in each mitotic stage.\", \"retrieved_evidence\": [\"Total cells in mitosis = 60 + 24 + 12 + 24 = 120 cells.\", \"Mitotic index calculation: MI = Mitotic Cells / Total Cells = 120 / 1,200 = 0.100 (10.0%).\", \"Total mitosis duration = 10.0% * 24.0 hours = 2.40 hours (144.0 minutes).\", \"Anaphase duration = (12 / 1,200) * 24.0 hours = 0.010 * 24.0 = 0.24 hours = 14.4 minutes.\"], \"student_prompt\": \"What are the exact mitotic index, total mitotic duration, and anaphase duration calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The total number of cells undergoing mitosis is 60 + 24 + 12 + 24 = 120. Dividing by 1,200 total cells yields a mitotic index of 120 / 1,200 = 0.10 or 10.0%. Multiplying this fraction by the 24.0-hour cycle time gives a total mitotic duration of 0.10 * 24.0 = 2.40 hours (144.0 minutes). For anaphase, 12 / 1,200 = 1.0% of the cycle, yielding 0.01 * 24.0 = 0.24 hours, or exactly 14.4 minutes. The course text directly establishes the mitotic index at 10.0%, total mitosis at 2.40 hours, and anaphase at 14.4 minutes.\", \"calculated_result\": \"Mitotic Index = 10.0%, Total Mitosis = 2.40 hrs (144 min), Anaphase = 14.4 min\"}, \"pattern_b_derive\": {\"document_title\": \"Cellular Dynamics: Chromosome and Chromatid Tracking\", \"page\": 295, \"section\": \"Chromosome and DNA Molecule Counting Across Mitosis\", \"selected_text\": \"In diploid human cells (2n = 46), tracking the number of physical chromosomes versus chromatids depends on centromere separation.\", \"surrounding_context\": \"A chromosome is counted by its functional centromere; sister chromatids joined at one centromere count as one replicated chromosome.\", \"retrieved_evidence\": [\"Counting rules: Before Anaphase (G2, Prophase, Metaphase): 46 chromosomes, 92 sister chromatids. During Anaphase: Centromeres split; each sister chromatid is now an independent chromosome. Post-Telophase: Two daughter cells, each with 46 chromosomes.\", \"Question: Track chromosome count during Anaphase.\"], \"student_prompt\": \"How do we derive the number of chromosomes and chromatids present in a human cell during anaphase?\", \"target_response\": \"To derive the chromosome count during anaphase: In G2 and metaphase, the cell possesses 46 duplicated chromosomes, each containing 2 sister chromatids held by a single centromere (46 chromosomes, 92 chromatids). At the start of anaphase, the cohesin proteins cleave and the centromeres split simultaneously. The moment sister chromatids separate, each becomes an independent, single-stranded chromosome. Therefore, during anaphase, the single cell temporarily contains 46 * 2 = 92 separate chromosomes and 0 paired chromatids, until cytokinesis divides them into two cells of 46 chromosomes each.\", \"formula\": \"Anaphase Chromosomes = 46 * 2 = 92\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale catalog price of an Olympus BX53 clinical fluorescence microscope\", \"actual_topic\": \"the stages of mitosis (prophase, metaphase, anaphase, telophase) and mitotic index formulas\", \"authoritative_source\": \"Olympus Life Science laboratory equipment sales catalogs\", \"document_title\": \"Cellular Reproduction Principles\", \"page\": 302, \"section\": \"The Spindle Assembly Checkpoint\", \"selected_text\": \"The spindle assembly checkpoint (SAC) monitors kinetochore tension and prevents anaphase onset until all chromosomes achieve amphitelic bipolar alignment.\", \"surrounding_context\": \"Unattached kinetochores recruit Mad2 and BubR1 proteins to inhibit the anaphase-promoting complex (APC/C).\", \"retrieved_evidence\": [\"Section 3.2: Molecular signaling cascades of the mitotic checkpoint complex.\"], \"student_prompt\": \"According to this document, what is the wholesale catalog price of an Olympus BX53 microscope?\"}, {\"unmentioned_term\": \"the total number of employees working at Genentech's South San Francisco facility\", \"actual_topic\": \"cytokinesis cleavage furrow formation and actin-myosin contractile rings\", \"authoritative_source\": \"Genentech corporate annual employment reports or local county business filings\", \"document_title\": \"Cellular Reproduction Principles\", \"page\": 306, \"section\": \"Mechanics of Cytokinesis\", \"selected_text\": \"In animal cells, cytokinesis occurs through the constriction of an equatorial contractile ring composed of actin microfilaments and myosin II motors.\", \"surrounding_context\": \"Plant cells cannot pinch in half due to rigid cell walls; instead, they construct a membrane-bound cell plate.\", \"retrieved_evidence\": [\"Section 3.4: Golgi vesicle fusion during phragmoplast formation in plant cytokinesis.\"], \"student_prompt\": \"What does this text state regarding the headcount of Genentech employees in South San Francisco?\"}], \"grounded_paraphrase\": {\"document_title\": \"Principles of Cell Biology\", \"page\": 285, \"section\": \"The Mitotic Equational Division Axiom\", \"selected_text\": \"Mitosis constitutes an equational nuclear karyokinesis wherein an antecedent diploid somatic parent cell orchestrates the precise segregation of duplicated genomic sister chromatids, yielding two genetically pristine daughter nuclei endowed with identical diploid karyotypic complements.\", \"surrounding_context\": \"This fidelity underpins tissue morphogenesis, physiological tissue regeneration, and somatic maintenance.\", \"retrieved_evidence\": [\"Page 285: 'Mitosis divides a cell's duplicated chromosomes equally into two new nuclei, creating two genetically identical daughter cells.'\"], \"student_prompt\": \"Can you explain the primary purpose of mitosis based on this passage in simple terms?\", \"faithful_paraphrase\": \"This passage explains that mitosis is the process of cell division that allows a single cell to copy its chromosomes and divide them equally between two new cells. The goal of mitosis is to create two genetically identical daughter cells that each have the exact same set of DNA as the original cell, which is essential for growing, repairing tissues, and healing wounds.\"}, \"conflict_handling\": {\"document_title\": \"Cytogenetics and Oncology\", \"page\": 315, \"section\": \"Centrosome Roles: Essential vs dispensable for Spindle Assembly\", \"selected_text\": \"Classic cell biology textbooks state that centrosomes are essential microtubule-organizing centers (MTOCs) required for constructing the mitotic spindle.\", \"surrounding_context\": \"However, higher plant cells divide normally without any centrosomes, and laser-ablation studies show animal cells can assemble functional bipolar spindles via chromatin-driven Ran-GTP pathways.\", \"retrieved_evidence\": [\"Classic View: Centrosomes are necessary to nucleate spindle microtubules in animal mitosis.\", \"Modern View: Centrosomes accelerate spindle formation and focus poles, but chromatin-mediated pathways (Ran-GTP) can self-assemble a functional mitotic spindle in the absence of centrosomes.\"], \"student_prompt\": \"My biology teacher said cells cannot divide without centrosomes, but an oncology article says cancer cells with ablated centrosomes still divide. Why?\", \"resolution_explanation\": \"This conflict reflects the evolution of scientific understanding. Historically, centrosomes were thought to be strictly essential because they are the main centers organizing microtubules in healthy animal cells. However, modern research shows that centrosomes are not strictly required for spindle assembly. If centrosomes are ablated with lasers, cells can activate an alternative chromatin-driven pathway (using Ran-GTP) that organizes microtubules around chromosomes directly, allowing spindle formation to proceed even without centrosomes.\"}}}, \"science::Thermodynamics\": {\"domain\": \"science\", \"concept\": \"Thermodynamics\", \"explanation\": \"the branch of physics dealing with heat, work, energy, and the laws governing energy transformation and transfer\", \"reason\": \"it explains why engines work, why heat flows from hot to cold, and why perpetual motion machines are impossible\", \"concrete_examples\": [\"A car engine converts chemical energy (fuel) into mechanical energy (motion) and waste heat \u2014 illustrating the first and second laws.\", \"An ice cube melting in warm water: heat transfers from the water to the ice until thermal equilibrium.\", \"A refrigerator moves heat from cold (inside) to hot (outside) by doing work, consistent with the second law.\"], \"numerical_examples\": [\"First Law: If a gas absorbs 500 J of heat and does 200 J of work, its internal energy increases by 300 J (\u0394U = Q \u2212 W).\", \"Carnot efficiency: A heat engine operating between 600 K and 300 K has maximum efficiency = 1 \u2212 300/600 = 50%.\", \"Specific heat: Heating 2 kg of water from 20\u00b0C to 100\u00b0C requires Q = mc\u0394T = 2 \u00d7 4186 \u00d7 80 = 669,760 J \u2248 670 kJ.\"], \"misconceptions\": [[\"Cold is transferred from cold objects to warm objects\", \"There is no such thing as 'cold' being transferred. Heat (thermal energy) always flows from higher temperature to lower temperature. A cold object feels cold because heat is flowing OUT of your hand INTO the object, not because 'cold' is entering your hand.\"]], \"analogies\": [\"Thermodynamics is like banking \u2014 the first law says energy is conserved (you can't create money from nothing), and the second law says every transaction has a fee (entropy always increases).\"], \"prerequisites\": [\"basic algebra\", \"temperature scales\"], \"formulas\": [\"\u0394U = Q \u2212 W (First Law)\", \"Efficiency = 1 \u2212 T_cold/T_hot (Carnot)\", \"Q = mc\u0394T\"], \"document_evidence\": [\"The text states: 'The First Law of Thermodynamics is conservation of energy: energy cannot be created or destroyed, only converted.'\", \"The Second Law (Section 12.4): 'Heat spontaneously flows from hot to cold; the reverse requires work input.'\"], \"practice_problems\": [\"A system absorbs 800 J of heat and performs 350 J of work. What is the change in internal energy?\", \"Calculate the maximum efficiency of a steam engine operating between 400\u00b0C (673 K) and 25\u00b0C (298 K).\"], \"hints\": [\"First Law: energy in = energy out + change in internal energy.\", \"Entropy always increases in an isolated system \u2014 nature tends toward disorder.\"], \"follow_up_questions\": [\"Why can no real heat engine be 100% efficient?\", \"How does the concept of entropy relate to everyday experiences like ice melting?\"], \"diagnostic_questions\": [\"If you hold an ice cube, is 'cold' flowing into your hand? Explain what's actually happening.\", \"What does the Second Law of Thermodynamics tell us about the direction of natural processes?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The second law of thermodynamics means that the entropy of a living organism must constantly increase until it dies, so organisms cannot create order.\", \"error_reason\": \"The second law applies to isolated (closed) systems; living organisms are open systems that consume energy and export entropy to their surroundings, allowing internal entropy to decrease locally.\", \"correct_claim\": \"The second law states that the entropy of an isolated system must increase (\u0394S_universe \u2265 0). Living organisms are open systems that decrease local entropy by taking in energy and expelling heat and waste into their surroundings.\", \"understanding_probe\": \"How can complex living organisms grow and create order without violating the second law of thermodynamics?\", \"expected_answer\": \"Because living things are open systems; they take in high-quality energy (food/sunlight) and export heat and disorder to the environment, so total entropy of the universe still increases.\"}, {\"prior_erroneous_claim\": \"A heat engine can achieve 100% thermal efficiency if all friction and mechanical resistance are eliminated.\", \"error_reason\": \"The Carnot limit and Kelvin-Planck statement establish that even in an idealized frictionless engine, thermal efficiency cannot exceed \u03b7 = 1 - (T_cold / T_hot), which is strictly less than 100%.\", \"correct_claim\": \"Even in an ideal frictionless engine, 100% thermal efficiency is physically impossible. By the Kelvin-Planck statement, an engine must reject heat to a colder reservoir: \u03b7_max = 1 - (T_cold / T_hot).\", \"understanding_probe\": \"Why can an ideal heat engine never be 100% efficient even with zero friction?\", \"expected_answer\": \"Because thermodynamics requires heat to flow from hot to cold; converting all absorbed heat entirely into work without rejecting any heat to a colder sink is prohibited by the Second Law.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Engineering Thermodynamics: Heat Engines and the Carnot Cycle\", \"page\": 330, \"section\": \"Carnot Thermal Efficiency and Maximum Power\", \"selected_text\": \"A geothermal power plant operates as an ideal Carnot heat engine between a subterranean steam reservoir at Thot = 250.0\u00b0C and a cooling tower at Tcold = 25.0\u00b0C, absorbing Qin = 800.0 MJ of heat per cycle.\", \"surrounding_context\": \"Section 3.1 calculates the maximum Carnot thermal efficiency, work output, and heat rejected in megajoules.\", \"retrieved_evidence\": [\"Temperature conversion to Kelvin: Thot = 250.0 + 273.15 = 523.15 K; Tcold = 25.0 + 273.15 = 298.15 K.\", \"Carnot efficiency formula: \u03b7_Carnot = 1 - (Tcold / Thot) = 1 - (298.15 / 523.15) = 1 - 0.5699 = 0.4301 (43.01%).\", \"Maximum work output: W_max = \u03b7 * Qin = 0.4301 * 800.0 MJ = 344.08 MJ.\", \"Heat rejected to cooling tower: Qout = Qin - W = 800.0 MJ - 344.08 MJ = 455.92 MJ.\"], \"student_prompt\": \"What are the exact Carnot efficiency, maximum work produced, and heat rejected calculated in Section 3.1?\", \"target_response\": \"Following the explicit steps in Section 3.1: First convert temperatures to Kelvin: Thot = 523.15 K and Tcold = 298.15 K. The maximum Carnot efficiency is \u03b7 = 1 - (298.15 / 523.15) = 1 - 0.5699 = 0.4301, or 43.01%. Multiplying efficiency by heat input yields maximum work: W = 0.4301 * 800.0 MJ = 344.08 MJ. Heat rejected to the cooling sink is 800.0 - 344.08 = 455.92 MJ. The text directly establishes Carnot efficiency at 43.01%, work at 344.08 MJ, and heat rejected at 455.92 MJ.\", \"calculated_result\": \"Efficiency = 43.01%, Work = 344.08 MJ, Heat rejected = 455.92 MJ\"}, \"pattern_b_derive\": {\"document_title\": \"Chemical Thermodynamics: Gibbs Free Energy\", \"page\": 338, \"section\": \"Deriving the Temperature of Reaction Spontaneity\", \"selected_text\": \"A chemical reaction is thermodynamically spontaneous at constant temperature and pressure when change in Gibbs free energy is negative: \u0394G = \u0394H - T\u0394S < 0.\", \"surrounding_context\": \"When an endothermic reaction (\u0394H > 0) increases entropy (\u0394S > 0), spontaneity depends strictly on temperature.\", \"retrieved_evidence\": [\"Formula: \u0394G = \u0394H - T\u0394S; Equilibrium threshold: \u0394G = 0 at T_threshold = \u0394H / \u0394S.\", \"Reaction data: Endothermic phase change with \u0394H = +45.0 kJ/mol (45,000 J/mol) and \u0394S = +150.0 J/(mol\u00b7K).\"], \"student_prompt\": \"How do we derive the threshold temperature in Kelvin above which this reaction becomes spontaneous?\", \"target_response\": \"To derive the threshold temperature of spontaneity: Set Gibbs free energy to zero (equilibrium): \u0394G = \u0394H - T\u0394S = 0. Add T\u0394S to both sides: T\u0394S = \u0394H. Divide both sides by \u0394S: T = \u0394H / \u0394S. Substitute the reaction parameters, converting kJ to Joules: T = 45,000 J/mol / 150.0 J/(mol\u00b7K) = 300.0 K. Since both \u0394H and \u0394S are positive, the term -T\u0394S becomes increasingly negative as temperature rises; therefore, the reaction is spontaneous at any temperature above 300.0 K (26.85\u00b0C).\", \"formula\": \"T_threshold = \u0394H / \u0394S\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale spot price of liquefied natural gas (LNG) at the Henry Hub in Louisiana\", \"actual_topic\": \"the laws of thermodynamics, Carnot engine efficiency, and Gibbs free energy\", \"authoritative_source\": \"the United States Energy Information Administration (EIA) Henry Hub natural gas spot price tables\", \"document_title\": \"Principles of Classical Thermodynamics\", \"page\": 348, \"section\": \"Entropy Changes in Ideal Gases\", \"selected_text\": \"The change in entropy for an ideal gas undergoing a reversible process is \u0394S = n C_v ln(T2/T1) + n R ln(V2/V1).\", \"surrounding_context\": \"For an isothermal expansion, temperature is constant and entropy increases solely due to volume expansion.\", \"retrieved_evidence\": [\"Equation 4.2: General differential expression for ideal gas entropy.\"], \"student_prompt\": \"According to this chapter, what was the Henry Hub spot price for LNG per million BTU?\"}, {\"unmentioned_term\": \"the exact fuel efficiency in miles per gallon of the 2024 Ford F-150 hybrid truck\", \"actual_topic\": \"refrigeration cycles, heat pumps, and coefficients of performance\", \"authoritative_source\": \"the United States Environmental Protection Agency (EPA) official fuel economy guide\", \"document_title\": \"Principles of Classical Thermodynamics\", \"page\": 352, \"section\": \"Refrigeration and Heat Pumps\", \"selected_text\": \"The coefficient of performance (COP) for a refrigerator is defined as COP = Q_cold / W_in.\", \"surrounding_context\": \"Refrigerators pump thermal energy from a cold interior to a warmer exterior by consuming external electrical work.\", \"retrieved_evidence\": [\"Section 4.4: Maximum theoretical COP for a Carnot refrigeration cycle.\"], \"student_prompt\": \"What does the reading cite as the EPA highway MPG rating for the Ford F-150 hybrid?\"}], \"grounded_paraphrase\": {\"document_title\": \"Statistical Thermodynamics\", \"page\": 325, \"section\": \"Boltzmann's Entropy Formula Axiom\", \"selected_text\": \"Boltzmann's thermodynamic postulate formalizes entropy as the logarithmic scalar measure of accessible microscopic microstate configurations commensurate with an assigned macroscopic thermodynamic macrostate: S = k_B ln(W).\", \"surrounding_context\": \"Consequently, isolated thermodynamic systems spontaneously evolve toward macrostates exhibiting overwhelmingly superior statistical multiplicities.\", \"retrieved_evidence\": [\"Page 325: 'Entropy (S = k_B ln W) measures the number of microstates in a macrostate; systems move toward states that have the most ways to be arranged.'\"], \"student_prompt\": \"Can you explain what entropy means according to Boltzmann's formula in simple terms?\", \"faithful_paraphrase\": \"This passage explains that entropy is simply a measure of probability and arrangements. Boltzmann's formula shows that entropy counts how many different microscopic ways the particles can be arranged while still looking the same from the outside. Systems naturally move toward higher entropy simply because those states have vastly more possible ways to exist, making them statistically inevitable.\"}, \"conflict_handling\": {\"document_title\": \"Chemical Thermodynamics: Sign Conventions\", \"page\": 360, \"section\": \"First Law Sign Conventions: Chemistry vs Physics\", \"selected_text\": \"In standard physics textbooks, the First Law of Thermodynamics is written as \u0394U = Q - W, where W is work done BY the system on the surroundings.\", \"surrounding_context\": \"In chemistry textbooks and IUPAC international standards, the First Law is written as \u0394U = Q + W, where W is work done ON the system by the surroundings.\", \"retrieved_evidence\": [\"Physics Convention: \u0394U = Q - W (Work done BY system is positive; expanding gas does positive work, reducing internal energy).\", \"Chemistry / IUPAC Convention: \u0394U = Q + W (Work done ON system is positive; compressing gas does positive work, increasing internal energy).\"], \"student_prompt\": \"My physics book says \u0394U = Q - W, but my chemistry book says \u0394U = Q + W. Why do they have opposite signs?\", \"resolution_explanation\": \"These two equations describe the exact same physical reality; they differ only in who they define as the worker. In physics, work (W) is traditionally defined as work done BY the system on the outside world (like a piston lifting a weight), so doing work drains the system's energy (\u0394U = Q - W). In chemistry and modern IUPAC standards, work (W) is defined from the system's perspective as energy entering the system (work done ON the system), so work adds energy (\u0394U = Q + W). Both yield identical results when applied consistently.\"}}}, \"science::Electromagnetic Spectrum\": {\"domain\": \"science\", \"concept\": \"Electromagnetic Spectrum\", \"explanation\": \"the complete range of electromagnetic radiation, from low-energy radio waves to high-energy gamma rays, all traveling at the speed of light but differing in wavelength and frequency\", \"reason\": \"it encompasses everything from radio communication to medical X-rays to visible light, making it fundamental to technology and understanding nature\", \"concrete_examples\": [\"Your smartphone receives radio waves (long wavelength), your microwave oven uses microwaves, and your eyes detect visible light \u2014 all are electromagnetic radiation.\", \"UV radiation from the sun causes sunburn because its high energy damages skin cell DNA.\", \"X-rays pass through soft tissue but are absorbed by bone, creating medical images.\"], \"numerical_examples\": [\"Visible light spans wavelengths of approximately 400 nm (violet) to 700 nm (red).\", \"Speed of light: c = \u03bbf. For red light (\u03bb = 700 nm): f = 3\u00d710\u2078 / 7\u00d710\u207b\u2077 = 4.3\u00d710\u00b9\u2074 Hz.\", \"Photon energy: E = hf. For UV light at f = 1\u00d710\u00b9\u2075 Hz: E = 6.63\u00d710\u207b\u00b3\u2074 \u00d7 10\u00b9\u2075 = 6.63\u00d710\u207b\u00b9\u2079 J.\"], \"misconceptions\": [[\"Radio waves and gamma rays are completely different types of energy\", \"They are all the SAME type of energy \u2014 electromagnetic radiation. The only difference is wavelength and frequency. Radio waves have long wavelengths and low energy; gamma rays have short wavelengths and high energy. They all travel at the speed of light in a vacuum.\"]], \"analogies\": [\"The EM spectrum is like a piano keyboard \u2014 radio waves are the deep bass notes (low frequency, long wavelength) and gamma rays are the high-pitched notes (high frequency, short wavelength), but they're all sound waves (well, light waves).\"], \"prerequisites\": [\"basic physics\", \"wave properties\"], \"formulas\": [\"c = \u03bbf\", \"E = hf\"], \"document_evidence\": [\"The text organizes the spectrum: 'From longest to shortest wavelength: radio, microwave, infrared, visible, ultraviolet, X-ray, gamma ray.'\", \"Figure 7.2 displays the EM spectrum with wavelength ranges and common applications for each band.\"], \"practice_problems\": [\"Calculate the frequency of green light with wavelength 550 nm.\", \"Which has more energy per photon: infrared light or ultraviolet light? Explain using E = hf.\"], \"hints\": [\"Higher frequency = shorter wavelength = more energy per photon.\", \"Use c = \u03bbf to convert between wavelength and frequency (c = 3\u00d710\u2078 m/s).\"], \"follow_up_questions\": [\"Why do different materials absorb different parts of the EM spectrum?\", \"How do astronomers use the EM spectrum to learn about distant stars?\"], \"diagnostic_questions\": [\"Are radio waves and visible light fundamentally different kinds of energy?\", \"Why is UV radiation more dangerous than visible light?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Higher frequency electromagnetic waves travel faster through a vacuum than lower frequency radio waves.\", \"error_reason\": \"In a vacuum, all electromagnetic waves travel at the exact same constant speed of light c \u2248 3.0 x 10^8 m/s; frequency affects energy, not vacuum propagation speed.\", \"correct_claim\": \"All electromagnetic waves (from radio to gamma rays) travel at the exact same speed in a vacuum: c \u2248 3.0 x 10^8 m/s. Higher frequency means higher photon energy, not faster velocity.\", \"understanding_probe\": \"Do X-rays travel faster through empty space than AM radio waves?\", \"expected_answer\": \"No, all electromagnetic radiation travels at the identical speed of light (c) in a vacuum; X-rays have more energy and higher frequency, but the same speed.\"}, {\"prior_erroneous_claim\": \"Radio waves are acoustic sound waves that vibrate air particles.\", \"error_reason\": \"Radio waves are transverse electromagnetic waves composed of oscillating electric and magnetic fields that travel through vacuum; sound waves are longitudinal mechanical vibrations that require a physical medium.\", \"correct_claim\": \"Radio waves are electromagnetic radiation (light), not sound waves. They travel at the speed of light through empty space without needing air or any physical medium.\", \"understanding_probe\": \"Can radio waves travel through the vacuum of outer space where sound cannot?\", \"expected_answer\": \"Yes, because radio waves are electromagnetic radiation made of oscillating electric and magnetic fields, unlike sound waves which require a physical medium like air to vibrate.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Optics and Electromagnetic Waves\", \"page\": 375, \"section\": \"Wave Equation and Photon Energy Calculations\", \"selected_text\": \"An FM radio broadcast station transmits at a carrier frequency of f = 100.0 MHz (1.00 x 10^8 s\u207b\u00b9) in a vacuum, where c = 3.00 x 10^8 m/s and Planck's constant h = 6.626 x 10^(-34) J\u00b7s.\", \"surrounding_context\": \"Section 2.1 computes the wavelength in meters and the energy of a single transmitted photon in Joules and electron-volts.\", \"retrieved_evidence\": [\"Wavelength formula: \u03bb = c / f = (3.00 x 10^8 m/s) / (1.00 x 10^8 s\u207b\u00b9) = 3.00 meters.\", \"Photon energy formula: E = h * f = (6.626 x 10^(-34) J\u00b7s) * (1.00 x 10^8 s\u207b\u00b9) = 6.626 x 10^(-26) Joules.\", \"Energy conversion to eV: E = 6.626 x 10^(-26) J / (1.602 x 10^(-19) J/eV) = 4.136 x 10^(-7) eV.\"], \"student_prompt\": \"What are the exact wavelength in meters and photon energy in Joules calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The wavelength is \u03bb = c / f = (3.00 x 10^8 m/s) / (1.00 x 10^8 s\u207b\u00b9) = 3.00 meters. The energy of a single photon is E = h * f = (6.626 x 10^(-34) J\u00b7s) * (1.00 x 10^8 s\u207b\u00b9) = 6.626 x 10^(-26) Joules. The text directly establishes that the broadcast wavelength is exactly 3.00 meters and each photon carries 6.626 x 10^(-26) Joules of energy.\", \"calculated_result\": \"Wavelength = 3.00 m, Photon Energy = 6.626 x 10^(-26) J\"}, \"pattern_b_derive\": {\"document_title\": \"Astrophysics and Radiation: Blackbody Radiation Laws\", \"page\": 382, \"section\": \"Deriving Peak Wavelength via Wien's Displacement Law\", \"selected_text\": \"Wien's displacement law relates the surface temperature T of an ideal blackbody radiator to its peak emission wavelength \u03bb_max.\", \"surrounding_context\": \"The relationship states that peak wavelength is inversely proportional to absolute temperature: \u03bb_max * T = b, where Wien's constant b = 2.898 x 10^(-3) m\u00b7K.\", \"retrieved_evidence\": [\"Wien's Law Formula: \u03bb_max = b / T, with b = 2.898 x 10^(-3) m\u00b7K.\", \"Stellar data: The surface of the Sun has an effective blackbody temperature of T = 5,800 K.\"], \"student_prompt\": \"How do we derive the peak emission wavelength in nanometers for a star with temperature T = 5,800 K?\", \"target_response\": \"To derive the peak emission wavelength using Wien's displacement law: Substitute the stellar temperature and Wien's constant into \u03bb_max = b / T: \u03bb_max = (2.898 x 10^(-3) m\u00b7K) / 5,800 K. Performing the division yields 4.9965 x 10^(-7) meters. To convert meters to nanometers, multiply by 10^9: 4.9965 x 10^(-7) * 10^9 = 499.65 nm, or approximately 500 nm. This confirms that the Sun's peak radiation falls squarely in the green-blue visible light portion of the spectrum.\", \"formula\": \"\u03bb_max = b / T\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact construction cost in Swiss Francs of the Jungfraujoch High Altitude Research Station\", \"actual_topic\": \"the electromagnetic spectrum, photon energies, wavelengths, and Wien's displacement law\", \"authoritative_source\": \"the Swiss National Science Foundation historical financial records or Jungfrau Railway corporate archives\", \"document_title\": \"Foundations of Electromagnetic Radiation\", \"page\": 390, \"section\": \"Atmospheric Transmission Windows\", \"selected_text\": \"Earth's atmosphere is transparent to visible light and specific radio bands, but absorbs most ultraviolet, X-ray, and gamma radiation.\", \"surrounding_context\": \"Water vapor and carbon dioxide absorb specific bands in the infrared spectrum.\", \"retrieved_evidence\": [\"Figure 4.2: Atmospheric opacity curve from radio to gamma wavelengths.\"], \"student_prompt\": \"According to this document, how many Swiss Francs did it cost to build the Jungfraujoch research station?\"}, {\"unmentioned_term\": \"the total streaming viewership numbers for the 2024 Eurovision Song Contest grand final\", \"actual_topic\": \"Doppler effect for electromagnetic radiation and cosmological red shift\", \"authoritative_source\": \"the European Broadcasting Union (EBU) official television audience audit reports\", \"document_title\": \"Foundations of Electromagnetic Radiation\", \"page\": 395, \"section\": \"The Relativistic Doppler Effect\", \"selected_text\": \"The relativistic Doppler formula for light receding along the line of sight is f_obs = f_source * \u221a((1 - \u03b2)/(1 + \u03b2)).\", \"surrounding_context\": \"Distant galaxies exhibit red-shifted spectral lines due to the metric expansion of space.\", \"retrieved_evidence\": [\"Section 4.4: Derivation of cosmological redshift parameter z = \u0394\u03bb / \u03bb0.\"], \"student_prompt\": \"What does this text state regarding Eurovision 2024 streaming viewer counts?\"}], \"grounded_paraphrase\": {\"document_title\": \"Classical Electrodynamics\", \"page\": 370, \"section\": \"Maxwell's Prediction of Electromagnetic Waves\", \"selected_text\": \"Maxwell's synthesis demonstrated that mutually perpendicular, time-varying electric and magnetic vector fields perpetuate autonomously through the vacuum by mutual induction, propagating at an invariant velocity determined exclusively by the dielectric permittivity and magnetic permeability of free space: c = 1 / \u221a(\u03b50 \u03bc0).\", \"surrounding_context\": \"This confirmed that visible light is a manifestation of electromagnetic wave phenomena.\", \"retrieved_evidence\": [\"Page 370: 'Maxwell showed that changing electric and magnetic fields create each other and travel through empty space as light waves at speed c = 1/\u221a(\u03b50 \u03bc0).'\"], \"student_prompt\": \"Can you explain what electromagnetic waves are in simple terms based on this passage?\", \"faithful_paraphrase\": \"This passage explains that electromagnetic waves are self-sustaining ripples of energy traveling through empty space. A changing electric field produces a magnetic field, and that changing magnetic field produces an electric field in return. Because they continuously create each other, these paired fields can travel through the vacuum of space forever at the speed of light.\"}, \"conflict_handling\": {\"document_title\": \"Wave-Particle Duality and Quantum Optics\", \"page\": 402, \"section\": \"Wave Theory vs Photon Theory of Light\", \"selected_text\": \"In classical wave optics, Maxwell's equations treat light as continuous wave fields that explain interference, diffraction, and polarization.\", \"surrounding_context\": \"In quantum electrodynamics, light consists of quantized particles called photons, which explain the photoelectric effect, Compton scattering, and blackbody radiation.\", \"retrieved_evidence\": [\"Wave Model (Young, Maxwell): Light is continuous waves; required to explain double-slit interference fringes.\", \"Particle Model (Einstein): Light is localized packets of energy (photons); required to explain the immediate ejection of electrons in the photoelectric effect.\"], \"student_prompt\": \"Is light a continuous wave or is it a stream of particles? Why do two chapters describe it in contradictory ways?\", \"resolution_explanation\": \"These two descriptions are not contradictory; they reflect the principle of wave-particle duality. Light behaves as a wave when it propagates through space, creating interference patterns and bending around obstacles (diffraction). However, when light interacts with matter and exchanges energy (like striking a solar panel or camera sensor), it behaves strictly as discrete packets of energy called photons. Modern quantum electrodynamics unites both models: light has both wave and particle characteristics.\"}}}, \"science::Plate Tectonics\": {\"domain\": \"science\", \"concept\": \"Plate Tectonics\", \"explanation\": \"the scientific theory that Earth's lithosphere is divided into large plates that float on the semi-fluid asthenosphere and move slowly, causing earthquakes, volcanic activity, and mountain formation\", \"reason\": \"it explains the distribution of earthquakes and volcanoes, continental shapes, ocean floor features, and the long-term evolution of Earth's surface\", \"concrete_examples\": [\"South America and Africa's coastlines fit together like puzzle pieces because they were once joined as part of Pangaea.\", \"The Himalayas formed from the collision of the Indian plate and the Eurasian plate \u2014 a convergent boundary.\", \"Iceland sits on the Mid-Atlantic Ridge, where the North American and Eurasian plates are pulling apart.\"], \"numerical_examples\": [\"The Atlantic Ocean widens by about 2.5 cm per year as the plates diverge \u2014 about the speed your fingernails grow.\", \"The Pacific Plate moves northwest at about 7\u201310 cm per year.\", \"The oldest oceanic crust is about 200 million years old, compared to continental crust up to 4 billion years old.\"], \"misconceptions\": [[\"Earthquakes happen because the ground suddenly opens up into a giant crack\", \"Earthquakes occur when stress built up along fault lines is suddenly released as the plates slip. The ground shakes from seismic waves, but it doesn't open into chasms. Buildings collapse from shaking, not from the ground splitting open.\"]], \"analogies\": [\"Tectonic plates are like giant crackers floating on thick soup \u2014 they drift, bump into each other (causing earthquakes), spread apart (creating new crust), and sometimes slide under one another.\"], \"prerequisites\": [\"basic geology\", \"Earth's layers\"], \"formulas\": [\"Plate velocity \u2248 distance / time (geological timescale)\"], \"document_evidence\": [\"The text states: 'Evidence for plate tectonics includes matching fossils on separated continents, seafloor spreading magnetic stripes, and GPS measurements of plate motion.'\", \"Map 10.1 shows the major tectonic plates and the types of boundaries between them.\"], \"practice_problems\": [\"If the Atlantic Ocean is 5,000 km wide and opened at 2.5 cm/year, approximately how long ago did it start forming?\", \"Classify the following as convergent, divergent, or transform: Himalayas, Mid-Atlantic Ridge, San Andreas Fault.\"], \"hints\": [\"Three boundary types: convergent (collide), divergent (separate), transform (slide past).\", \"Fossils of the same species on different continents = evidence they were once connected.\"], \"follow_up_questions\": [\"What drives the movement of tectonic plates?\", \"Why is oceanic crust younger than continental crust?\"], \"diagnostic_questions\": [\"What evidence convinced scientists that continents move?\", \"What type of plate boundary creates new oceanic crust?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Tectonic plates float directly on a vast ocean of liquid molten magma beneath the Earth's crust.\", \"error_reason\": \"The mantle (asthenosphere) is almost entirely solid rock that behaves plastically over millions of years (solid-state ductile flow); it is NOT a liquid ocean of magma.\", \"correct_claim\": \"The mantle asthenosphere is solid rock that deforms plastically under extreme heat and pressure over geological timescales; tectonic plates do not float on liquid magma.\", \"understanding_probe\": \"Is the mantle beneath tectonic plates a liquid ocean of melted rock?\", \"expected_answer\": \"No, the mantle is overwhelmingly solid rock that flows like extremely stiff silly putty over millions of years due to high temperature and pressure.\"}, {\"prior_erroneous_claim\": \"Continental drift and plate tectonics are caused solely by the centrifugal spin of the Earth.\", \"error_reason\": \"Plate motion is driven by mantle convection, slab pull at subduction zones, and ridge push at mid-ocean ridges; Earth's rotational centrifugal forces are millions of times too weak to move continents.\", \"correct_claim\": \"Tectonic plate movement is powered by internal thermal convection, mantle plumes, slab pull (the primary driver), and ridge push, not the Earth's rotational spin.\", \"understanding_probe\": \"What is the primary physical driving force behind modern plate tectonic movement?\", \"expected_answer\": \"Slab pull, where cold, dense oceanic lithosphere sinks into the mantle at subduction zones, pulling the rest of the plate along with it.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Geodynamics and Global Tectonics\", \"page\": 418, \"section\": \"Seafloor Spreading Rates from Magnetic Stripe Anomalies\", \"selected_text\": \"Marine geomagnetic surveys across the Mid-Atlantic Ridge reveal symmetric magnetic reversals. An identifiable magnetic anomaly matching the Brunhes-Matuyama reversal (dated at t = 780,000 years ago) is located at distance d = 19.50 km on both sides of the central spreading axis.\", \"surrounding_context\": \"Section 2.1 computes the half-spreading rate and full spreading rate in centimeters per year.\", \"retrieved_evidence\": [\"Half-spreading rate formula: v_half = distance / time = 19.50 km / 780,000 years.\", \"Unit conversion: 19.50 km = 1,950,000 cm.\", \"Step-by-step arithmetic from text: v_half = 1,950,000 cm / 780,000 yr = 2.50 cm/year.\", \"Full plate separation rate: v_full = 2 * v_half = 2 * 2.50 cm/yr = 5.00 cm/year.\"], \"student_prompt\": \"What are the exact half-spreading and full-spreading rates calculated in Section 2.1 in centimeters per year?\", \"target_response\": \"Following the explicit steps in Section 2.1: Converting 19.50 km to centimeters gives 1,950,000 cm. Dividing by the 780,000-year age of the anomaly yields a half-spreading rate of 1,950,000 / 780,000 = 2.50 cm/year for each flank. The full plate separation rate is double the half rate: 2 * 2.50 = 5.00 cm/year. The text directly establishes the half-rate at 2.50 cm/year and the full spreading rate at 5.00 cm/year.\", \"calculated_result\": \"Half-rate = 2.50 cm/yr, Full rate = 5.00 cm/yr\"}, \"pattern_b_derive\": {\"document_title\": \"Thermal Structure of Oceanic Lithosphere\", \"page\": 425, \"section\": \"Deriving Oceanic Basin Depth from Lithospheric Cooling\", \"selected_text\": \"As newly formed oceanic lithosphere moves away from a mid-ocean ridge, conductive cooling increases its density and causes seafloor subsidence.\", \"surrounding_context\": \"The boundary layer cooling model establishes that ocean depth d(t) increases with the square root of seafloor age t.\", \"retrieved_evidence\": [\"Subsidence formula: d(t) = d0 + C * \u221at, where d0 = 2,500 m (ridge crest depth), C = 350 m / Ma^(1/2), and t is seafloor age in millions of years (Ma).\", \"Target age: Calculate depth for an ocean basin of age t = 36 Ma.\"], \"student_prompt\": \"How do we derive the water depth of an oceanic basin at age t = 36 Ma using the boundary layer cooling model?\", \"target_response\": \"To derive the seafloor depth: Use the subsidence equation d(t) = d0 + C * \u221at. First take the square root of the seafloor age: \u221a36 = 6.0. Next, multiply this value by the thermal cooling constant: 350 m * 6.0 = 2,100 meters of cumulative thermal subsidence. Finally, add this subsidence to the ridge crest baseline depth: d = 2,500 m + 2,100 m = 4,600 meters. The ocean basin depth at 36 Ma is exactly 4,600 meters.\", \"formula\": \"d(t) = 2,500 + 350 * \u221at\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the annual ticket revenue collected from tourists visiting Mount Vesuvius national park\", \"actual_topic\": \"convergent, divergent, and transform plate boundaries, subduction zones, and seafloor spreading\", \"authoritative_source\": \"the Italian Ministry of Tourism or Ente Parco Nazionale del Vesuvio official accounts\", \"document_title\": \"Principles of Plate Tectonics\", \"page\": 435, \"section\": \"Transform Fault Mechanics\", \"selected_text\": \"Transform plate boundaries accommodate horizontal shear motion without creating or destroying lithosphere.\", \"surrounding_context\": \"The San Andreas Fault is a right-lateral strike-slip boundary connecting the East Pacific Rise with the Mendocino Triple Junction.\", \"retrieved_evidence\": [\"Section 3.3: Strike-slip kinematics and seismic recurrence intervals.\"], \"student_prompt\": \"According to this document, how much ticket revenue does Mount Vesuvius collect from tourists each year?\"}, {\"unmentioned_term\": \"the exact wholesale spot price of commercial diamonds per carat in Antwerp, Belgium\", \"actual_topic\": \"mantle plumes, hot spots, and Hawaiian island chain volcanic age progressions\", \"authoritative_source\": \"the Antwerp World Diamond Centre (AWDC) trade data bulletins\", \"document_title\": \"Principles of Plate Tectonics\", \"page\": 440, \"section\": \"Mantle Plumes and Intraplate Volcanism\", \"selected_text\": \"Hot spots originate from deep, stationary mantle plumes rising from the core-mantle boundary (D'' layer).\", \"surrounding_context\": \"The northwest progression of the Hawaiian-Emperor seamount chain records Pacific plate motion over a fixed thermal plume.\", \"retrieved_evidence\": [\"Table 3.5: Radiometric ages of volcanic shield basalts along the Hawaiian ridge.\"], \"student_prompt\": \"What does the reading state regarding the per-carat price of wholesale diamonds in Antwerp?\"}], \"grounded_paraphrase\": {\"document_title\": \"Earth System Science\", \"page\": 412, \"section\": \"The Lithosphere-Asthenosphere Boundary Axiom\", \"selected_text\": \"The lithosphere constitutes a mechanically rigid outer shell encompassing the continental and oceanic crust fused to the brittle uppermost mantle, decoupled from the underlying convective planet interior along an isothermal boundary corresponding to the 1,300\u00b0C rheological transition.\", \"surrounding_context\": \"This mechanical rigidity enables coherent horizontal translation of tectonic plates across the ductile asthenosphere.\", \"retrieved_evidence\": [\"Page 412: 'Tectonic plates are made of the rigid lithosphere (crust plus upper mantle), which slides horizontally over the hotter, flexible asthenosphere below.'\"], \"student_prompt\": \"Can you explain what a tectonic plate is in simple language based on this passage?\", \"faithful_paraphrase\": \"This passage explains that a tectonic plate is a hard, rigid slab made up of the Earth's crust and the very top solid layer of the mantle, together called the lithosphere. This stiff shell rests on top of a deeper, hotter rock layer called the asthenosphere, which is soft enough to slowly deform, allowing the rigid plates above to slide across the Earth's surface.\"}, \"conflict_handling\": {\"document_title\": \"Plate Tectonics Historical Foundations\", \"page\": 448, \"section\": \"Wegener's Continental Drift vs Modern Plate Tectonics\", \"selected_text\": \"Alfred Wegener proposed continental drift in 1912 based on fossil distributions and matching continental coastlines, but his hypothesis was rejected by geophysicists because he suggested continents plowed through ocean floors like icebreakers.\", \"surrounding_context\": \"Modern plate tectonics (formulated in the late 1960s) resolved this by showing that continents do not plow through oceanic crust; rather, continental and oceanic crust are both passengers embedded within larger rigid lithospheric plates.\", \"retrieved_evidence\": [\"Wegener's Model (1912): Continents plow independently through solid ocean basins (mechanically flawed).\", \"Plate Tectonic Model (1968): Entire plates (containing both oceans and continents) move together as cohesive units riding atop the asthenosphere.\"], \"student_prompt\": \"Why did scientists reject Wegener's idea of moving continents in 1915, but fully accept plate tectonics in the 1960s?\", \"resolution_explanation\": \"Wegener was right that the continents had moved, but his proposed mechanism was physically impossible. He suggested that lightweight continents plowed directly through hard ocean floors like icebreakers, and geologists rightly pointed out that rock cannot plow through rock without shattering. Plate tectonics was accepted in the 1960s because discovery of seafloor spreading and subduction proved that continents do not plow through the ocean; instead, the continents and oceans are parts of the same large rigid plates moving together over the mantle.\"}}}, \"science::Natural Selection\": {\"domain\": \"science\", \"concept\": \"Natural Selection\", \"explanation\": \"the process by which organisms with traits better suited to their environment tend to survive and reproduce more, passing those advantageous traits to the next generation\", \"reason\": \"it is the primary mechanism of evolution, explaining how species adapt to their environments and how biodiversity arises\", \"concrete_examples\": [\"Peppered moths in industrial England: dark-colored moths survived better on soot-darkened trees, shifting the population from mostly light to mostly dark.\", \"Antibiotic-resistant bacteria: when antibiotics kill susceptible bacteria, resistant ones survive and multiply.\", \"Darwin's finches: different beak shapes evolved on different Gal\u00e1pagos islands to exploit different food sources.\"], \"numerical_examples\": [\"If 10% of a beetle population has a camouflage mutation and predators eat 80% of non-camouflaged beetles but only 20% of camouflaged ones, the camouflaged fraction grows rapidly across generations.\", \"If a trait provides a 1% survival advantage, it can spread through a population of 10,000 in roughly 1,000 generations.\", \"Hardy-Weinberg: if p\u00b2 + 2pq + q\u00b2 = 1 and q = 0.3, then q\u00b2 = 0.09 (9% show the recessive phenotype).\"], \"misconceptions\": [[\"Organisms evolve on purpose to adapt to their environment\", \"Evolution has no purpose or direction. Random mutations occur, and natural selection acts on existing variation. Organisms don't 'choose' to evolve. Those with beneficial mutations survive more \u2014 it's a filtering process, not a goal-directed one.\"]], \"analogies\": [\"Natural selection is like a sieve \u2014 all varieties of organisms pass through, but only those whose traits fit through the environmental 'holes' survive and reproduce.\"], \"prerequisites\": [\"basic biology\", \"genetics\"], \"formulas\": [\"Fitness = reproductive success relative to other individuals in the population\"], \"document_evidence\": [\"The text states: 'Natural selection requires: variation in traits, heritability of those traits, and differential fitness based on traits.'\", \"Darwin's observations in the Gal\u00e1pagos (Section 11.2) provided key evidence for natural selection.\"], \"practice_problems\": [\"Explain how antibiotic resistance in bacteria is an example of natural selection. Identify the variation, selection pressure, and outcome.\", \"Why doesn't natural selection produce 'perfect' organisms?\"], \"hints\": [\"Three requirements: variation exists, traits are heritable, and some variants survive/reproduce better.\", \"Natural selection acts on existing variation \u2014 it cannot create new traits from scratch.\"], \"follow_up_questions\": [\"What is the difference between natural selection and genetic drift?\", \"Can natural selection lead to the loss of traits? Give an example.\"], \"diagnostic_questions\": [\"Did giraffes evolve long necks because they 'needed' to reach high leaves? Explain the correct mechanism.\", \"What are the three conditions necessary for natural selection to occur?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Individual organisms evolve adaptations during their lifetime in response to environmental need and pass those acquired traits to offspring.\", \"error_reason\": \"This is Lamarckian inheritance, which is genetically invalid; natural selection acts on existing heritable genetic variation within a population across generations, not acquired individual changes.\", \"correct_claim\": \"Individual organisms do not evolve; populations evolve over generations. Natural selection filters existing heritable genetic variations that confer differential reproductive success.\", \"understanding_probe\": \"Does a giraffe stretch its neck during its lifetime and pass that longer neck down to its calves?\", \"expected_answer\": \"No, that is the discredited Lamarckian idea. In natural selection, giraffes that already inherited genes for slightly longer necks survived and reproduced more successfully.\"}, {\"prior_erroneous_claim\": \"Survival of the fittest means that only the strongest, most aggressive, and physically dominant animals survive.\", \"error_reason\": \"In evolutionary biology, 'fitness' refers strictly to differential reproductive success\u2014an organism's relative contribution of viable offspring to the next generation's gene pool\u2014not physical combat strength.\", \"correct_claim\": \"Evolutionary fitness measures reproductive success (the number of surviving offspring an individual leaves), not physical fighting strength or aggression.\", \"understanding_probe\": \"In evolutionary biology, what does the word 'fitness' actually mean?\", \"expected_answer\": \"It measures reproductive success: the relative ability of an organism to survive and pass its genes on to the next generation.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Population Genetics and Evolution\", \"page\": 465, \"section\": \"Natural Selection and the Selection Coefficient\", \"selected_text\": \"In a diploid population of insects, three genotypes exhibit differential survival to adulthood: Genotype AA survival = 90.0%; Genotype Aa survival = 90.0%; Genotype aa survival = 54.0%.\", \"surrounding_context\": \"Section 3.1 calculates relative fitness (w) and the selection coefficient (s) against the homozygous recessive genotype.\", \"retrieved_evidence\": [\"Relative fitness definition: Standardize by dividing all survival rates by the highest survival rate (90.0%).\", \"Fitness calculations: w_AA = 0.90 / 0.90 = 1.00; w_Aa = 0.90 / 0.90 = 1.00; w_aa = 0.54 / 0.90 = 0.60.\", \"Selection coefficient formula: s = 1 - w_aa.\", \"Step-by-step arithmetic from text: s = 1.00 - 0.60 = 0.40 (40.0% selective disadvantage).\"], \"student_prompt\": \"What are the exact relative fitness values and selection coefficient calculated in Section 3.1?\", \"target_response\": \"Following the explicit steps in Section 3.1: Dividing each genotype's survival rate by the maximum rate (0.90) gives relative fitness values: w_AA = 1.00, w_Aa = 1.00, and w_aa = 0.54 / 0.90 = 0.60. The selection coefficient against the aa genotype is s = 1 - w_aa = 1.00 - 0.60 = 0.40. The text directly establishes that the aa genotype has a relative fitness of 0.60 and faces a selection coefficient of 0.40 (a 40% reproductive disadvantage).\", \"calculated_result\": \"w_AA = 1.00, w_Aa = 1.00, w_aa = 0.60, Selection coefficient s = 0.40\"}, \"pattern_b_derive\": {\"document_title\": \"Evolutionary Genetics: The Hardy-Weinberg Baseline\", \"page\": 472, \"section\": \"Hardy-Weinberg Equilibrium Allele Frequencies\", \"selected_text\": \"In the absence of natural selection, mutation, migration, genetic drift, and non-random mating, allele frequencies remain constant: p + q = 1 and p\u00b2 + 2pq + q\u00b2 = 1.\", \"surrounding_context\": \"When a recessive condition exhibits frequency q\u00b2, the frequency of heterozygous carriers can be derived algebraically.\", \"retrieved_evidence\": [\"Hardy-Weinberg Equations: p + q = 1; p\u00b2 + 2pq + q\u00b2 = 1\", \"Phenotypic frequency: In a sample population, 4.0% of individuals express a recessive trait (aa), so q\u00b2 = 0.04.\"], \"student_prompt\": \"How do we derive the recessive allele frequency q, dominant allele frequency p, and the percentage of heterozygous carriers (2pq)?\", \"target_response\": \"To derive the population frequencies: First take the square root of the homozygous recessive frequency: q = \u221a0.04 = 0.20. Next, use the relation p + q = 1 to find the dominant allele frequency: p = 1 - 0.20 = 0.80. Finally, calculate the frequency of heterozygous carriers using 2pq: 2 * (0.80) * (0.20) = 0.32 or 32.0%. In this population, 20% of the alleles are recessive, 80% are dominant, and 32% of individuals are heterozygous carriers.\", \"formula\": \"q = \u221aq\u00b2; p = 1 - q; Carrier frequency = 2pq\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact annual budget of the Charles Darwin Research Station on Santa Cruz Island in 2024\", \"actual_topic\": \"differential reproductive success, directional, stabilizing, and disruptive selection\", \"authoritative_source\": \"the Charles Darwin Foundation annual financial audit reports\", \"document_title\": \"Principles of Evolutionary Biology\", \"page\": 482, \"section\": \"Modes of Natural Selection\", \"selected_text\": \"Directional selection shifts the population phenotypic distribution toward an extreme phenotype.\", \"surrounding_context\": \"Stabilizing selection culls phenotypic extremes, favoring intermediate phenotypes, as seen in human birth weights.\", \"retrieved_evidence\": [\"Figure 4.3: Bell curve shifts under directional, stabilizing, and disruptive selection.\"], \"student_prompt\": \"According to this document, what was the 2024 operating budget of the Charles Darwin Research Station in the Galapagos?\"}, {\"unmentioned_term\": \"the current wholesale market price of industrial synthetic indigo dye per metric ton\", \"actual_topic\": \"the peppered moth (Biston betularia) industrial melanism natural selection case study\", \"authoritative_source\": \"chemical commodity market reports published by Platts or ICIS\", \"document_title\": \"Principles of Evolutionary Biology\", \"page\": 486, \"section\": \"Industrial Melanism\", \"selected_text\": \"Kettlewell's experiments with Biston betularia demonstrated that dark melanic moths enjoyed higher survival on soot-darkened trees.\", \"surrounding_context\": \"Clean air acts later reversed this trend, illustrating how changing environments alter selective pressures.\", \"retrieved_evidence\": [\"Table 4.4: Mark-release-recapture recovery rates of typical vs carbonaria morphs.\"], \"student_prompt\": \"What does this text state regarding the wholesale price of synthetic indigo dye per ton?\"}], \"grounded_paraphrase\": {\"document_title\": \"Evolutionary Synthesis Foundations\", \"page\": 460, \"section\": \"Natural Selection Axiom\", \"selected_text\": \"Natural selection designates the non-random differential reproductive propagation of discrete phenotypic variants within an ancestral population, emergent from the interaction between heritable phenotypic variation and environmental resource constraints.\", \"surrounding_context\": \"This differential fecundity inexorably drives adaptive shifts in the genomic composition of subsequent generations.\", \"retrieved_evidence\": [\"Page 460: 'Natural selection is the non-random process where individuals with traits better suited to their environment have more offspring, making those traits more common over time.'\"], \"student_prompt\": \"Can you explain what natural selection means based on this text in plain language?\", \"faithful_paraphrase\": \"This passage explains that natural selection is a straightforward, non-random process: within any population of living things, individuals have natural variations in their traits. Those individuals with traits that help them survive and find food in their specific environment are more likely to live and reproduce, passing those helpful traits down to the next generation so the population becomes better adapted over time.\"}, \"conflict_handling\": {\"document_title\": \"Evolutionary Theory Controversies\", \"page\": 495, \"section\": \"Gradualism vs Punctuated Equilibrium\", \"selected_text\": \"Darwin's classical view held that evolutionary change proceeds continuously at a slow, constant, gradual pace over millions of years (phyletic gradualism).\", \"surrounding_context\": \"In 1972, Niles Eldredge and Stephen Jay Gould proposed punctuated equilibrium, arguing the fossil record demonstrates long periods of morphological stasis interrupted by rapid bursts of speciation.\", \"retrieved_evidence\": [\"Phyletic Gradualism: Species accumulate morphological changes gradually and continuously across geological time.\", \"Punctuated Equilibrium: Species remain essentially unchanged for millions of years (stasis), with major evolutionary branchings occurring rapidly in small isolated populations.\"], \"student_prompt\": \"Did evolution happen as a slow, continuous change or in sudden rapid bursts? Why do two evolutionary biologists disagree?\", \"resolution_explanation\": \"Both patterns occur in nature, and they describe different facets of the evolutionary record. Phyletic gradualism describes steady, continuous adaptations that occur within a species as it refines itself in a slowly shifting environment. Punctuated equilibrium describes the pattern commonly seen in the fossil record, where a species remains stable for millions of years (stasis) until a sudden environmental disruption or isolation of a small group triggers rapid evolutionary branching over tens of thousands of years. Modern evolutionary biology recognizes that both gradual and punctuated tempos operate.\"}}}, \"nutrition_food_science::Macronutrients\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Macronutrients\", \"explanation\": \"the three main categories of nutrients \u2014 carbohydrates, proteins, and fats \u2014 that provide energy (calories) and serve structural and functional roles in the body\", \"reason\": \"understanding macronutrients is essential for balanced nutrition, disease prevention, and athletic performance\", \"concrete_examples\": [\"Carbohydrates in rice and bread provide quick energy (4 cal/g) for brain function and exercise.\", \"Proteins in chicken and beans build and repair muscles and tissues (4 cal/g).\", \"Fats in avocados and olive oil store energy (9 cal/g), insulate organs, and absorb fat-soluble vitamins.\"], \"numerical_examples\": [\"A meal with 60g carbs, 30g protein, and 20g fat provides: (60\u00d74) + (30\u00d74) + (20\u00d79) = 240 + 120 + 180 = 540 calories.\", \"An athlete needing 3,000 cal/day at 50/30/20 split: 375g carbs, 225g protein, 67g fat.\", \"A tablespoon of olive oil (14g fat) provides 14 \u00d7 9 = 126 calories.\"], \"misconceptions\": [[\"All fats are unhealthy and should be avoided\", \"Fats are essential for absorbing vitamins A, D, E, K, for brain function, and for hormone production. Unsaturated fats (found in fish, nuts, olive oil) are heart-healthy. Only trans fats and excessive saturated fats are associated with health risks.\"]], \"analogies\": [\"Macronutrients are like the three types of fuel for a car \u2014 carbs are gasoline (quick burn), fats are diesel (slow, sustained burn), and proteins are repair kits (fix and build parts).\"], \"prerequisites\": [\"basic biology\", \"chemistry basics\"], \"formulas\": [\"Carbs: 4 cal/g\", \"Protein: 4 cal/g\", \"Fat: 9 cal/g\", \"Total calories = sum of all macronutrient calories\"], \"document_evidence\": [\"The text states: 'Each macronutrient plays a distinct role: carbohydrates provide primary energy, proteins build structure, and fats store energy and support cell membranes.'\", \"Table 1.1 shows recommended daily macronutrient ranges from dietary guidelines.\"], \"practice_problems\": [\"A nutrition label shows 45g carbs, 12g protein, and 8g fat per serving. Calculate the total calories.\", \"If someone needs 2,500 calories/day with 55% from carbs, how many grams of carbs should they eat?\"], \"hints\": [\"Fats have more than double the calories per gram compared to carbs or protein.\", \"To convert percentage of calories to grams: (total cal \u00d7 %) / cal per gram of that macro.\"], \"follow_up_questions\": [\"Why do athletes often 'carb-load' before endurance events?\", \"What happens if you consume too much protein \u2014 does it all become muscle?\"], \"diagnostic_questions\": [\"Which macronutrient provides the most calories per gram?\", \"Are all types of fat equally bad for health? Explain.\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Dietary fats provide 4 kilocalories per gram, exactly identical to carbohydrates and proteins.\", \"error_reason\": \"Dietary fats provide 9 kcal/gram due to their highly reduced hydrocarbon chains, more than double the 4 kcal/gram provided by carbohydrates and proteins.\", \"correct_claim\": \"Dietary fats provide 9 kcal/gram, while carbohydrates and proteins provide 4 kcal/gram each (and alcohol provides 7 kcal/gram). Fats are the most energy-dense macronutrient.\", \"understanding_probe\": \"How many kilocalories are provided by 10 grams of pure dietary fat compared to 10 grams of pure carbohydrate?\", \"expected_answer\": \"10 grams of fat yields 90 kcal (10 * 9), whereas 10 grams of carbohydrate yields only 40 kcal (10 * 4).\"}, {\"prior_erroneous_claim\": \"All carbohydrates are broken down into amino acids during digestion.\", \"error_reason\": \"Carbohydrates are digested into monosaccharides (simple sugars like glucose, fructose, and galactose); proteins are broken down into amino acids.\", \"correct_claim\": \"Carbohydrates are enzymatically hydrolyzed into simple monosaccharide sugars (primarily glucose); proteins are what break down into amino acids.\", \"understanding_probe\": \"What are the basic monomer building blocks produced when the body digests proteins versus carbohydrates?\", \"expected_answer\": \"Proteins are broken down into amino acids, while carbohydrates are broken down into simple sugars (monosaccharides like glucose).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Human Nutrition: Macronutrient Energetics\", \"page\": 55, \"section\": \"Atwater Energy Values and Caloric Distribution\", \"selected_text\": \"A standard nutritional meal contains 60.0 g of carbohydrates, 30.0 g of protein, and 20.0 g of fat.\", \"surrounding_context\": \"Section 2.1 applies Atwater general factors (4 kcal/g for carbs, 4 kcal/g for protein, 9 kcal/g for fat) to calculate total caloric energy and macronutrient percentage splits.\", \"retrieved_evidence\": [\"Carbohydrate calories = 60.0 g * 4.0 kcal/g = 240.0 kcal.\", \"Protein calories = 30.0 g * 4.0 kcal/g = 120.0 kcal.\", \"Fat calories = 20.0 g * 9.0 kcal/g = 180.0 kcal.\", \"Total meal caloric energy = 240.0 + 120.0 + 180.0 = 540.0 kcal.\", \"Macronutrient percentages: Carbohydrates = 240 / 540 = 44.44%; Protein = 120 / 540 = 22.22%; Fat = 180 / 540 = 33.33%.\"], \"student_prompt\": \"What are the exact total kilocalories and macronutrient caloric percentages calculated in Section 2.1?\", \"target_response\": \"Following the explicit Atwater calculations in Section 2.1: Carbohydrates provide 60.0 * 4 = 240.0 kcal, protein provides 30.0 * 4 = 120.0 kcal, and fat provides 20.0 * 9 = 180.0 kcal, summing to a total meal energy of 540.0 kcal. In percentage terms, carbohydrates contribute 44.44% (240 / 540), protein contributes 22.22% (120 / 540), and fat contributes 33.33% (180 / 540). The course text directly establishes the total energy at 540.0 kcal and the 44.4% / 22.2% / 33.3% distribution.\", \"calculated_result\": \"Total energy = 540.0 kcal; Carbs = 44.44%, Protein = 22.22%, Fat = 33.33%\"}, \"pattern_b_derive\": {\"document_title\": \"Dietary Reference Intakes and Protein Needs\", \"page\": 62, \"section\": \"Calculating Daily Recommended Dietary Allowance (RDA) for Protein\", \"selected_text\": \"The Recommended Dietary Allowance (RDA) for protein for a healthy sedentary adult is 0.80 grams of protein per kilogram of body weight per day.\", \"surrounding_context\": \"Body weight in pounds must be converted to kilograms by dividing by 2.20462 before applying the protein factor.\", \"retrieved_evidence\": [\"Formula: Daily Protein RDA (g) = Weight (kg) * 0.80 g/kg/day, where Weight (kg) = Weight (lbs) / 2.20462.\", \"Client baseline: A healthy adult female weighs 154.0 lbs.\"], \"student_prompt\": \"How do we derive the daily protein requirement in grams for a 154.0 lb adult from the RDA formula?\", \"target_response\": \"To derive the daily protein RDA: First convert body weight from pounds to kilograms: 154.0 lbs / 2.20462 = 70.0 kg (or 154 / 2.2 = 70 kg). Next, multiply body mass in kilograms by the adult protein recommendation factor of 0.80 g/kg: 70.0 kg * 0.80 g/kg/day = 56.0 grams of protein per day. A sedentary adult weighing 154 pounds requires exactly 56.0 grams of dietary protein daily to meet the RDA.\", \"formula\": \"Protein (g) = (Weight in lbs / 2.2) * 0.80\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale spot price of commercial soybean oil per pound on the Chicago Board of Trade\", \"actual_topic\": \"macronutrient classifications, Atwater energy density factors, and dietary reference intakes\", \"authoritative_source\": \"the CME Group / Chicago Board of Trade daily agricultural commodity price indexes\", \"document_title\": \"Foundations of Human Nutrition\", \"page\": 70, \"section\": \"Lipid Structure and Essential Fatty Acids\", \"selected_text\": \"Essential fatty acids encompass linoleic acid (omega-6) and alpha-linolenic acid (omega-3), which humans cannot synthesize de novo.\", \"surrounding_context\": \"These polyunsaturated fatty acids serve as biosynthetic precursors for eicosanoid signaling molecules.\", \"retrieved_evidence\": [\"Section 3.2: Chemical structure of omega-3 and omega-6 double bonds.\"], \"student_prompt\": \"According to this document, what was the CBOT price of soybean oil per pound?\"}, {\"unmentioned_term\": \"the retail price of a 5-pound tub of Optimum Nutrition Gold Standard whey protein powder\", \"actual_topic\": \"nitrogen balance, protein quality, and complete versus incomplete protein sources\", \"authoritative_source\": \"retail commercial sports supplement store pricing sheets\", \"document_title\": \"Foundations of Human Nutrition\", \"page\": 75, \"section\": \"Protein Quality Scoring\", \"selected_text\": \"Protein quality is evaluated via the Protein Digestibility-Corrected Amino Acid Score (PDCAAS).\", \"surrounding_context\": \"Egg white and milk casein achieve the maximum score of 1.00.\", \"retrieved_evidence\": [\"Table 3.4: PDCAAS scores of animal and plant protein isolates.\"], \"student_prompt\": \"What does this text state regarding the retail price of Optimum Nutrition whey protein?\"}], \"grounded_paraphrase\": {\"document_title\": \"Nutritional Biochemistry\", \"page\": 50, \"section\": \"Macronutrient Definition Axiom\", \"selected_text\": \"Macronutrients encompass dietary chemical constituents required in macroscopic gram-scale quantities that furnish exogenous substrates for cellular oxidative bioenergetics and serve as structural biopolymers for tissue synthesis and physiological homeostatic maintenance.\", \"surrounding_context\": \"They contrast with micronutrients like vitamins and trace minerals, which operate in microgram to milligram quantities as metabolic cofactors.\", \"retrieved_evidence\": [\"Page 50: 'Macronutrients (carbohydrates, fats, and proteins) are nutrients needed in large amounts to supply calories and build body structures.'\"], \"student_prompt\": \"Can you explain what macronutrients are in simple language based on this text?\", \"faithful_paraphrase\": \"This passage explains that macronutrients are the primary nutrients our bodies need in large amounts every day: carbohydrates, proteins, and fats. They provide the actual calories (energy) our cells burn to stay alive, as well as the raw physical building blocks our bodies use to grow muscles, repair tissues, and maintain organs.\"}, \"conflict_handling\": {\"document_title\": \"Sports Nutrition Guidelines\", \"page\": 82, \"section\": \"Sedentary RDA vs Athletic Protein Recommendations\", \"selected_text\": \"Government public health agencies establish the general adult protein RDA at 0.8 g/kg/day to prevent clinical nitrogen deficiency.\", \"surrounding_context\": \"The American College of Sports Medicine (ACSM) and International Society of Sports Nutrition (ISSN) recommend 1.4 to 2.0 g/kg/day for resistance-trained athletes.\", \"retrieved_evidence\": [\"Public Health Guideline (RDA): 0.8 g/kg/day (Designed for sedentary adults to prevent deficiency; 56 g for a 70 kg person).\", \"Sports Medicine Guideline (ISSN/ACSM): 1.4 - 2.0 g/kg/day (Designed for athletes to optimize muscle protein synthesis and recovery; 98 - 140 g for a 70 kg athlete).\"], \"student_prompt\": \"Why does the standard dietary guideline say adults only need 56 grams of protein, but my sports medicine book says I need 120 grams?\", \"resolution_explanation\": \"These two recommendations target completely different physiological goals. The standard public health RDA of 0.8 g/kg (56 g for a 70 kg person) is a baseline minimum designed to prevent nutritional deficiency in ordinary sedentary individuals. Sports science guidelines recommend 1.4 to 2.0 g/kg (98 to 140 g for that same person) specifically for active or resistance-training athletes who need additional amino acids to repair exercise-induced muscle damage and build new muscle tissue.\"}}}, \"nutrition_food_science::Glycemic Index\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Glycemic Index\", \"explanation\": \"a numerical scale (0\u2013100) that ranks carbohydrate-containing foods by how quickly they raise blood sugar levels after eating, with glucose set at 100\", \"reason\": \"it helps people with diabetes manage blood sugar, and guides food choices for sustained energy and weight management\", \"concrete_examples\": [\"White bread has a high GI (~75), causing rapid blood sugar spikes, while whole-grain bread has a lower GI (~50).\", \"An apple (GI ~36) releases sugar slowly, providing sustained energy, unlike apple juice (GI ~41) which is faster.\", \"Athletes may choose high-GI foods after exercise for quick recovery, but low-GI foods before exercise for sustained energy.\"], \"numerical_examples\": [\"GI of white rice: ~73 (high). GI of brown rice: ~50 (low-medium). A diabetic choosing brown rice would experience a slower, lower blood sugar peak.\", \"Glycemic load = (GI \u00d7 grams of carbs per serving) / 100. For a slice of white bread (GI 75, 15g carbs): GL = 75\u00d715/100 = 11.25.\", \"A meal with GL < 10 is low glycemic load, 10-20 is medium, >20 is high.\"], \"misconceptions\": [[\"All sugar causes the same blood sugar spike\", \"Different forms of sugar and different foods containing sugar raise blood sugar at very different rates. Fructose (fruit sugar) has a much lower GI (~20) than glucose (100). The food matrix \u2014 fiber, fat, protein content \u2014 significantly slows sugar absorption.\"]], \"analogies\": [\"The glycemic index is like a speed limit for blood sugar \u2014 high-GI foods rush sugar into the bloodstream like a highway, while low-GI foods release it slowly like a winding country road.\"], \"prerequisites\": [\"basic biology\", \"carbohydrate chemistry\"], \"formulas\": [\"Glycemic Load = (GI \u00d7 carbs per serving in grams) / 100\"], \"document_evidence\": [\"The text explains: 'The glycemic index measures how quickly a food raises blood glucose compared to pure glucose.'\", \"Table 3.2 lists GI values for common foods including white bread (75), apple (36), and lentils (32).\"], \"practice_problems\": [\"Compare the glycemic load of a banana (GI 51, 27g carbs) versus a chocolate bar (GI 44, 30g carbs). Which has a higher glycemic load?\", \"Why might a low-GI diet be beneficial for someone with Type 2 diabetes?\"], \"hints\": [\"GI measures how FAST blood sugar rises. Glycemic LOAD also considers HOW MUCH carb you eat.\", \"Fiber, fat, and protein in a meal slow down sugar absorption, lowering the effective GI.\"], \"follow_up_questions\": [\"How does cooking method affect a food's glycemic index?\", \"What is the difference between glycemic index and glycemic load, and why does it matter?\"], \"diagnostic_questions\": [\"If a food has a high GI but you eat only a tiny portion, will your blood sugar spike? Explain.\", \"Why do whole grains tend to have a lower GI than refined grains?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The Glycemic Index (GI) and Glycemic Load (GL) are the exact same metric and provide identical values for all foods.\", \"error_reason\": \"Glycemic Index measures the quality/speed of carbohydrate absorption (compared to glucose = 100) based on an equal 50g carb portion; Glycemic Load factors in the actual quantity of carbohydrates per typical serving: GL = (GI * Carb grams per serving) / 100.\", \"correct_claim\": \"Glycemic Index (GI) measures how rapidly a carbohydrate raises blood glucose, whereas Glycemic Load (GL) accounts for both the rate and the actual amount of carbohydrate in a realistic serving size.\", \"understanding_probe\": \"Why does watermelon have a high Glycemic Index (GI = 72) but a very low Glycemic Load (GL = 5)?\", \"expected_answer\": \"Because the carbohydrates in watermelon digest rapidly (high GI), but watermelon is mostly water and contains very few total carbohydrate grams per serving, resulting in a low total glycemic impact (low GL).\"}, {\"prior_erroneous_claim\": \"All sweet-tasting fruits have a high Glycemic Index above 70.\", \"error_reason\": \"Many sweet fruits contain high proportions of fructose (which has a very low GI of ~19 because it is metabolized by the liver) and soluble dietary fiber, giving fruits like apples (GI ~36) and cherries (GI ~22) low glycemic indexes.\", \"correct_claim\": \"Sweetness does not equate to a high GI. Many sweet fruits contain fructose and dietary fiber, resulting in low glycemic index scores (e.g., apples GI ~36, cherries GI ~22).\", \"understanding_probe\": \"Why don't sweet fruits like apples and cherries spike blood sugar as fast as white bread?\", \"expected_answer\": \"Because they contain fructose, which is absorbed and metabolized slowly in the liver, and soluble fiber, which slows down gastric emptying and enzymatic sugar absorption.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Clinical Nutrition and Carbohydrate Metabolism\", \"page\": 105, \"section\": \"Glycemic Load Formulation and Classification\", \"selected_text\": \"A standard serving of baked potato contains 30.0 g of available carbohydrates with a Glycemic Index of GI = 85.0. In contrast, a typical serving of cooked lentils contains 20.0 g of carbohydrates with a Glycemic Index of GI = 30.0.\", \"surrounding_context\": \"Section 3.1 calculates the exact Glycemic Load for both servings using GL = (GI * Available Carbs in grams) / 100.\", \"retrieved_evidence\": [\"Formula: Glycemic Load = (GI * Carbohydrate grams) / 100.\", \"Baked potato GL calculation: GL = (85.0 * 30.0) / 100 = 2,550 / 100 = 25.5 (High GL, threshold > 20).\", \"Cooked lentils GL calculation: GL = (30.0 * 20.0) / 100 = 600 / 100 = 6.0 (Low GL, threshold < 10).\"], \"student_prompt\": \"What are the exact Glycemic Load values calculated for the baked potato and lentils in Section 3.1?\", \"target_response\": \"Following the calculation explicitly provided in Section 3.1: For the baked potato, GL = (85.0 * 30.0) / 100 = 25.5, which falls into the high glycemic load category (above 20). For the lentils, GL = (30.0 * 20.0) / 100 = 6.0, which falls into the low glycemic load category (below 10). The course text directly establishes the potato GL at 25.5 and the lentils GL at 6.0.\", \"calculated_result\": \"Baked Potato GL = 25.5, Lentils GL = 6.0\"}, \"pattern_b_derive\": {\"document_title\": \"Dietary Management of Diabetes\", \"page\": 112, \"section\": \"Composite Meal Glycemic Index Calculation\", \"selected_text\": \"When a mixed meal contains multiple carbohydrate sources, the composite meal GI is the weighted average of the individual food GIs, weighted by each food's proportion of total meal carbohydrate.\", \"surrounding_context\": \"Calculate the composite GI for a meal containing 40 g of carbohydrate from white rice (GI = 70) and 20 g of carbohydrate from steamed broccoli (GI = 15).\", \"retrieved_evidence\": [\"Weighted Formula: Composite GI = sum(GI_i * Carbs_i) / Total Carbs\", \"Meal data: White rice: 40 g carbs, GI = 70. Broccoli: 20 g carbs, GI = 15. Total carbohydrate = 40 + 20 = 60 g.\"], \"student_prompt\": \"How do we derive the composite Glycemic Index of this mixed meal using the weighted average formula?\", \"target_response\": \"To derive the composite Glycemic Index: First calculate the weighted contribution of each carbohydrate source: Rice contribution = 70 * 40 g = 2,800. Broccoli contribution = 15 * 20 g = 300. Sum the weighted contributions: 2,800 + 300 = 3,100. Finally, divide by total meal carbohydrates (60 g): Composite GI = 3,100 / 60 = 51.67, or approximately 52. The composite glycemic index of the mixed meal is approximately 52, placing it in the low GI tier (\u2264 55).\", \"formula\": \"Composite GI = [(70 * 40) + (15 * 20)] / 60 = 51.67\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale spot price of raw sugarcane per metric ton at the port of Santos, Brazil\", \"actual_topic\": \"glycemic index testing protocols, blood glucose curves, and insulin response dynamics\", \"authoritative_source\": \"the Brazilian Secretariat of Foreign Trade (SECEX) export commodity pricing releases\", \"document_title\": \"Carbohydrates and Glycemic Response\", \"page\": 122, \"section\": \"Standardized Testing Protocol\", \"selected_text\": \"The international standard protocol for GI testing requires healthy fasted subjects to ingest a portion containing 50 g of available carbohydrate.\", \"surrounding_context\": \"Blood glucose is measured over a two-hour postprandial window to compute the incremental area under the curve (iAUC).\", \"retrieved_evidence\": [\"Section 4.1: ISO 26642:2010 food product glycemic index determination standard.\"], \"student_prompt\": \"According to this chapter, what was the export price of raw sugarcane per ton at Santos?\"}, {\"unmentioned_term\": \"the retail price of the Abbott FreeStyle Libre 3 continuous glucose monitor sensor\", \"actual_topic\": \"factors influencing glycemic index including amylose-to-amylopectin ratio, food processing, and acidity\", \"authoritative_source\": \"pharmacy retail pricing databases or Abbott Diabetes Care commercial product sheets\", \"document_title\": \"Carbohydrates and Glycemic Response\", \"page\": 128, \"section\": \"Starch Structure and Digestibility\", \"selected_text\": \"High amylose starches resist enzymatic amylase cleavage compared to branched amylopectin, resulting in lower glycemic responses.\", \"surrounding_context\": \"Retrogradation of cooked and cooled starches creates resistant starch type 3, substantially depressing the GI.\", \"retrieved_evidence\": [\"Table 4.3: Comparison of amylose percentages and glycemic indices in long-grain versus short-grain rice.\"], \"student_prompt\": \"What does the reading cite as the retail cost of a FreeStyle Libre 3 CGM sensor?\"}], \"grounded_paraphrase\": {\"document_title\": \"Applied Nutritional Science\", \"page\": 100, \"section\": \"The Glycemic Index Construct\", \"selected_text\": \"The Glycemic Index formalizes a physiological ranking methodology that benchmarks the postprandial blood glucose excursions elicited by a fixed 50-gram available carbohydrate bolus of a test food relative to an equicarbohydrate reference standard of pure D-glucose.\", \"surrounding_context\": \"This standardized index reflects intrinsic enzymatic hydrolysis velocity and gastrointestinal transit dynamics.\", \"retrieved_evidence\": [\"Page 100: 'The Glycemic Index measures how quickly 50 grams of carbs from a food raises blood sugar compared to 50 grams of pure glucose.'\"], \"student_prompt\": \"Can you explain what the Glycemic Index is based on this text in plain words?\", \"faithful_paraphrase\": \"This passage explains that the Glycemic Index is a standardized scale that rates carbohydrate foods based on how fast they raise your blood sugar. It tests a serving size containing exactly 50 grams of digestible carbs and compares how quickly your body absorbs that sugar compared to drinking 50 grams of pure glucose, which is assigned a baseline score of 100.\"}, \"conflict_handling\": {\"document_title\": \"Carbohydrate Quality Controversies\", \"page\": 135, \"section\": \"Bread vs Table Sugar Glycemic Paradox\", \"selected_text\": \"Many people assume pure sucrose (table sugar) causes the fastest possible blood sugar spike, yet white bread has a higher Glycemic Index (GI \u2248 70-75) than table sugar (GI \u2248 65).\", \"surrounding_context\": \"This occurs because table sugar is a disaccharide of 50% glucose and 50% fructose; fructose must be processed by the liver and does not directly raise immediate blood glucose.\", \"retrieved_evidence\": [\"White Bread GI: ~70-75 (Made of pure starch chains of 100% glucose, rapidly hydrolyzed by amylase).\", \"Table Sugar (Sucrose) GI: ~65 (Composed of 50% glucose + 50% fructose; fructose has a GI of only 19).\"], \"student_prompt\": \"Why does plain white bread have a higher glycemic index than sweet table sugar? That seems completely backwards.\", \"resolution_explanation\": \"This seems counterintuitive, but it comes down to the types of sugar molecules involved. White bread is made of starch, which consists entirely of long chains of pure glucose that digestive enzymes break down almost instantly into blood glucose. Table sugar (sucrose) is half glucose and half fructose. While the glucose half enters the bloodstream quickly, the fructose half must travel to the liver for conversion, so it does not spike blood glucose immediately. Because half of table sugar is slow-metabolizing fructose, white bread actually spikes blood sugar faster than pure table sugar.\"}}}, \"nutrition_food_science::Protein Synthesis\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Protein Synthesis\", \"explanation\": \"the cellular process by which the information in DNA is used to build proteins through transcription (DNA \u2192 mRNA) and translation (mRNA \u2192 protein at ribosomes)\", \"reason\": \"proteins carry out nearly all functions in the body \u2014 from enzymes to hormones to antibodies \u2014 making protein synthesis fundamental to life\", \"concrete_examples\": [\"Your body synthesizes hemoglobin protein in bone marrow cells to carry oxygen in red blood cells.\", \"After exercise, muscle cells ramp up protein synthesis to repair and grow muscle fibers using amino acids from dietary protein.\", \"Insulin is a protein hormone synthesized by pancreatic beta cells from the INS gene.\"], \"numerical_examples\": [\"A ribosome translates mRNA at about 6 amino acids per second in eukaryotes.\", \"The human body has about 20,000 protein-coding genes, each capable of producing multiple protein variants through alternative splicing.\", \"A codon (3 nucleotides) codes for 1 amino acid. A 300-nucleotide mRNA produces a 100-amino-acid protein.\"], \"misconceptions\": [[\"Eating protein directly becomes muscle in your body\", \"Dietary protein is first digested into individual amino acids, which are absorbed into the bloodstream. The body then reassembles these amino acids into its own proteins as needed, using instructions from DNA. You don't absorb chicken muscle and paste it onto your biceps.\"]], \"analogies\": [\"Protein synthesis is like a factory assembly line \u2014 DNA is the master blueprint locked in the office (nucleus), mRNA is a photocopy carried to the factory floor (ribosome), and tRNA workers bring the right parts (amino acids) to build the product (protein).\"], \"prerequisites\": [\"DNA structure\", \"basic cell biology\"], \"formulas\": [\"DNA \u2192 mRNA (transcription) \u2192 Protein (translation)\", \"3 nucleotides = 1 codon = 1 amino acid\"], \"document_evidence\": [\"The text explains: 'Transcription occurs in the nucleus, where RNA polymerase synthesizes mRNA from a DNA template. Translation occurs at ribosomes, where tRNA delivers amino acids matching the mRNA codons.'\", \"The codon table (Figure 5.4) maps each 3-letter codon to its corresponding amino acid or stop signal.\"], \"practice_problems\": [\"Given the DNA template strand 3'-TACGGA-5', write the mRNA sequence and the resulting amino acid sequence.\", \"Explain why a mutation in the DNA sequence could result in a non-functional protein.\"], \"hints\": [\"mRNA is complementary to the template DNA strand (A\u2192U, T\u2192A, G\u2192C, C\u2192G).\", \"Not all DNA mutations change the protein \u2014 the genetic code has redundancy (multiple codons for the same amino acid).\"], \"follow_up_questions\": [\"What is the role of tRNA in translation?\", \"How does alternative splicing increase protein diversity?\"], \"diagnostic_questions\": [\"Where in the cell does transcription occur? Where does translation occur?\", \"What determines the order of amino acids in a protein?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Translation occurs inside the nucleus where the ribosome reads the DNA strand directly.\", \"error_reason\": \"Translation occurs exclusively in the cytoplasm (at ribosomes on the rough ER or free-floating); DNA never leaves the nucleus; transcription produces mRNA inside the nucleus, which then exports to the cytoplasm for translation.\", \"correct_claim\": \"Translation occurs in the cytoplasm at ribosomes, not in the nucleus. Transcription makes mRNA inside the nucleus, which is then exported to the cytoplasm for the ribosome to read.\", \"understanding_probe\": \"Where in a eukaryotic cell do transcription and translation take place?\", \"expected_answer\": \"Transcription occurs in the nucleus (copying DNA to mRNA), while translation occurs in the cytoplasm (ribosomes reading mRNA to make proteins).\"}, {\"prior_erroneous_claim\": \"Each amino acid in a protein is coded for by a single nucleotide base in the mRNA chain.\", \"error_reason\": \"Each amino acid is coded for by a triplet codon of three consecutive nucleotide bases; one base could only code for 4 amino acids, whereas triplet codons provide 4\u00b3 = 64 combinations.\", \"correct_claim\": \"The genetic code is a triplet code: every amino acid is specified by a 3-nucleotide codon on the mRNA (e.g., AUG codes for methionine).\", \"understanding_probe\": \"Why must the genetic code use triplets of nucleotides (codons) rather than single bases or pairs to code for amino acids?\", \"expected_answer\": \"Because there are 20 different amino acids; 1 base only gives 4 codes, 2 bases give 16 (4\u00b2), but 3 bases provide 64 (4\u00b3) combinations, enough to code for all 20 amino acids.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Molecular Biology and Protein Translation\", \"page\": 145, \"section\": \"Energetics and Nucleotide Coding of Translation\", \"selected_text\": \"A mature eukaryotic mRNA transcript contains an open reading frame (ORF) encoding a polypeptide chain of 250 amino acids, including the initial methionine.\", \"surrounding_context\": \"Section 2.1 computes the required coding nucleotides, total codons, and high-energy phosphate bonds (ATP and GTP) consumed during translation.\", \"retrieved_evidence\": [\"Codon stoichiometry: 250 amino acids require 250 sense codons + 1 stop codon = 251 codons.\", \"Nucleotide count: 251 codons * 3 nucleotides/codon = 753 coding nucleotides (excluding 5' cap and poly-A tail).\", \"Energetic cost of peptide bond formation: 4 high-energy phosphates per amino acid (2 ATP for tRNA aminoacylation + 1 GTP for elongation factor Tu + 1 GTP for translocation).\", \"Total energy consumed = 250 amino acids * 4 high-energy bonds = 1,000 ATP/GTP equivalents.\"], \"student_prompt\": \"What are the exact number of coding nucleotides and total high-energy phosphate bonds consumed calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The open reading frame requires 250 amino acid codons plus 1 stop codon = 251 codons. Multiplying by 3 yields 753 coding nucleotides. Synthesizing each peptide link requires 4 high-energy phosphate equivalents (2 from ATP during tRNA charging, 1 from GTP during codon-anticodon binding, and 1 from GTP during ribosome translocation). For a 250-amino acid protein, total energy consumed is 250 * 4 = 1,000 high-energy phosphate equivalents. The text directly establishes 753 coding nucleotides and 1,000 ATP/GTP equivalents.\", \"calculated_result\": \"Coding nucleotides = 753, Total energy consumed = 1,000 ATP/GTP\"}, \"pattern_b_derive\": {\"document_title\": \"The Genetic Code: Degeneracy and Wobble Hypothesis\", \"page\": 152, \"section\": \"Deriving Combinatorial Coding Capacities\", \"selected_text\": \"With four distinct RNA ribonucleotides (Adenine, Uracil, Cytosine, Guanine), codons are arrangements of length k.\", \"surrounding_context\": \"Derive why a triplet code (k = 3) is the minimal mathematical length necessary to encode the 20 standard proteinogenic amino acids.\", \"retrieved_evidence\": [\"Combinatorial formula: Total unique codons = 4^k, where k is the number of bases per codon.\", \"Biological requirement: Must encode at least 20 unique amino acids.\"], \"student_prompt\": \"How do we derive mathematically why the genetic code uses triplets (k = 3) rather than singlets or doublets?\", \"target_response\": \"To derive the minimal codon length: Evaluate the number of unique combinations for increasing word lengths with 4 bases. For singlets (k = 1): 4\u00b9 = 4 unique codons, which is insufficient for 20 amino acids. For doublets (k = 2): 4\u00b2 = 16 unique codons, which is still fewer than the 20 required amino acids. For triplets (k = 3): 4\u00b3 = 64 unique codons. Since 64 > 20, a triplet code is the minimum integer length that provides enough unique codons to specify all 20 amino acids (leaving surplus codons for degeneracy and stop signals).\", \"formula\": \"4^1 = 4 < 20; 4^2 = 16 < 20; 4^3 = 64 > 20\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale price of recombinant human insulin per 10 mL vial on the Indian generic drug exchange\", \"actual_topic\": \"transcription, translation, tRNA charging, ribosomal subunits, and post-translational folding\", \"authoritative_source\": \"the National Pharmaceutical Pricing Authority (NPPA) of India official gazette price lists\", \"document_title\": \"Protein Synthesis and Translation\", \"page\": 162, \"section\": \"Chaperone-Assisted Protein Folding\", \"selected_text\": \"Molecular chaperones such as Hsp70 prevent nascent polypeptide misfolding and aggregation during translation.\", \"surrounding_context\": \"ATP-dependent conformational cycles assist proteins in reaching their thermodynamically stable tertiary structure.\", \"retrieved_evidence\": [\"Section 3.4: GroEL-GroES barrel complex folding mechanics.\"], \"student_prompt\": \"According to this text, what is the price in Indian rupees of a 10 mL vial of recombinant insulin?\"}, {\"unmentioned_term\": \"the total number of Cryo-EM microscopes operating in the state of California\", \"actual_topic\": \"ribosome architecture, rRNA catalytic peptidyl transferase activity, and antibiotic inhibition\", \"authoritative_source\": \"scientific structural biology research consortium facility inventories\", \"document_title\": \"Protein Synthesis and Translation\", \"page\": 168, \"section\": \"Antibiotic Mechanisms Targeting Bacterial Ribosomes\", \"selected_text\": \"Tetracyclines inhibit bacterial protein synthesis by blocking aminoacyl-tRNA attachment to the 30S ribosomal A-site.\", \"surrounding_context\": \"Chloramphenicol binds the 50S subunit, inhibiting peptidyl transferase activity.\", \"retrieved_evidence\": [\"Table 3.5: Clinical antibiotics categorized by targeted ribosomal subunit.\"], \"student_prompt\": \"What does this text state regarding the total number of Cryo-EM facilities in California?\"}], \"grounded_paraphrase\": {\"document_title\": \"Cellular Biochemistry\", \"page\": 140, \"section\": \"The Central Dogma Axiom\", \"selected_text\": \"The central dogma of molecular biology formalizes the directional fidelity of genetic information transfer, dictating that nucleic acid sequence paradigms are transcribed from DNA into transient mRNA intermediaries and irreversibly translated into functional polypeptide sequences.\", \"surrounding_context\": \"Once sequence information transfers into protein space, it cannot be reverse-translated back into polynucleotide code.\", \"retrieved_evidence\": [\"Page 140: 'The central dogma states that genetic information flows from DNA to RNA and then to protein, and protein information cannot flow back into nucleic acids.'\"], \"student_prompt\": \"Can you explain what the central dogma of molecular biology means in everyday words?\", \"faithful_paraphrase\": \"This passage explains the central rule of genetics: information flows in a one-way street from DNA to RNA to protein. Your master genetic blueprint in DNA is transcribed into a temporary messenger RNA copy, and the cell uses that RNA to assemble a finished protein. Once that protein is built, the information cannot flow backward from the protein to rewrite the DNA.\"}, \"conflict_handling\": {\"document_title\": \"Modern Molecular Genetics\", \"page\": 175, \"section\": \"Exceptions to the Central Dogma: Reverse Transcription and Prions\", \"selected_text\": \"The original 1958 Central Dogma stated that information flows unidirectionally from DNA -> RNA -> Protein without exception.\", \"surrounding_context\": \"Discovery of retroviral reverse transcriptase (RNA -> DNA) in 1970 and infectious prion proteins (protein conformational templating) expanded and modified the original strict formulation.\", \"retrieved_evidence\": [\"Original Central Dogma (1958): DNA -> RNA -> Protein (strictly unidirectional).\", \"Modern Revisions: Retroviruses like HIV use reverse transcriptase to copy RNA back into DNA; prions transmit structural information directly between proteins without nucleic acids.\"], \"student_prompt\": \"My introductory biology book says genetic information only flows from DNA to RNA, but an immunology article says retroviruses copy RNA into DNA. Who is right?\", \"resolution_explanation\": \"Both are correct in context. The classical 'Central Dogma' accurately describes how normal animal and plant cells make proteins: DNA is transcribed into RNA, which is translated into protein. However, biology has discovered fascinating exceptions. Retroviruses (like HIV) carry the enzyme reverse transcriptase, which allows them to copy their viral RNA backward into host DNA. This modified our understanding: information can flow backward from RNA to DNA, but it still cannot flow backward from protein to nucleic acid.\"}}}, \"nutrition_food_science::Vitamin Absorption\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Vitamin Absorption\", \"explanation\": \"the process by which vitamins are taken up from digested food in the small intestine and transported to cells, differing significantly between fat-soluble vitamins (A, D, E, K) and water-soluble vitamins (B-complex, C)\", \"reason\": \"proper vitamin absorption is essential for health, and understanding it explains why some vitamins require dietary fat, why deficiencies occur, and how supplements should be taken\", \"concrete_examples\": [\"Taking vitamin D with a meal containing fat (like avocado toast) increases absorption because vitamin D is fat-soluble.\", \"Excess water-soluble vitamins (like vitamin C) are excreted in urine, which is why you need them daily.\", \"People who have had gastric bypass surgery often have vitamin absorption problems because the absorptive surface is reduced.\"], \"numerical_examples\": [\"The recommended daily intake of vitamin D is 600\u2013800 IU. Absorption increases from ~10% to ~30% when taken with 15g of dietary fat.\", \"Fat-soluble vitamins can accumulate in liver and fat tissue. Vitamin A toxicity can occur above 10,000 IU/day over prolonged periods.\", \"Water-soluble vitamin C has a half-life of about 10\u201320 days in the body, requiring regular dietary intake.\"], \"misconceptions\": [[\"Taking more vitamins is always better for your health\", \"Fat-soluble vitamins (A, D, E, K) can accumulate to toxic levels because they are stored in body fat and liver. Excess vitamin A causes liver damage; excess vitamin D causes calcium buildup. Water-soluble vitamins are generally safer in excess but still have upper limits.\"]], \"analogies\": [\"Vitamin absorption is like shipping goods \u2014 fat-soluble vitamins are like oil paints that need a fat 'container' to travel through the gut, while water-soluble vitamins dissolve freely in the body's water and any excess gets flushed away.\"], \"prerequisites\": [\"basic biology\", \"digestive system basics\"], \"formulas\": [\"Fat-soluble: A, D, E, K (stored in fat)\", \"Water-soluble: B-complex, C (excreted in urine)\"], \"document_evidence\": [\"The text states: 'Fat-soluble vitamins require bile salts and dietary lipids for absorption in the small intestine.'\", \"Table 4.3 compares the absorption mechanisms, storage sites, and toxicity risks of fat-soluble vs. water-soluble vitamins.\"], \"practice_problems\": [\"Explain why a person on a very low-fat diet might develop vitamin D deficiency even with adequate sun exposure.\", \"Which vitamins pose a greater toxicity risk if over-consumed: fat-soluble or water-soluble? Explain why.\"], \"hints\": [\"'ADEK' are fat-soluble. Think: 'A DEK of cards needs fat.'\", \"Water-soluble vitamins need daily intake because they aren't stored long-term.\"], \"follow_up_questions\": [\"How does gut health affect vitamin absorption?\", \"Why might elderly people have different vitamin absorption than younger adults?\"], \"diagnostic_questions\": [\"If you take a vitamin D supplement on an empty stomach, will you absorb as much as with a meal? Why?\", \"Why can't you 'stock up' on vitamin C by taking a large dose once a week?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Fat-soluble vitamins (A, D, E, K) can be absorbed efficiently in the digestive tract even on a diet with zero dietary fat.\", \"error_reason\": \"Fat-soluble vitamins require dietary lipids and bile salts to form mixed micelles in the small intestine for enterocyte absorption; without fat, their absorption plummets to near zero.\", \"correct_claim\": \"Fat-soluble vitamins (A, D, E, K) depend on the presence of dietary fat and bile salts to form micelles for intestinal absorption; consuming them without fat severely impairs absorption.\", \"understanding_probe\": \"Why is it recommended to consume a salad with olive oil or dressing rather than eating completely fat-free greens when absorbing fat-soluble vitamins?\", \"expected_answer\": \"Because the oil provides dietary fat needed to form micelles with bile salts, allowing vitamins A, D, E, and K to be absorbed into intestinal cells.\"}, {\"prior_erroneous_claim\": \"Water-soluble vitamins are stored in massive reserves in adipose tissue for decades.\", \"error_reason\": \"Water-soluble vitamins (B-complex, C) cannot be stored in adipose tissue; with the exception of B12 stored in the liver, excess water-soluble vitamins are excreted in urine within days.\", \"correct_claim\": \"Water-soluble vitamins (B-vitamins and vitamin C) are not stored in body fat; excess amounts are filtered and excreted in urine, so they must be consumed regularly.\", \"understanding_probe\": \"What happens when someone consumes 1,000 mg of water-soluble vitamin C, far exceeding their daily need?\", \"expected_answer\": \"The body absorbs what it needs and excretes the excess water-soluble vitamin C in the urine, rather than storing it in fat.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Nutritional Biochemistry: Micronutrient Bioavailability\", \"page\": 195, \"section\": \"Beta-Carotene to Retinol Equivalent Conversions\", \"selected_text\": \"The Institute of Medicine defines Retinol Activity Equivalents (RAE) to account for the lower absorption and conversion efficiency of provitamin A carotenoids. The conversion standard establishes that 12.0 \u03bcg of dietary beta-carotene from food provides 1.0 \u03bcg of active retinol (1 RAE).\", \"surrounding_context\": \"Section 2.1 computes the active vitamin A yielded from a carrot serving containing 9,600 \u03bcg of beta-carotene.\", \"retrieved_evidence\": [\"Conversion factor: 12.0 \u03bcg food beta-carotene = 1.0 \u03bcg Retinol Activity Equivalent (RAE).\", \"Beta-carotene ingested = 9,600 \u03bcg.\", \"Step-by-step arithmetic from text: Active Vitamin A (RAE) = 9,600 \u03bcg / 12.0 = 800.0 \u03bcg RAE.\", \"Comparison to adult male RDA (900 \u03bcg RAE): 800.0 / 900.0 = 0.8889 (88.89% of daily requirement).\"], \"student_prompt\": \"What are the exact Retinol Activity Equivalents (RAE) in micrograms and the percentage of the adult male RDA provided in Section 2.1?\", \"target_response\": \"Following the explicit conversion in Section 2.1: Dividing 9,600 \u03bcg of dietary beta-carotene by the 12:1 conversion factor yields 9,600 / 12.0 = 800.0 \u03bcg of Retinol Activity Equivalents (RAE). Compared to the adult male RDA of 900 \u03bcg RAE, this single serving delivers 800 / 900 = 88.89% of the daily vitamin A requirement. The text directly establishes the yield at 800.0 \u03bcg RAE and 88.89% of the RDA.\", \"calculated_result\": \"Active Vitamin A = 800.0 \u03bcg RAE; % of RDA = 88.89%\"}, \"pattern_b_derive\": {\"document_title\": \"Gastrointestinal Physiology: Vitamin B12 Absorption\", \"page\": 202, \"section\": \"Intrinsic Factor Receptors and Saturation Kinetics\", \"selected_text\": \"Vitamin B12 (cobalamin) absorption in the terminal ileum relies on intrinsic factor (IF) synthesized by gastric parietal cells.\", \"surrounding_context\": \"Ileal cubilin receptors are saturable, limiting active physiological absorption to approximately 1.5 to 2.0 \u03bcg per meal, with passive diffusion accounting for only 1.0% of uncomplexed cobalamin.\", \"retrieved_evidence\": [\"Absorption Model: Total B12 Absorbed = Active Ileal Max (1.5 \u03bcg) + [Passive Diffusion Rate (0.01) * Remaining Uncomplexed Dose].\", \"Dose scenario: A patient with pernicious anemia lacking intrinsic factor takes a massive oral supplement of 1,000.0 \u03bcg cobalamin.\"], \"student_prompt\": \"How do we derive the total vitamin B12 absorbed from a 1,000.0 \u03bcg oral supplement in a patient lacking intrinsic factor?\", \"target_response\": \"To derive the absorbed B12 in the absence of intrinsic factor: Because the patient lacks intrinsic factor, receptor-mediated active ileal absorption is 0 \u03bcg. The entire dose relies solely on passive paracellular diffusion across the intestinal epithelium, which occurs at a flat 1.0% efficiency (0.01). Multiplying the 1,000.0 \u03bcg oral dose by 0.01: Total Absorbed = 1,000.0 \u03bcg * 0.01 = 10.0 \u03bcg. This passive diffusion yields 10.0 \u03bcg, which successfully covers the daily adult requirement of 2.4 \u03bcg despite zero intrinsic factor.\", \"formula\": \"Absorbed = 0 + (1,000 * 0.01) = 10.0 \u03bcg\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact gross box office receipts of the film Dune: Part Two in United States theaters\", \"actual_topic\": \"mechanisms of fat-soluble and water-soluble vitamin absorption, intrinsic factor, and micellar packaging\", \"authoritative_source\": \"Box Office Mojo or the National Association of Theatre Owners official box office databases\", \"document_title\": \"Vitamins in Human Physiology\", \"page\": 210, \"section\": \"Vitamin D Hydroxylation Pathways\", \"selected_text\": \"Cholecalciferol undergoes 25-hydroxylation in the liver to form 25-hydroxyvitamin D [25(OH)D], followed by 1-alpha-hydroxylation in the kidneys to produce calcitriol [1,25(OH)2D].\", \"surrounding_context\": \"Calcitriol upregulates intestinal calbindin protein expression to stimulate active calcium absorption.\", \"retrieved_evidence\": [\"Figure 3.2: Endocrine regulation of renal 1-alpha-hydroxylase by parathyroid hormone.\"], \"student_prompt\": \"According to this text, what were the total domestic box office earnings of Dune: Part Two?\"}, {\"unmentioned_term\": \"the exact wholesale price of industrial ascorbic acid per drum on the Shanghai Chemical Exchange\", \"actual_topic\": \"sodium-dependent vitamin C transporters (SVCT1 and SVCT2) and intestinal enterocyte uptake\", \"authoritative_source\": \"the Shanghai Chemical Exchange chemical commodity export pricing lists\", \"document_title\": \"Vitamins in Human Physiology\", \"page\": 215, \"section\": \"Vitamin C Transport and Tissue Distribution\", \"selected_text\": \"Ascorbic acid is transported across intestinal enterocyte brush border membranes via sodium-dependent vitamin C transporter 1 (SVCT1).\", \"surrounding_context\": \"At high oral doses above 1,000 mg, SVCT1 transporters saturate, dropping absorption efficiency to under 50%.\", \"retrieved_evidence\": [\"Section 3.5: Dose-dependency curve of human intestinal ascorbic acid absorption.\"], \"student_prompt\": \"What does the reading cite as the wholesale price of ascorbic acid drums in Shanghai?\"}], \"grounded_paraphrase\": {\"document_title\": \"Gastrointestinal Nutritional Physiology\", \"page\": 190, \"section\": \"Micellar Solubilization of Fat-Soluble Micronutrients\", \"selected_text\": \"Intestinal assimilation of lipophilic vitamins mandates their incorporation into mixed polymolecular bile salt-phospholipid micelles within the duodenal lumen, facilitating their diffusion across the unstirred aqueous mucosal boundary layer for passive and protein-mediated enterocyte internalization.\", \"surrounding_context\": \"Biliary duct obstruction or pancreatic lipase insufficiency severely compromises fat-soluble vitamin uptake.\", \"retrieved_evidence\": [\"Page 190: 'Fat-soluble vitamins must be packaged inside bile salt micelles so they can pass through the watery layer lining the intestine and enter gut cells.'\"], \"student_prompt\": \"Can you explain why bile salts are necessary for absorbing fat-soluble vitamins in simple terms?\", \"faithful_paraphrase\": \"This passage explains that because vitamins A, D, E, and K are oily and cannot dissolve in water, they cannot cross the watery fluid lining the intestinal wall on their own. The body uses bile salts from the liver like natural soap bubbles (called micelles) to wrap up the vitamin droplets, allowing them to dissolve in the watery intestinal fluid and safely enter the gut cells.\"}, \"conflict_handling\": {\"document_title\": \"Micronutrient Supplementation Guidelines\", \"page\": 225, \"section\": \"Toxicity Risks: Fat-Soluble vs Water-Soluble Vitamins\", \"selected_text\": \"Public health campaigns emphasize that consuming excess water-soluble vitamins (like vitamin C or B2) rarely causes serious toxicity because excess amounts are readily excreted in urine.\", \"surrounding_context\": \"However, high megadoses of vitamin B6 (pyridoxine) can cause severe sensory peripheral neuropathy, contradicting the common myth that water-soluble vitamins are completely harmless in unlimited doses.\", \"retrieved_evidence\": [\"General Rule: Fat-soluble vitamins (especially A and D) accumulate in adipose and liver tissues, carrying high toxicity risks when overconsumed.\", \"Clinical Exception: While most water-soluble vitamins are excreted safely, chronic megadoses of water-soluble vitamin B6 (>500 mg/day) cause disabling neurotoxic sensory nerve damage.\"], \"student_prompt\": \"My teacher said you can take as many water-soluble vitamins as you want because excess washes out in urine, but a medical article warned against taking too much vitamin B6. Why?\", \"resolution_explanation\": \"As a broad general rule, your teacher is right that water-soluble vitamins are generally much safer than fat-soluble vitamins because your kidneys excrete excess amounts in urine rather than storing them in body fat. However, this rule is not absolute. Chronic megadoses of certain water-soluble vitamins\u2014most notably vitamin B6 (pyridoxine)\u2014overwhelm metabolic pathways and cause real clinical toxicity, specifically severe sensory nerve damage (peripheral neuropathy). So while water-soluble vitamins don't build up in fat, massive megadoses can still be toxic.\"}}}, \"nutrition_food_science::Food Preservation\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Food Preservation\", \"explanation\": \"the methods used to prevent food spoilage caused by microorganisms, enzymes, and oxidation, thereby extending shelf life and maintaining safety\", \"reason\": \"it prevents foodborne illness, reduces food waste, and enables year-round access to seasonal foods\", \"concrete_examples\": [\"Refrigeration slows bacterial growth: milk lasts 1\u20132 weeks refrigerated but spoils in hours at room temperature.\", \"Canning involves heating food to kill bacteria and sealing it in airtight containers \u2014 canned vegetables can last 2\u20135 years.\", \"Salting and smoking fish draws out moisture and creates conditions hostile to bacteria, preserving fish for months.\"], \"numerical_examples\": [\"The 'danger zone' for bacterial growth is 40\u2013140\u00b0F (4\u201360\u00b0C). At 90\u00b0F, bacteria can double every 20 minutes.\", \"Pasteurization heats milk to 161\u00b0F (72\u00b0C) for 15 seconds, killing 99.999% of harmful bacteria.\", \"Water activity (aw) below 0.85 prevents most bacterial growth. Honey has aw ~0.6, explaining its long shelf life.\"], \"misconceptions\": [[\"Freezing food kills all bacteria\", \"Freezing does NOT kill bacteria \u2014 it puts them in a dormant state. Once food thaws, bacteria resume multiplying. That's why you should never refreeze thawed raw meat without cooking it first. Proper cooking (not freezing) is what kills most pathogens.\"]], \"analogies\": [\"Food preservation is like pressing 'pause' on the bacterial clock \u2014 refrigeration slows the clock, freezing stops it, but only cooking or sterilization actually destroys the bacteria.\"], \"prerequisites\": [\"basic biology\", \"microbiology basics\"], \"formulas\": [\"Bacterial doubling: N = N\u2080 \u00d7 2^(t/generation_time)\"], \"document_evidence\": [\"The text explains: 'The five main preservation methods are: temperature control, moisture reduction, chemical preservation, irradiation, and modified atmosphere packaging.'\", \"Table 6.2 lists minimum cooking temperatures for different food types to ensure pathogen destruction.\"], \"practice_problems\": [\"If bacteria double every 30 minutes at room temperature and you start with 1,000 bacteria, how many will there be after 4 hours?\", \"Explain why beef jerky lasts much longer than fresh beef without refrigeration.\"], \"hints\": [\"Bacteria need warmth, moisture, nutrients, and time to grow. Remove any one factor to preserve food.\", \"Water activity is key: reducing available water (drying, salting, adding sugar) inhibits microbial growth.\"], \"follow_up_questions\": [\"Why do some preserved foods still need refrigeration after opening?\", \"What is the difference between pasteurization and sterilization?\"], \"diagnostic_questions\": [\"If frozen chicken thaws on the counter for 6 hours, is it still safe? Why or why not?\", \"How does salt preserve food?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Food preservation techniques like commercial canning are designed to regulate human Body Mass Index (BMI).\", \"error_reason\": \"Food preservation methods (thermal processing, canning, drying, pickling) are food science techniques designed to inhibit spoilage microorganisms and inactivate food enzymes; they have zero connection to Body Mass Index or weight loss.\", \"correct_claim\": \"Food preservation techniques (such as canning, pasteurization, and drying) are methods designed to destroy pathogenic bacteria, inhibit microbial growth, and prevent food spoilage. They have nothing to do with Body Mass Index (BMI).\", \"understanding_probe\": \"What is the primary objective of food preservation techniques like canning and pasteurization?\", \"expected_answer\": \"To destroy or inhibit food spoilage microorganisms and pathogenic bacteria (like Clostridium botulinum) and inactivate degrading enzymes, extending shelf life and ensuring food safety.\"}, {\"prior_erroneous_claim\": \"Refrigeration at 4\u00b0C sterilizes food and kills all bacteria completely.\", \"error_reason\": \"Refrigeration is bacteriostatic, not bactericidal; it significantly slows down microbial metabolism and reproduction, but psychrotrophic bacteria (like Listeria monocytogenes) can still slowly multiply, and pathogens resume rapid growth once warmed.\", \"correct_claim\": \"Refrigeration (around 4\u00b0C) does not kill or sterilize bacteria; it only slows down bacterial reproduction (bacteriostatic). Psychrotrophic bacteria like Listeria can still slowly grow at refrigeration temperatures.\", \"understanding_probe\": \"Does putting raw chicken into a standard refrigerator kill the Salmonella bacteria present on it?\", \"expected_answer\": \"No, refrigeration only slows down bacterial growth; it does not kill the bacteria, which will multiply rapidly again if left at room temperature.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Food Microbiology and Thermal Processing\", \"page\": 240, \"section\": \"Thermal Death Time: D-Value and 12D Botulinum Cook\", \"selected_text\": \"Commercial canning of low-acid foods (pH > 4.6) mandates a '12D botulinum cook' to reduce Clostridium botulinum endospores by 12 logarithmic cycles. At 121.1\u00b0C (250\u00b0F), the decimal reduction time (D-value) for C. botulinum spores is D_121 = 0.21 minutes (12.6 seconds).\", \"surrounding_context\": \"Section 3.1 calculates the minimum thermal process time F0 required for commercial sterility.\", \"retrieved_evidence\": [\"Formula: Thermal Process Time F0 = 12 * D_121.\", \"D-value at 121.1\u00b0C = 0.21 minutes.\", \"Step-by-step arithmetic from text: F0 = 12 * 0.21 minutes = 2.52 minutes (151.2 seconds).\", \"Spore reduction verification: Starting from an initial load of 1.0 x 10^12 spores, surviving load = 1.0 x 10^(12 - 12) = 1.0 x 10^0 = 1 surviving spore (a 99.9999999999% reduction).\"], \"student_prompt\": \"What is the exact minimum thermal processing time F0 in minutes and seconds calculated in Section 3.1 for a 12D botulinum cook?\", \"target_response\": \"Following the explicit calculation in Section 3.1: The decimal reduction time D at 121.1\u00b0C is 0.21 minutes. A 12D reduction requires multiplying this D-value by 12: F0 = 12 * 0.21 minutes = 2.52 minutes (or 151.2 seconds). This thermal cook ensures a 12-decimal-log reduction in Clostridium botulinum endospores, achieving commercial sterility. The text directly establishes the minimum thermal time at 2.52 minutes (151.2 seconds).\", \"calculated_result\": \"F0 = 2.52 minutes = 151.2 seconds\"}, \"pattern_b_derive\": {\"document_title\": \"Water Activity and Food Stability\", \"page\": 248, \"section\": \"Deriving Microbial Growth Thresholds from Water Activity (aw)\", \"selected_text\": \"Water activity (aw = p / p0) measures the availability of unbound water for microbial metabolism. Most pathogenic bacteria require aw \u2265 0.91, while Staphylococcus aureus can tolerate aw down to 0.85, and osmophilic yeasts grow down to 0.60.\", \"surrounding_context\": \"Adding solutes like sucrose or sodium chloride lowers water activity according to Raoult's Law: aw = n_water / (n_water + n_solute).\", \"retrieved_evidence\": [\"Raoult's Law for Ideal Solutions: aw = n_water / (n_water + n_solute)\", \"Recipe data: 900 g of water (M = 18 g/mol -> n_water = 50.0 moles) and 342 g of sucrose (M = 342 g/mol -> n_sucrose = 1.0 mole).\"], \"student_prompt\": \"How do we derive the water activity aw of this sugar syrup and determine if standard pathogenic bacteria can grow in it?\", \"target_response\": \"To derive the water activity: Compute moles of water: 900 g / 18 g/mol = 50.0 moles. Compute moles of sucrose solute: 342 g / 342 g/mol = 1.0 mole. Substitute into Raoult's Law: aw = n_water / (n_water + n_solute) = 50.0 / (50.0 + 1.0) = 50.0 / 51.0 = 0.9804. Since standard pathogenic bacteria require aw \u2265 0.91, and this syrup has aw \u2248 0.98, standard foodborne pathogens can still grow; additional sugar or cooking is needed to lower aw below 0.91.\", \"formula\": \"aw = 50.0 / (50.0 + 1.0) = 0.980\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale auction price of bluefin tuna per kilogram at the Toyosu fish market in Tokyo\", \"actual_topic\": \"thermal canning, water activity, pasteurization, pickling, and chemical food preservatives\", \"authoritative_source\": \"the Tokyo Metropolitan Central Wholesale Market daily auction pricing bulletins\", \"document_title\": \"Principles of Food Preservation\", \"page\": 258, \"section\": \"Chemical Food Preservatives\", \"selected_text\": \"Sodium benzoate and potassium sorbate function as antimicrobial preservatives in acidic foods (pH < 4.5).\", \"surrounding_context\": \"The undissociated acid form penetrates microbial plasma membranes and disrupts cytoplasmic proton gradients.\", \"retrieved_evidence\": [\"Section 4.2: Henderson-Hasselbalch dissociation curves for benzoic and sorbic acids.\"], \"student_prompt\": \"According to this chapter, what was the average auction price per kilogram of bluefin tuna at Toyosu?\"}, {\"unmentioned_term\": \"the construction cost of a commercial blast freezer warehouse in Des Moines, Iowa\", \"actual_topic\": \"freeze-drying (lyophilization) and cryogenic freezing technology\", \"authoritative_source\": \"commercial industrial cold-storage engineering contractor construction estimates\", \"document_title\": \"Principles of Food Preservation\", \"page\": 264, \"section\": \"Freeze-Drying Mechanics\", \"selected_text\": \"Lyophilization sublimates ice directly into water vapor under reduced pressure below the triple point of water (0.01\u00b0C, 611 Pa).\", \"surrounding_context\": \"This preserves food cellular structure and nutrient content without thermal degradation.\", \"retrieved_evidence\": [\"Figure 4.4: Pressure-temperature phase diagram of water during lyophilization cycles.\"], \"student_prompt\": \"What does the text state regarding the construction cost of a commercial cold storage warehouse in Iowa?\"}], \"grounded_paraphrase\": {\"document_title\": \"Industrial Food Technology\", \"page\": 235, \"section\": \"The Commercial Sterility Axiom\", \"selected_text\": \"Commercial sterility in food thermal processing designates the complete thermal inactivation of pathogenic microorganisms capable of vegetative replication under customary non-refrigerated distribution and storage environments, rather than the absolute mathematical eradication of all quiescent hyper-thermophilic spores.\", \"surrounding_context\": \"Canned products may harbor harmless thermophilic obligates that cannot germinate at ambient shelf temperatures.\", \"retrieved_evidence\": [\"Page 235: 'Commercial sterility means all harmful and spoilage bacteria capable of growing at room temperature are destroyed, even if harmless heat-loving spores remain dormant.'\"], \"student_prompt\": \"Can you explain what 'commercial sterility' means in food preservation based on this text?\", \"faithful_paraphrase\": \"This passage explains that in commercial canning, 'commercial sterility' does not mean every single microscopic spore in the universe is killed. Instead, it means that all dangerous pathogens (like botulism) and all bacteria that could ever grow and spoil the food at normal room temperatures have been completely destroyed. Any harmless spores that might survive are completely unable to grow unless the can is heated to extreme temperatures.\"}, \"conflict_handling\": {\"document_title\": \"Food Processing Regulations\", \"page\": 270, \"section\": \"High-Acid vs Low-Acid Canning Standards\", \"selected_text\": \"High-acid foods (pH \u2264 4.6, such as tomatoes, peaches, and pickles) can be safely processed in a simple boiling water bath at 100\u00b0C (212\u00b0F).\", \"surrounding_context\": \"Low-acid foods (pH > 4.6, such as meats, corn, beans, and soups) strictly mandate pressure canning at 116-121\u00b0C (240-250\u00b0F) to destroy heat-resistant Clostridium botulinum endospores.\", \"retrieved_evidence\": [\"High-Acid Rule (pH \u2264 4.6): Boiling water bath (100\u00b0C) is sufficient because the natural acid prevents C. botulinum spores from germinating and producing toxin.\", \"Low-Acid Rule (pH > 4.6): Pressurized retort (121\u00b0C) is legally required because spores can germinate in low-acid anaerobic cans, and boiling water (100\u00b0C) cannot kill the spores.\"], \"student_prompt\": \"Why can fruit jams be canned in boiling water, but canning green beans requires a heavy pressure cooker?\", \"resolution_explanation\": \"The required preservation method depends entirely on the acidity of the food. Clostridium botulinum bacteria produce a deadly neurotoxin, but their spores cannot germinate or grow in acidic environments with a pH of 4.6 or lower. High-acid foods like fruits and jams naturally inhibit botulism growth, so a boiling water bath (100\u00b0C) is sufficient to kill ordinary molds and yeasts. Low-acid foods like green beans (pH ~5.5) have no natural acid to stop botulism; because botulinum spores easily survive boiling water, green beans must be pressure-canned at 121\u00b0C under pressure to physically destroy the heat-resistant spores.\"}}}, \"nutrition_food_science::Enzyme Activity\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Enzyme Activity\", \"explanation\": \"the catalytic function of enzymes \u2014 biological proteins that speed up chemical reactions in living organisms without being consumed, by lowering the activation energy required\", \"reason\": \"enzymes control virtually every metabolic process: digestion, energy production, DNA replication, and detoxification\", \"concrete_examples\": [\"Amylase in saliva breaks down starch into sugar \u2014 that's why bread tastes sweet if you chew it long enough.\", \"Lactase breaks down lactose (milk sugar); people who lack it are lactose intolerant.\", \"Pineapple contains bromelain, a protease enzyme that tenderizes meat by breaking down protein fibers.\"], \"numerical_examples\": [\"Catalase decomposes H\u2082O\u2082 at a rate of 40 million molecules per second \u2014 one of the fastest enzymes known.\", \"Most human enzymes work optimally at 37\u00b0C (body temperature) and denature above 40\u201350\u00b0C.\", \"A 10\u00b0C increase typically doubles enzymatic reaction rate (Q\u2081\u2080 \u2248 2), until the denaturation temperature.\"], \"misconceptions\": [[\"Enzymes are consumed in reactions like other reagents\", \"Enzymes are catalysts \u2014 they speed up reactions without being used up. After facilitating a reaction, the enzyme returns to its original shape and can catalyze another reaction. A single enzyme molecule can process millions of substrate molecules.\"]], \"analogies\": [\"An enzyme is like a locksmith's key-cutting machine \u2014 it shapes raw keys (substrates) into finished keys (products) over and over without wearing out, making the process much faster than filing by hand.\"], \"prerequisites\": [\"basic chemistry\", \"protein structure\"], \"formulas\": [\"Rate \u221d [Enzyme] \u00d7 [Substrate] (simplified)\", \"Michaelis-Menten: v = Vmax[S] / (Km + [S])\"], \"document_evidence\": [\"The text states: 'Enzymes lower activation energy by providing an alternative reaction pathway, binding substrates at their active site.'\", \"Graph 7.1 shows how reaction rate varies with substrate concentration, temperature, and pH.\"], \"practice_problems\": [\"Explain what happens to enzyme activity if temperature increases from 37\u00b0C to 60\u00b0C.\", \"Why does changing the pH dramatically affect enzyme function?\"], \"hints\": [\"Enzymes are substrate-specific \u2014 the active site fits only certain substrates (lock-and-key model).\", \"Denaturation changes the enzyme's 3D shape, destroying the active site.\"], \"follow_up_questions\": [\"What is the difference between competitive and non-competitive enzyme inhibition?\", \"How do cells regulate enzyme activity?\"], \"diagnostic_questions\": [\"What happens to an enzyme after it catalyzes a reaction?\", \"Why does cooking an egg change its texture permanently?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Enzymes speed up biochemical reactions by adding heat energy and shifting the equilibrium toward products.\", \"error_reason\": \"Enzymes do not add energy or alter the reaction equilibrium (K_eq and \u0394G remain unchanged); they act purely as catalysts by lowering the activation energy (E_a) barrier.\", \"correct_claim\": \"Enzymes lower the activation energy barrier of a reaction; they do not alter the chemical equilibrium, \u0394G, or add energy to the system.\", \"understanding_probe\": \"Do enzymes change the equilibrium constant or the net free energy change (\u0394G) of a reaction?\", \"expected_answer\": \"No, enzymes do not change \u0394G or equilibrium; they only increase the speed at which equilibrium is reached by lowering the activation energy barrier.\"}, {\"prior_erroneous_claim\": \"Increasing temperature always continuously increases enzyme activity indefinitely without limit.\", \"error_reason\": \"Higher temperatures increase reaction rates initially through molecular kinetic collisions, but once temperature exceeds the enzyme's thermal optimum, heat disrupts non-covalent bonds, permanently denaturing the protein's active site.\", \"correct_claim\": \"Enzyme activity increases with temperature only up to an optimum point; beyond that optimum temperature, thermal denaturation destroys the enzyme's 3D tertiary structure and active site.\", \"understanding_probe\": \"What happens to the rate of an enzyme-catalyzed reaction when the temperature is raised to 90\u00b0C?\", \"expected_answer\": \"The reaction rate drops to zero because extreme heat denatures the enzyme, unfolding its 3D active site so it can no longer bind substrate.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Enzymology and Biochemical Kinetics\", \"page\": 285, \"section\": \"Michaelis-Menten Steady-State Kinetics\", \"selected_text\": \"An enzyme exhibits a maximum catalytic velocity of Vmax = 120.0 \u03bcmol/(min\u00b7mg) and a Michaelis constant of Km = 4.0 mM. Calculate the reaction velocity v when substrate concentration is [S] = 12.0 mM.\", \"surrounding_context\": \"Section 2.1 applies the Michaelis-Menten equation v = (Vmax * [S]) / (Km + [S]) to compute reaction rate and percentage of Vmax achieved.\", \"retrieved_evidence\": [\"Michaelis-Menten formula: v = (Vmax * [S]) / (Km + [S])\", \"Parameter values: Vmax = 120.0 \u03bcmol/(min\u00b7mg); Km = 4.0 mM; [S] = 12.0 mM.\", \"Step-by-step arithmetic from text: Denominator = Km + [S] = 4.0 + 12.0 = 16.0 mM.\", \"Numerator = Vmax * [S] = 120.0 * 12.0 = 1,440.0.\", \"Velocity calculation: v = 1,440.0 / 16.0 = 90.0 \u03bcmol/(min\u00b7mg).\", \"Percentage of Vmax: 90.0 / 120.0 = 0.750 (75.0% of Vmax).\"], \"student_prompt\": \"What are the exact catalytic velocity and percentage of Vmax calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: In the Michaelis-Menten equation, the numerator is Vmax * [S] = 120.0 * 12.0 = 1,440.0. The denominator is Km + [S] = 4.0 + 12.0 = 16.0. Dividing 1,440.0 by 16.0 yields a catalytic velocity of v = 90.0 \u03bcmol/(min\u00b7mg). Comparing this to Vmax gives 90.0 / 120.0 = 0.75, or 75.0% of maximum velocity. The text directly establishes the reaction velocity at 90.0 \u03bcmol/(min\u00b7mg) and 75.0% of Vmax.\", \"calculated_result\": \"Velocity v = 90.0 \u03bcmol/(min\u00b7mg); % of Vmax = 75.0%\"}, \"pattern_b_derive\": {\"document_title\": \"Enzyme Kinetics: Inhibition Mechanics\", \"page\": 292, \"section\": \"Competitive vs Non-Competitive Kinetic Parameters\", \"selected_text\": \"Competitive inhibitors bind reversibly to the active site, competing directly with substrate, whereas non-competitive inhibitors bind to an allosteric site.\", \"surrounding_context\": \"Derive how Lineweaver-Burk double reciprocal plots distinguish competitive from non-competitive inhibition.\", \"retrieved_evidence\": [\"Lineweaver-Burk Equation: 1/v = (Km / Vmax) * (1/[S]) + (1 / Vmax)\", \"Inhibition effects: Competitive: Km increases to alpha*Km; Vmax is unchanged. Non-competitive: Vmax decreases to Vmax / alpha; Km is unchanged.\"], \"student_prompt\": \"How do we derive why competitive inhibition does not change Vmax on a Lineweaver-Burk plot?\", \"target_response\": \"To derive why Vmax is unchanged: In competitive inhibition, the inhibitor and substrate compete for the exact same active site. The Lineweaver-Burk y-intercept represents 1/Vmax (where 1/[S] = 0, meaning infinite substrate concentration). As substrate concentration [S] approaches infinity, the sheer number of substrate molecules completely outcompetes and floods out the competitive inhibitor, forcing all active sites to be occupied by substrate. Consequently, the enzyme still reaches its normal maximum velocity Vmax at infinite substrate, keeping the y-intercept (1/Vmax) unchanged on the plot.\", \"formula\": \"y-intercept = 1/Vmax; [S] -> inf outcompetes inhibitor\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact production capacity of the Novozymes industrial enzyme fermentation plant in Kalundborg, Denmark in tons\", \"actual_topic\": \"enzyme kinetics, activation energy, active site binding, and allosteric regulation\", \"authoritative_source\": \"Novozymes A/S corporate industrial environmental reports or Danish commercial registry filings\", \"document_title\": \"Principles of Enzyme Biochemistry\", \"page\": 300, \"section\": \"Allosteric Feedback Inhibition\", \"selected_text\": \"In branched biosynthetic pathways, the final end product often binds an allosteric regulatory site on the pathway's initial pacemaker enzyme.\", \"surrounding_context\": \"Threonine deaminase is allosterically inhibited by isoleucine, preventing wasteful metabolic overproduction.\", \"retrieved_evidence\": [\"Section 3.4: Sigmoidal Hill cooperative binding curve for threonine deaminase.\"], \"student_prompt\": \"According to this document, how many tons of enzyme does the Novozymes Kalundborg facility produce annually?\"}, {\"unmentioned_term\": \"the retail sticker price of a 100-gram tub of commercial lactase enzyme drops at CVS Pharmacy\", \"actual_topic\": \"optimal pH ranges of pepsin, trypsin, and salivary amylase\", \"authoritative_source\": \"commercial drugstore retail inventory databases\", \"document_title\": \"Principles of Enzyme Biochemistry\", \"page\": 305, \"section\": \"pH Optima of Digestive Hydrolases\", \"selected_text\": \"Pepsin operates at an acidic optimum of pH 1.5 to 2.0 in the gastric lumen, while pancreatic trypsin operates at pH 7.5 to 8.0.\", \"surrounding_context\": \"Extreme pH changes ionize active site amino acid side chains, abolishing catalytic competence.\", \"retrieved_evidence\": [\"Figure 3.3: Bell-shaped pH activity profiles of human gastrointestinal proteases.\"], \"student_prompt\": \"What does this text state regarding the retail price of lactase enzyme drops at CVS?\"}], \"grounded_paraphrase\": {\"document_title\": \"Molecular Enzymology\", \"page\": 280, \"section\": \"The Induced Fit Catalytic Axiom\", \"selected_text\": \"Koshland's induced fit hypothesis posits that initial non-covalent substrate association induces dynamic conformational stereochemical rearrangements within the catalytic cleft, optimizing complementary spatial interactions and straining target substrate covalent bonds toward the transition state geometry.\", \"surrounding_context\": \"This flexible transition state stabilization surpasses the rigid steric constraints of Fischer's historic lock-and-key model.\", \"retrieved_evidence\": [\"Page 280: 'The induced fit model shows that an enzyme shapes itself around the substrate when it binds, bending and stressing bonds to help the reaction happen.'\"], \"student_prompt\": \"Can you explain the induced fit model of enzymes based on this text in plain words?\", \"faithful_paraphrase\": \"This passage explains that instead of acting like a rigid lock and key, an enzyme is flexible. When the matching molecule enters its active site, the enzyme subtly changes its shape to hug the molecule tightly. By squeezing and bending the substrate into just the right position, it weakens the chemical bonds that need to break, making the chemical reaction happen much faster.\"}, \"conflict_handling\": {\"document_title\": \"Biochemical Catalyst Reference\", \"page\": 312, \"section\": \"Lock-and-Key vs Induced Fit Models\", \"selected_text\": \"Emil Fischer proposed the lock-and-key model in 1894, asserting that the enzyme's active site has a pre-formed rigid geometry perfectly complementary to the unreacted substrate.\", \"surrounding_context\": \"Modern structural biology proved that if an active site were perfectly complementary to the ground-state substrate, the substrate would get trapped in a deep energy well; instead, enzymes are complementary to the transition state.\", \"retrieved_evidence\": [\"Fischer Model (1894): Rigid active site complementary to unreacted substrate (historical introductory model).\", \"Pauling/Koshland Model (1948/1958): Flexible active site complementary to the high-energy transition state, not the stable ground state.\"], \"student_prompt\": \"Why did my high school biology book teach the lock-and-key model if college textbooks say enzymes are shaped to fit the transition state?\", \"resolution_explanation\": \"The lock-and-key model was a brilliant early analogy that helped scientists understand that enzymes are highly specific to certain molecules. However, real enzymes cannot be rigid locks. If an enzyme fit the stable substrate perfectly, the substrate would bind so tightly that it would never react. Modern biochemistry showed that enzymes actually fit the unstable 'transition state'\u2014the halfway point of the chemical reaction. High school books still teach the lock-and-key model because it introduces enzyme specificity simply, while college texts introduce transition-state stabilization for chemical accuracy.\"}}}, \"nutrition_food_science::Metabolism\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Metabolism\", \"explanation\": \"the sum of all chemical reactions in a living organism that convert food into energy (catabolism) and use that energy to build molecules (anabolism)\", \"reason\": \"it determines how the body processes nutrients, regulates weight, generates energy, and maintains cellular functions\", \"concrete_examples\": [\"After eating a sandwich, your metabolism breaks down carbs into glucose (catabolism), then uses that glucose to produce ATP for energy.\", \"Building muscle after exercise involves anabolic metabolism \u2014 assembling amino acids into new muscle proteins.\", \"Your basal metabolic rate (BMR) accounts for about 60-75% of daily calorie expenditure, just to maintain basic functions.\"], \"numerical_examples\": [\"BMR for a 70 kg male \u2248 10 \u00d7 70 + 6.25 \u00d7 175 \u2212 5 \u00d7 30 + 5 = 1,648 kcal/day (using the Mifflin-St Jeor equation).\", \"1 molecule of glucose through aerobic respiration yields approximately 36-38 ATP molecules.\", \"A person with a TDEE of 2,500 kcal who eats 2,000 kcal/day creates a 500 kcal deficit, losing roughly 1 lb per week.\"], \"misconceptions\": [[\"A slow metabolism is the main cause of obesity\", \"Research shows that overweight individuals actually have HIGHER absolute metabolic rates because more mass requires more energy. Obesity is primarily driven by caloric surplus \u2014 eating more calories than expended \u2014 combined with genetic, behavioral, and environmental factors.\"]], \"analogies\": [\"Metabolism is like a city's infrastructure \u2014 catabolism is the power plants burning fuel (food) to generate electricity (energy), and anabolism is the construction crews using that electricity to build new buildings (cells and tissues).\"], \"prerequisites\": [\"basic biology\", \"chemistry basics\"], \"formulas\": [\"BMR (Mifflin-St Jeor): 10\u00d7weight(kg) + 6.25\u00d7height(cm) \u2212 5\u00d7age + s (s=+5 male, \u2212161 female)\", \"ATP yield from glucose \u2248 36-38 ATP\"], \"document_evidence\": [\"The text explains: 'Catabolism breaks down complex molecules into simpler ones, releasing energy. Anabolism uses energy to build complex molecules from simpler ones.'\", \"Figure 8.3 illustrates the relationship between BMR, thermic effect of food, and physical activity in total daily energy expenditure.\"], \"practice_problems\": [\"Calculate BMR for a 65 kg, 160 cm, 25-year-old female using the Mifflin-St Jeor equation.\", \"If someone's TDEE is 2,200 kcal and they consume 2,700 kcal daily, how long until they gain 1 lb (assuming 3,500 kcal = 1 lb)?\"], \"hints\": [\"Basal metabolic rate is what your body burns at rest \u2014 just to breathe, pump blood, and maintain temperature.\", \"Anabolism = building up (needs energy). Catabolism = breaking down (releases energy).\"], \"follow_up_questions\": [\"Does exercise increase your resting metabolic rate? If so, how?\", \"What hormones regulate metabolism?\"], \"diagnostic_questions\": [\"What is the difference between catabolism and anabolism?\", \"If you eat 500 fewer calories than your body needs daily, what happens over time?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The electron transport chain produces ATP directly by transferring electrons to glucose molecules.\", \"error_reason\": \"Electrons are transferred through protein complexes to oxygen (the terminal electron acceptor, forming H2O); this electron flow pumps protons to generate a proton gradient that drives ATP synthase, not glucose.\", \"correct_claim\": \"Electrons flow through the electron transport chain to oxygen (forming water). The energy released pumps protons into the intermembrane space, creating a gradient that powers ATP synthase.\", \"understanding_probe\": \"What is the final electron acceptor in the mitochondrial electron transport chain during aerobic cellular respiration?\", \"expected_answer\": \"Oxygen (O2) is the final electron acceptor, combining with electrons and protons to produce water (H2O).\"}, {\"prior_erroneous_claim\": \"Anaerobic glycolysis produces more ATP per molecule of glucose than aerobic cellular respiration.\", \"error_reason\": \"Glycolysis alone yields only 2 net ATP per glucose; complete aerobic respiration yields approximately 30 to 32 ATP per glucose via pyruvate oxidation, the Krebs cycle, and oxidative phosphorylation.\", \"correct_claim\": \"Aerobic respiration produces far more energy (~30-32 net ATP per glucose) than anaerobic glycolysis, which produces only 2 net ATP per glucose.\", \"understanding_probe\": \"How does the net ATP yield of anaerobic glycolysis compare to complete aerobic respiration?\", \"expected_answer\": \"Anaerobic glycolysis yields only 2 net ATP per glucose, whereas aerobic cellular respiration produces approximately 30 to 32 ATP per glucose.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Cellular Bioenergetics and Metabolic Pathways\", \"page\": 325, \"section\": \"Net ATP Accounting in Aerobic Respiration\", \"selected_text\": \"Complete aerobic oxidation of one mole of glucose (C6H12O6) through glycolysis, pyruvate dehydrogenase, the citric acid cycle, and oxidative phosphorylation yields reduced cofactors: 10 NADH and 2 FADH2, plus 4 substrate-level ATP/GTP.\", \"surrounding_context\": \"Section 2.1 applies modern P/O ratios (2.5 ATP per mitochondrial NADH and 1.5 ATP per FADH2) to calculate the exact net ATP yield.\", \"retrieved_evidence\": [\"ATP from substrate-level phosphorylation: Glycolysis = 2 ATP; Citric Acid Cycle = 2 GTP (2 ATP) -> Total substrate = 4 ATP.\", \"ATP from oxidative phosphorylation: 10 NADH * 2.5 ATP/NADH = 25.0 ATP.\", \"ATP from FADH2: 2 FADH2 * 1.5 ATP/FADH2 = 3.0 ATP.\", \"Total theoretical net ATP yield per glucose = 4 + 25.0 + 3.0 = 32.0 ATP.\"], \"student_prompt\": \"What is the exact net ATP yield per molecule of glucose calculated in Section 2.1 using modern P/O ratios?\", \"target_response\": \"Following the explicit accounting in Section 2.1: Substrate-level phosphorylation produces 4 ATP (2 from glycolysis and 2 from the citric acid cycle). Oxidative phosphorylation from 10 NADH yields 10 * 2.5 = 25.0 ATP, and 2 FADH2 yields 2 * 1.5 = 3.0 ATP. Summing all components: 4 + 25.0 + 3.0 = 32.0 net ATP per glucose molecule. The text directly establishes the modern net ATP yield at exactly 32.0 ATP.\", \"calculated_result\": \"Total net ATP yield = 32.0 ATP per glucose\"}, \"pattern_b_derive\": {\"document_title\": \"Energy Expenditure: Basal Metabolic Rate (BMR)\", \"page\": 332, \"section\": \"Harris-Benedict and Mifflin-St Jeor Equations\", \"selected_text\": \"The Mifflin-St Jeor equation estimates Basal Metabolic Rate (BMR) in kilocalories per day based on mass in kg, height in cm, age in years, and gender.\", \"surrounding_context\": \"For an adult male, BMR = (10.0 * weight in kg) + (6.25 * height in cm) - (5.0 * age in years) + 5.0.\", \"retrieved_evidence\": [\"Formula: BMR (male) = (10.0 * W) + (6.25 * H) - (5.0 * A) + 5.0\", \"Subject parameters: Male, Weight W = 80.0 kg, Height H = 180.0 cm, Age A = 30.0 years.\"], \"student_prompt\": \"How do we derive the daily Basal Metabolic Rate for this 30-year-old male using the Mifflin-St Jeor equation?\", \"target_response\": \"To derive the BMR using the Mifflin-St Jeor equation: Evaluate each term separately: Weight term = 10.0 * 80.0 kg = 800.0 kcal. Height term = 6.25 * 180.0 cm = 1,125.0 kcal. Age term = 5.0 * 30.0 years = 150.0 kcal. Combine terms according to the formula: BMR = 800.0 + 1,125.0 - 150.0 + 5.0. Summing the positive terms: 1,925.0 - 150.0 + 5.0 = 1,775.0 + 5.0 = 1,780.0 kcal/day. The subject's basal metabolic rate is exactly 1,780.0 kcal per day.\", \"formula\": \"BMR = (10 * 80) + (6.25 * 180) - (5 * 30) + 5 = 1,780 kcal/day\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact market capitalization of Novo Nordisk in Danish kroner\", \"actual_topic\": \"glycolysis, the citric acid cycle, oxidative phosphorylation, and basal metabolic rate\", \"authoritative_source\": \"Nasdaq Copenhagen stock exchange financial market data\", \"document_title\": \"Foundations of Human Metabolism\", \"page\": 342, \"section\": \"Beta-Oxidation of Fatty Acids\", \"selected_text\": \"Fatty acids are activated to acyl-CoA in the cytoplasm and transported across the mitochondrial membrane via the carnitine shuttle.\", \"surrounding_context\": \"Each turn of beta-oxidation cleaves a 2-carbon acetyl-CoA while generating one FADH2 and one NADH.\", \"retrieved_evidence\": [\"Section 3.3: Enzymatic cycle of palmitate (16-carbon) degradation.\"], \"student_prompt\": \"According to this text, what was the market cap of Novo Nordisk in Danish kroner?\"}, {\"unmentioned_term\": \"the price of a gym membership at Equinox in New York City\", \"actual_topic\": \"ketogenesis, gluconeogenesis, and the Cori cycle between muscle and liver\", \"authoritative_source\": \"Equinox Fitness commercial membership pricing agreements\", \"document_title\": \"Foundations of Human Metabolism\", \"page\": 348, \"section\": \"The Cori Cycle\", \"selected_text\": \"Under anaerobic muscle exertion, lactate produced by glycolysis enters the bloodstream and travels to the liver.\", \"surrounding_context\": \"Hepatic gluconeogenesis converts two molecules of lactate back into glucose, consuming 6 ATP equivalents.\", \"retrieved_evidence\": [\"Section 3.6: Metabolic energy balance of the glucose-lactate inter-organ shuttle.\"], \"student_prompt\": \"What does the reading cite as the monthly membership fee at Equinox in New York?\"}], \"grounded_paraphrase\": {\"document_title\": \"Human Metabolic Physiology\", \"page\": 320, \"section\": \"Chemiosmotic Coupling Hypothesis\", \"selected_text\": \"Mitchell's chemiosmotic hypothesis establishes that electron transport chain exergonic redox reactions are coupled to the vector-directed extrusion of protons across the inner mitochondrial membrane, synthesizing a transmembrane proton-motive force that drives mechanical torque in ATP synthase for ADP phosphorylation.\", \"surrounding_context\": \"This electrochemical coupling reconciles electron flow with mechanical ATP synthesis without covalent chemical intermediates.\", \"retrieved_evidence\": [\"Page 320: 'Peter Mitchell proved that pumping protons across the mitochondrial membrane creates a gradient like water behind a dam, which turns ATP synthase to make ATP.'\"], \"student_prompt\": \"Can you explain how the mitochondria make ATP based on this text in simple words?\", \"faithful_paraphrase\": \"This passage explains the chemiosmotic theory: as electrons flow through the mitochondria's energy chain, they pump protons across the inner membrane, building up pressure like water stored behind a hydroelectric dam. These protons can only flow back through a microscopic rotary motor called ATP synthase, and as they rush through, they spin the motor to generate ATP molecules.\"}, \"conflict_handling\": {\"document_title\": \"Cellular Energetics Historical Perspectives\", \"page\": 355, \"section\": \"Historical vs Modern ATP Yield per Glucose: 36/38 vs 30/32\", \"selected_text\": \"Older biochemistry textbooks from the 1980s and 1990s taught that one glucose molecule yields 36 or 38 ATP.\", \"surrounding_context\": \"Modern structural measurements of ATP synthase c-ring stoichiometry revised the P/O ratio from 3.0 to 2.5 per NADH, and from 2.0 to 1.5 per FADH2, establishing the actual net yield at 30 to 32 ATP.\", \"retrieved_evidence\": [\"Older Standard: 1 NADH = 3 ATP, 1 FADH2 = 2 ATP -> Total = 36 or 38 ATP per glucose.\", \"Modern Empirical Standard: 1 NADH = 2.5 ATP, 1 FADH2 = 1.5 ATP -> Total = 30 or 32 ATP per glucose (due to proton leakage and transport costs).\"], \"student_prompt\": \"My older textbook says cellular respiration makes 38 ATP, but my new professor says it only makes 30 to 32 ATP. Why did the number change?\", \"resolution_explanation\": \"The actual biology did not change, but our scientific measurement tools became much more precise. The older estimate of 36 to 38 ATP assumed whole-number ratios (3 ATP per NADH and 2 per FADH2). However, in the 1990s, biophysicists directly counted the number of protons needed to turn the rotor of ATP synthase and transport phosphate. They discovered that it actually takes 4 protons to make and export one ATP, resulting in true yields of 2.5 ATP per NADH and 1.5 per FADH2. Modern textbooks updated the total to 30-32 ATP to reflect these accurate experimental measurements.\"}}}, \"nutrition_food_science::Nutrient Deficiencies\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Nutrient Deficiencies\", \"explanation\": \"conditions that arise when the body does not receive or absorb adequate amounts of essential nutrients (vitamins, minerals, or macronutrients), leading to specific health problems\", \"reason\": \"they cause a wide range of diseases \u2014 from scurvy (vitamin C) to anemia (iron) to rickets (vitamin D) \u2014 and understanding them is critical for public health and clinical nutrition\", \"concrete_examples\": [\"Iron deficiency anemia causes fatigue because hemoglobin (which carries oxygen) requires iron. It's the most common nutritional deficiency worldwide.\", \"Vitamin C deficiency causes scurvy \u2014 bleeding gums, bruising, and poor wound healing \u2014 as seen historically in sailors without access to fresh fruit.\", \"Vitamin D deficiency leads to rickets in children (soft, weak bones) because vitamin D is needed to absorb calcium.\"], \"numerical_examples\": [\"About 2 billion people worldwide are affected by iron deficiency, making it the #1 nutritional deficiency.\", \"The recommended daily intake of vitamin C is 65\u201390 mg. Scurvy symptoms appear after about 3 months of intake below 10 mg/day.\", \"Severe iodine deficiency during pregnancy can lower a child's IQ by 10\u201315 points due to impaired thyroid function.\"], \"misconceptions\": [[\"Nutrient deficiencies only occur in developing countries\", \"Deficiencies are common worldwide. In developed countries, vitamin D deficiency affects about 40% of adults, iron deficiency affects many women, and B12 deficiency is common among vegetarians. Processed food diets can lead to multiple micronutrient gaps.\"]], \"analogies\": [\"A nutrient deficiency is like a missing ingredient in a recipe \u2014 if you leave out baking powder (vitamin D), the cake won't rise (bones won't strengthen), even if all other ingredients are present.\"], \"prerequisites\": [\"basic biology\", \"vitamins and minerals\"], \"formulas\": [\"RDA (Recommended Dietary Allowance) varies by nutrient, age, and sex\"], \"document_evidence\": [\"The text states: 'Micronutrient deficiencies are often called 'hidden hunger' because symptoms may not appear until the deficiency is severe.'\", \"Table 9.1 links specific deficiencies to their symptoms: iron\u2192anemia, vitamin C\u2192scurvy, vitamin D\u2192rickets, B12\u2192neurological damage.\"], \"practice_problems\": [\"A patient presents with fatigue, pale skin, and brittle nails. Which nutrient deficiency is most likely? What dietary changes would you recommend?\", \"Why might a strict vegan be at risk for vitamin B12 deficiency?\"], \"hints\": [\"Match the symptom to the nutrient: bone issues \u2192 vitamin D/calcium, bleeding \u2192 vitamin C/K, nerve issues \u2192 B12.\", \"Deficiencies can be caused by inadequate intake, poor absorption, or increased needs (pregnancy, illness).\"], \"follow_up_questions\": [\"How can cooking methods affect the nutrient content of food?\", \"What is the difference between a deficiency and a toxicity?\"], \"diagnostic_questions\": [\"Which deficiency causes night blindness?\", \"Why might someone eating plenty of food still have a nutrient deficiency?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Scurvy is caused by an acute dietary deficiency of vitamin D.\", \"error_reason\": \"Scurvy is caused by vitamin C (ascorbic acid) deficiency, which impairs collagen proline hydroxylation; vitamin D deficiency causes rickets in children and osteomalacia in adults.\", \"correct_claim\": \"Scurvy is caused by a severe deficiency of vitamin C (ascorbic acid), which is required for collagen synthesis. Vitamin D deficiency causes rickets or osteomalacia.\", \"understanding_probe\": \"What disease results from a prolonged deficiency of vitamin C, and how does it manifest?\", \"expected_answer\": \"Scurvy, which manifests as bleeding gums, skin hemorrhages, delayed wound healing, and joint pain due to impaired collagen synthesis.\"}, {\"prior_erroneous_claim\": \"Iron deficiency anemia causes red blood cells to become abnormally large and dark red.\", \"error_reason\": \"Iron deficiency causes microcytic, hypochromic anemia (cells are abnormally small and pale due to lack of hemoglobin); large macrocytic cells are caused by vitamin B12 or folate deficiency.\", \"correct_claim\": \"Iron deficiency produces microcytic (small) and hypochromic (pale) red blood cells because the body cannot synthesize sufficient hemoglobin. Large cells (macrocytic) indicate B12 or folate deficiency.\", \"understanding_probe\": \"What do red blood cells look like under a microscope in severe iron deficiency anemia?\", \"expected_answer\": \"They appear microcytic and hypochromic, meaning they are unusually small in size and pale in color due to low hemoglobin content.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Clinical Hematology and Micronutrient Disorders\", \"page\": 375, \"section\": \"Red Blood Cell Indices in Anemia Diagnosis\", \"selected_text\": \"A clinical patient presents with fatigue and paleness. Laboratory blood analysis reveals: Hemoglobin = 9.0 g/dL, Hematocrit (Hct) = 28.0% (0.28), Total Red Blood Cell Count (RBC) = 4.00 x 10^12 cells/L (4.0 million/\u03bcL).\", \"surrounding_context\": \"Section 2.2 computes the Mean Corpuscular Volume (MCV in femtoliters) and Mean Corpuscular Hemoglobin (MCH in picograms) to classify the anemia.\", \"retrieved_evidence\": [\"Formulas: MCV (fL) = [Hematocrit (%) * 10] / RBC count (millions/\u03bcL); MCH (pg) = [Hemoglobin (g/dL) * 10] / RBC count (millions/\u03bcL).\", \"Step-by-step arithmetic from text: MCV = (28.0 * 10) / 4.00 = 280.0 / 4.00 = 70.0 fL (Normal range: 80 - 100 fL; classified as Microcytic).\", \"MCH = (9.0 * 10) / 4.00 = 90.0 / 4.00 = 22.5 pg (Normal range: 27 - 33 pg; classified as Hypochromic).\", \"Diagnostic conclusion: Microcytic hypochromic indices indicate classic iron-deficiency anemia.\"], \"student_prompt\": \"What are the exact MCV and MCH values calculated in Section 2.2 and their clinical classification?\", \"target_response\": \"Following the explicit calculations in Section 2.2: The Mean Corpuscular Volume is MCV = (28.0 * 10) / 4.00 = 70.0 fL, which is well below the normal 80-100 fL range, confirming microcytosis (abnormally small red blood cells). The Mean Corpuscular Hemoglobin is MCH = (9.0 * 10) / 4.00 = 22.5 pg, which is below the normal 27-33 pg range, confirming hypochromia (pale cells). The text directly establishes MCV at 70.0 fL and MCH at 22.5 pg, diagnosing microcytic hypochromic iron-deficiency anemia.\", \"calculated_result\": \"MCV = 70.0 fL (Microcytic), MCH = 22.5 pg (Hypochromic)\"}, \"pattern_b_derive\": {\"document_title\": \"Micronutrient Deficiencies: Dietary Mineral Bioavailability\", \"page\": 382, \"section\": \"Calculating Absorbable Dietary Iron\", \"selected_text\": \"Dietary iron exists as heme iron (in animal meat, absorbed at approximately 25.0%) and non-heme iron (in plant foods and grains, absorbed at only approximately 5.0% under baseline conditions).\", \"surrounding_context\": \"Calculate the net bioavailable iron absorbed from a meal containing 4.0 mg of heme iron and 16.0 mg of non-heme iron.\", \"retrieved_evidence\": [\"Formula: Total Absorbable Iron = (Heme Iron * 0.25) + (Non-Heme Iron * 0.05)\", \"Meal content: 4.0 mg heme iron, 16.0 mg non-heme iron.\"], \"student_prompt\": \"How do we derive the total absorbable iron in milligrams from this mixed meal?\", \"target_response\": \"To derive the total bioavailable iron: Calculate the absorbed portion of heme iron: 4.0 mg * 0.25 = 1.00 mg. Next, calculate the absorbed portion of non-heme iron: 16.0 mg * 0.05 = 0.80 mg. Sum the two bioavailable fractions: 1.00 mg + 0.80 mg = 1.80 mg. Although the meal contained 20.0 mg of total gross iron, the body actually absorbs only 1.80 mg of iron.\", \"formula\": \"Total Absorbed = (4.0 * 0.25) + (16.0 * 0.05) = 1.80 mg\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact pharmaceutical wholesale price of injectable hydroxocobalamin in the United Kingdom\", \"actual_topic\": \"vitamin and mineral deficiencies, scurvy, rickets, beriberi, pellagra, and goiter\", \"authoritative_source\": \"the British National Formulary (BNF) NHS indicative drug price tables\", \"document_title\": \"Global Nutritional Pathology\", \"page\": 392, \"section\": \"Iodine Deficiency Disorders\", \"selected_text\": \"Iodine deficiency impairs thyroxine (T4) and triiodothyronine (T3) synthesis, causing thyroid gland enlargement (endemic goiter).\", \"surrounding_context\": \"Universal salt iodization programs have dramatically reduced severe congenital iodine deficiency syndrome (cretinism).\", \"retrieved_evidence\": [\"Section 4.1: WHO urinary iodine concentration epidemiological monitoring thresholds.\"], \"student_prompt\": \"According to this document, what is the NHS price for injectable hydroxocobalamin in the UK?\"}, {\"unmentioned_term\": \"the annual operating budget of the UNICEF global nutrition division in Geneva\", \"actual_topic\": \"protein-energy malnutrition including kwashiorkor (hypoalbuminemia) and marasmus (caloric wasting)\", \"authoritative_source\": \"the UNICEF executive board annual financial audit and budget reports\", \"document_title\": \"Global Nutritional Pathology\", \"page\": 398, \"section\": \"Protein-Energy Malnutrition Syndromes\", \"selected_text\": \"Kwashiorkor is characterized by bilateral pitting edema and distended abdomen resulting from profound hypoalbuminemia and decreased oncotic pressure.\", \"surrounding_context\": \"Marasmus presents with severe somatic muscle and subcutaneous adipose tissue wasting without edema.\", \"retrieved_evidence\": [\"Table 4.3: Differential diagnostic features of Kwashiorkor versus Marasmus.\"], \"student_prompt\": \"What does the reading cite as the annual budget of UNICEF's nutrition division in Geneva?\"}], \"grounded_paraphrase\": {\"document_title\": \"Clinical Pathology of Nutrition\", \"page\": 370, \"section\": \"Etiology of Scurvy and Collagen Cross-Linking\", \"selected_text\": \"Ascorbic acid deficiency impairs the post-translational enzymatic hydroxylation of prolyl and lysyl residues within procollagen alpha chains by prolyl 4-hydroxylase, preventing stable triple-helix tropocollagen self-assembly and precipitating catastrophic microvascular capillary fragility.\", \"surrounding_context\": \"This defect causes petechiae, follicular hyperkeratosis, and periodontal tissue breakdown.\", \"retrieved_evidence\": [\"Page 370: 'Vitamin C is required for enzymes to add hydroxyl groups to collagen; without it, collagen fibers cannot assemble properly, causing blood vessels and tissues to weaken and bleed.'\"], \"student_prompt\": \"Can you explain why lack of vitamin C causes bleeding and loose teeth in simple terms?\", \"faithful_paraphrase\": \"This passage explains that your body needs vitamin C to build collagen, which is the essential structural glue that holds skin, blood vessels, and gums together. Without vitamin C, your cells cannot chemically assemble strong collagen fibers, causing tiny blood vessels to become brittle and burst and connective tissues around teeth and joints to break down and bleed.\"}, \"conflict_handling\": {\"document_title\": \"Hematological Diagnosis Handbook\", \"page\": 405, \"section\": \"Folate vs Vitamin B12: The Neurological Trap\", \"selected_text\": \"Both vitamin B12 deficiency and folate (vitamin B9) deficiency cause identical megaloblastic, macrocytic anemia on blood smears.\", \"surrounding_context\": \"Administering high-dose folate supplements corrects the anemia in both deficiencies, but if the patient actually has B12 deficiency, folate fails to prevent irreversible subacute combined degeneration of the spinal cord.\", \"retrieved_evidence\": [\"Common Presentation: Both B12 and Folate deficiencies produce identical large, immature red blood cells (MCV > 100 fL).\", \"Clinical Conflict / Danger: Treating a B12-deficient patient with folate cures the anemia on lab tests, masking the underlying deficiency while allowing permanent neurological spinal cord damage to progress.\"], \"student_prompt\": \"If folate supplements cure the anemia, why do doctors warn that giving folate to a B12-deficient patient is dangerous?\", \"resolution_explanation\": \"This is a famous clinical dilemma known as the 'folate trap.' Both B12 and folate deficiencies cause the exact same type of anemia (megaloblastic macrocytic anemia). Giving high doses of folate will fix the anemia on a blood test, making it look like the patient is cured. However, vitamin B12 is also uniquely required to maintain the myelin insulation around spinal nerves. If the patient is actually deficient in B12, the folate masks the symptoms while the hidden B12 deficiency continues quietly causing permanent, irreversible spinal cord and nerve damage.\"}}}, \"nutrition_food_science::Food Safety\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Food Safety\", \"explanation\": \"the practices and procedures that prevent foodborne illness by ensuring food is properly handled, prepared, stored, and served to minimize contamination from pathogens, chemicals, and physical hazards\", \"reason\": \"improper food safety causes an estimated 48 million foodborne illnesses and 3,000 deaths annually in the US alone, making it a critical public health concern\", \"concrete_examples\": [\"Cross-contamination: using the same cutting board for raw chicken and salad without washing it can transfer Salmonella to the salad.\", \"The '2-hour rule': perishable food left at room temperature for more than 2 hours should be discarded.\", \"Proper handwashing (20 seconds with soap) before handling food is the single most effective food safety practice.\"], \"numerical_examples\": [\"Chicken must reach an internal temperature of 165\u00b0F (74\u00b0C) to kill Salmonella \u2014 a food thermometer is essential.\", \"Refrigerators should be at or below 40\u00b0F (4\u00b0C) and freezers at 0\u00b0F (\u221218\u00b0C) to keep food safely stored.\", \"HACCP identifies 7 principles for systematic food safety management, with critical control points monitored at specific temperatures.\"], \"misconceptions\": [[\"You can tell if food is safe by smelling or tasting it\", \"Many dangerous pathogens \u2014 including Salmonella, E. coli O157:H7, and Listeria \u2014 produce no change in food's appearance, smell, or taste. Food can look and smell perfectly fine but contain millions of harmful bacteria. You CANNOT rely on senses to determine food safety.\"]], \"analogies\": [\"Food safety is like defensive driving \u2014 you can't see the danger (bacteria) directly, so you follow systematic rules (temperature control, hygiene, separation) to stay safe.\"], \"prerequisites\": [\"basic biology\", \"microbiology basics\"], \"formulas\": [\"Danger zone: 40\u2013140\u00b0F (4\u201360\u00b0C)\", \"Minimum cooking temps vary by food type\"], \"document_evidence\": [\"The text states: 'The four core principles of food safety are: Clean, Separate, Cook, and Chill.'\", \"Table 10.1 lists minimum internal cooking temperatures: poultry 165\u00b0F, ground beef 160\u00b0F, whole cuts 145\u00b0F.\"], \"practice_problems\": [\"A restaurant leaves potato salad on a buffet at 75\u00b0F for 3 hours. Is it still safe to eat? Explain.\", \"Design a HACCP plan for a sandwich-making operation. Identify at least 3 critical control points.\"], \"hints\": [\"Remember the four Cs: Clean (hands/surfaces), Combat (cross-contamination), Cook (to safe temps), Chill (refrigerate promptly).\", \"When in doubt, throw it out \u2014 you can't see or smell most dangerous bacteria.\"], \"follow_up_questions\": [\"What is HACCP and why is it used in food manufacturing?\", \"How does refrigeration prevent foodborne illness?\"], \"diagnostic_questions\": [\"Can you determine if cooked chicken is safe by cutting it open and looking at the color?\", \"What is cross-contamination and how do you prevent it?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The temperature 'Danger Zone' where foodborne bacteria rapidly multiply is between 0\u00b0F and 32\u00b0F (-18\u00b0C to 0\u00b0C).\", \"error_reason\": \"0\u00b0F to 32\u00b0F is the freezing zone where bacteria are dormant; the FDA/USDA temperature danger zone is 40\u00b0F to 140\u00b0F (4\u00b0C to 60\u00b0C).\", \"correct_claim\": \"The temperature Danger Zone for rapid bacterial proliferation is 40\u00b0F to 140\u00b0F (4\u00b0C to 60\u00b0C). Perishable foods should not remain in this zone for more than 2 hours.\", \"understanding_probe\": \"What is the official USDA/FDA temperature 'Danger Zone' in degrees Fahrenheit, and why is it dangerous?\", \"expected_answer\": \"40\u00b0F to 140\u00b0F (4\u00b0C to 60\u00b0C); it is dangerous because foodborne bacteria double in population every 20 minutes within this temperature range.\"}, {\"prior_erroneous_claim\": \"You can always tell if food is contaminated with dangerous bacteria like Salmonella or E. coli because it will smell rotten and look slimy.\", \"error_reason\": \"Pathogenic bacteria (like Salmonella, Listeria, E. coli) do not typically alter food smell, taste, or appearance; spoilage organisms cause foul odors, but dangerous pathogens can thrive in perfectly fresh-tasting food.\", \"correct_claim\": \"Pathogenic bacteria that cause severe foodborne illness do not change the smell, taste, or appearance of food. Food can look, smell, and taste completely normal while carrying lethal doses of Salmonella or E. coli.\", \"understanding_probe\": \"Can food that smells and tastes completely delicious still make someone sick with food poisoning?\", \"expected_answer\": \"Yes, pathogenic bacteria do not cause noticeable foul odors or spoilage; food can smell and taste fresh while harboring dangerous pathogens.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Food Protection and Sanitation Standards\", \"page\": 420, \"section\": \"Bacterial Doubling Kinetics in the Temperature Danger Zone\", \"selected_text\": \"Under optimal temperature abuse conditions in the danger zone (37\u00b0C / 98.6\u00b0F), Salmonella enterica exhibits an exponential generation time of G = 20.0 minutes. A warm potato salad is inoculated with an initial contamination of N0 = 50 bacterial cells.\", \"surrounding_context\": \"Section 2.1 computes the number of generations and final bacterial population N(t) after t = 3.0 hours (180.0 minutes) of temperature abuse.\", \"retrieved_evidence\": [\"Number of generations: n = t / G = 180.0 minutes / 20.0 minutes = 9.0 generations.\", \"Exponential growth formula: N(t) = N0 * 2^n.\", \"Power of two calculation: 2^9 = 512.\", \"Step-by-step arithmetic from text: N(180) = 50 * 512 = 25,600 bacterial cells.\"], \"student_prompt\": \"What are the exact number of bacterial generations and total bacterial population calculated in Section 2.1 after 3 hours?\", \"target_response\": \"Following the explicit steps in Section 2.1: In 3 hours (180 minutes), with a doubling time of 20.0 minutes, the bacteria undergo n = 180 / 20 = 9.0 generations. Applying the exponential growth formula N = N0 * 2^n gives N = 50 * 2^9 = 50 * 512 = 25,600 cells. The text directly establishes that 9 generations occur and the bacterial population surges from 50 cells to 25,600 cells in 3 hours.\", \"calculated_result\": \"Generations n = 9.0, Final Population = 25,600 bacterial cells\"}, \"pattern_b_derive\": {\"document_title\": \"Food Safety Systems: HACCP Principles\", \"page\": 428, \"section\": \"Establishing Critical Control Point (CCP) Cooking Temperatures\", \"selected_text\": \"In HACCP plans, poultry cooking is a Critical Control Point requiring a 7-log10 reduction (99.99999% reduction) in Salmonella.\", \"surrounding_context\": \"Thermal destruction depends on internal endpoint temperature: at 165\u00b0F (73.9\u00b0C), the 7-log reduction is instantaneous (0 seconds), while at 150\u00b0F (65.6\u00b0C), it requires holding the core temperature for 2.7 minutes.\", \"retrieved_evidence\": [\"USDA Lethality Rule: Instantaneous 7-D Salmonella kill achieved at 165\u00b0F (73.9\u00b0C).\", \"Alternative low-temperature pasteurization: 150\u00b0F requires maintaining core temperature for exactly 2.7 minutes.\"], \"student_prompt\": \"How do we derive why a chicken breast cooked to 150\u00b0F can be just as safe as one cooked to 165\u00b0F under HACCP principles?\", \"target_response\": \"To derive the microbiological equivalence: Bacterial lethality is a function of both temperature AND time. Cooking to 165\u00b0F achieves the required 7-D (99.99999%) kill of Salmonella instantaneously, which is why consumer guidelines recommend 165\u00b0F for safety without timing. However, at 150\u00b0F, the exact same 7-D reduction is achieved if that core temperature is held continuously for 2.7 minutes. Under HACCP principles, both methods achieve identical pasteurization lethality because time compensates for lower temperature.\", \"formula\": \"Lethality = Time * Temperature kill rate; 165\u00b0F instant = 150\u00b0F held 2.7 min\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact penalty fine levied against Blue Bell Creameries in its 2020 federal court settlement\", \"actual_topic\": \"HACCP principles, cross-contamination prevention, Danger Zone, and sanitizer concentrations\", \"authoritative_source\": \"the United States Department of Justice official court press releases and sentencing memoranda\", \"document_title\": \"Principles of Commercial Food Safety\", \"page\": 438, \"section\": \"Listeria monocytogenes in Food Manufacturing\", \"selected_text\": \"Listeria monocytogenes is an environmental psychrotroph capable of forming persistent biofilms on stainless steel floor drains.\", \"surrounding_context\": \"Sanitation standard operating procedures (SSOPs) require rotating quaternary ammonium compounds with peracetic acid.\", \"retrieved_evidence\": [\"Section 3.2: Biofilm formation stages on food-contact surfaces.\"], \"student_prompt\": \"According to this document, how much was Blue Bell Creameries fined in its 2020 court settlement?\"}, {\"unmentioned_term\": \"the wholesale price of a commercial Hobart 20-quart commercial kitchen food mixer\", \"actual_topic\": \"chemical sanitation ppm standards for chlorine, iodine, and quaternary ammonium sanitizers\", \"authoritative_source\": \"restaurant supply equipment dealer retail catalogs\", \"document_title\": \"Principles of Commercial Food Safety\", \"page\": 442, \"section\": \"Chemical Sanitizer Concentration Standards\", \"selected_text\": \"Chlorine bleach sanitizing solutions mandate concentration between 50 and 100 ppm available chlorine at pH 6.0 to 7.5.\", \"surrounding_context\": \"Test strips must be dipped into third-compartment sinks to verify active parts per million.\", \"retrieved_evidence\": [\"Table 3.4: FDA Food Code sanitizer contact times and temperature minimums.\"], \"student_prompt\": \"What does this text state regarding the wholesale price of a Hobart 20-quart kitchen mixer?\"}], \"grounded_paraphrase\": {\"document_title\": \"Food Hygiene Principles\", \"page\": 415, \"section\": \"Cross-Contamination Etiology\", \"selected_text\": \"Cross-contamination designates the inadvertent physical or convective translocation of pathogenic biological agents from infectious reservoirs\u2014predominantly raw animal flesh, contaminated cutting surfaces, or unwashed food handler epidermis\u2014onto ready-to-eat culinary substrates that receive no subsequent terminal lethality step.\", \"surrounding_context\": \"Segregating prep surfaces with color-coded polymer cutting boards is an essential preventative control.\", \"retrieved_evidence\": [\"Page 415: 'Cross-contamination happens when bacteria from raw meat or dirty hands get transferred onto food that is eaten without cooking.'\"], \"student_prompt\": \"Can you explain what cross-contamination means in everyday kitchen language?\", \"faithful_paraphrase\": \"This passage explains that cross-contamination happens when harmful bacteria from raw foods (like uncooked chicken) or unwashed hands are accidentally spread onto foods that are ready to eat (like salad greens or bread). Because those ready-to-eat foods will not be cooked before serving, any bacteria transferred to them will survive and can cause severe food poisoning.\"}, \"conflict_handling\": {\"document_title\": \"Food Safety Regulatory Perspectives\", \"page\": 450, \"section\": \"Thawing Meat: Countertop vs Refrigerator Protocols\", \"selected_text\": \"Some home cooks claim leaving frozen turkey on the countertop for hours is safe as long as the center is still cold.\", \"surrounding_context\": \"Food safety scientists strictly forbid countertop thawing because the outer exterior layer enters the temperature danger zone (40-140\u00b0F) hours before the interior thaws, allowing surface bacteria to multiply to dangerous levels.\", \"retrieved_evidence\": [\"Culinary Myth: Thawing meat on the kitchen counter is fine because 'it's still frozen in the middle.'\", \"Scientific Reality (USDA Rule): Thawing must occur in the refrigerator, under cold running water, or in the microwave. On a counter, the outer 1/2 inch warms above 40\u00b0F within an hour, breeding massive bacterial colonies while the core is still frozen.\"], \"student_prompt\": \"Why does the USDA say never thaw raw meat on the counter if the middle of the meat is still completely frozen solid?\", \"resolution_explanation\": \"This is a critical food safety principle. Even though the inside of the meat is still rock solid, heat transfers from the outside in. That means the outer skin and surface layer will warm up past 40\u00b0F into the 'Danger Zone' within an hour, while the center remains frozen for hours longer. Bacteria on the outside surface can multiply into tens of thousands of cells and produce toxins long before the center ever finishes thawing. Thawing in the refrigerator keeps the entire bird under 40\u00b0F throughout the entire process.\"}}}, \"nutrition_food_science::Dietary Fiber\": {\"domain\": \"nutrition_food_science\", \"concept\": \"Dietary Fiber\", \"explanation\": \"the indigestible plant carbohydrates (soluble and insoluble) that pass through the digestive system largely intact, providing bulk, feeding gut bacteria, and regulating digestion\", \"reason\": \"adequate fiber intake reduces risk of heart disease, diabetes, and colon cancer, promotes healthy bowel function, and helps maintain a healthy weight\", \"concrete_examples\": [\"Oatmeal is rich in soluble fiber (beta-glucan) which forms a gel in the gut that slows sugar absorption and lowers cholesterol.\", \"Wheat bran contains insoluble fiber that adds bulk to stool and prevents constipation.\", \"Beans and lentils are excellent sources of both soluble and insoluble fiber, providing 15-18g per cup.\"], \"numerical_examples\": [\"Recommended daily fiber intake: 25g for women, 38g for men. Average American intake is only about 15g/day.\", \"One cup of lentils provides about 16g of fiber \u2014 roughly half the daily recommendation for women.\", \"Increasing fiber from 15g to 30g/day is associated with a 27% lower risk of developing Type 2 diabetes.\"], \"misconceptions\": [[\"Fiber supplements are as effective as fiber from whole foods\", \"Whole food sources of fiber come packaged with vitamins, minerals, phytochemicals, and water that supplements lack. Studies show that the health benefits of fiber \u2014 like reduced cancer risk and improved gut microbiome diversity \u2014 are strongest from whole food sources, not isolated supplements.\"]], \"analogies\": [\"Dietary fiber is like a broom for your digestive system \u2014 soluble fiber acts like a sponge (soaking up cholesterol and sugar), while insoluble fiber acts like bristles (sweeping waste through the intestines).\"], \"prerequisites\": [\"basic biology\", \"carbohydrate chemistry\"], \"formulas\": [\"Daily recommended intake: 14g per 1,000 calories consumed\"], \"document_evidence\": [\"The text explains: 'Soluble fiber dissolves in water to form a viscous gel that slows digestion, while insoluble fiber adds bulk and accelerates intestinal transit.'\", \"Research summary (Box 11.1): Higher fiber intake is consistently associated with lower rates of cardiovascular disease, type 2 diabetes, and colorectal cancer.\"], \"practice_problems\": [\"Plan a day's meals that provide at least 30g of fiber using common foods.\", \"Explain the difference between soluble and insoluble fiber and give two food sources of each.\"], \"hints\": [\"Soluble fiber: oats, beans, apples, citrus (dissolves in water, lowers cholesterol).\", \"Insoluble fiber: wheat bran, vegetables, whole grains (doesn't dissolve, prevents constipation).\"], \"follow_up_questions\": [\"How does fiber feed beneficial gut bacteria?\", \"Why should you increase fiber intake gradually rather than all at once?\"], \"diagnostic_questions\": [\"Why can't humans digest fiber like they digest starch?\", \"What happens in the digestive system when you eat soluble fiber?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Human digestive enzymes easily break down dietary fiber into glucose molecules in the stomach.\", \"error_reason\": \"Humans lack enzymes (such as cellulase) to cleave the beta-1,4-glycosidic bonds in dietary fiber; fiber passes undigested through the stomach and small intestine into the colon.\", \"correct_claim\": \"Humans do not produce enzymes capable of hydrolyzing the beta-glycosidic bonds in dietary fiber. Fiber travels undigested through the stomach and small intestine to the large intestine.\", \"understanding_probe\": \"Why can humans digest starch into glucose, but cannot digest cellulose (dietary fiber)?\", \"expected_answer\": \"Because human enzymes (amylase) can only break alpha-1,4-glycosidic bonds found in starch; humans lack cellulase to break the beta-1,4-glycosidic bonds in cellulose.\"}, {\"prior_erroneous_claim\": \"Soluble fiber and insoluble fiber have the exact same physical properties and effects in the digestive system.\", \"error_reason\": \"Soluble fiber dissolves in water to form viscous gels that slow digestion and bind cholesterol; insoluble fiber does not dissolve, adding bulk to stool and accelerating intestinal transit time.\", \"correct_claim\": \"Soluble fiber dissolves in water, forming viscous gels that slow glucose absorption and lower cholesterol; insoluble fiber does not dissolve in water and speeds up bowel transit by adding bulk.\", \"understanding_probe\": \"What is the key functional difference in the body between soluble fiber (like oat beta-glucan) and insoluble fiber (like wheat bran)?\", \"expected_answer\": \"Soluble fiber forms a gel that slows digestion and lowers cholesterol, while insoluble fiber adds physical bulk to stool and speeds up transit through the intestines.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Dietary Fiber and Chronic Disease Prevention\", \"page\": 465, \"section\": \"Daily Fiber Intake Targets and Caloric Densities\", \"selected_text\": \"The National Academy of Medicine establishes the Adequate Intake (AI) for dietary fiber at 14.0 grams per 1,000 kilocalories consumed. An individual consumes an average daily diet of 2,500 kcal.\", \"surrounding_context\": \"Section 2.1 computes the target daily fiber intake in grams and evaluates a patient's current intake of 18.0 g.\", \"retrieved_evidence\": [\"Formula: Target Fiber Intake (g) = (Daily Calories / 1,000) * 14.0 g.\", \"Calculation for 2,500 kcal diet: Target = (2,500 / 1,000) * 14.0 = 2.5 * 14.0 = 35.0 grams/day.\", \"Deficit analysis from report: Current intake = 18.0 g; Daily deficit = 35.0 g - 18.0 g = 17.0 grams/day.\", \"Percentage of recommendation achieved: 18.0 / 35.0 = 0.5143 (51.43%).\"], \"student_prompt\": \"What are the exact target daily fiber intake and current deficit calculated in Section 2.1 for a 2,500 kcal diet?\", \"target_response\": \"Following the explicit calculation in Section 2.1: Based on the guideline of 14.0 g fiber per 1,000 kcal, a 2,500 kcal diet requires (2,500 / 1,000) * 14.0 = 2.5 * 14.0 = 35.0 grams of dietary fiber daily. With the patient's current intake at 18.0 g, their daily fiber deficit is 35.0 - 18.0 = 17.0 grams (they achieve only 51.43% of the target). The text directly establishes the target at 35.0 grams/day and the deficit at 17.0 grams/day.\", \"calculated_result\": \"Target Fiber = 35.0 g/day, Current Deficit = 17.0 g/day\"}, \"pattern_b_derive\": {\"document_title\": \"Colonic Fermentation and Short-Chain Fatty Acids\", \"page\": 472, \"section\": \"Microbial Fermentation of Soluble Fiber\", \"selected_text\": \"Anaerobic colonic microbiota ferment soluble dietary fiber into short-chain fatty acids (SCFAs): predominantly acetate, propionate, and butyrate.\", \"surrounding_context\": \"Although fiber resists human digestion, colonic absorption of SCFAs yields approximately 2.0 kcal per gram of fermented soluble fiber.\", \"retrieved_evidence\": [\"Energy conversion factor: Fermented soluble fiber yields 2.0 kcal/gram through colonic SCFA absorption.\", \"Dietary intake: A nutrition bar contains 12.0 g of completely fermentable soluble prebiotic fiber (inulin).\"], \"student_prompt\": \"How do we derive the total caloric energy yielded to the human body from 12.0 grams of fermentable soluble fiber?\", \"target_response\": \"To derive the caloric energy yielded from fiber fermentation: Multiply the grams of fermentable fiber by the colonic short-chain fatty acid energetic conversion factor: 12.0 g * 2.0 kcal/g = 24.0 kcal. While standard food tables historically labeled all fiber as 0 calories, microbial fermentation into short-chain fatty acids like butyrate and acetate allows the colon to absorb approximately 24.0 kcal of usable energy from that 12.0 g serving.\", \"formula\": \"Energy = 12.0 g * 2.0 kcal/g = 24.0 kcal\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact wholesale export price of psyllium husk per metric ton from Gujarat, India\", \"actual_topic\": \"dietary fiber classifications, colonic fermentation, short-chain fatty acids, and bowel motility\", \"authoritative_source\": \"the Agricultural and Processed Food Products Export Development Authority (APEDA) of India price reports\", \"document_title\": \"Dietary Fiber in Human Health\", \"page\": 482, \"section\": \"Bile Acid Sequestration Mechanics\", \"selected_text\": \"Soluble viscous fibers like oat beta-glucan bind bile acids in the intestinal lumen, preventing their enterohepatic reabsorption.\", \"surrounding_context\": \"The liver is forced to consume circulating LDL cholesterol to synthesize replacement bile acids, reducing serum cholesterol.\", \"retrieved_evidence\": [\"Section 3.3: Clinical meta-analysis of beta-glucan and circulating LDL reduction.\"], \"student_prompt\": \"According to this document, what was the export price per metric ton of psyllium husk from Gujarat?\"}, {\"unmentioned_term\": \"the advertising budget spent promoting Metamucil during the 2024 NFL season\", \"actual_topic\": \"prebiotics, bifidobacteria stimulation, and colonic epithelial barrier integrity\", \"authoritative_source\": \"Procter & Gamble commercial marketing expenditure filings or Nielsen ad spend tracking\", \"document_title\": \"Dietary Fiber in Human Health\", \"page\": 488, \"section\": \"Prebiotics and the Microbiome\", \"selected_text\": \"Inulin and fructooligosaccharides (FOS) selectively stimulate the proliferation of beneficial Bifidobacteria in the distal colon.\", \"surrounding_context\": \"Butyrate produced during fermentation serves as the primary energetic fuel for colonocyte epithelial cells.\", \"retrieved_evidence\": [\"Figure 3.5: Colonocyte ATP generation from microbial butyrate oxidation.\"], \"student_prompt\": \"What does the reading cite as the advertising budget for Metamucil during the 2024 football season?\"}], \"grounded_paraphrase\": {\"document_title\": \"Nutritional Physiology and Fiber\", \"page\": 460, \"section\": \"The Dietary Fiber Definition Axiom\", \"selected_text\": \"Dietary fiber designates carbohydrate polymers consisting of ten or more monomeric units that are refractory to endogenous enzymatic hydrolysis within the human small intestine, translocating intact into the cecum and colon to undergo variable anaerobic fermentation by commensal microbiota.\", \"surrounding_context\": \"This resistance stems from beta-acetal linkages that human salivary and pancreatic amylases cannot cleave.\", \"retrieved_evidence\": [\"Page 460: 'Dietary fiber consists of plant carbohydrates that our digestive enzymes cannot break down, allowing them to reach the large intestine intact.'\"], \"student_prompt\": \"Can you explain what dietary fiber is based on this text in plain language?\", \"faithful_paraphrase\": \"This passage explains that dietary fiber consists of complex plant carbohydrates that your stomach and small intestine cannot digest because humans lack the enzymes to break their specific chemical bonds. Because they cannot be broken down, fiber travels all the way through your digestive tract to your colon, where it feeds beneficial gut bacteria and helps waste pass smoothly through the body.\"}, \"conflict_handling\": {\"document_title\": \"Nutritional Labeling Guidelines\", \"page\": 495, \"section\": \"The 'Zero Calorie' Fiber Labeling Myth\", \"selected_text\": \"Traditional nutritional labeling historically treated all dietary fiber as having 0 kcal/gram because it is not digested in the upper GI tract.\", \"surrounding_context\": \"Modern nutritional physiology and FDA regulations recognize that fermented soluble fiber provides approximately 1.5 to 2.0 kcal/gram via absorbed short-chain fatty acids, while completely insoluble fiber provides near 0 kcal.\", \"retrieved_evidence\": [\"Traditional Consumer Labeling: Fiber = 0 kcal/gram (Simplified assumption based on lack of small intestine glucose absorption).\", \"Modern Scientific & FDA Standard: Insoluble fiber \u2248 0 kcal/g; Soluble/fermentable fiber \u2248 2 kcal/g (Energy absorbed as short-chain fatty acids by colonic cells).\"], \"student_prompt\": \"My fitness app logs dietary fiber as 0 calories, but my nutrition textbook says fiber provides 2 calories per gram. Which one is right?\", \"resolution_explanation\": \"Both reflect different levels of accounting. In everyday consumer fitness apps and older food labels, all dietary fiber was counted as 0 calories because your stomach and small intestine cannot digest it into sugar. However, modern science proves that soluble fiber is fermented by gut bacteria in your colon into short-chain fatty acids (like acetate and butyrate), which your intestinal walls absorb and burn for fuel. Modern nutritional standards therefore assign soluble fiber a real energy value of approximately 2 kcal per gram.\"}}}, \"general_academic::Critical Thinking\": {\"domain\": \"general_academic\", \"concept\": \"Critical Thinking\", \"explanation\": \"the disciplined process of actively analyzing, evaluating, and synthesizing information to form well-reasoned judgments, rather than accepting claims at face value\", \"reason\": \"it is the foundation of academic inquiry, informed decision-making, and protection against manipulation and misinformation\", \"concrete_examples\": [\"Reading a news article and checking the primary source rather than trusting the headline is critical thinking.\", \"When a friend says 'everyone is switching to X brand,' questioning whether 'everyone' is an exaggeration uses critical thinking.\", \"Evaluating whether a study's sample size is large enough before accepting its conclusions.\"], \"numerical_examples\": [\"A study claims 'Product X reduces cold duration by 50%.' Critical analysis: the reduction was from 6 days to 3 days in a sample of only 20 people \u2014 the sample is too small for strong conclusions.\", \"A politician says 'crime has doubled.' Critical check: if crime went from 2 incidents to 4 incidents in a small area, that's technically correct but misleading in context.\", \"An ad says '4 out of 5 dentists recommend' \u2014 critical thinking asks: How were the dentists selected? What were they asked?\"], \"misconceptions\": [[\"Critical thinking means being negative or cynical about everything\", \"Critical thinking is about being analytically fair, not negative. It means evaluating evidence objectively \u2014 which can lead to SUPPORTING a claim as well as rejecting one. A critical thinker follows evidence wherever it leads, whether it confirms or challenges their initial view.\"]], \"analogies\": [\"Critical thinking is like being a detective \u2014 you don't accept the first explanation; you examine evidence, question witnesses, and look for what doesn't fit before drawing conclusions.\"], \"prerequisites\": [\"basic literacy\", \"logical reasoning\"], \"formulas\": [\"N/A \u2014 critical thinking is a process, not a formula\"], \"document_evidence\": [\"The text defines: 'Critical thinking involves asking: What is the claim? What is the evidence? Is the reasoning valid? Are there alternative explanations?'\", \"Bloom's Taxonomy (Figure 1.2) places critical thinking skills (analyze, evaluate, create) at the top of the learning hierarchy.\"], \"practice_problems\": [\"Evaluate this claim: 'A study of 15 people found that drinking green tea cured their insomnia.' What questions should you ask?\", \"Identify the logical flaw: 'My grandfather smoked all his life and lived to 95, so smoking can't be that bad.'\"], \"hints\": [\"Ask: What is the evidence? Is it anecdotal or systematic? Could there be another explanation?\", \"Watch for logical fallacies like hasty generalization, appeal to authority, and false dichotomy.\"], \"follow_up_questions\": [\"How can confirmation bias undermine critical thinking?\", \"What is the difference between skepticism and cynicism in critical analysis?\"], \"diagnostic_questions\": [\"Is it critical thinking to always disagree with experts?\", \"How would you evaluate a claim that you already agree with?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Critical thinking means being cynical, disagreeing with everything you hear, and constantly finding fault with others.\", \"error_reason\": \"Critical thinking is objective, disciplined evaluation of evidence, arguments, and reasoning; it is not negative fault-finding, hostility, or stubborn cynicism.\", \"correct_claim\": \"Critical thinking is the disciplined, objective analysis and evaluation of an issue based on evidence and logic to form a sound judgment, not mere criticism or reflexive disagreement.\", \"understanding_probe\": \"What is the core distinction between being 'critical' in everyday speech versus practicing 'critical thinking'?\", \"expected_answer\": \"Being critical usually means expressing negative disapproval, whereas critical thinking is the unbiased, rational evaluation of claims and evidence to determine truth.\"}, {\"prior_erroneous_claim\": \"An argument is automatically valid and sound as long as the person delivering it speaks with total confidence and passion.\", \"error_reason\": \"Emotional confidence and persuasive delivery do not establish logical validity or empirical truth; arguments must be evaluated on premises, reasoning, and evidence.\", \"correct_claim\": \"The validity and soundness of an argument depend entirely on the truth of its premises and logical structure, not on the emotional conviction or delivery style of the speaker.\", \"understanding_probe\": \"Can a speaker be completely confident and passionate while delivering a logically invalid argument?\", \"expected_answer\": \"Yes, emotional conviction has no bearing on logical truth; an argument can be passionately delivered while relying on completely false premises or fallacious logic.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Informal Logic and Critical Reasoning\", \"page\": 35, \"section\": \"Evaluating Deductive Argument Validity and Soundness\", \"selected_text\": \"An academic committee evaluates 80 candidate arguments submitted in policy debates. Thorough formal analysis reveals that 60 of the 80 arguments have valid logical forms (Valid = 60). Of those 60 valid arguments, empirical premise verification demonstrates that 45 have strictly true premises (Sound = 45).\", \"surrounding_context\": \"Section 2.1 computes the validity rate, soundness rate among valid arguments, and overall soundness percentage across all evaluated submissions.\", \"retrieved_evidence\": [\"Total submitted arguments = 80.\", \"Validity calculation: Validity Rate = Valid Arguments / Total Submissions = 60 / 80 = 0.750 (75.0%).\", \"Soundness conditional rate: Soundness given Validity = 45 / 60 = 0.750 (75.0%).\", \"Overall soundness calculation: Overall Soundness Rate = Sound Arguments / Total Submissions = 45 / 80 = 0.5625 (56.25%).\", \"Unsound argument count = Total Submissions - Sound Arguments = 80 - 45 = 35 arguments (43.75%).\"], \"student_prompt\": \"What are the exact validity rate, overall soundness percentage, and number of unsound arguments calculated in Section 2.1?\", \"target_response\": \"Following the explicit calculations in Section 2.1: The logical validity rate across all submissions is 60 / 80 = 75.0%. The overall soundness percentage (arguments that are both logically valid and have empirically true premises) is 45 / 80 = 0.5625, or exactly 56.25%. The number of unsound arguments is 80 - 45 = 35 (accounting for 43.75% of submissions). The text directly establishes the validity rate at 75.0%, overall soundness at 56.25%, and 35 unsound arguments.\", \"calculated_result\": \"Validity Rate = 75.0%, Overall Soundness = 56.25%, Unsound Count = 35\"}, \"pattern_b_derive\": {\"document_title\": \"Bayesian Epistemology: Updating Beliefs on Evidence\", \"page\": 42, \"section\": \"Deriving Posterior Probability via Bayes' Theorem\", \"selected_text\": \"Critical thinkers update belief in a hypothesis H upon receiving new evidence E using Bayes' Rule: P(H|E) = [P(E|H) * P(H)] / P(E).\", \"surrounding_context\": \"When P(E) = [P(E|H) * P(H)] + [P(E|not-H) * P(not-H)], derive the posterior probability from prior probability and likelihood ratios.\", \"retrieved_evidence\": [\"Bayes' Formula: P(H|E) = [P(E|H) * P(H)] / [P(E|H)*P(H) + P(E|not-H)*P(not-H)]\", \"Parameters: Prior belief in hypothesis P(H) = 0.10 (so P(not-H) = 0.90); True positive rate P(E|H) = 0.80; False positive rate P(E|not-H) = 0.10.\"], \"student_prompt\": \"How do we derive the posterior probability P(H|E) that the hypothesis is true after observing positive evidence E?\", \"target_response\": \"To derive the posterior probability: First compute the numerator: P(E|H) * P(H) = 0.80 * 0.10 = 0.08. Next compute the denominator, which is total probability P(E): [P(E|H) * P(H)] + [P(E|not-H) * P(not-H)] = 0.08 + (0.10 * 0.90) = 0.08 + 0.09 = 0.17. Finally, divide numerator by denominator: P(H|E) = 0.08 / 0.17 \u2248 0.4706, or 47.06%. Even though the evidence was positive, the low prior probability (10%) means the posterior probability is approximately 47.1%, demonstrating how critical thinking prevents base-rate neglect.\", \"formula\": \"P(H|E) = 0.08 / (0.08 + 0.09) = 47.06%\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact endowment value in British pounds of Trinity College, Cambridge in 2024\", \"actual_topic\": \"deductive validity, inductive strength, premise evaluation, and cognitive heuristics\", \"authoritative_source\": \"Trinity College Cambridge official annual financial audit reports and accounts\", \"document_title\": \"Principles of Critical Inquiry\", \"page\": 52, \"section\": \"Cognitive Biases and Heuristics\", \"selected_text\": \"System 1 thinking relies on fast, automatic heuristics that are vulnerable to anchoring and framing effects.\", \"surrounding_context\": \"System 2 thinking requires deliberate, effortful cognitive reflection to evaluate formal syllogistic validity.\", \"retrieved_evidence\": [\"Section 3.1: Dual-process cognitive theories of judgment.\"], \"student_prompt\": \"According to this text, what was the total endowment of Trinity College, Cambridge in 2024?\"}, {\"unmentioned_term\": \"the wholesale price of a barista espresso machine manufactured by La Marzocco\", \"actual_topic\": \"evaluating causal claims versus correlation in observational studies\", \"authoritative_source\": \"commercial coffee equipment wholesale vendor catalogs\", \"document_title\": \"Principles of Critical Inquiry\", \"page\": 58, \"section\": \"Causation versus Correlation\", \"selected_text\": \"Establishing a causal relationship requires demonstrating temporal precedence, covariation, and non-spuriousness.\", \"surrounding_context\": \"Confounding third variables frequently generate illusory statistical correlations.\", \"retrieved_evidence\": [\"Table 3.3: Bradford Hill criteria for evaluating causal epidemiological claims.\"], \"student_prompt\": \"What does this text cite as the wholesale cost of a La Marzocco espresso machine?\"}], \"grounded_paraphrase\": {\"document_title\": \"Epistemology and Critical Reasoning\", \"page\": 30, \"section\": \"The Critical Thinking Epistemic Axiom\", \"selected_text\": \"Critical thinking designates metacognitive, self-regulatory epistemic deliberation directed toward evaluating the evidential warrants and inferential cogency of propositions prior to apportioning doxastic assent.\", \"surrounding_context\": \"It acts as a normative cognitive filter against cognitive biases, ideological dogmatism, and epistemic gullibility.\", \"retrieved_evidence\": [\"Page 30: 'Critical thinking is the habit of pausing to carefully examine evidence and logic before deciding whether to believe a claim.'\"], \"student_prompt\": \"Can you explain what critical thinking means based on this text in plain words?\", \"faithful_paraphrase\": \"This passage explains that critical thinking is simply the mental habit of hitting the pause button before accepting a claim. Instead of automatically believing what you are told, you consciously inspect the evidence, check whether the reasoning actually makes sense, and only accept the idea once the facts genuinely support it.\"}, \"conflict_handling\": {\"document_title\": \"Philosophical Logic Reference\", \"page\": 65, \"section\": \"Validity vs Soundness in Deductive Logic\", \"selected_text\": \"Laypersons frequently use 'valid argument' as a synonym for 'true statement' or 'good argument.'\", \"surrounding_context\": \"In formal logic, validity refers strictly to deductive structure (if premises were true, conclusion must follow), whereas soundness additionally requires that the premises actually be empirically true in the real world.\", \"retrieved_evidence\": [\"Lay Definition: 'Valid argument' loosely means any believable or persuasive point.\", \"Formal Logic Standard: 'Valid' means the logical structure is unbreakable (e.g., All fish are mammals; all mammals fly; therefore all fish fly -> strictly VALID structure, but completely UNSOUND due to false premises).\"], \"student_prompt\": \"My debate coach said my argument had a valid structure, but my philosophy professor gave it an F and said it was completely unsound. Why?\", \"resolution_explanation\": \"Your coach and professor were evaluating two different criteria. An argument is 'valid' if its logical skeleton is structurally airtight: IF the premises were true, the conclusion would be guaranteed to follow. That is what your debate coach praised. However, an argument is only 'sound' if it has that valid structure AND its starting premises are factually true in the real world. Your professor failed it because while your logical connections held together, your starting facts were false or unproven, rendering the argument unsound.\"}}}, \"general_academic::Research Methods\": {\"domain\": \"general_academic\", \"concept\": \"Research Methods\", \"explanation\": \"the systematic approaches used to collect, analyze, and interpret data to answer research questions, including experimental, observational, survey, and qualitative methods\", \"reason\": \"they ensure findings are reliable, valid, and reproducible, forming the backbone of scientific knowledge and evidence-based policy\", \"concrete_examples\": [\"A randomized controlled trial (RCT) testing a new drug randomly assigns patients to treatment or placebo groups to control for confounding factors.\", \"A survey of 1,000 voters about their preferred candidate uses random sampling to estimate the views of the entire electorate.\", \"An ethnographic study where a researcher lives with a community for a year to understand their cultural practices uses qualitative methods.\"], \"numerical_examples\": [\"A study with n=30 has a larger standard error than one with n=3,000. Doubling sample size reduces standard error by a factor of \u221a2 \u2248 1.41.\", \"If a clinical trial shows p=0.03, there is a 3% probability of seeing results this extreme if the drug had no effect.\", \"An effect size of d=0.8 is considered large, d=0.5 medium, and d=0.2 small in social science research.\"], \"misconceptions\": [[\"Correlation implies causation\", \"A correlation between two variables only means they move together; it does NOT mean one causes the other. Ice cream sales and drowning rates are correlated (both increase in summer), but ice cream doesn't cause drowning. Only controlled experiments or very careful causal analysis can establish causation.\"]], \"analogies\": [\"Research methods are like cooking recipes \u2014 following them carefully ensures your results (dish) turn out as expected. Skipping steps or substituting ingredients (cutting corners) leads to unreliable results.\"], \"prerequisites\": [\"basic statistics\", \"critical thinking\"], \"formulas\": [\"Standard error = SD / \u221an\", \"Effect size (Cohen's d) = (M\u2081 \u2212 M\u2082) / SDpooled\"], \"document_evidence\": [\"The text explains: 'The gold standard for establishing causation is the randomized controlled trial, where random assignment ensures groups are comparable before treatment.'\", \"Table 2.1 compares experimental, quasi-experimental, correlational, and descriptive research designs.\"], \"practice_problems\": [\"A study finds that students who eat breakfast score higher on tests. Can we conclude that eating breakfast causes better scores? What would a better study design look like?\", \"What is the purpose of a control group in an experiment?\"], \"hints\": [\"Randomization controls for confounding variables \u2014 factors other than the treatment that might affect the outcome.\", \"Internal validity = can we trust the causal claim? External validity = can we generalize to other populations?\"], \"follow_up_questions\": [\"What is the difference between reliability and validity in research?\", \"When would qualitative methods be more appropriate than quantitative methods?\"], \"diagnostic_questions\": [\"What makes an experiment 'controlled'?\", \"If a study finds a correlation of r=0.85 between hours studied and exam score, does studying cause better scores?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Qualitative research methods are simply unscientific guessing that should never be used in academic research.\", \"error_reason\": \"Qualitative methods (grounded theory, ethnography, phenomenology) are rigorous, systematic scientific methodologies designed to explore complex social phenomena, meanings, and contexts that numerical quantitative metrics cannot capture.\", \"correct_claim\": \"Qualitative research is a rigorous, systematic scientific methodology designed to investigate meanings, contexts, and complex mechanisms that cannot be quantified numerically.\", \"understanding_probe\": \"When is qualitative research (such as semi-structured interviews) more appropriate than quantitative surveys?\", \"expected_answer\": \"When researchers want to explore underlying reasons, lived experiences, and complex human motivations in depth, rather than measuring numerical frequencies across a population.\"}, {\"prior_erroneous_claim\": \"A research instrument with high reliability is automatically guaranteed to have high validity.\", \"error_reason\": \"Reliability measures consistency/repeatability, while validity measures accuracy/truth; a broken scale can give the exact same weight every time (high reliability) while being off by 10 pounds (zero validity).\", \"correct_claim\": \"Reliability (consistency) is necessary for validity, but does not guarantee it. An instrument can be perfectly consistent while consistently measuring the wrong construct.\", \"understanding_probe\": \"If a bathroom scale always shows exactly 150 lbs every time you step on it, but your true weight is 170 lbs, is the scale reliable, valid, or both?\", \"expected_answer\": \"It is highly reliable (extremely consistent), but completely invalid (inaccurate, does not measure true weight).\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Methodological Measurement and Psychometrics\", \"page\": 88, \"section\": \"Inter-Rater Reliability: Cohen's Kappa Calculation\", \"selected_text\": \"Two independent academic researchers code 100 student essays into 'Pass' or 'Fail' categories to assess qualitative grading consistency. Both researchers agree on Pass for 60 essays and agree on Fail for 20 essays (Observed Agreement = 80 essays). Researcher 1 rated 70 Pass and 30 Fail; Researcher 2 rated 65 Pass and 35 Fail.\", \"surrounding_context\": \"Section 2.2 computes observed agreement P_o, expected agreement by chance P_e, and Cohen's Kappa \u03ba.\", \"retrieved_evidence\": [\"Observed agreement: P_o = (60 + 20) / 100 = 80 / 100 = 0.800.\", \"Expected agreement by chance: P_e = [(70/100) * (65/100)] + [(30/100) * (35/100)] = (0.70 * 0.65) + (0.30 * 0.35) = 0.455 + 0.105 = 0.560.\", \"Cohen's Kappa formula: \u03ba = (P_o - P_e) / (1 - P_e).\", \"Step-by-step arithmetic from text: \u03ba = (0.800 - 0.560) / (1 - 0.560) = 0.240 / 0.440 = 0.5455 \u2248 0.55 (Moderate agreement).\"], \"student_prompt\": \"What are the exact observed agreement P_o, chance agreement P_e, and Cohen's Kappa calculated in Section 2.2?\", \"target_response\": \"Following the explicit steps in Section 2.2: Observed agreement is P_o = (60 + 20) / 100 = 0.800 (80.0%). The probability of agreement by chance is P_e = (0.70 * 0.65) + (0.30 * 0.35) = 0.455 + 0.105 = 0.560 (56.0%). Substituting into Cohen's Kappa yields \u03ba = (0.800 - 0.560) / (1 - 0.560) = 0.240 / 0.440 = 0.5455 (approximately 0.55), indicating moderate inter-rater reliability. The text directly establishes P_o = 0.80, P_e = 0.56, and \u03ba = 0.5455.\", \"calculated_result\": \"P_o = 0.80, P_e = 0.56, Cohen's Kappa \u03ba = 0.5455\"}, \"pattern_b_derive\": {\"document_title\": \"Sampling Theory: Sample Size Determination\", \"page\": 95, \"section\": \"Cochran's Formula for Unknown Population Size\", \"selected_text\": \"Cochran's formula calculates the required sample size n for estimating a population proportion with margin of error e and confidence level Z.\", \"surrounding_context\": \"Assuming maximum population variability p = 0.50 (where p(1 - p) = 0.25) provides the most conservative sample estimate.\", \"retrieved_evidence\": [\"Formula: n = [Z\u00b2 * p * (1 - p)] / e\u00b2\", \"Study parameters: 95% confidence level (Z = 1.96, Z\u00b2 = 3.8416); Desired margin of error e = 5.0% (0.05, e\u00b2 = 0.0025); Conservative variance p = 0.50.\"], \"student_prompt\": \"How do we derive the required sample size n using Cochran's formula from the study parameters?\", \"target_response\": \"To derive the required sample size using Cochran's formula: Substitute the parameters into n = [Z\u00b2 * p * (1 - p)] / e\u00b2. First compute the numerator: 3.8416 * 0.50 * 0.50 = 3.8416 * 0.25 = 0.9604. Next, compute the denominator: (0.05)\u00b2 = 0.0025. Finally, divide the numerator by the denominator: n = 0.9604 / 0.0025 = 384.16. Rounding up to the next whole integer ensures the desired precision: n = 385 participants.\", \"formula\": \"n = [1.96\u00b2 * 0.5 * 0.5] / 0.05\u00b2 = 384.16 -> 385\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact annual software licensing fee for Qualtrics CoreXM Enterprise at Stanford University\", \"actual_topic\": \"quantitative versus qualitative research designs, validity, reliability, and sampling methodologies\", \"authoritative_source\": \"university IT procurement contracts or Qualtrics commercial enterprise sales agreements\", \"document_title\": \"Methodological Foundations of Social Science\", \"page\": 105, \"section\": \"Triangulation in Mixed Methods\", \"selected_text\": \"Triangulation combines quantitative surveys and qualitative interviews to corroborate convergent validity across disparate data streams.\", \"surrounding_context\": \"Methodological triangulation neutralizes the inherent idiosyncratic weaknesses of single-method research designs.\", \"retrieved_evidence\": [\"Section 3.1: Denzin's four types of research triangulation.\"], \"student_prompt\": \"According to this chapter, how much does Stanford pay annually for its Qualtrics software license?\"}, {\"unmentioned_term\": \"the average hourly wage of transcribed audio transcriptionists on Rev.com\", \"actual_topic\": \"thematic analysis coding, inter-rater reliability, and transcript sanitization\", \"authoritative_source\": \"independent contractor compensation disclosures or Rev.com service worker reports\", \"document_title\": \"Methodological Foundations of Social Science\", \"page\": 110, \"section\": \"Thematic Analysis and Coding Protocols\", \"selected_text\": \"Braun and Clarke outline a six-phase framework for reflexive thematic analysis of interview transcripts.\", \"surrounding_context\": \"Initial open coding transitions into axial coding to synthesize overarching thematic nodes.\", \"retrieved_evidence\": [\"Table 3.4: Six phases of thematic coding in qualitative research.\"], \"student_prompt\": \"What does this text state regarding the hourly pay rate for Rev.com transcription workers?\"}], \"grounded_paraphrase\": {\"document_title\": \"Foundations of Research Methodology\", \"page\": 80, \"section\": \"Construct Validity Axiom\", \"selected_text\": \"Construct validity formalizes the degree to which empirical operationalizations and psychometric measurement instruments legitimately evaluate the theoretical unobservable latent construct they purport to delineate, rather than capturing irrelevant method variance.\", \"surrounding_context\": \"Without construct validity, empirical hypothesis testing yields meaningless inferences.\", \"retrieved_evidence\": [\"Page 80: 'Construct validity means verifying that your survey or test is actually measuring the specific psychological concept you intended to measure.'\"], \"student_prompt\": \"Can you explain what construct validity means based on this text in simple terms?\", \"faithful_paraphrase\": \"This passage explains that construct validity means making sure your test or survey actually measures what you think it measures. For example, if you create a quiz designed to measure 'creativity,' construct validity ensures that your quiz is truly testing creative thinking, rather than accidentally testing vocabulary or general memory.\"}, \"conflict_handling\": {\"document_title\": \"Methodological Paradigms in Behavioral Science\", \"page\": 118, \"section\": \"Positivism vs Constructivism Epistemologies\", \"selected_text\": \"Positivist researchers argue that objective social realities exist independently of human perception and can be measured through detached quantitative instruments.\", \"surrounding_context\": \"Constructivist researchers argue that social reality is co-created through human language, social interactions, and cultural contexts, requiring qualitative immersion.\", \"retrieved_evidence\": [\"Positivist Paradigm: Reality is objective, singular, and measurable; researcher is detached from subject.\", \"Constructivist Paradigm: Reality is socially constructed, multiple, and contextual; researcher interacts directly with participants.\"], \"student_prompt\": \"One methods book says researchers must be completely detached and objective, but another says researchers must immerse themselves with participants. Which is right?\", \"resolution_explanation\": \"These approaches represent two different philosophical paradigms in science, both of which are valid for their respective goals. The detached, objective approach (positivism) is essential for quantitative research, like clinical drug trials or surveys, where personal bias must be eliminated so results can be measured and replicated. The immersive approach (constructivism) is used in qualitative research, like cultural anthropology or deep interviews, where understanding the nuances of human experience requires building trust and understanding context from the inside.\"}}}, \"general_academic::Argument Structure\": {\"domain\": \"general_academic\", \"concept\": \"Argument Structure\", \"explanation\": \"the logical framework of a reasoned argument, consisting of premises (supporting statements), conclusions (the claim being supported), and the logical connections between them\", \"reason\": \"understanding argument structure is essential for constructing persuasive essays, evaluating others' reasoning, and identifying fallacious logic\", \"concrete_examples\": [\"Premise 1: All mammals are warm-blooded. Premise 2: Dolphins are mammals. Conclusion: Dolphins are warm-blooded. (Valid deductive argument.)\", \"A student arguing 'Universities should allow pets in dorms because research shows pets reduce stress' needs evidence linking that research to the specific dorm context.\", \"An editorial arguing 'we should ban plastic bags' must provide premises about environmental harm, available alternatives, and feasibility.\"], \"numerical_examples\": [\"In a formal debate, a team might present 3 main claims, each supported by 2-3 pieces of evidence, for 6-9 total evidence citations.\", \"If 80% of peer-reviewed studies support conclusion X, the argument for X is stronger than if only 20% support it.\", \"A survey of 100 arguments found 47% contained at least one logical fallacy \u2014 nearly half of everyday reasoning is flawed.\"], \"misconceptions\": [[\"An argument with true premises always has a true conclusion\", \"Only VALID deductive arguments guarantee a true conclusion from true premises. Invalid arguments can have true premises but a false conclusion. Inductive arguments, even with strong premises, only make the conclusion probable, not certain. The structure of the argument matters as much as the truth of the premises.\"]], \"analogies\": [\"An argument is like a building \u2014 premises are the foundation and walls (support), the conclusion is the roof (what everything holds up), and the logic is the architecture (how it all fits together).\"], \"prerequisites\": [\"basic literacy\", \"logical reasoning\"], \"formulas\": [\"Deductive: If P\u2081 and P\u2082, then C (conclusion follows necessarily)\", \"Inductive: P\u2081, P\u2082, ... \u2192 C is probable\"], \"document_evidence\": [\"The text states: 'A sound argument has two properties: it is valid (the conclusion follows logically from the premises) and its premises are all true.'\", \"Section 3.2 distinguishes between deductive arguments (certainty) and inductive arguments (probability).\"], \"practice_problems\": [\"Identify the premises and conclusion: 'Students who study regularly perform better on exams. You should study regularly because you want to perform well.'\", \"Is this argument valid? 'All birds can fly. Penguins are birds. Therefore, penguins can fly.' Explain.\"], \"hints\": [\"Look for conclusion indicators: therefore, so, thus, consequently, it follows that.\", \"Look for premise indicators: because, since, given that, as evidenced by.\"], \"follow_up_questions\": [\"What is the difference between a valid argument and a sound argument?\", \"How can an argument be valid but not sound?\"], \"diagnostic_questions\": [\"What is a premise and how does it differ from a conclusion?\", \"Can a false conclusion come from true premises in a valid argument?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The conclusion of an argument is always the very last sentence of a paragraph.\", \"error_reason\": \"Conclusions can appear anywhere in an argument: at the beginning (thesis first), in the middle, or at the end; placement is determined by logical indicators (e.g., 'therefore', 'consequently'), not physical line position.\", \"correct_claim\": \"The conclusion is the claim supported by the premises; it can appear at the beginning, middle, or end of a passage. Look for conclusion indicators like 'therefore' or 'thus,' not physical location.\", \"understanding_probe\": \"Where in a paragraph does the conclusion of an argument have to be located?\", \"expected_answer\": \"It can be located anywhere\u2014at the start, in the middle, or at the end; its role is defined by logical relationships, not sentence position.\"}, {\"prior_erroneous_claim\": \"In Toulmin's model of argumentation, the warrant and the backing are the exact same thing.\", \"error_reason\": \"The warrant is the underlying bridge or general principle connecting the data to the claim; the backing is explicit evidence or authority that supports the warrant itself.\", \"correct_claim\": \"In Toulmin's model, a warrant is the general principle or bridge connecting evidence to the claim, while the backing provides specific supporting evidence or authority for the warrant itself.\", \"understanding_probe\": \"What is the difference between a warrant and its backing in Toulmin's argument model?\", \"expected_answer\": \"The warrant is the logical rule connecting the evidence to the conclusion, while backing is the additional evidence that proves the warrant itself is valid.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Rhetoric and Argumentation: Argument Mapping\", \"page\": 135, \"section\": \"Proposition Decomposition and Premise Weighting\", \"selected_text\": \"An academic editorial comprises 12 distinct propositions. Detailed argument mapping classifies them as follows: 1 central overarching conclusion (C), 3 independent major premises (P1, P2, P3), 6 sub-premises serving as evidentiary support for the major premises (SP1-SP6), and 2 non-argumentative rhetorical concessions.\", \"surrounding_context\": \"Section 2.1 computes the premise-to-conclusion ratio and the percentage of active argumentative propositions.\", \"retrieved_evidence\": [\"Total propositions = 12.\", \"Active argumentative propositions: 1 conclusion + 3 major premises + 6 sub-premises = 10 propositions.\", \"Non-argumentative concessions = 2 propositions.\", \"Argumentative density ratio: Active Propositions / Total Propositions = 10 / 12 = 0.8333 (83.33%).\", \"Total premises supporting conclusion = 3 major + 6 sub-premises = 9 supporting premises.\", \"Premise-to-conclusion ratio = 9 : 1.\"], \"student_prompt\": \"What are the exact argumentative density percentage and premise-to-conclusion ratio calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The text contains 10 active argumentative propositions out of 12 total propositions, giving an argumentative density of 10 / 12 = 0.8333 or 83.33%. With 9 total supporting premises (3 major premises and 6 sub-premises) supporting the single main conclusion, the premise-to-conclusion ratio is exactly 9:1. The text directly establishes the density at 83.33% and the premise ratio at 9:1.\", \"calculated_result\": \"Argumentative Density = 83.33%, Premise-to-Conclusion Ratio = 9:1\"}, \"pattern_b_derive\": {\"document_title\": \"Formal Logic and Syllogistic Structures\", \"page\": 142, \"section\": \"Evaluating Enthymemes (Missing Premises)\", \"selected_text\": \"An enthymeme is an incomplete syllogism where one or more premises are unstated. Consider the enthymeme: 'Socrates is mortal, because Socrates is human.'\", \"surrounding_context\": \"Derive the unstated warrant (major premise) required to make this deductive argument structurally valid.\", \"retrieved_evidence\": [\"Expressed Stated Premise (Minor Premise): Socrates is human.\", \"Expressed Conclusion: Socrates is mortal.\", \"Structural requirement: Deductive Modus Ponens (If H, then M).\"], \"student_prompt\": \"How do we derive the unstated major premise needed to complete this enthymeme into a valid categorical syllogism?\", \"target_response\": \"To derive the missing premise: Identify the terms in the argument. The minor term is 'Socrates' (subject of conclusion) and the major term is 'mortal' (predicate of conclusion). The stated premise connects the minor term to the middle term: 'Socrates is human.' To link the middle term ('human') to the major term ('mortal') in a valid universal syllogism, the unstated major premise must state: 'All humans are mortal.' Inserting 'All humans are mortal' completes the standard categorical syllogism (All H are M; S is H; therefore S is M).\", \"formula\": \"Missing Premise: All [Middle Term] are [Major Term] -> 'All humans are mortal'\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact annual print circulation figures for The New Yorker magazine in 2024\", \"actual_topic\": \"Toulmin argument model (claim, data, warrant, backing, rebuttal, qualifier) and enthymemes\", \"authoritative_source\": \"the Alliance for Audited Media (AAM) consumer magazine publisher circulation statements\", \"document_title\": \"Foundations of Rhetorical Argument\", \"page\": 152, \"section\": \"The Toulmin Model of Argumentation\", \"selected_text\": \"Stephen Toulmin proposed that practical everyday arguments consist of six functional elements: Claims, Data, Warrants, Backing, Modal Qualifiers, and Rebuttals.\", \"surrounding_context\": \"Modal qualifiers indicate the degree of certainty or conditionality of the author's claim.\", \"retrieved_evidence\": [\"Figure 3.1: Diagrammatic flow of Toulmin argument components.\"], \"student_prompt\": \"According to this document, what was the average print circulation of The New Yorker in 2024?\"}, {\"unmentioned_term\": \"the retail price of the software package Scrivener 3 for macOS\", \"actual_topic\": \"Rogerian argument structure and consensus-building rhetoric\", \"authoritative_source\": \"Literature & Latte commercial software retail pricing pages\", \"document_title\": \"Foundations of Rhetorical Argument\", \"page\": 158, \"section\": \"Rogerian Argument and Common Ground\", \"selected_text\": \"Rogerian rhetoric emphasizes empathetic listening, acknowledging opposing perspectives, and identifying common ground before proposing solutions.\", \"surrounding_context\": \"This non-adversarial framework reduces psychological reactance in polarizing policy disputes.\", \"retrieved_evidence\": [\"Table 3.3: Comparison of Classical Aristotelian versus Rogerian argument structures.\"], \"student_prompt\": \"What does this text state regarding the purchase price of Scrivener 3 for Mac?\"}], \"grounded_paraphrase\": {\"document_title\": \"Rhetoric and Philosophical Logic\", \"page\": 130, \"section\": \"The Argument Structure Axiom\", \"selected_text\": \"An argument designates a structured constellation of interconnected declarative propositions comprising one or more premises adduced to provide evidential or logical justification for a designated ultimate conclusion.\", \"surrounding_context\": \"Disconnected assertions devoid of supportive inferential linkages fail to satisfy the formal criteria of an argument.\", \"retrieved_evidence\": [\"Page 130: 'An argument is not simply expressing an opinion; it is a set of claims where reasons (premises) are offered to support a main point (conclusion).'\"], \"student_prompt\": \"Can you explain what an argument is in simple language based on this text?\", \"faithful_paraphrase\": \"This passage explains that in logic, an argument is not an angry disagreement or shouting match. Instead, it is a thoughtful chain of ideas where you offer specific reasons and evidence (called premises) to show why your main point (the conclusion) is true. Without reasons to back up a statement, an assertion is just an unsupported opinion, not an argument.\"}, \"conflict_handling\": {\"document_title\": \"Practical vs Formal Logic Guide\", \"page\": 165, \"section\": \"Deductive vs Inductive Argument Evaluation Criteria\", \"selected_text\": \"Deductive arguments are evaluated under the binary standards of validity and soundness, where true premises guarantee the conclusion with 100% certainty.\", \"surrounding_context\": \"Inductive arguments deal with probabilities and are evaluated on a continuous spectrum of strength and cogency, where true premises render the conclusion probable, but never absolute.\", \"retrieved_evidence\": [\"Deductive Evaluation: Binary (Valid/Invalid, Sound/Unsound). Absolute guarantee of truth.\", \"Inductive Evaluation: Continuous spectrum (Weak/Strong, Uncogent/Cogent). Probabilistic support, never 100% guaranteed.\"], \"student_prompt\": \"One logic textbook says an argument is either valid or invalid, but my writing teacher said my paper was 'moderately strong.' Are they using conflicting rules?\", \"resolution_explanation\": \"These two evaluations are using rules designed for two different types of arguments. In formal deductive arguments (like mathematics), logic is strictly black-and-white: the structure is either 100% valid or invalid. In inductive arguments (like empirical science or persuasive essays), arguments deal with real-world evidence and probabilities. They cannot guarantee an absolute conclusion, so they are judged on a continuous scale of being weak, moderately strong, or highly strong based on how likely the evidence makes the conclusion.\"}}}, \"general_academic::Evidence Evaluation\": {\"domain\": \"general_academic\", \"concept\": \"Evidence Evaluation\", \"explanation\": \"the process of assessing the quality, relevance, and strength of evidence used to support claims, considering source reliability, methodology, sample size, and potential biases\", \"reason\": \"it protects against misinformation and enables informed decisions by distinguishing strong evidence from weak, biased, or fabricated claims\", \"concrete_examples\": [\"A peer-reviewed medical study is stronger evidence than a single doctor's opinion because it has been vetted by other experts.\", \"A product review from a verified purchaser is more reliable than a review from an anonymous account with no purchase history.\", \"Government statistics from census data are generally more reliable than self-reported online surveys.\"], \"numerical_examples\": [\"A meta-analysis combining 50 studies with a total n=15,000 provides stronger evidence than any single study alone.\", \"A study with 95% confidence level and p=0.01 provides stronger evidence against the null hypothesis than one with p=0.04.\", \"If a study has an attrition rate of 40% (many participants dropped out), its results are less trustworthy.\"], \"misconceptions\": [[\"Published research is always correct and unbiased\", \"Publication bias, funding conflicts, methodological flaws, and even fraud affect published research. Studies funded by companies are more likely to report favorable results. Replication crises in psychology and medicine show that many published findings fail to reproduce. Always evaluate methodology, not just the journal name.\"]], \"analogies\": [\"Evaluating evidence is like being a judge in a courtroom \u2014 you must weigh the testimony (evidence) by considering the witness's (source's) credibility, consistency, and potential motives before reaching a verdict.\"], \"prerequisites\": [\"critical thinking\", \"basic statistics\"], \"formulas\": [\"Hierarchy of evidence: Systematic reviews > RCTs > Cohort studies > Case studies > Expert opinion\"], \"document_evidence\": [\"The text presents the evidence pyramid: 'Systematic reviews and meta-analyses represent the strongest form of evidence, while anecdotal reports represent the weakest.'\", \"Section 4.3 discusses common biases: confirmation bias, publication bias, selection bias, and recall bias.\"], \"practice_problems\": [\"Rank these in order of evidence strength: a celebrity endorsement, a randomized controlled trial, a case study, a meta-analysis.\", \"A pharmaceutical company funds a study of its own drug and reports positive results. What concerns should you have?\"], \"hints\": [\"Ask: Who conducted the study? Who funded it? Was there a control group? How large was the sample?\", \"Replication is key \u2014 a finding is more trustworthy if multiple independent groups have confirmed it.\"], \"follow_up_questions\": [\"What is the 'replication crisis' and why does it matter?\", \"How does peer review work, and what are its limitations?\"], \"diagnostic_questions\": [\"Is a study published in a prestigious journal automatically good evidence?\", \"What makes anecdotal evidence less reliable than statistical evidence?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"A personal anecdotal story from a friend on social media carries the same scientific evidential weight as a peer-reviewed meta-analysis.\", \"error_reason\": \"In the hierarchy of scientific evidence, individual anecdotes are at the bottom because they are subject to recall bias, placebo effects, and lack controls; peer-reviewed meta-analyses sit at the very top.\", \"correct_claim\": \"Anecdotal stories have very low evidential weight because they lack control groups, blinding, and statistical power. Systematic reviews and peer-reviewed meta-analyses provide the highest level of empirical evidence.\", \"understanding_probe\": \"Where do personal anecdotes rank on the hierarchy of scientific evidence, and why?\", \"expected_answer\": \"At the very bottom, because anecdotes cannot control for confounding factors, bias, or the placebo effect, and cannot establish cause-and-effect.\"}, {\"prior_erroneous_claim\": \"Evidence from an observational study proves that the exposure directly caused the observed outcome.\", \"error_reason\": \"Observational studies can identify associations and correlations, but confounding variables and reverse causation prevent them from proving direct causality without randomized controlled trials.\", \"correct_claim\": \"Observational evidence establishes correlation and association, not direct causation. Uncontrolled confounding variables can create strong statistical associations between unrelated factors.\", \"understanding_probe\": \"Can an observational study showing that people who drink coffee live longer prove that coffee causes longevity?\", \"expected_answer\": \"No, because observational studies cannot eliminate confounding variables (like diet, income, or lifestyle); only randomized controlled trials can establish direct causation.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Evidence-Based Practice and Clinical Epidemiology\", \"page\": 178, \"section\": \"Calculating Relative Risk (RR) and Number Needed to Treat (NNT)\", \"selected_text\": \"In a randomized controlled trial of 1,000 high-risk patients, 500 received a new preventative therapy and 500 received a control placebo. Over two years, adverse clinical events occurred in 25 out of 500 patients in the treatment group (Event Rate = 5.0%), and in 50 out of 500 patients in the control group (Event Rate = 10.0%).\", \"surrounding_context\": \"Section 2.1 computes the Relative Risk (RR), Relative Risk Reduction (RRR), Absolute Risk Reduction (ARR), and Number Needed to Treat (NNT).\", \"retrieved_evidence\": [\"Experimental Event Rate: EER = 25 / 500 = 0.050 (5.0%). Control Event Rate: CER = 50 / 500 = 0.100 (10.0%).\", \"Relative Risk: RR = EER / CER = 0.050 / 0.100 = 0.500 (50.0%).\", \"Relative Risk Reduction: RRR = 1 - RR = 1 - 0.500 = 0.500 (50.0% relative reduction).\", \"Absolute Risk Reduction: ARR = CER - EER = 0.100 - 0.050 = 0.050 (5.0% absolute reduction).\", \"Number Needed to Treat: NNT = 1 / ARR = 1 / 0.050 = 20.0 patients.\"], \"student_prompt\": \"What are the exact Relative Risk, Absolute Risk Reduction, and Number Needed to Treat calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The Relative Risk is RR = 0.050 / 0.100 = 0.500, representing a 50% relative risk reduction. The Absolute Risk Reduction is ARR = 0.100 - 0.050 = 0.050 (a 5.0 percentage point reduction in event risk). The Number Needed to Treat is NNT = 1 / ARR = 1 / 0.050 = 20.0 patients. This means 20 patients must receive the therapy to prevent one adverse event. The text directly establishes RR at 0.50, ARR at 5.0%, and NNT at 20.\", \"calculated_result\": \"RR = 0.50 (50%), ARR = 0.05 (5.0%), NNT = 20 patients\"}, \"pattern_b_derive\": {\"document_title\": \"Evaluating Scientific Evidence: Diagnostic Accuracy\", \"page\": 185, \"section\": \"Deriving Positive Predictive Value from Sensitivity and Specificity\", \"selected_text\": \"Diagnostic test evaluation depends on sensitivity, specificity, and disease prevalence.\", \"surrounding_context\": \"Derive the Positive Predictive Value (PPV) for a population of 10,000 individuals where disease prevalence is 1.0% (100 sick people, 9,900 healthy people), test sensitivity is 95.0%, and test specificity is 90.0%.\", \"retrieved_evidence\": [\"Formulas: True Positives (TP) = Sick Population * Sensitivity; False Positives (FP) = Healthy Population * (1 - Specificity); PPV = TP / (TP + FP).\", \"Parameters: Population = 10,000; Prevalence = 1.0% (100 sick, 9,900 healthy); Sensitivity = 95.0%; Specificity = 90.0%.\"], \"student_prompt\": \"How do we derive the Positive Predictive Value (PPV) of this diagnostic test using the population parameters?\", \"target_response\": \"To derive the Positive Predictive Value: First compute True Positives: 100 sick people * 0.95 sensitivity = 95 true positive test results. Next compute False Positives among healthy individuals: 9,900 healthy people * (1 - 0.90 specificity) = 9,900 * 0.10 = 990 false positive test results. Sum all positive results: 95 + 990 = 1,085 positive tests. Finally, calculate PPV by dividing true positives by total positive tests: PPV = 95 / 1,085 \u2248 0.0876, or 8.76%. Despite 95% sensitivity and 90% specificity, a patient testing positive has only an 8.76% chance of actually having the disease due to low population prevalence.\", \"formula\": \"PPV = 95 / (95 + 990) = 8.76%\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact legal settlement amount paid by Pfizer in the 2009 Bextra off-label marketing case\", \"actual_topic\": \"the hierarchy of evidence, systematic reviews, randomized controlled trials, and risk metrics\", \"authoritative_source\": \"the United States Department of Justice official criminal settlement press announcements\", \"document_title\": \"Principles of Evidence Evaluation\", \"page\": 195, \"section\": \"The Evidence Hierarchy Pyramid\", \"selected_text\": \"The evidence hierarchy ranks study designs from systematic reviews and meta-analyses at the apex to in vitro laboratory models and expert opinion at the base.\", \"surrounding_context\": \"Risk of bias decreases monotonically as researchers move upward toward blinded randomized trials.\", \"retrieved_evidence\": [\"Figure 3.2: The Oxford Centre for Evidence-Based Medicine Levels of Evidence pyramid.\"], \"student_prompt\": \"According to this text, what exact dollar amount did Pfizer pay in the 2009 Bextra settlement?\"}, {\"unmentioned_term\": \"the current annual salary of the editor-in-chief of The Lancet\", \"actual_topic\": \"evaluating peer review rigor, publication bias, and funnel plot asymmetry\", \"authoritative_source\": \"Elsevier corporate executive compensation disclosures\", \"document_title\": \"Principles of Evidence Evaluation\", \"page\": 200, \"section\": \"Publication Bias and Funnel Plots\", \"selected_text\": \"Publication bias occurs when studies with statistically significant positive findings are published more readily than studies with null results.\", \"surrounding_context\": \"Asymmetry in funnel plots alerts researchers to selective non-reporting of small-sample negative trials.\", \"retrieved_evidence\": [\"Section 3.5: Egger's regression test for detecting funnel plot publication asymmetry.\"], \"student_prompt\": \"What does the reading cite as the annual salary of the chief editor of The Lancet?\"}], \"grounded_paraphrase\": {\"document_title\": \"Epistemology of Evidence\", \"page\": 172, \"section\": \"The Principle of Total Evidence\", \"selected_text\": \"Carnap's principle of total evidence dictates that in apportioning credence to an empirical hypothesis, an epistemic agent must consider the totality of accessible relevant evidence, rather than selectively privileging confirming subsets while disregarding disconfirming observational data.\", \"surrounding_context\": \"Cherry-picking subsets of data constitutes a fundamental violation of normative scientific rationality.\", \"retrieved_evidence\": [\"Page 172: 'The principle of total evidence means you must look at all available data when judging a claim, not just the pieces that support your personal view.'\"], \"student_prompt\": \"Can you explain the principle of total evidence based on this text in simple terms?\", \"faithful_paraphrase\": \"This passage explains the rule of total evidence: whenever you evaluate whether an idea is true, you are required to look at all the facts, both the evidence that supports it and the evidence that contradicts it. You cannot cherry-pick only the pieces of data that agree with what you already want to believe while ignoring the rest.\"}, \"conflict_handling\": {\"document_title\": \"Clinical Evidence Controversies\", \"page\": 208, \"section\": \"Relative Risk vs Absolute Risk Communication\", \"selected_text\": \"Pharmaceutical advertisements frequently emphasize Relative Risk Reduction (e.g., 'Drug X cuts heart attack risk by 50%!'), which sounds dramatic.\", \"surrounding_context\": \"Independent medical journals insist on reporting Absolute Risk Reduction, which reveals that the risk dropped from 2 in 100 to 1 in 100\u2014an absolute decrease of only 1 percentage point.\", \"retrieved_evidence\": [\"Drug Ad Claim: '50% reduction in risk' (Relative Risk Reduction: from 2% down to 1% is a 50% relative drop).\", \"Independent Review: Absolute Risk Reduction is only 1.0% (You must treat 100 patients for 1 person to benefit).\"], \"student_prompt\": \"An advertisement claimed a medication reduces stroke risk by 50%, but a consumer health report said it only helps 1 in 100 people. Are they lying?\", \"resolution_explanation\": \"Neither source is lying; they are reporting the exact same data using two different statistical metrics. If the baseline risk of having a stroke is 2% and the drug lowers it to 1%, cutting the risk from 2% to 1% is a 50% relative reduction (the advertisement's number). However, the absolute difference between 2% and 1% is only 1 percentage point, which means 99 out of 100 people taking the drug would have seen no difference, while 1 in 100 was helped. Marketers use relative risk because it sounds much more impressive, but doctors prefer absolute risk because it reflects realistic personal benefit.\"}}}, \"general_academic::Logical Fallacies\": {\"domain\": \"general_academic\", \"concept\": \"Logical Fallacies\", \"explanation\": \"errors in reasoning that undermine the logic of an argument, making the conclusion unreliable even if it sounds persuasive\", \"reason\": \"recognizing fallacies is essential for evaluating arguments, avoiding manipulation, and constructing sound reasoning in academic and everyday contexts\", \"concrete_examples\": [\"Ad hominem: 'You can't trust the professor's climate research because she drives an SUV.' (Attacks the person, not the argument.)\", \"Straw man: 'My opponent wants to reduce military spending, so they clearly want to leave us defenseless.' (Misrepresents the position.)\", \"False dichotomy: 'You're either with us or against us.' (Ignores middle ground and other options.)\"], \"numerical_examples\": [\"Hasty generalization: 'I surveyed 3 people and all 3 support Policy X, so 100% of people must support it.' (Sample far too small.)\", \"Gambler's fallacy: 'The roulette wheel landed on red 5 times, so black is due.' (Each spin is independent; P(black) is still ~47%.)\", \"Base rate fallacy: A test with 99% accuracy applied to a population where only 1% are positive means most positives are false positives.\"], \"misconceptions\": [[\"If someone uses a fallacy, their conclusion must be wrong\", \"A fallacious argument means the reasoning is flawed, not that the conclusion is necessarily false. The conclusion might still be true \u2014 it's just not properly supported by the given argument. This is called the 'fallacy fallacy' \u2014 concluding something is false BECAUSE the argument for it contains a fallacy.\"]], \"analogies\": [\"Logical fallacies are like optical illusions for the mind \u2014 they look convincing at first glance but fall apart under careful examination.\"], \"prerequisites\": [\"basic literacy\", \"logical reasoning\"], \"formulas\": [\"No formula \u2014 fallacy identification requires recognizing patterns in reasoning\"], \"document_evidence\": [\"The text lists 15 common fallacies: ad hominem, straw man, false dichotomy, appeal to authority, red herring, slippery slope, circular reasoning, hasty generalization, post hoc, tu quoque, bandwagon, false cause, appeal to emotion, equivocation, and burden of proof reversal.\", \"Section 5.2 provides real-world examples of each fallacy from media and political discourse.\"], \"practice_problems\": [\"Identify the fallacy: 'If we allow students to use calculators on tests, next they'll want to use AI to write all their papers.' (Slippery slope)\", \"Identify the fallacy: 'This diet must work because a famous actress uses it.' (Appeal to authority/celebrity)\"], \"hints\": [\"Ask: Does the argument actually support the conclusion, or does it distract, mislead, or oversimplify?\", \"Common patterns: attacking the person (ad hominem), misrepresenting the argument (straw man), offering only two options (false dichotomy).\"], \"follow_up_questions\": [\"Can an argument contain a fallacy and still reach a correct conclusion?\", \"How can you politely point out a fallacy in someone's argument?\"], \"diagnostic_questions\": [\"What is the difference between ad hominem and a legitimate criticism of someone's expertise?\", \"Give an example of the post hoc fallacy from everyday life.\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"The ad hominem fallacy occurs whenever you politely disagree with someone's argument.\", \"error_reason\": \"An ad hominem fallacy occurs specifically when someone attacks the person's character, background, or physical traits instead of addressing the substance and evidence of their argument; polite disagreement is not ad hominem.\", \"correct_claim\": \"An ad hominem fallacy involves rejecting an argument by attacking the opponent's personal traits, character, or background rather than engaging with the logic or evidence of the argument itself.\", \"understanding_probe\": \"If someone says 'Your economic proposal is flawed because your inflation numbers are mathematically wrong,' is that an ad hominem attack?\", \"expected_answer\": \"No, that is a legitimate critique of the argument's factual evidence, not an ad hominem attack on the person's character.\"}, {\"prior_erroneous_claim\": \"If an argument contains a logical fallacy, its conclusion is automatically guaranteed to be completely false in reality.\", \"error_reason\": \"This is itself the 'fallacy fallacy' (argumentum ad logicam); an argument can use terrible or fallacious logic while its conclusion happens to be true in the real world.\", \"correct_claim\": \"The 'fallacy fallacy' reminds us that having fallacious reasoning does not prove the conclusion is false; it only proves the argument failed to justify the conclusion.\", \"understanding_probe\": \"If someone argues 'The Earth is round because my psychic told me in a dream,' their argument is fallacious, but is the Earth actually flat?\", \"expected_answer\": \"No, the conclusion is still true (the Earth is round); committing a fallacy means the argument is bad, not that the conclusion itself is automatically false.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Fallacy Analysis and Rhetorical Auditing\", \"page\": 220, \"section\": \"Quantifying Fallacy Incidence in Public Debates\", \"selected_text\": \"An audit of 150 arguments delivered in a televised legislative debate identified 45 fallacious arguments. Taxonomic classification categorized the fallacies as: 18 Ad Hominem attacks, 12 Straw Man distortions, 9 Slippery Slope projections, and 6 False Dilemmas.\", \"surrounding_context\": \"Section 2.1 computes the total fallacy rate and the percentage distribution of each fallacy category among the detected fallacies.\", \"retrieved_evidence\": [\"Total evaluated arguments = 150; Total detected fallacies = 45.\", \"Overall fallacy incidence rate = 45 / 150 = 0.300 (30.0%).\", \"Fallacy distribution percentages (out of 45 fallacies): Ad Hominem = 18 / 45 = 0.400 (40.0%); Straw Man = 12 / 45 = 0.2667 (26.67%); Slippery Slope = 9 / 45 = 0.200 (20.0%); False Dilemma = 6 / 45 = 0.1333 (13.33%).\"], \"student_prompt\": \"What are the exact overall fallacy incidence rate and the percentage breakdown of the four fallacy types calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The overall fallacy incidence rate across all debate arguments is 45 / 150 = 30.0%. Among the 45 detected fallacies, the percentage breakdown is: Ad Hominem accounts for 40.0% (18 / 45), Straw Man accounts for 26.67% (12 / 45), Slippery Slope accounts for 20.0% (9 / 45), and False Dilemma accounts for 13.33% (6 / 45). The text directly establishes the overall fallacy rate at 30.0% and the four specific percentages.\", \"calculated_result\": \"Fallacy Rate = 30.0%; Ad Hominem = 40.0%, Straw Man = 26.67%, Slippery Slope = 20.0%, False Dilemma = 13.33%\"}, \"pattern_b_derive\": {\"document_title\": \"Formal Logic: Denying the Antecedent and Affirming the Consequent\", \"page\": 228, \"section\": \"Differentiating Formal Fallacies via Truth Tables\", \"selected_text\": \"Consider the conditional proposition: 'If it rains (P), the street is wet (Q).' (P -> Q).\", \"surrounding_context\": \"Derive why 'The street is wet (Q), therefore it rained (P)' is a formal fallacy (Affirming the Consequent) using truth values.\", \"retrieved_evidence\": [\"Premise 1: P -> Q (True). Premise 2: Q is True. Concluded Claim: Therefore P is True.\", \"Counterexample analysis: Alternative causes for Q (e.g., street sweepers, fire hydrants, lawn sprinklers) can make Q True while P is False.\"], \"student_prompt\": \"How do we derive why Affirming the Consequent is an invalid logical deduction?\", \"target_response\": \"To derive why Affirming the Consequent is a formal fallacy: The rule P -> Q states only that rain guarantees a wet street; it does not claim that rain is the ONLY way a street can get wet. When we observe that the street is wet (Q is true), that condition could easily be produced by a different cause, such as a broken water main, a street cleaning truck, or lawn sprinklers, while it did not rain at all (P is false). Because a situation exists where both premises are true but the conclusion is false (Q = True while P = False), the argument form is invalid.\", \"formula\": \"Invalid Form: [(P -> Q) and Q] does not imply P\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact gross profit of the book 'Thank You for Arguing' by Jay Heinrichs\", \"actual_topic\": \"informal fallacies, formal fallacies, cognitive biases, and circular reasoning (begging the question)\", \"authoritative_source\": \"Penguin Random House corporate royalty and book sales financial ledgers\", \"document_title\": \"A Guide to Logical Fallacies\", \"page\": 238, \"section\": \"Begging the Question and Circular Reasoning\", \"selected_text\": \"Begging the question (petitio principii) occurs when an argument's premises assume the truth of the conclusion they are supposed to prove.\", \"surrounding_context\": \"The reasoning is circular because the claim is used as its own justification without external evidence.\", \"retrieved_evidence\": [\"Section 3.2: Structural analysis of circular syllogisms.\"], \"student_prompt\": \"According to this text, how much money in gross profits has 'Thank You for Arguing' generated?\"}, {\"unmentioned_term\": \"the legal defense retainers charged by prominent criminal defense attorneys in Manhattan\", \"actual_topic\": \"fallacies of relevance including red herring, tu quoque, and appeal to authority\", \"authoritative_source\": \"New York State Bar Association attorney billing surveys\", \"document_title\": \"A Guide to Logical Fallacies\", \"page\": 242, \"section\": \"Fallacies of Defective Induction\", \"selected_text\": \"The appeal to unqualified authority (argumentum ad verecundiam) cites an authority who lacks genuine expertise in the disputed subject matter.\", \"surrounding_context\": \"Celebrity endorsements of nutritional supplements represent classic appeals to unqualified authority.\", \"retrieved_evidence\": [\"Table 3.4: Criteria for determining legitimate expert authority.\"], \"student_prompt\": \"What does this text state regarding standard attorney retainer fees in Manhattan?\"}], \"grounded_paraphrase\": {\"document_title\": \"Informal Logic Foundations\", \"page\": 215, \"section\": \"The Logical Fallacy Axiom\", \"selected_text\": \"A logical fallacy designates an error in discursive reasoning that fatally impairs the inferential cogency or structural validity of an argument, rendering its articulated premises structurally or epistemically incompetent to substantiate its purported conclusion.\", \"surrounding_context\": \"Fallacies frequently mimic valid deductive or inductive forms, imparting an illusory facade of persuasiveness.\", \"retrieved_evidence\": [\"Page 215: 'A fallacy is a flaw in reasoning that ruins an argument's logic, meaning its premises do not actually prove its conclusion, even if it sounds persuasive.'\"], \"student_prompt\": \"Can you explain what a logical fallacy is in simple language based on this text?\", \"faithful_paraphrase\": \"This passage explains that a logical fallacy is a breakdown in reasoning that ruins an argument. Even though the argument might sound clever or convincing on the surface, its premises don't actually support or prove the conclusion. Spotting a fallacy means recognizing that the logical bridge between the facts and the conclusion is broken.\"}, \"conflict_handling\": {\"document_title\": \"Fallacy Identification in Practice\", \"page\": 250, \"section\": \"Legitimate Authority vs Fallacious Appeal to Authority\", \"selected_text\": \"Some debate manuals claim that whenever an arguer cites an authority figure, they are committing the fallacy of Appeal to Authority (argumentum ad verecundiam).\", \"surrounding_context\": \"Formal epistemologists distinguish fallacious appeals (citing a celebrity or an expert outside their field) from legitimate appeals to relevant, peer-reviewed consensus experts within their specialized domain.\", \"retrieved_evidence\": [\"Misconception: Citing any expert is always a fallacy.\", \"Epistemic Standard: Citing a qualified expert speaking within their domain of expertise regarding established scientific consensus is a valid inductive warrant, not a fallacy.\"], \"student_prompt\": \"My friend said citing a climate scientist on global warming is an 'Appeal to Authority' fallacy. Is citing an expert really a logical fallacy?\", \"resolution_explanation\": \"Citing a qualified expert speaking within their actual field of expertise is NOT a logical fallacy; it is legitimate inductive evidence. The 'Appeal to Authority' fallacy occurs only when someone cites an authority who has no relevant training in the topic (like citing a famous actor on medical treatments), when the expert is heavily biased, or when the expert's opinion contradicts the overwhelming consensus of their peers. Citing a qualified climate scientist on climate data is an entirely valid appeal to relevant expertise.\"}}}, \"general_academic::Study Design\": {\"domain\": \"general_academic\", \"concept\": \"Study Design\", \"explanation\": \"the plan and structure of a research study that determines how data will be collected, what comparisons will be made, and how variables will be controlled to answer a research question\", \"reason\": \"good study design minimizes bias, maximizes validity, and ensures that conclusions drawn from data are trustworthy and meaningful\", \"concrete_examples\": [\"A randomized controlled trial (RCT) randomly assigns participants to treatment or control groups to test a drug's effectiveness.\", \"A longitudinal study follows the same group of people for 20 years to study how diet affects heart disease risk.\", \"A cross-sectional study surveys 5,000 people at a single point in time to estimate the prevalence of depression.\"], \"numerical_examples\": [\"Power analysis: To detect a medium effect (d=0.5) with 80% power at \u03b1=0.05, you need approximately 64 participants per group.\", \"A study with n=10 per group has very low power (~17%) to detect a small effect, meaning it will likely miss real differences.\", \"Stratified sampling: if 40% of the population is under 30, the sample should also be ~40% under 30.\"], \"misconceptions\": [[\"More data always means a better study\", \"Data quality matters more than quantity. A well-designed study with 200 carefully selected participants can be more informative than a poorly designed study with 10,000 participants affected by selection bias, measurement error, or confounding variables.\"]], \"analogies\": [\"Study design is like building a house's blueprint \u2014 you plan every room (variable), doorway (measurement), and structural support (control) BEFORE construction (data collection) begins.\"], \"prerequisites\": [\"basic statistics\", \"research methods\"], \"formulas\": [\"Power = P(reject H\u2080 | H\u2081 true)\", \"Sample size calculations depend on effect size, power, and \u03b1\"], \"document_evidence\": [\"The text states: 'The choice of study design should be guided by the research question, ethical constraints, available resources, and the type of evidence needed.'\", \"Figure 6.1 compares the strengths and weaknesses of experimental, quasi-experimental, and observational designs.\"], \"practice_problems\": [\"Design a study to test whether meditation reduces exam anxiety in college students. Specify the design type, variables, control group, and outcome measure.\", \"Why would a researcher choose an observational study over an experiment to study the effects of smoking?\"], \"hints\": [\"Match your design to your question: causal questions need experiments; prevalence questions need surveys.\", \"Always identify: independent variable, dependent variable, confounding variables, and control conditions.\"], \"follow_up_questions\": [\"What is the difference between a between-subjects and within-subjects design?\", \"How does blinding improve the validity of a study?\"], \"diagnostic_questions\": [\"What makes a randomized controlled trial the 'gold standard'?\", \"What is a confounding variable and why is it a problem?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"In a cross-sectional study, researchers follow a group of subjects forward in time over 20 years to see who develops disease.\", \"error_reason\": \"Following subjects forward in time over years is a prospective cohort study; a cross-sectional study assesses exposure and outcome simultaneously at a single snapshot in time.\", \"correct_claim\": \"A cross-sectional study measures exposure and disease status at a single point in time (a snapshot). Following people forward over years is a prospective cohort study.\", \"understanding_probe\": \"What is the difference between a cross-sectional study and a prospective cohort study?\", \"expected_answer\": \"A cross-sectional study observes data at a single snapshot in time, whereas a prospective cohort study tracks disease-free individuals forward across years into the future.\"}, {\"prior_erroneous_claim\": \"Randomization in a clinical trial is done so that patients can freely choose which treatment they prefer.\", \"error_reason\": \"Randomization randomly allocates subjects to treatment or control arms by chance alone to balance known and unknown confounding variables equally across groups.\", \"correct_claim\": \"Randomization assigns participants to experimental groups purely by chance, preventing selection bias and ensuring that both known and unknown confounding factors are evenly distributed.\", \"understanding_probe\": \"Why do randomized controlled trials use random assignment rather than letting patients choose their treatment?\", \"expected_answer\": \"To eliminate selection bias and ensure that confounding variables (like age, health status, and motivation) are evenly balanced between the two groups.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Epidemiology and Experimental Study Design\", \"page\": 265, \"section\": \"Odds Ratios in Retrospective Case-Control Studies\", \"selected_text\": \"A retrospective case-control study investigates dietary pesticide exposure and rare lymphoma. The study enrols 100 lymphoma cases and 200 matched disease-free controls. Among the 100 cases, 60 were exposed to high pesticides (a = 60, b = 40). Among the 200 controls, 40 were exposed to high pesticides (c = 40, d = 160).\", \"surrounding_context\": \"Section 2.1 computes the exposure Odds Ratio (OR = (a * d) / (b * c)) and its interpretation.\", \"retrieved_evidence\": [\"Formula: Odds Ratio = (a * d) / (b * c).\", \"Table counts: a (Exposed cases) = 60; b (Unexposed cases) = 40; c (Exposed controls) = 40; d (Unexposed controls) = 160.\", \"Step-by-step arithmetic from text: Numerator = a * d = 60 * 160 = 9,600. Denominator = b * c = 40 * 40 = 1,600.\", \"Odds Ratio calculation: OR = 9,600 / 1,600 = 6.00.\", \"Interpretation: Cases have 6.0 times the odds of pesticide exposure compared to controls.\"], \"student_prompt\": \"What is the exact Odds Ratio calculated in Section 2.1 for the case-control study?\", \"target_response\": \"Following the explicit steps in Section 2.1: In the case-control 2x2 table, numerator cross-product is a * d = 60 * 160 = 9,600. The denominator cross-product is b * c = 40 * 40 = 1,600. Dividing numerator by denominator yields an Odds Ratio of OR = 9,600 / 1,600 = 6.00. The text directly establishes that individuals with lymphoma had 6.0 times higher odds of previous high pesticide exposure compared to disease-free controls.\", \"calculated_result\": \"Odds Ratio OR = 6.00\"}, \"pattern_b_derive\": {\"document_title\": \"Clinical Trial Methodology: Blinding Protocols\", \"page\": 272, \"section\": \"Double-Blind vs Single-Blind Architecture\", \"selected_text\": \"Clinical trial blinding minimizes performance bias and detection bias.\", \"surrounding_context\": \"Derive why double-blinding (blinding both participants and investigators) is methodologically superior to single-blinding in subjective pain outcome assessment.\", \"retrieved_evidence\": [\"Biases controlled: Participant blinding prevents placebo response and lifestyle modifications. Investigator blinding prevents differential assessment, unconscious prompting, and co-intervention bias.\", \"Objective: Derive why investigator knowledge distorts subjective outcomes even when patients are blinded.\"], \"student_prompt\": \"How do we derive why double-blinding is necessary even when patients are already blinded in pain trials?\", \"target_response\": \"To derive the necessity of double-blinding: If only patients are blinded (single-blind), an investigator who knows which patient received the active drug may unconsciously alter their clinical interactions\u2014such as probing more deeply for side effects, offering subtle verbal encouragement, or scoring subjective pain scales more favorably for active drug recipients. This investigator knowledge introduces severe diagnostic assessment bias and performance bias. Double-blinding removes investigator expectations completely, ensuring that subjective ratings reflect true pharmacological efficacy rather than subconscious observer bias.\", \"formula\": \"Double-Blind = Controls Participant Placebo Effect + Investigator Assessment Bias\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact construction contract cost of the National Institutes of Health Clinical Center in Bethesda, Maryland\", \"actual_topic\": \"randomized controlled trials, cohort studies, case-control studies, and confounding variables\", \"authoritative_source\": \"the United States General Services Administration (GSA) federal capital project ledger\", \"document_title\": \"Principles of Epidemiological Study Design\", \"page\": 282, \"section\": \"Controlling Confounding through Matching\", \"selected_text\": \"Individual matching pairs each case with one or more controls possessing identical demographic confounders such as age and sex.\", \"surrounding_context\": \"Overmatching must be avoided to prevent eliminating the primary exposure of interest.\", \"retrieved_evidence\": [\"Section 3.3: Statistical power considerations in 1:M matched case-control designs.\"], \"student_prompt\": \"According to this document, what was the construction cost of the NIH Clinical Center in Bethesda?\"}, {\"unmentioned_term\": \"the total number of patient hospital beds at Massachusetts General Hospital in Boston\", \"actual_topic\": \"loss to follow-up, attrition bias, and intention-to-treat analysis\", \"authoritative_source\": \"the Massachusetts Department of Public Health licensed healthcare facility rosters\", \"document_title\": \"Principles of Epidemiological Study Design\", \"page\": 286, \"section\": \"Intention-to-Treat vs Per-Protocol Analysis\", \"selected_text\": \"Intention-to-treat (ITT) analysis preserves the integrity of randomization by evaluating participants in their assigned groups regardless of protocol adherence.\", \"surrounding_context\": \"Per-protocol analysis excludes dropouts, introducing post-randomization attrition bias.\", \"retrieved_evidence\": [\"Figure 3.4: Flow diagram of randomized participant attrition.\"], \"student_prompt\": \"What does the reading cite as the total bed count at Massachusetts General Hospital?\"}], \"grounded_paraphrase\": {\"document_title\": \"Clinical Research Methodology\", \"page\": 260, \"section\": \"The Randomization Axiom\", \"selected_text\": \"Randomized allocation constitutes the foundational methodological mechanism designed to achieve probabilistic stochastic parity among experimental and control cohorts, neutralizing both observable and unobservable confounding covariates across study arms.\", \"surrounding_context\": \"This balance underpins the internal validity required to attribute divergent outcomes strictly to the intervention.\", \"retrieved_evidence\": [\"Page 260: 'Randomly assigning participants to groups ensures that both known and hidden differences between people are spread out equally, making groups identical at the start.'\"], \"student_prompt\": \"Can you explain why researchers use randomization in simple terms based on this text?\", \"faithful_paraphrase\": \"This passage explains that the purpose of random assignment is to make sure the two groups being tested start out completely equal. By letting chance decide who gets the treatment and who gets the placebo, you evenly spread out all differences\u2014like age, health habits, genetics, and factors scientists don't even know about\u2014so that any final difference between the groups can only be caused by the treatment itself.\"}, \"conflict_handling\": {\"document_title\": \"Epidemiological Method Controversies\", \"page\": 295, \"section\": \"Prospective Cohort vs Case-Control Feasibility\", \"selected_text\": \"Prospective cohort studies are widely celebrated as the gold standard of observational epidemiology because they establish clear temporal sequence and calculate true incidence rates.\", \"surrounding_context\": \"However, for extremely rare diseases (e.g., incidence of 1 in 100,000 per year), a prospective cohort study would require following millions of people for decades at enormous expense, making retrospective case-control designs the only feasible method.\", \"retrieved_evidence\": [\"Cohort Study: Excellent for common conditions; establishes true incidence; impractical and cost-prohibitive for ultra-rare diseases.\", \"Case-Control Study: Highly efficient and cost-effective for rare diseases by starting with known cases, but susceptible to recall bias.\"], \"student_prompt\": \"If cohort studies are more rigorous than case-control studies, why do scientists ever choose to use case-control designs?\", \"resolution_explanation\": \"While prospective cohort studies provide cleaner evidence, they are practically impossible when studying rare diseases. For example, if a disease only affects 1 in 100,000 people, a cohort study would require monitoring 500,000 healthy people for 20 years just to see 5 people get sick, costing tens of millions of dollars. A case-control study solves this by starting with 50 people who already have the rare condition, finding 50 healthy matches, and looking back at their past exposures. It is chosen because it is vastly faster, cheaper, and feasible for rare conditions.\"}}}, \"general_academic::Bias Identification\": {\"domain\": \"general_academic\", \"concept\": \"Bias Identification\", \"explanation\": \"the process of recognizing systematic errors in thinking, research, or data collection that skew results or conclusions away from the truth\", \"reason\": \"unidentified biases lead to flawed conclusions, unfair decisions, and flawed research \u2014 recognizing them is essential for objective analysis\", \"concrete_examples\": [\"Confirmation bias: a researcher who believes a treatment works may unconsciously interpret ambiguous results as supportive.\", \"Selection bias: a health survey conducted only in gyms would overestimate the general population's fitness levels.\", \"Survivorship bias: studying only successful companies to find success factors ignores the many failed companies that used the same strategies.\"], \"numerical_examples\": [\"In one study, researchers who knew which group received the drug rated symptom improvement 30% higher than blinded researchers \u2014 observer bias in action.\", \"An online poll about internet access has 100% self-selection bias: it can only reach people who already have internet access.\", \"Anchoring bias: when asked 'Is the population of Turkey greater or less than 35 million?' people systematically estimate lower than when asked about 85 million.\"], \"misconceptions\": [[\"Being aware of your biases is enough to eliminate them\", \"Research shows that simply knowing about a bias does NOT prevent it from affecting your thinking. Deliberate, systematic corrective procedures \u2014 like blind review, structured decision-making, pre-registration, and checklists \u2014 are needed to mitigate bias effectively.\"]], \"analogies\": [\"Bias is like a tilt in a pinball machine \u2014 the ball (your thinking) always drifts in one direction unless you recognize the tilt and actively correct for it.\"], \"prerequisites\": [\"critical thinking\"], \"formulas\": [\"No formula \u2014 bias identification requires awareness and systematic checking\"], \"document_evidence\": [\"The text identifies major cognitive biases: 'Confirmation bias, anchoring, availability heuristic, and dunning-kruger effect are among the most impactful biases affecting academic and professional work.'\", \"Section 7.3 describes debiasing strategies: blind review, pre-registration, adversarial collaboration, and red teams.\"], \"practice_problems\": [\"A company surveys its current customers to ask if they like the product. What type of bias is present?\", \"A researcher expects her new teaching method to improve test scores. How could this expectation bias her study? What safeguards should she implement?\"], \"hints\": [\"Ask: Who was included in the sample? Who was excluded? Could the method systematically favor certain results?\", \"Blinding (not knowing group assignment) is the primary defense against observer bias.\"], \"follow_up_questions\": [\"How does pre-registration help reduce researcher bias?\", \"What is the difference between bias and random error?\"], \"diagnostic_questions\": [\"What is survivorship bias and how does it mislead conclusions?\", \"If you only read news sources you agree with, what bias are you exhibiting?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Confirmation bias means that a researcher is actively and fraudulently fabricating fake numbers to fool journals.\", \"error_reason\": \"Confirmation bias is an unconscious psychological cognitive bias where individuals unintentionally notice, search for, and remember evidence that confirms prior beliefs while overlooking contradictory evidence; it is not intentional fraud.\", \"correct_claim\": \"Confirmation bias is the unconscious psychological tendency to search for, interpret, and recall information in a way that confirms preexisting beliefs. It is an inadvertent cognitive bias, not deliberate academic fraud.\", \"understanding_probe\": \"What is confirmation bias, and is it the same as intentional scientific fraud?\", \"expected_answer\": \"No, it is not fraud; it is an unconscious cognitive habit where a person naturally notices and believes facts supporting their view while ignoring opposing evidence.\"}, {\"prior_erroneous_claim\": \"Selection bias only happens when participants intentionally lie on questionnaire forms.\", \"error_reason\": \"Selection bias occurs during the sampling or recruitment phase when the study sample is not representative of the target population; participants lying is response bias or social desirability bias.\", \"correct_claim\": \"Selection bias occurs when the method of selecting participants causes the sample to differ systematically from the broader population. Dishonest answers represent response bias, not selection bias.\", \"understanding_probe\": \"If a researcher conducts a survey about exercise habits only at an upscale gym at 6:00 AM, what bias is present?\", \"expected_answer\": \"Selection bias, because the sample of early morning gym members is not representative of the general population's exercise habits.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Cognitive Psychology and Behavioral Decision Science\", \"page\": 310, \"section\": \"Quantifying Confirmation Bias in Search Query Selections\", \"selected_text\": \"An experimental trial investigates confirmation bias among 200 partisan voters searching an online news database. Subjects are presented with 50 search result articles (25 ideologically supportive, 25 ideologically counter-attitudinal). On average, participants clicked on 18.0 supportive articles and only 2.0 counter-attitudinal articles (Total clicks = 20.0).\", \"surrounding_context\": \"Section 2.1 computes the confirmation selectivity ratio and the percentage skew toward supportive evidence.\", \"retrieved_evidence\": [\"Total articles clicked = 18.0 + 2.0 = 20.0 articles.\", \"Supportive article selection rate: 18.0 / 20.0 = 0.900 (90.0%).\", \"Counter-attitudinal selection rate: 2.0 / 20.0 = 0.100 (10.0%).\", \"Confirmation selectivity ratio: Supportive / Counter = 18.0 / 2.0 = 9.00.\", \"Step-by-step arithmetic from text: Participants chose confirming evidence at 9 times the rate of challenging evidence.\"], \"student_prompt\": \"What are the exact supportive article percentage and confirmation selectivity ratio calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: Out of 20 total clicked articles, participants chose an average of 18 confirming articles, representing 18.0 / 20.0 = 90.0% of their selections. Comparing confirming to challenging selections yields a confirmation selectivity ratio of 18.0 / 2.0 = 9.00. The text directly establishes that 90.0% of selections favored preexisting beliefs, demonstrating a 9:1 confirmation bias ratio over counter-attitudinal evidence.\", \"calculated_result\": \"Supportive Selection = 90.0%, Selectivity Ratio = 9.00 (9:1)\"}, \"pattern_b_derive\": {\"document_title\": \"Heuristics and Biases: Anchoring and Adjustment\", \"page\": 318, \"section\": \"Deriving the Anchoring Index (AI)\", \"selected_text\": \"The Anchoring Index (AI) quantifies the magnitude of an anchor's pull on subjective numerical estimates.\", \"surrounding_context\": \"The formula is AI = (Median Estimate_High - Median Estimate_Low) / (Anchor_High - Anchor_Low).\", \"retrieved_evidence\": [\"Formula: Anchoring Index AI = (Est_High - Est_Low) / (Anchor_High - Anchor_Low)\", \"Experimental data: Group A receives low anchor of 100; median estimate = 140. Group B receives high anchor of 500; median estimate = 340.\"], \"student_prompt\": \"How do we derive the Anchoring Index (AI) from the experimental estimates?\", \"target_response\": \"To derive the Anchoring Index: First calculate the difference in median estimates between the two groups: Est_High - Est_Low = 340 - 140 = 200. Next calculate the difference between the two arbitrary anchor values: Anchor_High - Anchor_Low = 500 - 100 = 400. Divide the estimate difference by the anchor difference: AI = 200 / 400 = 0.50 (or 50.0%). An Anchoring Index of 0.50 demonstrates that participants' estimates moved halfway toward the arbitrary numerical anchors.\", \"formula\": \"AI = (340 - 140) / (500 - 100) = 200 / 400 = 0.50\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact legal settlement paid by Facebook in the Cambridge Analytica class-action lawsuit\", \"actual_topic\": \"confirmation bias, selection bias, anchoring bias, hindsight bias, and availability heuristics\", \"authoritative_source\": \"the United States District Court for the Northern District of California settlement records\", \"document_title\": \"Handbook of Cognitive Bias\", \"page\": 328, \"section\": \"The Availability Heuristic\", \"selected_text\": \"The availability heuristic leads individuals to assess event likelihood based on the cognitive ease with which instances come to mind.\", \"surrounding_context\": \"Vivid media coverage of airplane crashes inflates subjective risk perception relative to automobile travel.\", \"retrieved_evidence\": [\"Section 3.2: Tversky and Kahneman frequency estimation experiments.\"], \"student_prompt\": \"According to this document, how much did Facebook pay to settle the Cambridge Analytica lawsuit?\"}, {\"unmentioned_term\": \"the commercial software price of a license for SPSS Statistics version 29\", \"actual_topic\": \"mitigating cognitive biases through pre-commitments and structured analytical techniques\", \"authoritative_source\": \"IBM software commercial pricing catalogs and enterprise licensing schedules\", \"document_title\": \"Handbook of Cognitive Bias\", \"page\": 332, \"section\": \"De-biasing Techniques in Analytical Intelligence\", \"selected_text\": \"Analysis of Competing Hypotheses (ACH) requires analysts to evaluate evidence against an exhaustive matrix of mutually exclusive hypotheses.\", \"surrounding_context\": \"Structuring evidence evaluation prevents premature closure driven by confirmation bias.\", \"retrieved_evidence\": [\"Table 3.4: Eight-step protocol for executing Analysis of Competing Hypotheses.\"], \"student_prompt\": \"What does the reading cite as the single-user license fee for IBM SPSS Statistics 29?\"}], \"grounded_paraphrase\": {\"document_title\": \"Cognitive Epistemology\", \"page\": 305, \"section\": \"The Cognitive Bias Axiom\", \"selected_text\": \"A cognitive bias designates an involuntary, systematic deviation from normative rationality in judgment and decision-making, wherein individuals construct an idiosyncratic subjective reality mediated by evolutionary heuristic shortcuts and affective processing filters.\", \"surrounding_context\": \"These systematic distortions operate unconsciously across both laypersons and domain experts.\", \"retrieved_evidence\": [\"Page 305: 'A cognitive bias is an automatic mental shortcut that causes our brain to make predictable, systematic mistakes when evaluating reality.'\"], \"student_prompt\": \"Can you explain what a cognitive bias is in plain language based on this text?\", \"faithful_paraphrase\": \"This passage explains that a cognitive bias is a built-in mental glitch. Our brains naturally rely on quick mental shortcuts to make fast decisions, but these shortcuts often cause us to make predictable, unconscious mistakes when judging facts. Instead of seeing the world purely objectively, our thinking gets filtered through our preexisting habits and feelings without us even realizing it.\"}, \"conflict_handling\": {\"document_title\": \"Evolutionary Psychology Perspectives\", \"page\": 340, \"section\": \"Error Management Theory: Bias as Evolutionary Adaptation\", \"selected_text\": \"Traditional cognitive psychologists view cognitive biases as irrational mental defects that lead to foolish errors in modern life.\", \"surrounding_context\": \"Evolutionary psychologists (Haselton & Buss) argue that biases are adaptive features shaped by natural selection; under asymmetric survival costs, having a bias that avoids lethal errors (false negatives) is evolutionarily advantageous even if it increases harmless false alarms.\", \"retrieved_evidence\": [\"Traditional View: Biases are irrational flaws and cognitive failures.\", \"Evolutionary View (Error Management Theory): Biases are adaptive survival mechanisms; assuming a rustle in the grass is a predator (a false positive error) is harmless, but assuming it's just the wind when it's a tiger (a false negative error) is lethal.\"], \"student_prompt\": \"One psychology book says cognitive biases are irrational mistakes, but an evolutionary biology book says they are smart adaptations. Which is right?\", \"resolution_explanation\": \"Both perspectives are accurate within their respective contexts. Traditional cognitive psychology looks at modern tasks\u2014like evaluating scientific statistics or investing in the stock market\u2014where cognitive shortcuts cause serious, irrational mistakes. Evolutionary psychology looks at our ancestral survival environment. In the jungle, if you hear rustling in the bushes, being biased to immediately assume it is a predator keeps you alive, even if it was just the wind 99% of the time. What was an adaptive survival mechanism in ancient times often functions as an irrational bias in the modern world.\"}}}, \"general_academic::Effective Communication\": {\"domain\": \"general_academic\", \"concept\": \"Effective Communication\", \"explanation\": \"the skill of conveying ideas clearly, persuasively, and appropriately to a specific audience through written, spoken, or visual means\", \"reason\": \"it is fundamental to academic success, professional achievement, and personal relationships \u2014 even brilliant ideas fail if poorly communicated\", \"concrete_examples\": [\"Structuring an essay with introduction, body, and conclusion helps readers follow your argument logically.\", \"Using visual aids in a presentation helps the audience grasp complex data that would be hard to follow verbally.\", \"Adjusting your vocabulary and tone when explaining physics to a child vs. a colleague demonstrates audience awareness.\"], \"numerical_examples\": [\"Studies show audiences retain about 10% of what they hear after 72 hours, but 65% when visuals are combined with verbal presentation.\", \"The average attention span during a lecture is about 10\u201320 minutes; breaking content into segments with activities improves engagement by up to 50%.\", \"Emails with clear subject lines are 26% more likely to be opened than those with vague or absent subjects.\"], \"misconceptions\": [[\"Good communication means using complex vocabulary and long sentences\", \"Clear communication uses the simplest language that accurately conveys the meaning. Research shows readability improves at 8th-grade reading level. Hemingway, Einstein, and Feynman are celebrated for explaining complex ideas simply. Jargon should be used only when the audience expects it.\"]], \"analogies\": [\"Communication is like a bridge \u2014 it only works if it connects YOUR side (your idea) to THEIR side (their understanding). A beautiful bridge that doesn't reach the other bank is useless.\"], \"prerequisites\": [\"basic literacy\"], \"formulas\": [\"N/A \u2014 communication is a skill, not a formula\"], \"document_evidence\": [\"The text advises: 'Know your audience, organize your message, use clear language, provide evidence, and seek feedback.'\", \"Research by Mehrabian (cited in Section 8.2) found that nonverbal cues account for a significant portion of face-to-face communication impact.\"], \"practice_problems\": [\"Rewrite this sentence for a general audience: 'The pharmacokinetic profile of the compound demonstrated a Cmax of 250 ng/mL with a Tmax of 2 hours.'\", \"You need to give a 5-minute presentation on climate change. Outline your key points for a non-scientific audience.\"], \"hints\": [\"Start with the main point, not the background. Audiences want to know WHY before HOW.\", \"Use the 'so what?' test: after every claim, ask if the audience understands why it matters to them.\"], \"follow_up_questions\": [\"How does audience analysis change the way you present the same information?\", \"What role does active listening play in effective communication?\"], \"diagnostic_questions\": [\"What makes a piece of writing 'clear'?\", \"Why might a brilliant scientist be a poor communicator?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Effective communication means talking as much as possible and using complex jargon to prove your intellectual superiority.\", \"error_reason\": \"Effective communication prioritizes message clarity, audience understanding, shared meaning, and active listening; using excessive jargon alienates the audience and creates comprehension barriers.\", \"correct_claim\": \"Effective communication centers on clear, accessible transmission of ideas tailored to the audience's background and needs, paired with active listening, not overwhelming them with jargon.\", \"understanding_probe\": \"Why is using dense academic jargon when explaining ideas to general audiences a failure of effective communication?\", \"expected_answer\": \"Because it creates a comprehension barrier, obscures the core message, and alienates the listener instead of fostering shared understanding.\"}, {\"prior_erroneous_claim\": \"Non-verbal communication (body language, eye contact, tone) plays zero role in interpersonal communication.\", \"error_reason\": \"Non-verbal cues (facial expressions, vocal tone, posture) convey emotional context and credibility, heavily influencing how verbal words are interpreted by listeners.\", \"correct_claim\": \"Non-verbal communication (tone, facial expressions, posture) provides vital context, reinforces or contradicts spoken words, and strongly shapes listener trust and comprehension.\", \"understanding_probe\": \"What happens when a speaker's non-verbal body language contradicts their spoken words?\", \"expected_answer\": \"Listeners instinctively trust the non-verbal cues (such as nervous tone or avoiding eye contact) over the spoken words, creating doubt and confusion.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Readability Metrics and Clear Communication\", \"page\": 355, \"section\": \"The Flesch-Kincaid Grade Level Formula\", \"selected_text\": \"An academic department assesses the readability of a patient health consent brochure containing 300 words, 15 sentences, and 450 syllables. The standard Flesch-Kincaid Grade Level formula is FKGL = 0.39 * (Total Words / Total Sentences) + 11.8 * (Total Syllables / Total Words) - 15.59.\", \"surrounding_context\": \"Section 2.1 computes the average sentence length, average syllables per word, and final Flesch-Kincaid Grade Level score.\", \"retrieved_evidence\": [\"Input parameters: Words = 300; Sentences = 15; Syllables = 450.\", \"Average Sentence Length (ASL) = 300 / 15 = 20.0 words/sentence.\", \"Average Syllables per Word (ASW) = 450 / 300 = 1.50 syllables/word.\", \"Step-by-step arithmetic from text: FKGL = (0.39 * 20.0) + (11.8 * 1.50) - 15.59 = 7.80 + 17.70 - 15.59 = 25.50 - 15.59 = 9.91 (approx 10th grade level).\"], \"student_prompt\": \"What are the exact Average Sentence Length, Syllables per Word, and Flesch-Kincaid Grade Level calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The Average Sentence Length is 300 / 15 = 20.0 words per sentence. The Average Syllables per Word is 450 / 300 = 1.50 syllables. Substituting into the formula yields FKGL = (0.39 * 20.0) + (11.8 * 1.50) - 15.59 = 7.80 + 17.70 - 15.59 = 9.91. The course text directly establishes that the text is written at an exact 9.91 reading grade level (approximately 10th grade).\", \"calculated_result\": \"ASL = 20.0, ASW = 1.50, FKGL = 9.91\"}, \"pattern_b_derive\": {\"document_title\": \"Information Theory: Channel Capacity and Noise\", \"page\": 362, \"section\": \"Shannon-Weaver Model of Communication\", \"selected_text\": \"In the Shannon-Weaver communication model, effective information fidelity is reduced by channel noise.\", \"surrounding_context\": \"Derive why feedback loops are mathematically essential to achieve perfect fidelity between sender's intended signal and receiver's received signal.\", \"retrieved_evidence\": [\"Components: Sender -> Encoder -> Channel (with Noise) -> Decoder -> Receiver -> Feedback loop.\", \"Principle: In an open-loop noisy channel, error probability P(error) > 0. A closed-loop feedback channel allows iterative error detection and correction.\"], \"student_prompt\": \"How do we derive why bidirectional feedback is necessary for error-free communication in the Shannon-Weaver model?\", \"target_response\": \"To derive the necessity of feedback: In an open-loop system (one-way transmission), any acoustic, psychological, or semantic noise in the transmission channel corrupts the signal, and because the sender receives no information back, the sender cannot know whether the signal was received accurately. With a closed-loop feedback channel, the receiver encodes and returns their decoded understanding back to the sender. This allows the sender to compare the feedback signal with the original message, detect any discrepancies caused by noise, and transmit corrective adjustments until error is eliminated.\", \"formula\": \"Fidelity requires: Closed Feedback Loop = Signal Verification + Noise Correction\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact production budget of the documentary film The Social Dilemma\", \"actual_topic\": \"verbal clarity, active listening, audience adaptation, non-verbal cues, and readability scores\", \"authoritative_source\": \"Exposure Labs production financial records or Netflix film procurement filings\", \"document_title\": \"Principles of Effective Communication\", \"page\": 372, \"section\": \"Active Listening Frameworks\", \"selected_text\": \"Active listening requires four sequential behaviors: attending, suspending judgment, reflective paraphrasing, and synthesizing.\", \"surrounding_context\": \"Reflective paraphrasing confirms mutual understanding before offering substantive responses.\", \"retrieved_evidence\": [\"Section 3.2: Psychological validation techniques in interpersonal dialogue.\"], \"student_prompt\": \"According to this text, what was the production budget for The Social Dilemma?\"}, {\"unmentioned_term\": \"the retail price of a Shure SM7B dynamic vocal microphone in Canadian dollars\", \"actual_topic\": \"vocal pacing, pitch modulation, and speech rate in public presentations\", \"authoritative_source\": \"Shure Incorporated authorized Canadian distributor retail price sheets\", \"document_title\": \"Principles of Effective Communication\", \"page\": 378, \"section\": \"Vocal Dynamics and Pacing\", \"selected_text\": \"Optimal public speaking delivery maintains a conversational cadence between 130 and 160 words per minute.\", \"surrounding_context\": \"Strategic pauses allow listeners cognitive space to encode complex information into working memory.\", \"retrieved_evidence\": [\"Table 3.4: Measured audience comprehension retention across varied speaking tempos.\"], \"student_prompt\": \"What does this text state regarding the price of a Shure SM7B microphone in Canada?\"}], \"grounded_paraphrase\": {\"document_title\": \"Interpersonal Communication Theory\", \"page\": 350, \"section\": \"The Communication Competence Axiom\", \"selected_text\": \"Communication competence designates an individual's dual capacity to achieve assigned relational and task objectives with strategic efficacy while concurrently preserving situational normative appropriateness within the sociocultural context of the interaction.\", \"surrounding_context\": \"Effective communicators fluidly adapt syntactic registers and non-verbal behaviors to their communicative counterparts.\", \"retrieved_evidence\": [\"Page 350: 'Communication competence means achieving your communication goal while staying polite and appropriate for the specific social setting.'\"], \"student_prompt\": \"Can you explain what communication competence means based on this passage in plain words?\", \"faithful_paraphrase\": \"This passage explains that communication competence is the ability to get your point across and achieve your goal while making sure you are speaking appropriately and respectfully for the specific social setting. A competent communicator knows how to adjust their tone, words, and body language depending on whether they are in a boardroom, a classroom, or chatting with friends.\"}, \"conflict_handling\": {\"document_title\": \"Cross-Cultural Communication\", \"page\": 385, \"section\": \"High-Context vs Low-Context Communication Norms\", \"selected_text\": \"In low-context communication cultures (e.g., Germany, United States), effective communication is defined as direct, explicit, and literal; listeners expect speakers to state exactly what they mean.\", \"surrounding_context\": \"In high-context cultures (e.g., Japan, Arab nations), effective communication is defined as indirect, nuanced, and relational, where blunt directness is viewed as crude, aggressive, and incompetent.\", \"retrieved_evidence\": [\"Low-Context Norm: Explicit, literal, direct ('Say what you mean; clear words prevent misunderstanding').\", \"High-Context Norm: Implicit, context-dependent, diplomatic ('Direct bluntness insults the listener; true meaning is embedded in context and relationship').\"], \"student_prompt\": \"One business communication guide says to always be completely direct and blunt, but another says being blunt is unprofessional. Which is right?\", \"resolution_explanation\": \"Both rules are correct within their respective cultural environments. In 'low-context' cultures (like the US or Germany), business value is placed on efficiency, clarity, and spelling everything out explicitly; being indirect can be seen as indecisive or evasive. In 'high-context' cultures (like Japan or much of the Middle East), communication relies heavily on shared relationships, context, and non-verbal cues; speaking with blunt directness can cause interpersonal offense and damage business relationships. Truly effective communication requires tailoring your directness to the cultural context of your audience.\"}}}, \"general_academic::Learning Strategies\": {\"domain\": \"general_academic\", \"concept\": \"Learning Strategies\", \"explanation\": \"evidence-based techniques for acquiring, retaining, and applying knowledge more effectively, including spaced repetition, active recall, interleaving, and elaboration\", \"reason\": \"using proven learning strategies can dramatically improve academic performance and reduce study time compared to passive review methods\", \"concrete_examples\": [\"Spaced repetition: reviewing flashcards at increasing intervals (1 day, 3 days, 7 days, 14 days) rather than cramming the night before.\", \"Active recall: closing the textbook and trying to write down everything you remember, rather than re-reading highlighted passages.\", \"Interleaving: mixing practice problems from different chapters instead of completing all Chapter 5 problems before moving to Chapter 6.\"], \"numerical_examples\": [\"Ebbinghaus's forgetting curve: without review, students forget about 70% of material within 24 hours. With one review at 24 hours, retention at 1 week improves from ~30% to ~70%.\", \"A meta-analysis of 10 studies found that practice testing (active recall) improved exam performance by 0.5 standard deviations compared to re-reading.\", \"Students using spaced repetition retained 90% of vocabulary after 6 months vs. 30% for massed practice (cramming).\"], \"misconceptions\": [[\"Highlighting and re-reading are effective study methods\", \"Research consistently shows that passive review methods like highlighting and re-reading are among the LEAST effective learning strategies. They create an 'illusion of fluency' \u2014 the material feels familiar, but you can't actually recall it on a test. Active recall and practice testing are far more effective.\"]], \"analogies\": [\"Learning strategies are like workout plans for your brain \u2014 just as doing the same easy exercise won't build muscle, re-reading the same notes won't build knowledge. You need to challenge yourself (test yourself) and allow recovery time (spaced repetition).\"], \"prerequisites\": [\"basic literacy\"], \"formulas\": [\"Spacing effect: optimal review intervals increase over time (e.g., 1, 3, 7, 14, 30 days)\"], \"document_evidence\": [\"The text states: 'The most effective learning strategies \u2014 practice testing, spaced repetition, and interleaving \u2014 are also the ones students use least, preferring easier but less effective methods like re-reading.'\", \"Dunlosky et al. (2013) rated 10 common learning techniques (Table 9.1): practice testing and spaced repetition rated 'high utility'; highlighting and re-reading rated 'low utility.'\"], \"practice_problems\": [\"Design a study plan using spaced repetition for an exam 3 weeks away, covering 5 chapters.\", \"Explain why interleaving problems from different topics improves learning, even though it feels harder in the moment.\"], \"hints\": [\"If studying feels easy, you're probably not learning much. Desirable difficulties improve long-term retention.\", \"Test yourself BEFORE reviewing \u2014 even getting things wrong improves subsequent learning.\"], \"follow_up_questions\": [\"What is the 'testing effect' and how does it work?\", \"How can you apply elaboration to deepen understanding of a new concept?\"], \"diagnostic_questions\": [\"Why does re-reading notes feel effective even though it isn't?\", \"What is spaced repetition and why does it work better than cramming?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Passive rereading and highlighting textbook pages with yellow markers is the most effective way to achieve long-term memory retention.\", \"error_reason\": \"Cognitive psychology shows passive rereading produces an 'illusion of competence' without durable retention; active retrieval practice (testing yourself) produces far superior long-term memory retention.\", \"correct_claim\": \"Passive rereading and highlighting are among the least effective study strategies. Active retrieval practice (flashcards, practice questions, self-testing) produces vastly superior retention.\", \"understanding_probe\": \"Why is taking a practice test or using flashcards more effective for memory retention than reading textbook notes three times?\", \"expected_answer\": \"Because active retrieval forces the brain to pull information out of memory, strengthening neural retrieval pathways, whereas passive reading only creates familiarity.\"}, {\"prior_erroneous_claim\": \"Massed practice (cramming all studying into a single 10-hour marathon the night before an exam) results in identical long-term retention as spaced practice.\", \"error_reason\": \"The spacing effect demonstrates that distributed practice across intervals dramatically outperforms massed cramming for durable long-term retention; cramming yields rapid forgetting within days.\", \"correct_claim\": \"Distributed (spaced) practice across multiple days dramatically outperforms massed cramming for long-term retention. Cramming allows rapid forgetting immediately after the test.\", \"understanding_probe\": \"What is the spacing effect in cognitive psychology?\", \"expected_answer\": \"The phenomenon where learning is far more durable when study sessions are spaced out over intervals of time rather than crammed into one single session.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Cognitive Science and Learning Optimization\", \"page\": 395, \"section\": \"The Testing Effect: Retention Interval Experiments\", \"selected_text\": \"In a controlled experiment on memory consolidation (Roediger & Karpicke framework), two cohorts study identical material for 4 hours. Group A uses repeated passive study (4 study sessions). Group B uses retrieval practice (1 study session + 3 active test sessions). On an unexpected delayed exam administered one week later, Group A achieves an average retention score of 40.0%, while Group B achieves 68.0%.\", \"surrounding_context\": \"Section 2.1 computes the absolute retention difference, the relative percentage gain, and Cohen's d effect size (pooled standard deviation SD = 14.0%).\", \"retrieved_evidence\": [\"Group A (Passive study) = 40.0%; Group B (Retrieval practice) = 68.0%.\", \"Absolute score improvement = 68.0% - 40.0% = +28.0 percentage points.\", \"Relative percentage advantage: (68.0 - 40.0) / 40.0 = 28.0 / 40.0 = 0.700 (70.0% relative gain).\", \"Cohen's d effect size formula: d = (Mean_B - Mean_A) / SD_pooled = (68.0 - 40.0) / 14.0 = 28.0 / 14.0 = 2.00 (Extremely large effect size).\"], \"student_prompt\": \"What are the exact absolute gain, relative percentage advantage, and Cohen's d effect size calculated in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: Retrieval practice achieved an absolute gain of 68.0% - 40.0% = 28.0 percentage points over passive rereading. In relative terms, this represents a 28.0 / 40.0 = 70.0% improvement in one-week memory retention. Dividing the 28.0-point difference by the pooled standard deviation (14.0%) yields an effect size of Cohen's d = 2.00, representing an exceptionally large educational effect. The text directly establishes the 28.0-point absolute gain, 70.0% relative advantage, and d = 2.00.\", \"calculated_result\": \"Absolute gain = +28.0%, Relative gain = +70.0%, Cohen's d = 2.00\"}, \"pattern_b_derive\": {\"document_title\": \"Memory Consolidation: Ebbinghaus Forgetting Curve\", \"page\": 402, \"section\": \"Mathematical Modeling of Memory Decay\", \"selected_text\": \"The Ebbinghaus forgetting curve models memory retention R over elapsed time t as an exponential decay: R(t) = e^(-t / S), where S represents memory strength.\", \"surrounding_context\": \"Active retrieval and spaced repetition increase memory strength S by a factor of 3 after each review session.\", \"retrieved_evidence\": [\"Decay Formula: R(t) = e^(-t / S)\", \"Baseline parameters: For initial learning without review, S = 2.0 days. After spaced retrieval, S increases to S = 6.0 days. Calculate retention R at t = 6.0 days.\"], \"student_prompt\": \"How do we derive memory retention at t = 6.0 days for both unreviewed learning (S = 2) and spaced retrieval (S = 6)?\", \"target_response\": \"To derive retention from the Ebbinghaus decay model: For unreviewed learning (S = 2.0): At t = 6.0 days, the exponent is -t/S = -6.0 / 2.0 = -3.0. Evaluating the decay: R(6) = e^(-3.0) \u2248 0.0498, or approximately 5.0% retention (95% forgotten). For spaced retrieval (S = 6.0): At t = 6.0 days, the exponent is -t/S = -6.0 / 6.0 = -1.0. Evaluating the decay: R(6) = e^(-1.0) \u2248 0.3679, or approximately 36.8% retention. Spaced retrieval increases 6-day retention from 5.0% to 36.8%, demonstrating an over 7-fold increase in preserved memory.\", \"formula\": \"R(6)_unreviewed = e^-3 \u2248 5.0%; R(6)_spaced = e^-1 \u2248 36.8%\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the total annual advertising revenue generated by the Duolingo mobile language app\", \"actual_topic\": \"retrieval practice, spaced repetition, interleaving, and metacognitive monitoring\", \"authoritative_source\": \"Duolingo Inc. quarterly Form 10-Q SEC regulatory filings\", \"document_title\": \"Principles of Evidence-Based Learning\", \"page\": 412, \"section\": \"Interleaving vs Blocked Practice\", \"selected_text\": \"Interleaving alternates between different types of problem sets during a single study session, forcing students to discriminate problem structures.\", \"surrounding_context\": \"While interleaving feels more difficult during practice, it dramatically improves test performance and conceptual transfer.\", \"retrieved_evidence\": [\"Figure 4.2: Performance curves contrasting blocked versus interleaved mathematics problem solving.\"], \"student_prompt\": \"According to this document, how much ad revenue did Duolingo make last year?\"}, {\"unmentioned_term\": \"the average cost of a room at the Cornell University Statler Hotel in Ithaca, New York\", \"actual_topic\": \"the Cornell note-taking system (cue column, notes column, summary box)\", \"authoritative_source\": \"Cornell University hospitality booking and rate databases\", \"document_title\": \"Principles of Evidence-Based Learning\", \"page\": 418, \"section\": \"The Cornell Note-Taking System\", \"selected_text\": \"Walter Pauk designed the Cornell system, dividing the page into a 2.5-inch cue column, a 6-inch notes column, and a 2-inch bottom summary.\", \"surrounding_context\": \"Covering the notes column and using the cue column to self-test transforms notes into an active retrieval tool.\", \"retrieved_evidence\": [\"Diagram 4.4: Structural layout of the Cornell note-taking template.\"], \"student_prompt\": \"What does the reading state regarding the nightly room rate at the Cornell Statler Hotel?\"}], \"grounded_paraphrase\": {\"document_title\": \"Cognitive Psychology of Education\", \"page\": 390, \"section\": \"Desirable Difficulties Axiom\", \"selected_text\": \"Bjork's concept of desirable difficulties establishes that instructional conditions that induce cognitive struggle and slow the initial rate of apparent acquisition routinely cultivate superior enduring retention and flexible conceptual transfer across novel domains.\", \"surrounding_context\": \"Conversely, methods that make initial learning feel effortless (like rereading) foster transient fluency without structural neural consolidation.\", \"retrieved_evidence\": [\"Page 390: 'Learning strategies that feel harder and slow down your initial progress actually create deeper, longer-lasting memory and better test scores.'\"], \"student_prompt\": \"Can you explain what 'desirable difficulties' means in studying based on this passage?\", \"faithful_paraphrase\": \"This passage explains that the best study strategies are supposed to feel difficult. When you challenge your brain by testing yourself or mixing up different types of problems, it slows you down and feels harder in the moment, but that mental effort is exactly what forces your brain to build strong, durable memories that stick with you for the long term.\"}, \"conflict_handling\": {\"document_title\": \"Educational Psychology Myths and Realities\", \"page\": 425, \"section\": \"The 'Learning Styles' Myth (VARK) vs Dual Coding\", \"selected_text\": \"A widespread commercial belief asserts that students learn best when instruction is matched to their preferred 'learning style' (Visual, Auditory, or Kinesthetic).\", \"surrounding_context\": \"Extensive empirical research (Pashler et al.) consistently disproves the learning styles meshing hypothesis, demonstrating that all learners benefit when content is paired with both visual representations and verbal explanations (Paivio's dual coding theory).\", \"retrieved_evidence\": [\"Learning Styles Myth: Students must only be taught according to their preferred modality (Visual, Auditory, Kinesthetic).\", \"Scientific Reality: Controlled trials show zero performance boost from matching learning styles; instead, Dual Coding (combining words with diagrams) improves learning for EVERY student.\"], \"student_prompt\": \"My teacher said I am a 'visual learner' and shouldn't bother with audio lectures, but a cognitive science paper says learning styles are a myth. Who is right?\", \"resolution_explanation\": \"The cognitive science research is correct: the idea that people have fixed 'learning styles' and can only learn through their preferred style (visual, auditory, or kinesthetic) is a disproven neuromyth. Controlled psychological studies have repeatedly shown that matching teaching to a student's self-reported style does not improve test scores. What scientific research actually proves is called 'dual coding'\u2014every human brain learns best when verbal explanations and visual diagrams are combined together, rather than relying on one sensory channel alone.\"}}}, \"general_academic::Information Synthesis\": {\"domain\": \"general_academic\", \"concept\": \"Information Synthesis\", \"explanation\": \"the process of combining information from multiple sources to create a new, integrated understanding or argument that is more than the sum of its parts\", \"reason\": \"it enables original thinking, comprehensive literature reviews, and the ability to connect ideas across disciplines \u2014 essential for advanced academic work\", \"concrete_examples\": [\"A literature review synthesizes findings from 30 studies on sleep and cognition to identify overall patterns and gaps.\", \"A policy report combines economic data, public health statistics, and case studies to recommend a course of action.\", \"A student connects ideas from biology (evolution), economics (market competition), and psychology (behavioral adaptation) to write a cross-disciplinary essay.\"], \"numerical_examples\": [\"A meta-analysis synthesizes effect sizes from 25 studies: individual studies range from d=0.2 to d=0.8, but the pooled effect is d=0.45 with narrow confidence interval.\", \"A systematic review screens 500 papers, includes 47 that meet criteria, and identifies 3 consistent themes across all 47.\", \"A research proposal cites 15 sources to build a theoretical framework, connecting findings from 4 different fields.\"], \"misconceptions\": [[\"Synthesis is the same as summarizing multiple sources\", \"Summarizing restates what each source says independently. Synthesis integrates ideas, identifies patterns across sources, resolves contradictions, and creates new understanding. A summary says 'Study A found X; Study B found Y.' A synthesis says 'Studies A and B together suggest Z, but disagree on W, pointing to a need for further research on Q.'\"]], \"analogies\": [\"Synthesis is like cooking a dish from multiple ingredients \u2014 you don't just pile raw vegetables on a plate (summary). You combine, season, and cook them into something new (synthesis) that wouldn't exist from any single ingredient alone.\"], \"prerequisites\": [\"critical thinking\", \"evidence evaluation\"], \"formulas\": [\"N/A \u2014 synthesis is a skill requiring integration, not computation\"], \"document_evidence\": [\"The text explains: 'Effective synthesis goes beyond juxtaposing sources; it identifies agreements, contradictions, and gaps to build a coherent argument or narrative.'\", \"Section 10.3 presents the 'synthesis matrix' technique for organizing findings from multiple sources by theme.\"], \"practice_problems\": [\"Given three sources with different conclusions about remote work productivity, write a synthesis paragraph that integrates all three.\", \"Create a synthesis matrix for 4 articles on the topic of social media and mental health.\"], \"hints\": [\"Organize by THEME, not by source. Don't summarize Source 1, then Source 2. Instead, discuss Theme A using evidence from Sources 1, 2, and 3.\", \"Look for where sources agree (convergence), disagree (contradiction), or leave questions unanswered (gaps).\"], \"follow_up_questions\": [\"How does synthesis differ from analysis?\", \"What is a synthesis matrix and how does it help organize research?\"], \"diagnostic_questions\": [\"If you write one paragraph per source, are you synthesizing or summarizing?\", \"What makes a literature review more than just a collection of summaries?\"], \"v04_enrichments\": {\"prior_error_scenarios\": [{\"prior_erroneous_claim\": \"Synthesizing research simply means summarizing each source in separate, consecutive paragraphs one after the other.\", \"error_reason\": \"That is sequential summary, not synthesis; synthesis combines and integrates multiple sources around thematic concepts, highlighting connections, contradictions, and gaps across texts.\", \"correct_claim\": \"Synthesis is not summarizing sources one by one. True synthesis weaves multiple sources together around common themes, comparing viewpoints, identifying agreements, and analyzing tensions.\", \"understanding_probe\": \"What is the difference between a literature review that summarizes sources versus one that synthesizes sources?\", \"expected_answer\": \"A summary describes each study in separate paragraphs, while a synthesis organizes paragraphs by theme, comparing and connecting multiple studies within the same paragraph.\"}, {\"prior_erroneous_claim\": \"When synthesizing differing academic sources, you should ignore all contradictory findings to make your essay sound consistent.\", \"error_reason\": \"Ignoring contradictory evidence is confirmation bias and academic dishonesty; rigorous synthesis explicitly analyzes contradictions, explores why findings diverge, and evaluates differences in study design.\", \"correct_claim\": \"Synthesizing research requires acknowledging and analyzing contradictory findings, exploring why studies disagree (such as differing sample sizes or methodologies), rather than omitting them.\", \"understanding_probe\": \"Why is it essential to include contradictory findings when synthesizing literature on a scientific topic?\", \"expected_answer\": \"Because addressing conflicting evidence prevents bias, accurately reflects scientific debates, and helps explain why different studies produced different results.\"}], \"evidence_data\": {\"pattern_a_calc\": {\"document_title\": \"Academic Writing and Meta-Synthesis\", \"page\": 440, \"section\": \"Thematic Synthesis Matrix and Cross-Source Convergence\", \"selected_text\": \"A literature synthesis examines 50 published studies on remote work productivity across four thematic nodes: (1) Employee Well-Being, (2) Output Quantity, (3) Communication Overhead, and (4) Team Collaboration. Analysis reveals that 35 studies report positive effects on Well-Being (70.0%), 25 studies report positive effects on Output (50.0%), 40 studies report increased Communication Overhead (80.0%), and 15 studies report positive effects on Collaboration (30.0%).\", \"surrounding_context\": \"Section 2.1 computes the cross-study consensus indices and overall convergence metrics across the four synthesis themes.\", \"retrieved_evidence\": [\"Total reviewed studies N = 50.\", \"Well-being consensus: 35 / 50 = 0.700 (70.0% consensus).\", \"Output quantity consensus: 25 / 50 = 0.500 (50.0% split/inconclusive).\", \"Communication overhead consensus: 40 / 50 = 0.800 (80.0% strong consensus).\", \"Team collaboration consensus: 15 / 50 = 0.300 (30.0% positive, meaning 70.0% reported neutral or negative effects).\", \"Step-by-step arithmetic from text: Communication overhead exhibits the highest consensus (80.0%), followed by well-being (70.0%).\"], \"student_prompt\": \"What are the exact consensus percentages calculated for all four thematic nodes in Section 2.1?\", \"target_response\": \"Following the explicit steps in Section 2.1: The cross-study consensus percentages across the 50 analyzed studies are: Communication Overhead has 80.0% consensus (40 / 50), Employee Well-Being has 70.0% consensus (35 / 50), Output Quantity is evenly split at 50.0% consensus (25 / 50), and Team Collaboration shows 30.0% positive consensus (15 / 50, with 70.0% reporting neutral or negative impacts). The text directly establishes these exact consensus figures across the synthesis matrix.\", \"calculated_result\": \"Overhead = 80.0%, Well-Being = 70.0%, Output = 50.0%, Collaboration = 30.0%\"}, \"pattern_b_derive\": {\"document_title\": \"Systematic Review Synthesis: Fixed-Effect Weighted Mean\", \"page\": 448, \"section\": \"Deriving the Inverse-Variance Weighted Summary Effect\", \"selected_text\": \"In meta-analytic synthesis, combining effect sizes across disparate studies requires weighting each study by the inverse of its variance (W_i = 1 / V_i).\", \"surrounding_context\": \"Studies with smaller variances (larger sample sizes) receive proportionally greater weight in the synthesized summary effect.\", \"retrieved_evidence\": [\"Formula: Summary Effect M = sum(W_i * Y_i) / sum(W_i), where W_i = 1 / V_i.\", \"Study data: Study 1: Effect Y1 = 4.0, Variance V1 = 1.0 (W1 = 1 / 1 = 1.0). Study 2: Effect Y2 = 2.0, Variance V2 = 0.25 (W2 = 1 / 0.25 = 4.0).\"], \"student_prompt\": \"How do we derive the inverse-variance weighted summary effect from these two studies?\", \"target_response\": \"To derive the synthesized summary effect: First calculate the weights: Study 1 weight is W1 = 1 / 1.0 = 1.0; Study 2 weight is W2 = 1 / 0.25 = 4.0. Next, calculate the weighted effects for both studies: W1 * Y1 = 1.0 * 4.0 = 4.0; W2 * Y2 = 4.0 * 2.0 = 8.0. Sum the weighted effects: 4.0 + 8.0 = 12.0. Sum the total weights: 1.0 + 4.0 = 5.0. Finally, divide sum of weighted effects by sum of weights: M = 12.0 / 5.0 = 2.40. The synthesized summary effect is 2.40, heavily influenced by the more precise second study.\", \"formula\": \"M = (1.0*4.0 + 4.0*2.0) / (1.0 + 4.0) = 12.0 / 5.0 = 2.40\"}}, \"absence_refusal\": [{\"unmentioned_term\": \"the exact commercial sales revenue of Zotero citation management software in 2024\", \"actual_topic\": \"thematic synthesis matrices, integrating conflicting findings, and conceptual mapping\", \"authoritative_source\": \"the Corporation for Digital Scholarship non-profit Form 990 tax filings\", \"document_title\": \"Synthesizing Academic Literature\", \"page\": 458, \"section\": \"Constructing Synthesis Matrices\", \"selected_text\": \"A synthesis matrix cross-tabulates extracted empirical studies against emergent conceptual themes across columns.\", \"surrounding_context\": \"Populating matrix cells highlights methodological discrepancies and unstudied research gaps.\", \"retrieved_evidence\": [\"Table 4.1: Four-column synthesis grid for organizational psychology reviews.\"], \"student_prompt\": \"According to this document, how much revenue did Zotero citation software generate in 2024?\"}, {\"unmentioned_term\": \"the total number of doctoral degrees awarded by Harvard University in May 2024\", \"actual_topic\": \"dialectical synthesis, identifying theoretical paradigms, and literature gap analysis\", \"authoritative_source\": \"the Harvard University Office of Institutional Research graduation statistics\", \"document_title\": \"Synthesizing Academic Literature\", \"page\": 464, \"section\": \"Dialectical Synthesis in the Humanities\", \"selected_text\": \"Dialectical synthesis juxtaposes a prevailing thesis against an opposing antithesis to formulate a higher-order conceptual synthesis.\", \"surrounding_context\": \"This synthesis resolves underlying theoretical contradictions without simply compromising between opposites.\", \"retrieved_evidence\": [\"Section 4.3: Hegelian dialectical structures applied to historical literature reviews.\"], \"student_prompt\": \"What does the reading cite as the total number of Harvard doctoral graduates in May 2024?\"}], \"grounded_paraphrase\": {\"document_title\": \"Advanced Academic Scholarship\", \"page\": 435, \"section\": \"The Synthesis Construct Axiom\", \"selected_text\": \"Information synthesis denotes the critical cognitive integration of heterogeneous theoretical perspectives and empirical findings from disparate autonomous sources into a coherent, higher-order conceptual framework that articulates emergent insights not discernible within any individual antecedent source.\", \"surrounding_context\": \"It transcends passive descriptive summarization by actively generating integrative conceptual value.\", \"retrieved_evidence\": [\"Page 435: 'Synthesis is the process of combining ideas from different sources to create a new, bigger-picture understanding that none of the individual sources could provide alone.'\"], \"student_prompt\": \"Can you explain what information synthesis means based on this text in plain words?\", \"faithful_paraphrase\": \"This passage explains that information synthesis is like putting together a jigsaw puzzle. Instead of just summarizing each research paper one by one, you combine facts and perspectives from multiple different studies to build a brand new, bigger picture. By looking at all of them together, you reveal connections, patterns, and insights that none of the individual studies could show on their own.\"}, \"conflict_handling\": {\"document_title\": \"Literature Review Methodology\", \"page\": 470, \"section\": \"Direct Conflicts: Resolving Divergent Empirical Findings\", \"selected_text\": \"When two peer-reviewed studies reach diametrically opposite conclusions on the same research question, novice writers assume one study must be incompetent.\", \"surrounding_context\": \"Expert scholars analyze methodological moderators\u2014such as differences in population demographics, operational definitions of variables, dosage, or measurement timing\u2014to explain why both findings can be valid within their respective parameters.\", \"retrieved_evidence\": [\"Novice Approach: Declare one study 'wrong' and dismiss its findings.\", \"Scholar Synthesis Approach: Identify methodological moderators (e.g., Study A tested adolescent beginners for 2 weeks; Study B tested adult experts for 6 months), explaining that the conflicting results reflect different boundary conditions.\"], \"student_prompt\": \"Study A says caffeine improves memory, but Study B says caffeine impairs memory. How can I synthesize them without calling one wrong?\", \"resolution_explanation\": \"Rather than calling one study wrong, an expert synthesis looks deeper at the specific conditions under which each study was conducted. Often, studies disagree because of differing methods or populations. For example, Study A might have given a low dose of caffeine to well-rested students before a simple recall task, while Study B gave high doses to sleep-deprived adults before a complex reasoning task. Your synthesis should explain that caffeine's effect on memory is not a simple 'yes or no'\u2014it depends on the dosage and task difficulty, turning a contradiction into a deeper, nuanced insight.\"}}}}"

CONCEPT_REGISTRY: Dict[Tuple[str, str], Dict[str, Any]] = {
    tuple(k.split("::", 1)): v for k, v in json.loads(_RAW_REGISTRY_JSON).items()
}


def get_domain_concepts(domain: str) -> List[str]:
    """Return all concept names for a given domain."""
    concepts = [k[1] for k in CONCEPT_REGISTRY if k[0] == domain]
    if not concepts:
        raise ValueError(f"Unknown domain: {domain}. Valid domains: {VALID_DOMAINS}")
    return concepts


def get_concept_info(domain: str, concept: str) -> Dict[str, Any]:
    """Retrieve the full concept info dictionary for a given domain and concept."""
    if (domain, concept) not in CONCEPT_REGISTRY:
        raise ValueError(f"Unknown concept '{concept}' for domain '{domain}'.")
    return CONCEPT_REGISTRY[(domain, concept)]


def get_prior_error_scenario(domain: str, concept: str, index: int) -> Dict[str, Any]:
    """Retrieve a prior error correction scenario for a concept."""
    info = get_concept_info(domain, concept)
    scenarios = info.get("v04_enrichments", {}).get("prior_error_scenarios", [])
    if not scenarios:
        raise ValueError(f"No prior error scenarios found for {domain}/{concept}")
    return scenarios[index % len(scenarios)]


def get_evidence_data(domain: str, concept: str, pattern: str = "pattern_a_calc") -> Dict[str, Any]:
    """Retrieve evidence data (pattern_a_calc or pattern_b_derive) for a concept."""
    info = get_concept_info(domain, concept)
    ev_data = info.get("v04_enrichments", {}).get("evidence_data", {})
    if pattern not in ev_data:
        raise ValueError(f"Pattern {pattern} not found for {domain}/{concept}")
    return ev_data[pattern]


def get_absence_refusal(domain: str, concept: str, index: int = 0) -> Dict[str, Any]:
    """Retrieve a document absence/refusal scenario for a concept."""
    info = get_concept_info(domain, concept)
    scenarios = info.get("v04_enrichments", {}).get("absence_refusal", [])
    if not scenarios:
        raise ValueError(f"No absence refusal scenarios found for {domain}/{concept}")
    return scenarios[index % len(scenarios)]


def get_grounded_paraphrase(domain: str, concept: str) -> Dict[str, Any]:
    """Retrieve a grounded paraphrase scenario for a concept."""
    info = get_concept_info(domain, concept)
    gp = info.get("v04_enrichments", {}).get("grounded_paraphrase", {})
    if not gp:
        raise ValueError(f"No grounded paraphrase scenario found for {domain}/{concept}")
    return gp


def get_conflict_handling(domain: str, concept: str) -> Dict[str, Any]:
    """Retrieve a conflict handling scenario for a concept."""
    info = get_concept_info(domain, concept)
    ch = info.get("v04_enrichments", {}).get("conflict_handling", {})
    if not ch:
        raise ValueError(f"No conflict handling scenario found for {domain}/{concept}")
    return ch


if __name__ == "__main__":
    print(f"Total concepts registered: {len(CONCEPT_REGISTRY)}")
    for dom in VALID_DOMAINS:
        concs = get_domain_concepts(dom)
        print(f"  {dom}: {len(concs)} concepts")
        for c in concs:
            info = get_concept_info(dom, c)
            assert 'v04_enrichments' in info
            assert len(info['v04_enrichments']['prior_error_scenarios']) >= 2
            assert 'pattern_a_calc' in info['v04_enrichments']['evidence_data']
            assert 'pattern_b_derive' in info['v04_enrichments']['evidence_data']
            assert len(info['v04_enrichments']['absence_refusal']) >= 2
            assert 'faithful_paraphrase' in info['v04_enrichments']['grounded_paraphrase']
            assert 'resolution_explanation' in info['v04_enrichments']['conflict_handling']
    print("All 60 concepts verified successfully with complete v0.4 enrichments!")
